INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'lesson', 'les_4cfff55b88f41741', '/courses/computer-vision/lectures/what-is-computer-vision', 'What is computer vision?', 'Computer vision lets a computer get useful information out of images and videos. Compare it with human vision, and see what a computer really receives from a camera, a grid of numbers. Say in one sentence what computer vision is and what it is for Compare human vision with computer vision step by step Explain that a computer first sees an image as a grid of pixel values How computers understand images and videos Computer vision is the part of computer science that lets computers understand visual information . It works with images (one picture) and videos (many pictures in a row). The goal is always the same: extract useful information from visual data . A camera only records light. A computer vision system turns that recording into something a program can use: Image → Computer vision system → Understanding or a decision For example, a car''s camera records the road ahead. The computer vision system finds the lane lines and the car in front. The understanding ("the lane bends left, a car is 20 metres ahead") lets the car decide what to do. Human vision vs computer vision Both follow three steps, but each step is done by something different: Step Human vision Computer vision --- --- --- 1. Capture the eyes capture the scene a camera captures an image 2. Interpret the brain recognises objects the computer processes pixels 3. Act the person makes a decision an algorithm makes a prediction Step 2 is the hard part. You recognise a car instantly, from any angle, in sunshine or at night, even when half of it is hidden. A computer has to be taught every one of those cases, and that is what this course is about. What does a computer see? When you look at a photo of a street, you see buildings, a road and a car. A computer sees no objects at first: just a grid of numbers . The image is cut into tiny squares called pixels . Each pixel stores numbers that say how bright it is (and, in a colour image, which colour). Everything a computer vision program does, from making a photo brighter to recognising a person, is done by working on those numbers. The street image, as the computer sees it This is street.png , a drawn street scene used throughout this course (download it with the link under the picture). The enlarged square is the top-left corner of one window. To the computer, the light wall is the number 181 and the dark window is 65 . The corner you see is only the place where the numbers change. A first look at the numbers You will learn every line of this program in the next lecture. For now, just look at the output: these are the 9 pixels at the corner of that window. import cv2 img = cv2.imread("street.png", cv2.IMREAD_GRAYSCALE) print(img[163:166, 31:34]) From numbers to understanding Look at the output again. Nothing in it says "window" or "building". A program has to find the pattern : a block of small numbers (dark) inside larger numbers (light), with straight borders and sharp corners. Then it has to decide that this pattern, repeated in a grid, is probably the windows of a building. That is why computer vision is usually done in steps: first clean up the numbers, then find simple patterns such as edges and corners, then combine them into objects. The next lesson shows those steps. Check yourself 307,200 numbers: one per pixel, and 640 × 480 = 307,200. A colour image of the same size stores three numbers per pixel, so 921,600. The computer processes pixels. It has no idea of "objects" at first; it calculates with pixel values until it finds patterns it was built to recognise. Common misunderstandings - "The computer sees the picture." It receives numbers. Seeing, in the human sense, is exactly what computer vision programs try to build. - "A camera is computer vision." A camera only captures. Computer vision is the processing that turns the capture into information. - "One program recognises everything." Each system is built for a task (find lanes, read a sign, count people) and is only as good as the examples and methods behind it. Key takeaways - Computer vision lets computers extract useful information from images and videos. - Human vision: eyes, brain, decision. Computer vision: camera, pixel processing, prediction. - To a computer an image is a grid of pixel values ; objects appear only after processing.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_d210cceea941f3d2', 'course_computer_vision', 'top_5bb64696cc8a4154', 'computer-vision-tasks-and-applications', 'Computer vision tasks and applications', 'Follow the five steps of a computer vision pipeline, tell apart the main tasks (classification, detection, segmentation, face recognition, tracking), and see where computer vision is used, from self-driving cars to farms. Ends with the course roadmap.', 1, 2, 'easy', '["Name the five steps of a basic computer vision pipeline in order","Tell image classification, object detection and image segmentation apart by their output","Describe face recognition and motion tracking in one sentence each","Give examples of computer vision applications, including autonomous vehicles"]', '["What is computer vision?"]', 4, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_d210cceea941f3d2';
DELETE FROM lesson_relations WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_d210cceea941f3d2';
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_c4f7fba239432db5', 'course_computer_vision', 'les_d210cceea941f3d2', 'explanation', 'The basic computer vision pipeline', 'Most computer vision systems work in the same five steps, one after the other:

| Step | What happens | Example: a car''s camera |
|---|---|---|
| 1. Image acquisition | a camera captures the image | one frame of the road ahead |
| 2. Image processing | the image is cleaned and prepared | make it the right size, reduce noise |
| 3. Feature extraction | simple, useful patterns are found | edges, corners, lane-line pixels |
| 4. Analysis | the patterns are interpreted | "these edges are the lane; that shape is a car" |
| 5. Decision | the system acts on what it found | keep in lane, slow down |

The labs in this course follow the same order: the next lecture is about step 2 (improving images) and the one after is about step 3 (features).', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d1ed49fca58b3a54', 'course_computer_vision', 'les_d210cceea941f3d2', 'diagram', 'Five steps from image to decision', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_d210cceea941f3d2/cv-pipeline.png', 'A row of five boxes joined by arrows: Image acquisition, Image processing, Feature extraction, Analysis and Decision. Under each box is a small picture: the street image, the same image in grey, its edges, the edges with the car outlined, and the word Slow down', 1512, 251, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_fe6f7950401a50df', 'course_computer_vision', 'les_d210cceea941f3d2', 'explanation', 'The main computer vision tasks', '| Task | What it gives you |
|---|---|
| **Image classification** | **one label** for the whole image |
| **Object detection** | each object''s **label and location** (a box) |
| **Image segmentation** | a label for **every pixel** |
| **Face recognition** | **who** a face belongs to |
| **Motion tracking** | where an object **moves** from frame to frame |

The first three answer more and more detailed questions about the same image. Classification asks "what is this a picture of?", detection asks "what objects are here, and where?", and segmentation asks "which object does each pixel belong to?".', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_20b31dccd94d471c', 'course_computer_vision', 'les_d210cceea941f3d2', 'diagram', 'Classification, detection and segmentation', 'These outputs were made from the drawing itself: the program that drew `street.png` knows where every object is. A real system has to work them out from the pixels, and that is what the later lectures build towards.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_d210cceea941f3d2/cv-tasks.png', 'Three panels. Classification: a close-up of the red car with the single label car. Detection: the whole street with labelled boxes around the car, the person and the stop sign. Segmentation: the street with every pixel coloured by what it shows, sky, mountain, buildings, grass, road, lane lines, car, tree, sign and person, with a colour key', 1389, 458, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_c0bff1da1af3a623', 'course_computer_vision', 'les_d210cceea941f3d2', 'explanation', 'Classification, detection, segmentation', '**Image classification** takes an input image and gives back a **class label**: input image → computer vision model → "car". It says what the image shows, but not where.

**Object detection** answers two questions: **what** objects are present, and **where** they are. Each object gets a box and a label. A real detector also gives each box a **confidence score**, a number from 0 to 1 that says how sure it is (0.97 means very sure). The pictures above have no scores, because their boxes come from the drawing, not from a detector.

**Image segmentation** classifies **every pixel** of the image, so it finds the **exact region** of each object, not just a box around it. A self-driving car uses this to know exactly which pixels are road.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_33c8d0bd6d9a334c', 'course_computer_vision', 'les_d210cceea941f3d2', 'explanation', 'Face recognition and motion tracking', '- **Face recognition** finds faces and identifies or verifies **who** each one is, as when a phone unlocks for its owner.
- **Motion tracking** follows objects **across video frames**: the same car in frame 1, frame 2, frame 3, so the system knows where it is going.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5c5366326fc1b779', 'course_computer_vision', 'les_d210cceea941f3d2', 'explanation', 'Where is computer vision used?', '| Application | One example |
|---|---|
| **Autonomous vehicles** | find lanes, cars, pedestrians and signs |
| **Medical imaging** | point out suspicious areas in X-rays and scans |
| **Security and surveillance** | notice a person entering a restricted area |
| **Robotics** | let a robot arm see where to grab an object |
| **Manufacturing** | spot faulty products on a production line |
| **Facial recognition** | unlock a phone, check identity at a gate |
| **Agriculture** | find diseased plants or count fruit from a drone |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_9ebfdad36f71c0af', 'course_computer_vision', 'les_d210cceea941f3d2', 'explanation', 'Computer vision in autonomous vehicles', 'A self-driving car runs the pipeline many times a second:

**Camera → computer vision → understanding the environment → vehicle decision**

From the camera''s view of the road, the computer vision system must find:

- **cars** and **pedestrians**, which move and must be avoided;
- **traffic signs** and **traffic lights**, which say what is allowed;
- **lane lines**, which say where the car should drive.

Only when all of these are understood can the car decide to continue, turn, slow down or stop. This course''s semester project builds a small version of exactly this system.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d37d74faf9a45f97', 'course_computer_vision', 'les_d210cceea941f3d2', 'diagram', 'What a car''s camera has to find', 'Our drawing has no traffic light, but every other item on the list is there. Again, the boxes and highlighted lanes come from the drawing, to show what a working system must produce.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_d210cceea941f3d2/cv-road-understanding.png', 'The street image with the lane lines highlighted in light blue and labelled boxes around the car, the person and the stop sign', 1016, 596, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_23868e0ca9ea87cd', 'course_computer_vision', 'les_d210cceea941f3d2', 'explanation', 'Course roadmap', 'What we will explore this semester:

1. Image enhancement and restoration
2. Feature detection and matching
3. Object detection
4. Deep learning for image classification
5. Semantic segmentation
6. 3D reconstruction
7. Motion analysis
8. Visual SLAM (building a map while finding where the camera is)
9. Vision-based navigation

Each topic adds one more ability, and the semester project puts them together on a vehicle.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e1b1074c24a75c7e', 'course_computer_vision', 'les_d210cceea941f3d2', 'note', 'Check yourself', '::: check Which task fits each job? (a) Decide whether a photo shows a cat or a dog. (b) Draw a box around every person in a crowd. (c) Colour every pixel of the road in a dashcam image.
???
(a) **Image classification**: one label for the whole image. (b) **Object detection**: a label and a box for each object. (c) **Image segmentation**: a label for every pixel.
:::

::: check In the pipeline, which step finds edges and corners: image processing or feature extraction?
???
**Feature extraction** (step 3). Image processing (step 2) only prepares the image, for example by resizing it or removing noise.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a82464256436b18a', 'course_computer_vision', 'les_d210cceea941f3d2', 'common_mistakes', 'Common mistakes', '- **Mixing up detection and segmentation.** Detection gives a **box** around each object; segmentation gives the **exact pixels**.
- **Thinking classification says where.** A classifier says "car" for the whole image, not where the car is.
- **Skipping step 2.** A dark or noisy image makes every later step worse. That is why the next lecture is about improving images.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_00e42e52a0128a7d', 'course_computer_vision', 'les_d210cceea941f3d2', 'key_takeaways', 'Key takeaways', '- The pipeline: **acquisition → processing → feature extraction → analysis → decision**.
- Classification gives one label, detection gives labels with boxes, segmentation labels every pixel.
- Face recognition says who; motion tracking follows objects across frames.
- Self-driving cars must find cars, pedestrians, signs, traffic lights and lane lines before they decide.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 13, 1792022400000);
