INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d9b86eae823d2f98', 'course_computer_vision', 'les_c2fc8d3dcbc2d6be', 'explanation', 'An image is a grid of numbers', 'To a computer, a picture is a **grid of tiny squares** called **pixels** (short for "picture elements"). Each pixel stores numbers that say what colour it is.

- In a **grayscale** image each pixel holds **one** number, from `0` (black) to `255` (white).
- In a **colour** image each pixel holds **three** numbers: how much blue, green and red light it has, each from `0` to `255`.

So a colour image that is 240 pixels wide and 160 pixels tall is really 160 × 240 × 3 = 115,200 numbers. Everything in computer vision, from blurring to recognising faces, is done by working on those numbers.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a441cfa92c831315', 'course_computer_vision', 'les_c2fc8d3dcbc2d6be', 'diagram', 'The image used in this lesson', 'This is `shapes.png`: 240 pixels wide and 160 pixels tall. Download it with the link under the picture and save it next to your Python file to run the examples on your own computer.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_c2fc8d3dcbc2d6be/shapes.png', 'A dark navy rectangle, 240 by 160 pixels, with a yellow filled circle on the left and a light-blue filled square on the right', 240, 160, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_98d0002ba5000e9a', 'course_computer_vision', 'les_c2fc8d3dcbc2d6be', 'code', 'Reading an image with OpenCV', '`cv2.imread()` loads an image file into a NumPy array, the grid of numbers described above.', 'import cv2

img = cv2.imread("shapes.png")
print(type(img))
print(img.shape)
print(img.dtype)', 'python', 0, '', '<class ''numpy.ndarray''>
(160, 240, 3)
uint8
', '{"notes":[{"line":3,"match":"cv2.imread","text":"loads the file","shape":"circle","color":"sky"},{"line":5,"match":"img.shape","text":"rows, columns, channels","shape":"square","color":"yel"},{"line":6,"match":"img.dtype","text":"8-bit numbers: 0 to 255","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_4d3c31721b6b061a', 'course_computer_vision', 'les_c2fc8d3dcbc2d6be', 'explanation', 'Reading the shape: rows first', '`img.shape` is `(160, 240, 3)`, in this order:

| Position | Value | Meaning |
|---|---|---|
| `shape[0]` | 160 | number of **rows** (the height) |
| `shape[1]` | 240 | number of **columns** (the width) |
| `shape[2]` | 3 | number of **channels** (blue, green, red) |

Height comes **before** width. A handy line for later: `h, w = img.shape[:2]`.

The data type `uint8` means "unsigned 8-bit integer": whole numbers from 0 to 255, which is exactly the range of one colour channel.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_054fa1865ebe855f', 'course_computer_vision', 'les_c2fc8d3dcbc2d6be', 'diagram', 'Zooming in on the circle''s edge', 'Each cell above is **one pixel**, labelled `[row,column]`. The navy pixels hold `B 61, G 33, R 20` and the yellow ones hold `B 59, G 212, R 255`.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_c2fc8d3dcbc2d6be/pixel-grid.png', 'A zoomed-in 4 by 4 grid of pixels at the left edge of the yellow circle. Navy cells show B 61, G 33, R 20; yellow cells show B 59, G 212, R 255. Each cell is labelled with its row and column', 530, 530, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_84a17b765f297202', 'course_computer_vision', 'les_c2fc8d3dcbc2d6be', 'code', 'Reading one pixel', 'You read a pixel with `img[row, column]`. For a colour image you get three numbers back.', 'import cv2

img = cv2.imread("shapes.png")
print(img[0, 0])
print(img[80, 70])
b, g, r = img[80, 70]
print("red:", r)', 'python', 0, '', '[61 33 20]
[ 59 212 255]
red: 255
', '{"notes":[{"line":4,"match":"img[0, 0]","text":"top-left pixel","shape":"circle","color":"sky"},{"line":5,"match":"img[80, 70]","text":"row 80, column 70","shape":"square","color":"yel"},{"line":6,"match":"b, g, r","text":"the order is B, G, R","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3fcd01c1729c84ef', 'course_computer_vision', 'les_c2fc8d3dcbc2d6be', 'explanation', 'Why BGR and not RGB?', 'Most tools list colours as **R**ed, **G**reen, **B**lue. OpenCV stores them the other way round: **B**lue, **G**reen, **R**ed. That''s why the yellow pixel prints as `[ 59 212 255]`: very little blue, a lot of green and full red, which our eyes see as yellow.

This matters when you mix OpenCV with other libraries. Showing an OpenCV image with a library that expects RGB swaps red and blue, so yellow looks light blue. Convert first with `cv2.cvtColor(img, cv2.COLOR_BGR2RGB)`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a31e691cb6835e90', 'course_computer_vision', 'les_c2fc8d3dcbc2d6be', 'diagram', 'The three channels, one at a time', 'Each channel on its own is a grayscale image. The light-blue square is bright in channel 0 (blue); the yellow circle is almost dark in channel 0 but fully bright in channel 2 (red).', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_c2fc8d3dcbc2d6be/bgr-channels.png', 'The shapes image split into three grey images labelled channel 0 B, channel 1 G and channel 2 R. The square is bright in the blue channel, the circle is brightest in the red channel', 740, 196, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5097966e126baff4', 'course_computer_vision', 'les_c2fc8d3dcbc2d6be', 'code', 'Grayscale: one number per pixel', 'Pass `cv2.IMREAD_GRAYSCALE` to load the image with a single channel. The third number disappears from the shape.', 'import cv2

gray = cv2.imread("shapes.png", cv2.IMREAD_GRAYSCALE)
print(gray.shape)
print(gray[80, 70])
print(gray[0, 0])', 'python', 0, '', '(160, 240)
207
32
', '{"notes":[{"line":3,"match":"cv2.IMREAD_GRAYSCALE","text":"load as grey","shape":"circle","color":"sky"},{"line":4,"match":"gray.shape","text":"no channel number","shape":"square","color":"yel"}],"strips":[]}', NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_37b1db2fe4730298', 'course_computer_vision', 'les_c2fc8d3dcbc2d6be', 'note', 'Check yourself', '::: check An image''s shape is `(480, 640, 3)`. How wide is it, and what does `img[479, 639]` give you?
???
It is **640 pixels wide** and 480 pixels tall, because the shape lists rows (height) first. `img[479, 639]` is the **bottom-right pixel**: its three numbers in B, G, R order. Row 479 and column 639 are the last ones, since indexes start at 0.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_339f669af73c5c48', 'course_computer_vision', 'les_c2fc8d3dcbc2d6be', 'code', 'Changing a block of pixels', 'Because an image is a NumPy array, slicing works on it like on a List, with one slice for the rows and one for the columns. Assigning a colour to a slice paints that whole block.', 'import cv2

img = cv2.imread("shapes.png")
img[10:30, 10:30] = (255, 255, 255)
print(img[20, 20])
cv2.imwrite("marked.png", img)', 'python', 0, '', '[255 255 255]
', '{"notes":[{"line":4,"match":"10:30, 10:30","text":"rows 10-29, columns 10-29","shape":"circle","color":"sky"},{"line":4,"match":"(255, 255, 255)","text":"white in B, G, R","shape":"square","color":"yel"},{"line":6,"match":"cv2.imwrite","text":"saves to a new file","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_647c47bcf02ce417', 'course_computer_vision', 'les_c2fc8d3dcbc2d6be', 'diagram', 'The saved file', '`marked.png` has a 20 × 20 white square in the top-left corner. The original `shapes.png` is unchanged, because `imwrite` wrote a new file.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_c2fc8d3dcbc2d6be/marked.png', 'The shapes image with a small white square painted in the top-left corner', 240, 160, 12, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_db1e686cbc19444a', 'course_computer_vision', 'les_c2fc8d3dcbc2d6be', 'common_mistakes', 'Common mistakes', '- **A wrong file name gives `None`, not an error.** `cv2.imread("shape.png")` (missing *s*) returns `None` and OpenCV only prints a warning. The program fails later with a confusing message such as `''NoneType'' object has no attribute ''shape''`. Check with `if img is None:` straight after reading.
- **Swapping x and y.** Pixels are `img[row, column]`, which is `img[y, x]`. Many drawing functions, such as `cv2.circle(img, (x, y), …)`, take **x first**. Mixing the two puts things in the wrong place.
- **Forgetting BGR.** `(255, 0, 0)` is **blue** in OpenCV, not red. Red is `(0, 0, 255)`.
- **Values above 255.** A `uint8` channel can''t hold 256 or more. The next lesson shows what happens when a calculation goes past 255.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 13, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_8fc377bf658625f2', 'course_computer_vision', 'les_c2fc8d3dcbc2d6be', 'key_takeaways', 'Key takeaways', '- An image is a grid of pixels; in OpenCV it''s a NumPy array with shape `(rows, columns, channels)`.
- `uint8` pixels hold whole numbers from 0 to 255.
- `img[row, column]` reads a pixel; colour pixels come back in **B, G, R** order.
- Slicing (`img[10:30, 10:30] = …`) changes a whole block; `cv2.imwrite` saves the result.
- Always check that `cv2.imread` didn''t return `None`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 14, 1792022400000);
DELETE FROM search_index WHERE course_id = 'course_computer_vision' AND entity_type = 'lesson' AND entity_id = 'les_c2fc8d3dcbc2d6be';
INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'lesson', 'les_c2fc8d3dcbc2d6be', '/courses/computer-vision/lectures/digital-images-and-pixels', 'Digital images and pixels', 'See what an image really is to a computer, a grid of numbers, and use OpenCV to read an image, check its size and read or change single pixels. Describe an image as a grid of pixels, each holding numbers Read an image with cv2.imread and check its shape and data type Read one pixel and explain OpenCV''s BGR channel order Change a block of pixels with slicing and save the result An image is a grid of numbers To a computer, a picture is a grid of tiny squares called pixels (short for "picture elements"). Each pixel stores numbers that say what colour it is. - In a grayscale image each pixel holds one number, from 0 (black) to 255 (white). - In a colour image each pixel holds three numbers: how much blue, green and red light it has, each from 0 to 255 . So a colour image that is 240 pixels wide and 160 pixels tall is really 160 × 240 × 3 = 115,200 numbers. Everything in computer vision, from blurring to recognising faces, is done by working on those numbers. The image used in this lesson This is shapes.png : 240 pixels wide and 160 pixels tall. Download it with the link under the picture and save it next to your Python file to run the examples on your own computer. Reading an image with OpenCV cv2.imread() loads an image file into a NumPy array, the grid of numbers described above. import cv2 img = cv2.imread("shapes.png") print(type(img)) print(img.shape) print(img.dtype) Reading the shape: rows first img.shape is (160, 240, 3) , in this order: Position Value Meaning --- --- --- shape[0] 160 number of rows (the height) shape[1] 240 number of columns (the width) shape[2] 3 number of channels (blue, green, red) Height comes before width. A handy line for later: h, w = img.shape[:2] . The data type uint8 means "unsigned 8-bit integer": whole numbers from 0 to 255, which is exactly the range of one colour channel. Zooming in on the circle''s edge Each cell above is one pixel , labelled [row,column] . The navy pixels hold B 61, G 33, R 20 and the yellow ones hold B 59, G 212, R 255 . Reading one pixel You read a pixel with img[row, column] . For a colour image you get three numbers back. import cv2 img = cv2.imread("shapes.png") print(img[0, 0]) print(img[80, 70]) b, g, r = img[80, 70] print("red:", r) Why BGR and not RGB? Most tools list colours as R ed, G reen, B lue. OpenCV stores them the other way round: B lue, G reen, R ed. That''s why the yellow pixel prints as [ 59 212 255] : very little blue, a lot of green and full red, which our eyes see as yellow. This matters when you mix OpenCV with other libraries. Showing an OpenCV image with a library that expects RGB swaps red and blue, so yellow looks light blue. Convert first with cv2.cvtColor(img, cv2.COLOR BGR2RGB) . The three channels, one at a time Each channel on its own is a grayscale image. The light-blue square is bright in channel 0 (blue); the yellow circle is almost dark in channel 0 but fully bright in channel 2 (red). Grayscale: one number per pixel Pass cv2.IMREAD GRAYSCALE to load the image with a single channel. The third number disappears from the shape. import cv2 gray = cv2.imread("shapes.png", cv2.IMREAD_GRAYSCALE) print(gray.shape) print(gray[80, 70]) print(gray[0, 0]) Check yourself It is 640 pixels wide and 480 pixels tall, because the shape lists rows (height) first. img[479, 639] is the bottom-right pixel : its three numbers in B, G, R order. Row 479 and column 639 are the last ones, since indexes start at 0. Changing a block of pixels Because an image is a NumPy array, slicing works on it like on a List, with one slice for the rows and one for the columns. Assigning a colour to a slice paints that whole block. import cv2 img = cv2.imread("shapes.png") img[10:30, 10:30] = (255, 255, 255) print(img[20, 20]) cv2.imwrite("marked.png", img) The saved file marked.png has a 20 × 20 white square in the top-left corner. The original shapes.png is unchanged, because imwrite wrote a new file. Common mistakes - A wrong file name gives None , not an error. cv2.imread("shape.png") (missing s ) returns None and OpenCV only prints a warning. The program fails later with a confusing message such as ''NoneType'' object has no attribute ''shape'' . Check with if img is None: straight after reading. - Swapping x and y. Pixels are img[row, column] , which is img[y, x] . Many drawing functions, such as cv2.circle(img, (x, y), …) , take x first . Mixing the two puts things in the wrong place. - Forgetting BGR. (255, 0, 0) is blue in OpenCV, not red. Red is (0, 0, 255) . - Values above 255. A uint8 channel can''t hold 256 or more. The next lesson shows what happens when a calculation goes past 255. Key takeaways - An image is a grid of pixels; in OpenCV it''s a NumPy array with shape (rows, columns, channels) . - uint8 pixels hold whole numbers from 0 to 255. - img[row, column] reads a pixel; colour pixels come back in B, G, R order. - Slicing ( img[10:30, 10:30] = … ) changes a whole block; cv2.imwrite saves the result. - Always check that cv2.imread didn''t return None .');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_68c8eb7ee571205f', 'course_computer_vision', 'top_b3d4cf2ba88a3e8e', 'grayscale-images', 'Colour to grayscale', 'Convert a colour image to grayscale with cv2.cvtColor, see why the channel number disappears from the shape, and work out how three colour values become one grey value.', 2, 5, 'easy', '["Convert a BGR image to grayscale with cv2.cvtColor","Explain why a grayscale shape has two numbers instead of three","Calculate a pixel''s grey value from its B, G and R values","Say why many computer vision steps work on grayscale images"]', '["Getting started with OpenCV","Digital images and pixels"]', 5, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_68c8eb7ee571205f';
DELETE FROM lesson_relations WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_68c8eb7ee571205f';
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5cd07e65949508b9', 'course_computer_vision', 'les_68c8eb7ee571205f', 'explanation', 'Why grayscale?', 'A colour image stores **3 numbers per pixel** (blue, green, red). A grayscale image stores **1**: how bright the pixel is, from 0 (black) to 255 (white).

Many computer vision steps only need brightness. Edges, corners and textures are changes in brightness, so colour adds little but triples the data to process. That is why most pipelines in this course start by converting to grayscale.

| Image | Channels | Numbers per pixel |
|---|---|---|
| Colour | 3 (B, G, R) | 3 |
| Grayscale | 1 | 1 |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d641b325968046e3', 'course_computer_vision', 'les_68c8eb7ee571205f', 'code', 'Step 3: convert to grayscale', '', 'import cv2

img = cv2.imread("street.png")
gray = cv2.cvtColor(
    img,
    cv2.COLOR_BGR2GRAY
)
cv2.imshow("Original", img)
cv2.imshow("Grayscale", gray)
print(img.shape)
print(gray.shape)
cv2.waitKey(0)
cv2.destroyAllWindows()', 'python', 0, '', '(540, 960, 3)
(540, 960)
', '{"notes":[{"line":4,"match":"cvtColor","text":"convert colour","shape":"circle","color":"sky"},{"line":6,"match":"COLOR_BGR2GRAY","text":"from BGR to grey","shape":"square","color":"yel"},{"line":11,"match":"gray.shape","text":"only two numbers","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_4c6c3f33a345f353', 'course_computer_vision', 'les_68c8eb7ee571205f', 'diagram', 'Two windows: colour and grayscale', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_68c8eb7ee571205f/cv-grayscale.png', 'Two windows side by side. Original shows the colour street scene. Grayscale shows the same scene in shades of grey: the red car is a mid grey, the yellow sun a light grey and the road a darker grey', 1208, 402, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_7dd6038f68aa45b5', 'course_computer_vision', 'les_68c8eb7ee571205f', 'explanation', 'Where did the 3 go?', 'The colour shape is `(540, 960, 3)`; the grayscale shape is `(540, 960)`. There is **no channel dimension** any more, because each pixel is a single number. Reading a pixel shows the difference:

| Code | Colour image `img` | Grayscale image `gray` |
|---|---|---|
| `[420, 600]` (on the car) | `[ 60  60 200]` | `102` |

`cv2.cvtColor()` can convert between many formats. The **code** in its second argument says which: `COLOR_BGR2GRAY` means "from BGR to grey". Its opposite, `COLOR_GRAY2BGR`, turns a grey image back into 3 channels, but the colour is gone for good: all three channels get the same grey value.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_682d41202ab3ed2e', 'course_computer_vision', 'les_68c8eb7ee571205f', 'explanation', 'How three numbers become one', 'OpenCV does **not** simply take the average of B, G and R. Our eyes are most sensitive to green and least to blue, so each channel gets its own weight:

**grey = 0.299 × R + 0.587 × G + 0.114 × B**

For the car pixel, B = 60, G = 60 and R = 200:

0.299 × 200 + 0.587 × 60 + 0.114 × 60 = 59.8 + 35.22 + 6.84 = **101.86**, stored as **102**.

So a bright red car becomes a fairly **dark** grey: red light counts for less than green.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ab485f46c9f4e7b6', 'course_computer_vision', 'les_68c8eb7ee571205f', 'code', 'Checking the formula on one pixel', '', 'import cv2

img = cv2.imread("street.png")
gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
b, g, r = img[420, 600]
print("B, G, R:", b, g, r)
print("formula:", round(0.299 * r + 0.587 * g + 0.114 * b, 2))
print("OpenCV:", gray[420, 600])', 'python', 0, '', 'B, G, R: 60 60 200
formula: 101.86
OpenCV: 102
', '{"notes":[{"line":5,"match":"b, g, r","text":"B first: OpenCV order","shape":"circle","color":"sky"},{"line":7,"match":"0.299 * r","text":"each channel has a weight","shape":"square","color":"yel"},{"line":8,"match":"gray[420, 600]","text":"one number, rounded","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_fac4795ce085388d', 'course_computer_vision', 'les_68c8eb7ee571205f', 'explanation', 'Loading in grayscale directly', 'If you only need grayscale, you can ask `imread()` for it and skip `cvtColor()`:

```python
gray = cv2.imread("street.png", cv2.IMREAD_GRAYSCALE)
```

You will also see `cv2.imread("street.png", 0)`: the `0` is the value of `cv2.IMREAD_GRAYSCALE`. The named version is easier to read. The two ways don''t round in exactly the same way: when we tried both on `street.png`, most pixels came out 1 grey level apart. That is invisible, but it changes printed numbers, so don''t mix the two ways in one experiment.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_4cf5a884049ba99b', 'course_computer_vision', 'les_68c8eb7ee571205f', 'note', 'Check yourself', '::: check A pixel is pure green in OpenCV: `(0, 255, 0)`. Roughly what grey value does it get?
???
About **150**: 0.587 × 255 ≈ 149.7. Pure blue `(255, 0, 0)` would only get about 29 (0.114 × 255), which is why blue things look dark in grayscale.
:::

::: check A grayscale image has shape `(480, 640)`. What does `gray[0, 0]` give?
???
**One number** from 0 to 255: the brightness of the top-left pixel. There is no list of three, because a grayscale image has only one channel.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5e907c6985c4b540', 'course_computer_vision', 'les_68c8eb7ee571205f', 'common_mistakes', 'Common mistakes', '- **`COLOR_RGB2GRAY` on an OpenCV image.** OpenCV images are BGR, so this swaps the weights of red and blue. Use `COLOR_BGR2GRAY`.
- **Unpacking three values from a grey shape.** `h, w, c = gray.shape` fails with `ValueError: not enough values to unpack`. Use `h, w = gray.shape`.
- **Expecting the colour back.** `COLOR_GRAY2BGR` gives three equal channels, not the original colours. Keep the colour image in its own variable.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_8027120a80ebcbc1', 'course_computer_vision', 'les_68c8eb7ee571205f', 'key_takeaways', 'Key takeaways', '- `gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)` converts colour to grayscale.
- A grayscale shape is `(height, width)`: **no channel dimension**.
- grey = 0.299 R + 0.587 G + 0.114 B, so green counts most and blue least.
- Most edge and feature methods work on grayscale images.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1792022400000);
