INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'lesson', 'les_68c8eb7ee571205f', '/courses/computer-vision/lectures/grayscale-images', 'Colour to grayscale', 'Convert a colour image to grayscale with cv2.cvtColor, see why the channel number disappears from the shape, and work out how three colour values become one grey value. Convert a BGR image to grayscale with cv2.cvtColor Explain why a grayscale shape has two numbers instead of three Calculate a pixel''s grey value from its B, G and R values Say why many computer vision steps work on grayscale images Why grayscale? A colour image stores 3 numbers per pixel (blue, green, red). A grayscale image stores 1 : how bright the pixel is, from 0 (black) to 255 (white). Many computer vision steps only need brightness. Edges, corners and textures are changes in brightness, so colour adds little but triples the data to process. That is why most pipelines in this course start by converting to grayscale. Image Channels Numbers per pixel --- --- --- Colour 3 (B, G, R) 3 Grayscale 1 1 Step 3: convert to grayscale import cv2 img = cv2.imread("street.png") gray = cv2.cvtColor( img, cv2.COLOR_BGR2GRAY ) cv2.imshow("Original", img) cv2.imshow("Grayscale", gray) print(img.shape) print(gray.shape) cv2.waitKey(0) cv2.destroyAllWindows() Two windows: colour and grayscale Where did the 3 go? The colour shape is (540, 960, 3) ; the grayscale shape is (540, 960) . There is no channel dimension any more, because each pixel is a single number. Reading a pixel shows the difference: Code Colour image img Grayscale image gray --- --- --- [420, 600] (on the car) [ 60 60 200] 102 cv2.cvtColor() can convert between many formats. The code in its second argument says which: COLOR BGR2GRAY means "from BGR to grey". Its opposite, COLOR GRAY2BGR , turns a grey image back into 3 channels, but the colour is gone for good: all three channels get the same grey value. How three numbers become one OpenCV does not simply take the average of B, G and R. Our eyes are most sensitive to green and least to blue, so each channel gets its own weight: grey = 0.299 × R + 0.587 × G + 0.114 × B For the car pixel, B = 60, G = 60 and R = 200: 0.299 × 200 + 0.587 × 60 + 0.114 × 60 = 59.8 + 35.22 + 6.84 = 101.86 , stored as 102 . So a bright red car becomes a fairly dark grey: red light counts for less than green. Checking the formula on one pixel import cv2 img = cv2.imread("street.png") gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY) b, g, r = img[420, 600] print("B, G, R:", b, g, r) print("formula:", round(0.299 * r + 0.587 * g + 0.114 * b, 2)) print("OpenCV:", gray[420, 600]) Loading in grayscale directly If you only need grayscale, you can ask imread() for it and skip cvtColor() : gray = cv2.imread("street.png", cv2.IMREAD GRAYSCALE) You will also see cv2.imread("street.png", 0) : the 0 is the value of cv2.IMREAD GRAYSCALE . The named version is easier to read. The two ways don''t round in exactly the same way: when we tried both on street.png , most pixels came out 1 grey level apart. That is invisible, but it changes printed numbers, so don''t mix the two ways in one experiment. Check yourself About 150 : 0.587 × 255 ≈ 149.7. Pure blue (255, 0, 0) would only get about 29 (0.114 × 255), which is why blue things look dark in grayscale. One number from 0 to 255: the brightness of the top-left pixel. There is no list of three, because a grayscale image has only one channel. Common mistakes - COLOR RGB2GRAY on an OpenCV image. OpenCV images are BGR, so this swaps the weights of red and blue. Use COLOR BGR2GRAY . - Unpacking three values from a grey shape. h, w, c = gray.shape fails with ValueError: not enough values to unpack . Use h, w = gray.shape . - Expecting the colour back. COLOR GRAY2BGR gives three equal channels, not the original colours. Keep the colour image in its own variable. Key takeaways - gray = cv2.cvtColor(img, cv2.COLOR BGR2GRAY) converts colour to grayscale. - A grayscale shape is (height, width) : no channel dimension . - grey = 0.299 R + 0.587 G + 0.114 B, so green counts most and blue least. - Most edge and feature methods work on grayscale images.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_776f7a5dd6219e8e', 'course_computer_vision', 'top_2639c7e13ccd319a', 'resizing-images', 'Changing image size', 'Resize an image with cv2.resize, remember that the size is given as (width, height), and keep the aspect ratio so the picture isn''t stretched.', 2, 6, 'easy', '["Resize an image to a fixed size with cv2.resize","Give the new size in the right order, (width, height)","Explain why computer vision programs resize images","Keep the aspect ratio by calculating the new height, or by using fx and fy"]', '["Getting started with OpenCV"]', 5, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_776f7a5dd6219e8e';
DELETE FROM lesson_relations WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_776f7a5dd6219e8e';
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a57fdf1d8c805371', 'course_computer_vision', 'les_776f7a5dd6219e8e', 'explanation', 'Why resize?', 'Cameras give images of many sizes: 1280 × 720, 1920 × 1080, 4000 × 3000. Computer vision programs often shrink them first:

| Reason | Why it helps |
|---|---|
| **Faster processing** | fewer pixels means less work for every later step |
| **Standard input size** | many methods and models expect one fixed size |
| **Lower memory use** | a smaller array takes less memory, which matters on a small board like the Jetson |

A vehicle that has to react quickly is a good example: processing a smaller frame leaves time to process more frames per second.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_909b01088b68be81', 'course_computer_vision', 'les_776f7a5dd6219e8e', 'code', 'Step 4: resize to 640 × 480', '', 'import cv2

img = cv2.imread("street.png")
resized = cv2.resize(img, (640, 480))
print("original:", img.shape)
print("resized:", resized.shape)
print("numbers before:", img.size)
print("numbers after:", resized.size)
cv2.imshow("Resized", resized)
cv2.waitKey(0)
cv2.destroyAllWindows()', 'python', 0, '', 'original: (540, 960, 3)
resized: (480, 640, 3)
numbers before: 1555200
numbers after: 921600
', '{"notes":[{"line":4,"match":"(640, 480)","text":"(width, height)!","shape":"circle","color":"sky"},{"line":6,"match":"resized.shape","text":"(height, width, …)","shape":"square","color":"yel"},{"line":7,"match":"img.size","text":"how many numbers","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_010186ee0fef2896', 'course_computer_vision', 'les_776f7a5dd6219e8e', 'explanation', 'Width first here, height first in shape', 'This is the most common mix-up in OpenCV:

| Where | Order | For our resized image |
|---|---|---|
| `cv2.resize(img, (640, 480))` | **(width, height)** | 640 wide, 480 tall |
| `resized.shape` | **(height, width, channels)** | `(480, 640, 3)` |

`img.size` counts every number in the array: 540 × 960 × 3 = 1,555,200 before and 480 × 640 × 3 = 921,600 after. The resized image needs about 40% less memory and work.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_37fb5fbe2c6dc4a4', 'course_computer_vision', 'les_776f7a5dd6219e8e', 'diagram', 'Three sizes of the same street', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_776f7a5dd6219e8e/cv-resize.png', 'Three windows drawn at the same scale. Original, 960 by 540. Resized to 640 by 480: smaller, and the scene is squeezed sideways so the car looks narrow and tall. Keeping the ratio, 640 by 360: smaller, with the scene''s proportions unchanged', 1232, 386, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_078adf055c6fb1c0', 'course_computer_vision', 'les_776f7a5dd6219e8e', 'explanation', 'Keep the aspect ratio', 'The **aspect ratio** is width divided by height. `street.png` is 960 × 540, a ratio of 16:9 (like a TV). 640 × 480 is 4:3, a different shape, so the picture is **squeezed**: look at the car in the middle window.

That is fine for a program that needs exactly 640 × 480, but for people (and for measuring shapes) it is better to keep the ratio. Pick the new width and calculate the height from it:

**new height = old height × new width ÷ old width = 540 × 640 ÷ 960 = 360**', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3ba0fa8841c2a4fe', 'course_computer_vision', 'les_776f7a5dd6219e8e', 'code', 'Resizing without stretching', '', 'import cv2

img = cv2.imread("street.png")
h, w = img.shape[:2]
new_w = 640
new_h = int(h * new_w / w)
small = cv2.resize(img, (new_w, new_h), interpolation=cv2.INTER_AREA)
print(small.shape)
half = cv2.resize(img, None, fx=0.5, fy=0.5)
print(half.shape)', 'python', 0, '', '(360, 640, 3)
(270, 480, 3)
', '{"notes":[{"line":4,"match":"img.shape[:2]","text":"height and width only","shape":"circle","color":"sky"},{"line":6,"match":"int(","text":"sizes must be whole numbers","shape":"square","color":"yel"},{"line":7,"match":"INTER_AREA","text":"best for shrinking","shape":"diamond","color":"green"},{"line":9,"match":"fx=0.5, fy=0.5","text":"half as wide, half as tall","shape":"circle","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_933bc02209ceb545', 'course_computer_vision', 'les_776f7a5dd6219e8e', 'explanation', 'Two ways to give the size, and interpolation', '- **A size**, `(new_w, new_h)`: you choose the exact width and height.
- **Scale factors**, `None, fx=0.5, fy=0.5`: the size is `None` and `fx` and `fy` multiply the width and the height. Using the same number for both keeps the ratio.

When an image is resized, new pixel values have to be calculated from the old ones. That calculation is called **interpolation**. The default, `cv2.INTER_LINEAR`, is fine for most work. OpenCV''s own documentation recommends `cv2.INTER_AREA` for shrinking and `cv2.INTER_CUBIC` (slower) or `cv2.INTER_LINEAR` for enlarging.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2ecbf8193068fe92', 'course_computer_vision', 'les_776f7a5dd6219e8e', 'note', 'Check yourself', '::: check What is the shape of `cv2.resize(img, (300, 200))` for a colour image?
???
**`(200, 300, 3)`**: 200 rows (height) and 300 columns (width). `resize` takes (width, height) but `shape` lists the height first.
:::

::: check A photo is 1280 × 720. You want it 320 pixels wide without stretching. What height do you use?
???
**180**: 720 × 320 ÷ 1280 = 180. Or use `fx=0.25, fy=0.25`, since 320 is a quarter of 1280.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2c7af19a24fecfcf', 'course_computer_vision', 'les_776f7a5dd6219e8e', 'common_mistakes', 'Common mistakes', '- **Giving (height, width).** `cv2.resize(img, (480, 640))` makes a **tall** image, 480 wide and 640 tall.
- **Decimal sizes.** `cv2.resize(img, (640, 360.0))` stops with an error. Wrap calculated sizes in `int()`.
- **Stretching by accident.** A fixed size with a different ratio distorts shapes; calculate the height if shapes matter.
- **Enlarging to get detail.** Making a small image bigger adds pixels, not detail: the result looks soft or blocky.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_794120db0e10780f', 'course_computer_vision', 'les_776f7a5dd6219e8e', 'key_takeaways', 'Key takeaways', '- `cv2.resize(img, (width, height))`: **width first**, unlike `shape`.
- Smaller images are faster to process and use less memory.
- Keep the aspect ratio: new height = old height × new width ÷ old width, or use `fx` and `fy`.
- `cv2.INTER_AREA` is a good choice for shrinking.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1792022400000);
