INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'lesson', 'les_776f7a5dd6219e8e', '/courses/computer-vision/lectures/resizing-images', 'Changing image size', 'Resize an image with cv2.resize, remember that the size is given as (width, height), and keep the aspect ratio so the picture isn''t stretched. Resize an image to a fixed size with cv2.resize Give the new size in the right order, (width, height) Explain why computer vision programs resize images Keep the aspect ratio by calculating the new height, or by using fx and fy Why resize? Cameras give images of many sizes: 1280 × 720, 1920 × 1080, 4000 × 3000. Computer vision programs often shrink them first: Reason Why it helps --- --- Faster processing fewer pixels means less work for every later step Standard input size many methods and models expect one fixed size Lower memory use a smaller array takes less memory, which matters on a small board like the Jetson A vehicle that has to react quickly is a good example: processing a smaller frame leaves time to process more frames per second. Step 4: resize to 640 × 480 import cv2 img = cv2.imread("street.png") resized = cv2.resize(img, (640, 480)) print("original:", img.shape) print("resized:", resized.shape) print("numbers before:", img.size) print("numbers after:", resized.size) cv2.imshow("Resized", resized) cv2.waitKey(0) cv2.destroyAllWindows() Width first here, height first in shape This is the most common mix-up in OpenCV: Where Order For our resized image --- --- --- cv2.resize(img, (640, 480)) (width, height) 640 wide, 480 tall resized.shape (height, width, channels) (480, 640, 3) img.size counts every number in the array: 540 × 960 × 3 = 1,555,200 before and 480 × 640 × 3 = 921,600 after. The resized image needs about 40% less memory and work. Three sizes of the same street Keep the aspect ratio The aspect ratio is width divided by height. street.png is 960 × 540, a ratio of 16:9 (like a TV). 640 × 480 is 4:3, a different shape, so the picture is squeezed : look at the car in the middle window. That is fine for a program that needs exactly 640 × 480, but for people (and for measuring shapes) it is better to keep the ratio. Pick the new width and calculate the height from it: new height = old height × new width ÷ old width = 540 × 640 ÷ 960 = 360 Resizing without stretching import cv2 img = cv2.imread("street.png") h, w = img.shape[:2] new_w = 640 new_h = int(h * new_w / w) small = cv2.resize(img, (new_w, new_h), interpolation=cv2.INTER_AREA) print(small.shape) half = cv2.resize(img, None, fx=0.5, fy=0.5) print(half.shape) Two ways to give the size, and interpolation - A size , (new w, new h) : you choose the exact width and height. - Scale factors , None, fx=0.5, fy=0.5 : the size is None and fx and fy multiply the width and the height. Using the same number for both keeps the ratio. When an image is resized, new pixel values have to be calculated from the old ones. That calculation is called interpolation . The default, cv2.INTER LINEAR , is fine for most work. OpenCV''s own documentation recommends cv2.INTER AREA for shrinking and cv2.INTER CUBIC (slower) or cv2.INTER LINEAR for enlarging. Check yourself (200, 300, 3) : 200 rows (height) and 300 columns (width). resize takes (width, height) but shape lists the height first. 180 : 720 × 320 ÷ 1280 = 180. Or use fx=0.25, fy=0.25 , since 320 is a quarter of 1280. Common mistakes - Giving (height, width). cv2.resize(img, (480, 640)) makes a tall image, 480 wide and 640 tall. - Decimal sizes. cv2.resize(img, (640, 360.0)) stops with an error. Wrap calculated sizes in int() . - Stretching by accident. A fixed size with a different ratio distorts shapes; calculate the height if shapes matter. - Enlarging to get detail. Making a small image bigger adds pixels, not detail: the result looks soft or blocky. Key takeaways - cv2.resize(img, (width, height)) : width first , unlike shape . - Smaller images are faster to process and use less memory. - Keep the aspect ratio: new height = old height × new width ÷ old width, or use fx and fy . - cv2.INTER AREA is a good choice for shrinking.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_ed3f022358ec5171', 'course_computer_vision', 'top_ed3f022358ec5171', 'brightness-and-contrast', 'Brightness and contrast', 'Make an image brighter with beta and punchier with alpha, using one formula, new = alpha × old + beta. Experiment with both, then avoid the overflow bug that turns bright pixels dark.', 2, 7, 'medium', '["Explain brightness and contrast as changes to pixel values","Apply new = alpha × old + beta with cv2.convertScaleAbs","Predict what larger or smaller alpha and beta values do to an image","Explain why adding to a uint8 image with + wraps around","Choose alpha and beta for a dull, low-contrast photo"]', '["Digital images and pixels"]', 10, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
