INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_98cb074798ff2a44', 'course_computer_vision', 'les_ed3f022358ec5171', 'explanation', 'Brightness and contrast are arithmetic', 'Every pixel value is a number from 0 (dark) to 255 (bright), so changing how an image looks means changing those numbers:

- **Brightness**: add the same amount to every value. Adding makes the whole image lighter; subtracting makes it darker.
- **Contrast**: multiply every value. Multiplying by more than 1 pushes values apart, so dark parts get darker relative to bright parts and details stand out. Multiplying by less than 1 squeezes them together and the image looks flat.

Both fit in one formula, applied to every channel of every pixel:

**new = alpha × old + beta**

Here `alpha` controls contrast and `beta` controls brightness. `alpha = 1` and `beta = 0` leave the image unchanged.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_4802f5ad5b356348', 'course_computer_vision', 'les_ed3f022358ec5171', 'code', 'Step 5: make the image brighter', '', 'import cv2

img = cv2.imread("street.png")
bright = cv2.convertScaleAbs(
    img,
    alpha=1,
    beta=50
)
print("average before:", round(img.mean(), 1))
print("average after:", round(bright.mean(), 1))
cv2.imshow("Original", img)
cv2.imshow("Bright", bright)
cv2.waitKey(0)
cv2.destroyAllWindows()', 'python', 0, '', 'average before: 150.0
average after: 194.4
', '{"notes":[{"line":4,"match":"convertScaleAbs","text":"alpha × old + beta","shape":"circle","color":"sky"},{"line":6,"match":"alpha=1","text":"contrast unchanged","shape":"square","color":"yel"},{"line":7,"match":"beta=50","text":"+ 50: brighter","shape":"diamond","color":"green"},{"line":9,"match":"img.mean()","text":"the average value","shape":"circle","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2b632f99c14e9b34', 'course_computer_vision', 'les_ed3f022358ec5171', 'diagram', 'beta = -50, 0 and +50', '**beta controls brightness**: `beta > 0` makes the image brighter, `beta < 0` makes it darker.

Why did the average only go up by 44.4, not 50? Because many values were already above 205, and 205 + 50 would pass 255. `convertScaleAbs` stops them at 255 (look at the washed-out sky on the right). Values that hit 255 lose their differences for good.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_ed3f022358ec5171/cv-beta.png', 'Three versions of the street scene side by side. beta = -50 is darker all over, beta = 0 is the original, beta = +50 is lighter and slightly washed out, with the sky almost white', 1552, 386, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_50696c51bb80a135', 'course_computer_vision', 'les_ed3f022358ec5171', 'code', 'Step 6: change the contrast', '', 'import cv2

img = cv2.imread("street.png")
contrast = cv2.convertScaleAbs(
    img,
    alpha=1.5,
    beta=0
)
saturated = (contrast == 255).mean() * 100
print("values at 255:", round(saturated, 1), "%")
cv2.imshow("Contrast", contrast)
cv2.waitKey(0)
cv2.destroyAllWindows()', 'python', 0, '', 'values at 255: 37.8 %
', '{"notes":[{"line":6,"match":"alpha=1.5","text":"× 1.5: more contrast","shape":"circle","color":"sky"},{"line":9,"match":"contrast == 255","text":"which values hit the top","shape":"square","color":"yel"}],"strips":[]}', NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_c29024285ac0c050', 'course_computer_vision', 'les_ed3f022358ec5171', 'diagram', 'alpha = 0.5, 1 and 2', '**alpha controls contrast**: `alpha < 1` makes the image **flatter**, `alpha > 1` makes it **punchier**. `street.png` is already bright (its average is 150), so `alpha = 1.5` pushes 37.8% of all values to 255, and `alpha = 2` even more. On a dark, dull photo the same alpha would look much better. The lesson''s second image, below, is such a photo.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_ed3f022358ec5171/cv-alpha.png', 'Three versions of the street scene. alpha = 0.5 is dark and flat, with low contrast. alpha = 1 is the original. alpha = 2 has very strong colours and large white areas where the sky and the buildings became pure white', 1552, 386, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_98b63d9c13fb8af8', 'course_computer_vision', 'les_ed3f022358ec5171', 'explanation', 'Experiment with alpha and beta', 'Change the two numbers, run, and observe:

```python
result = cv2.convertScaleAbs(
    img,
    alpha=1.5,
    beta=30
)
cv2.imshow("Result", result)
```

Try every alpha in **0.5, 1, 1.5, 2** with every beta in **-50, 0, 50, 100**. For each one, write down what happens to the image. Which combination gives the best-looking result? The grid below shows all sixteen on `street.png`, so you can compare with your own image.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_35100bf4d848eeba', 'course_computer_vision', 'les_ed3f022358ec5171', 'diagram', 'Sixteen combinations', 'Reading the grid: down a column, alpha spreads the values further apart; along a row, beta moves them all up. Corners with a large alpha and a large beta turn white; small ones turn very dark. For this bright image the best results are near the original; for a dark image they would be further down and to the right.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_ed3f022358ec5171/cv-alpha-beta.png', 'A grid of sixteen small versions of the street scene. Rows are alpha 0.5, 1, 1.5 and 2 from top to bottom; columns are beta -50, 0, 50 and 100 from left to right. The top-left image is very dark, the bottom-right almost white, and the original is in the second row, second column', 1070, 786, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_012c2bdf2672fd23', 'course_computer_vision', 'les_ed3f022358ec5171', 'diagram', 'A dull image to fix', 'This is `scene.png`, 270 × 180 pixels: dull and grey, the kind of photo alpha and beta are made for. Download it with the link under the picture to run the examples below on your own computer.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_ed3f022358ec5171/scene.png', 'A dull, grey-looking drawing of a landscape: a pale sky, a dim sun, a low hill, a small house and green ground', 270, 180, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_1e22f3687bf974ae', 'course_computer_vision', 'les_ed3f022358ec5171', 'code', 'The formula on three numbers', 'Before touching a whole image, try the formula on three pixel values. `cv2.convertScaleAbs()` computes `alpha × value + beta`, rounds the result and keeps it between 0 and 255.', 'import cv2
import numpy as np

row = np.array([[100, 150, 200]], dtype=np.uint8)
print(cv2.convertScaleAbs(row, alpha=1.5, beta=10))', 'python', 0, '', '[[160 235 255]]
', '{"notes":[{"line":4,"match":"dtype=np.uint8","text":"values 0 to 255","shape":"circle","color":"sky"},{"line":5,"match":"alpha=1.5","text":"contrast: × 1.5","shape":"square","color":"yel"},{"line":5,"match":"beta=10","text":"brightness: + 10","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_eb43024155130ac7', 'course_computer_vision', 'les_ed3f022358ec5171', 'explanation', 'Following the numbers', '| old | 1.5 × old + 10 | stored |
|---|---|---|
| 100 | 160 | 160 |
| 150 | 235 | 235 |
| 200 | 310 | **255** |

The last value would be 310, but a `uint8` pixel can''t go above 255, so OpenCV stores 255. This is called **saturation**: the value stops at the limit instead of going past it.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f524c00e4e9ecb73', 'course_computer_vision', 'les_ed3f022358ec5171', 'diagram', 'A dull photo and two fixes', 'The original `scene.png` (left) is dull: its values only range from 88 to 150. Adding brightness (middle) lifts everything but keeps it flat. Raising the contrast (right) spreads the values out, and the hill, house and sun stand out.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_ed3f022358ec5171/brightness-contrast.png', 'Three versions of a simple landscape with a hill, a house and a sun. The original is grey and flat; the beta 60 version is lighter but still flat; the alpha 2.0, beta minus 110 version has stronger colours and clearer edges', 834, 214, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b7660869846aa313', 'course_computer_vision', 'les_ed3f022358ec5171', 'code', 'Adjusting a real image', '', 'import cv2

img = cv2.imread("scene.png")
print("before:", img.min(), img.max())
brighter = cv2.convertScaleAbs(img, alpha=1.0, beta=60)
print("brighter:", brighter.min(), brighter.max())
punchy = cv2.convertScaleAbs(img, alpha=2.0, beta=-110)
print("contrast:", punchy.min(), punchy.max())
cv2.imwrite("punchy.png", punchy)', 'python', 0, '', 'before: 88 150
brighter: 148 210
contrast: 66 190
', '{"notes":[{"line":4,"match":"img.min(), img.max()","text":"darkest and brightest","shape":"circle","color":"sky"},{"line":5,"match":"beta=60","text":"everything + 60","shape":"square","color":"yel"},{"line":7,"match":"alpha=2.0, beta=-110","text":"spread out, then shift","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 12, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d8b217301628f320', 'course_computer_vision', 'les_ed3f022358ec5171', 'explanation', 'Why the contrast fix needs a negative beta', 'With `alpha = 2.0` alone, the darkest value 88 would become 176 and the brightest 150 would become 300, which saturates to 255: most of the image would turn almost white. Subtracting 110 brings the range back down to **66 to 190**. The spread is now 124 values instead of 62, which is what "more contrast" means.

A useful way to choose: pick `alpha` for the spread you want, then pick `beta` so the result is centred in 0 to 255.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 13, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_8c74303ad6b0b74e', 'course_computer_vision', 'les_ed3f022358ec5171', 'note', 'Check yourself', '::: check What does this print?
```python
import cv2
import numpy as np

row = np.array([[40, 200]], dtype=np.uint8)
print(cv2.convertScaleAbs(row, alpha=0.5, beta=0))
```
???
```output
[[ 20 100]]
```
Multiplying by 0.5 halves every value, so the two values move closer together: **less contrast**. NumPy pads the 20 with a space so the columns line up.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 14, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a84d94c0346927fd', 'course_computer_vision', 'les_ed3f022358ec5171', 'common_mistakes', 'The overflow bug: using + on uint8 images', 'It''s tempting to brighten with `img + 100`. With `uint8` arrays, NumPy does **not** stop at 255: it **wraps around** and starts again from 0. So 250 + 10 becomes 4, a nearly black value, right where the image was brightest.', 'import cv2
import numpy as np

row = np.array([[100, 200, 250]], dtype=np.uint8)
print(row + 10)
print(cv2.convertScaleAbs(row, alpha=1.0, beta=10))', 'python', 0, '', '[[110 210   4]]
[[110 210 255]]
', '{"notes":[{"line":5,"match":"row + 10","text":"wraps: 260 becomes 4","shape":"tri","color":"coral"},{"line":6,"match":"cv2.convertScaleAbs","text":"stops at 255","shape":"circle","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 15, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_4f7d98af243e0d62', 'course_computer_vision', 'les_ed3f022358ec5171', 'diagram', 'What the overflow does to a picture', 'With `img + 100` (middle) the yellow circle turns purple and the light-blue square turns red: their bright channels went past 255 and wrapped around to small numbers. `convertScaleAbs` (right) gives the lighter image you expected.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_ed3f022358ec5171/overflow.png', 'Three versions of the shapes image. The original has a yellow circle and a light-blue square. Adding 100 with NumPy turns the circle purple and the square red because bright values wrapped around. convertScaleAbs makes both shapes lighter, as expected', 744, 194, 16, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f50a72f71be97cfc', 'course_computer_vision', 'les_ed3f022358ec5171', 'common_mistakes', 'Other common mistakes', '- **Too much alpha.** Large values push most pixels to 255 (pure white) and the detail is lost for good. Check `min()` and `max()` after adjusting.
- **Changing the original by accident.** `convertScaleAbs` returns a **new** image. Keep the result in a new variable if you still need the original.
- **Expecting negative results.** `convertScaleAbs` takes the absolute value before saturating, so a result of -20 is stored as 20, not 0. Choose `beta` so results stay positive.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 17, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_8435d153652c9d34', 'course_computer_vision', 'les_ed3f022358ec5171', 'key_takeaways', 'Key takeaways', '- Brightness adds (`beta`); contrast multiplies (`alpha`): **new = alpha × old + beta**.
- `cv2.convertScaleAbs(img, alpha=…, beta=…)` applies the formula and keeps results from 0 to 255.
- `uint8` arithmetic with `+` wraps around past 255; that''s why bright areas turn dark.
- After adjusting, check `img.min()` and `img.max()` to see the new range.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 18, 1792022400000);
DELETE FROM search_index WHERE course_id = 'course_computer_vision' AND entity_type = 'lesson' AND entity_id = 'les_ed3f022358ec5171';
INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'lesson', 'les_ed3f022358ec5171', '/courses/computer-vision/lectures/brightness-and-contrast', 'Brightness and contrast', 'Make an image brighter with beta and punchier with alpha, using one formula, new = alpha × old + beta. Experiment with both, then avoid the overflow bug that turns bright pixels dark. Explain brightness and contrast as changes to pixel values Apply new = alpha × old + beta with cv2.convertScaleAbs Predict what larger or smaller alpha and beta values do to an image Explain why adding to a uint8 image with + wraps around Choose alpha and beta for a dull, low-contrast photo Brightness and contrast are arithmetic Every pixel value is a number from 0 (dark) to 255 (bright), so changing how an image looks means changing those numbers: - Brightness : add the same amount to every value. Adding makes the whole image lighter; subtracting makes it darker. - Contrast : multiply every value. Multiplying by more than 1 pushes values apart, so dark parts get darker relative to bright parts and details stand out. Multiplying by less than 1 squeezes them together and the image looks flat. Both fit in one formula, applied to every channel of every pixel: new = alpha × old + beta Here alpha controls contrast and beta controls brightness. alpha = 1 and beta = 0 leave the image unchanged. Step 5: make the image brighter import cv2 img = cv2.imread("street.png") bright = cv2.convertScaleAbs( img, alpha=1, beta=50 ) print("average before:", round(img.mean(), 1)) print("average after:", round(bright.mean(), 1)) cv2.imshow("Original", img) cv2.imshow("Bright", bright) cv2.waitKey(0) cv2.destroyAllWindows() beta = -50, 0 and +50 beta controls brightness : beta 0 makes the image brighter, beta < 0 makes it darker. Why did the average only go up by 44.4, not 50? Because many values were already above 205, and 205 + 50 would pass 255. convertScaleAbs stops them at 255 (look at the washed-out sky on the right). Values that hit 255 lose their differences for good. Step 6: change the contrast import cv2 img = cv2.imread("street.png") contrast = cv2.convertScaleAbs( img, alpha=1.5, beta=0 ) saturated = (contrast == 255).mean() * 100 print("values at 255:", round(saturated, 1), "%") cv2.imshow("Contrast", contrast) cv2.waitKey(0) cv2.destroyAllWindows() alpha = 0.5, 1 and 2 alpha controls contrast : alpha < 1 makes the image flatter , alpha 1 makes it punchier . street.png is already bright (its average is 150), so alpha = 1.5 pushes 37.8% of all values to 255, and alpha = 2 even more. On a dark, dull photo the same alpha would look much better. The lesson''s second image, below, is such a photo. Experiment with alpha and beta Change the two numbers, run, and observe: result = cv2.convertScaleAbs( img, alpha=1.5, beta=30 ) cv2.imshow("Result", result) Try every alpha in 0.5, 1, 1.5, 2 with every beta in -50, 0, 50, 100 . For each one, write down what happens to the image. Which combination gives the best-looking result? The grid below shows all sixteen on street.png , so you can compare with your own image. Sixteen combinations Reading the grid: down a column, alpha spreads the values further apart; along a row, beta moves them all up. Corners with a large alpha and a large beta turn white; small ones turn very dark. For this bright image the best results are near the original; for a dark image they would be further down and to the right. A dull image to fix This is scene.png , 270 × 180 pixels: dull and grey, the kind of photo alpha and beta are made for. Download it with the link under the picture to run the examples below on your own computer. The formula on three numbers Before touching a whole image, try the formula on three pixel values. cv2.convertScaleAbs() computes alpha × value + beta , rounds the result and keeps it between 0 and 255. import cv2 import numpy as np row = np.array([[100, 150, 200]], dtype=np.uint8) print(cv2.convertScaleAbs(row, alpha=1.5, beta=10)) Following the numbers old 1.5 × old + 10 stored --- --- --- 100 160 160 150 235 235 200 310 255 The last value would be 310, but a uint8 pixel can''t go above 255, so OpenCV stores 255. This is called saturation : the value stops at the limit instead of going past it. A dull photo and two fixes The original scene.png (left) is dull: its values only range from 88 to 150. Adding brightness (middle) lifts everything but keeps it flat. Raising the contrast (right) spreads the values out, and the hill, house and sun stand out. Adjusting a real image import cv2 img = cv2.imread("scene.png") print("before:", img.min(), img.max()) brighter = cv2.convertScaleAbs(img, alpha=1.0, beta=60) print("brighter:", brighter.min(), brighter.max()) punchy = cv2.convertScaleAbs(img, alpha=2.0, beta=-110) print("contrast:", punchy.min(), punchy.max()) cv2.imwrite("punchy.png", punchy) Why the contrast fix needs a negative beta With alpha = 2.0 alone, the darkest value 88 would become 176 and the brightest 150 would become 300, which saturates to 255: most of the image would turn almost white. Subtracting 110 brings the range back down to 66 to 190 . The spread is now 124 values instead of 62, which is what "more contrast" means. A useful way to choose: pick alpha for the spread you want, then pick beta so the result is centred in 0 to 255. Check yourself import cv2 import numpy as np row = np.array([[40, 200]], dtype=np.uint8) print(cv2.convertScaleAbs(row, alpha=0.5, beta=0)) [[ 20 100]] Multiplying by 0.5 halves every value, so the two values move closer together: less contrast . NumPy pads the 20 with a space so the columns line up. The overflow bug: using + on uint8 images It''s tempting to brighten with img + 100 . With uint8 arrays, NumPy does not stop at 255: it wraps around and starts again from 0. So 250 + 10 becomes 4, a nearly black value, right where the image was brightest. import cv2 import numpy as np row = np.array([[100, 200, 250]], dtype=np.uint8) print(row + 10) print(cv2.convertScaleAbs(row, alpha=1.0, beta=10)) What the overflow does to a picture With img + 100 (middle) the yellow circle turns purple and the light-blue square turns red: their bright channels went past 255 and wrapped around to small numbers. convertScaleAbs (right) gives the lighter image you expected. Other common mistakes - Too much alpha. Large values push most pixels to 255 (pure white) and the detail is lost for good. Check min() and max() after adjusting. - Changing the original by accident. convertScaleAbs returns a new image. Keep the result in a new variable if you still need the original. - Expecting negative results. convertScaleAbs takes the absolute value before saturating, so a result of -20 is stored as 20, not 0. Choose beta so results stay positive. Key takeaways - Brightness adds ( beta ); contrast multiplies ( alpha ): new = alpha × old + beta . - cv2.convertScaleAbs(img, alpha=…, beta=…) applies the formula and keeps results from 0 to 255. - uint8 arithmetic with + wraps around past 255; that''s why bright areas turn dark. - After adjusting, check img.min() and img.max() to see the new range.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_e0c31345b781f8a8', 'course_computer_vision', 'top_dee772f46241845b', 'smoothing-and-noise', 'Blurring and removing noise', 'Smooth an image with a Gaussian blur, compare the average, Gaussian and median filters, and remove salt-and-pepper noise with a median blur. Measure which filter really helps.', 2, 8, 'medium', '["Blur an image with cv2.GaussianBlur and choose a kernel size","Explain how a filter computes each new pixel from its neighbours","Compare cv2.blur, cv2.GaussianBlur and cv2.medianBlur on a noisy image","Remove salt-and-pepper noise with cv2.medianBlur"]', '["Brightness and contrast"]', 9, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_e0c31345b781f8a8';
DELETE FROM lesson_relations WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_e0c31345b781f8a8';
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_4e82650674f0ab06', 'course_computer_vision', 'les_e0c31345b781f8a8', 'explanation', 'Image smoothing', '**Blurring** (or smoothing) makes each pixel more like its neighbours. Small details and small random changes fade, while large shapes stay.

Why would we want a blurrier image? Because cameras add **noise**: unwanted random changes in pixel values, especially in dim light. Noise confuses later steps; for example, an edge detector reports every noisy speck as an edge. A little blur before those steps removes most of it.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_7100d1f469b49809', 'course_computer_vision', 'les_e0c31345b781f8a8', 'code', 'Step 7: a Gaussian blur', '', 'import cv2

img = cv2.imread("street.png")
blur = cv2.GaussianBlur(
    img,
    (5, 5),
    0
)
cv2.imshow("Original", img)
cv2.imshow("Blurred", blur)
cv2.waitKey(0)
cv2.destroyAllWindows()', 'python', 0, '', NULL, '{"notes":[{"line":4,"match":"GaussianBlur","text":"smooth the image","shape":"circle","color":"sky"},{"line":6,"match":"(5, 5)","text":"kernel: 5 × 5 neighbours","shape":"square","color":"yel"},{"line":7,"match":"0","text":"let OpenCV pick the spread","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e07be4f553b95497', 'course_computer_vision', 'les_e0c31345b781f8a8', 'explanation', 'What the arguments mean', '| Argument | Meaning |
|---|---|
| `img` | the image to blur |
| `(5, 5)` | the **kernel size**: each new pixel is computed from a 5 × 5 square of neighbours around it |
| `0` | how widely the weights spread (sigma); 0 tells OpenCV to calculate it from the kernel size |

The kernel width and height must be **odd** (3, 5, 7…), so the kernel has a centre pixel. Try `(3, 3)`, `(5, 5)` and `(15, 15)`: a **larger kernel gives more blur**.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2c02c65de615bb0f', 'course_computer_vision', 'les_e0c31345b781f8a8', 'diagram', 'Kernel sizes (3, 3), (5, 5) and (15, 15)', 'These are close-ups of the top-left part of the image, enlarged so you can see the difference.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_e0c31345b781f8a8/cv-gaussian-sizes.png', 'Four close-ups of the same part of the street scene, a building''s windows and the edge of the grass. The original is sharp. With a 3 by 3 kernel it is slightly soft, with 5 by 5 softer, and with 15 by 15 the windows have melted into blurry blobs', 1044, 704, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_8fc7aca8857067ce', 'course_computer_vision', 'les_e0c31345b781f8a8', 'explanation', 'How a filter computes a pixel', 'All three smoothing filters in this lecture slide a small window (the kernel) over the image. For **every** pixel, they look at the pixel and its neighbours, and compute one new value:

| Filter | Code | New value |
|---|---|---|
| **Average** | `cv2.blur(img, (5, 5))` | the plain average of the 25 neighbours |
| **Gaussian** | `cv2.GaussianBlur(img, (5, 5), 0)` | a weighted average: near neighbours count more than far ones |
| **Median** | `cv2.medianBlur(img, 5)` | the **middle** value after sorting the 25 neighbours |

The median is different from the other two: it doesn''t calculate a new value, it **picks** one of the existing ones. That matters a lot for some kinds of noise.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_332010a03bbcd0f6', 'course_computer_vision', 'les_e0c31345b781f8a8', 'code', 'Average or median? Try it on 9 numbers', 'This program runs in your browser. The nine numbers are a 3 × 3 patch of a grey area (values near 13) hit by one white dot (255) and one black dot (0).', 'import statistics

patch = [12, 14, 13,
         15, 255, 11,
         0, 14, 13]

print("average:", round(sum(patch) / len(patch), 1))
print("median:", statistics.median(patch))', 'python', 1, '', 'average: 38.6
median: 13
', '{"notes":[{"line":4,"match":"255","text":"a white dot (noise)","shape":"tri","color":"coral"},{"line":5,"match":"0","text":"a black dot (noise)","shape":"tri","color":"coral"},{"line":7,"match":"sum(patch) / len(patch)","text":"pulled up by the 255","shape":"square","color":"yel"},{"line":8,"match":"statistics.median","text":"the middle value","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_eb3acdcc4d56ce96', 'course_computer_vision', 'les_e0c31345b781f8a8', 'explanation', 'Why the median wins here', 'Sorted, the nine values are 0, 11, 12, 13, **13**, 14, 14, 15, 255. The median is the fifth one, **13**: a normal grey value. The two extreme values sit at the ends of the sorted list and are simply ignored.

The average adds everything up, so the single 255 drags it to **38.6**, nearly three times too bright. An average filter doesn''t remove a white dot; it spreads it into a lighter smudge.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_6f3ce5aa3ddcd187', 'course_computer_vision', 'les_e0c31345b781f8a8', 'explanation', 'Image noise: salt and pepper', '**Noise = unwanted random pixels.** One common kind is **salt-and-pepper noise**: random pixels turned pure white (salt) or pure black (pepper), for example by a faulty sensor or transmission errors. The next image has it: 4% of its pixels are salt or pepper.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a11feaaee10707aa', 'course_computer_vision', 'les_e0c31345b781f8a8', 'diagram', 'The noisy image', 'This is `noisy-street.png`. Download it to run the next two programs.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_e0c31345b781f8a8/noisy-street.png', 'The street scene at 640 by 360 pixels, covered in thousands of scattered pure white and pure black dots', 640, 360, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2c5c98046e0c7831', 'course_computer_vision', 'les_e0c31345b781f8a8', 'code', 'Removing salt and pepper with a median blur', '', 'import cv2
import numpy as np

noisy_img = cv2.imread("noisy-street.png")
clean = cv2.medianBlur(
    noisy_img,
    5
)
gray = cv2.cvtColor(noisy_img, cv2.COLOR_BGR2GRAY)
print("dots before:", np.count_nonzero((gray == 0) | (gray == 255)))
gray = cv2.cvtColor(clean, cv2.COLOR_BGR2GRAY)
print("dots after:", np.count_nonzero((gray == 0) | (gray == 255)))
cv2.imshow("Noisy Image", noisy_img)
cv2.imshow("Cleaner Image", clean)
cv2.waitKey(0)
cv2.destroyAllWindows()', 'python', 0, '', 'dots before: 9192
dots after: 0
', '{"notes":[{"line":5,"match":"medianBlur","text":"middle value of 5 × 5","shape":"circle","color":"sky"},{"line":7,"match":"5","text":"one number: always square","shape":"square","color":"yel"},{"line":10,"match":"count_nonzero","text":"count black or white pixels","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_79da4b136617d831', 'course_computer_vision', 'les_e0c31345b781f8a8', 'diagram', 'Noisy and cleaner', '`medianBlur` takes a single number, the kernel size (odd, and the kernel is always square). Every one of the 9,192 dots is gone, because each dot is an extreme value in its neighbourhood. **The median blur works very well with salt-and-pepper noise.** The price: a 5 × 5 median also smooths away small details, such as the letters on the STOP sign. `cv2.medianBlur(noisy_img, 3)` keeps more detail; try both.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_e0c31345b781f8a8/cv-median.png', 'Two windows. Noisy Image shows the street covered in white and black dots. Cleaner Image shows the same street with no dots at all; it is softer, and small details such as the STOP letters and the grass texture are smoothed away', 1368, 447, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_327370965087a1bc', 'course_computer_vision', 'les_e0c31345b781f8a8', 'code', 'Which filter helps most?', 'We can measure it. `noisy-street.png` was made from `street.png`, so we can rebuild the clean version and check how far each result is from it. `cv2.absdiff` gives the difference of every value; its average is the **average error**: smaller is better.', 'import cv2

clean = cv2.resize(cv2.imread("street.png"), (640, 360), interpolation=cv2.INTER_AREA)
noisy = cv2.imread("noisy-street.png")

average = cv2.blur(noisy, (5, 5))
gaussian = cv2.GaussianBlur(noisy, (5, 5), 0)
median = cv2.medianBlur(noisy, 5)

for name, result in [("noisy", noisy), ("average", average), ("gaussian", gaussian), ("median", median)]:
    error = cv2.absdiff(result, clean).mean()
    print(name, round(error, 1))', 'python', 0, '', 'noisy 5.1
average 8.2
gaussian 7.0
median 2.8
', '{"notes":[{"line":3,"match":"cv2.resize","text":"the clean 640 × 360 version","shape":"circle","color":"sky"},{"line":6,"match":"cv2.blur","text":"average filter","shape":"square","color":"yel"},{"line":11,"match":"absdiff","text":"difference per value","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 12, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a9fd1e948dff6724', 'course_computer_vision', 'les_e0c31345b781f8a8', 'diagram', 'Four results side by side', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_e0c31345b781f8a8/cv-filters.png', 'Four close-ups of the noisy street image. Original: sharp, with white and black dots. Average: blurry, with grey smudges where the dots were. Gaussian: a little sharper than the average, still with smudges. Median: clean, with no dots and sharp edges', 1044, 744, 13, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_adda2ea81ebbb603', 'course_computer_vision', 'les_e0c31345b781f8a8', 'explanation', 'Reading the results', 'The average and Gaussian filters made the image **worse** than doing nothing (8.2 and 7.0 against 5.1). They blur the real details and smear every dot into a smudge instead of removing it. The median filter more than halves the error (2.8).

That doesn''t make the median the best filter for everything. Real camera noise is usually **many small changes** on every pixel rather than a few extreme dots, and for that kind a Gaussian blur works well and is fast. Pick the filter for the noise you have:

| Noise | Good choice |
|---|---|
| salt and pepper (isolated black and white dots) | `cv2.medianBlur` |
| fine grain on every pixel | `cv2.GaussianBlur` |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 14, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5038ae48402f8e2c', 'course_computer_vision', 'les_e0c31345b781f8a8', 'note', 'Check yourself', '::: check What does `cv2.GaussianBlur(img, (4, 4), 0)` do?
???
It stops with an error: the kernel size must be **odd**, such as (3, 3) or (5, 5), so that the kernel has a centre pixel.
:::

::: check Five neighbours have the values 10, 200, 12, 11, 13. What is their median, and what is their average?
???
Sorted: 10, 11, **12**, 13, 200, so the median is **12**. The average is 246 ÷ 5 = **49.2**, dragged up by the 200.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 15, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_9ea9b5c01ebf359c', 'course_computer_vision', 'les_e0c31345b781f8a8', 'common_mistakes', 'Common mistakes', '- **Even kernel sizes.** `(4, 4)` or `medianBlur(img, 4)` stop with an error. Use odd numbers.
- **Too much blur.** A `(15, 15)` kernel removes noise and the details you wanted to keep. Use the smallest kernel that works.
- **Using an average blur on salt and pepper.** It turns dots into smudges. Use the median.
- **Passing a tuple to medianBlur.** `cv2.medianBlur(img, (5, 5))` is an error: it takes one number.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 16, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_127762623b90d7a4', 'course_computer_vision', 'les_e0c31345b781f8a8', 'key_takeaways', 'Key takeaways', '- Blurring makes each pixel more like its neighbours and removes small noise.
- `cv2.GaussianBlur(img, (k, k), 0)`: a larger odd `k` gives more blur.
- Average and Gaussian filters compute a (weighted) mean; the median filter picks the middle value.
- `cv2.medianBlur(img, 5)` removes salt-and-pepper noise almost completely.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 17, 1792022400000);
DELETE FROM search_index WHERE course_id = 'course_computer_vision' AND entity_type = 'lesson' AND entity_id = 'les_e0c31345b781f8a8';
INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'lesson', 'les_e0c31345b781f8a8', '/courses/computer-vision/lectures/smoothing-and-noise', 'Blurring and removing noise', 'Smooth an image with a Gaussian blur, compare the average, Gaussian and median filters, and remove salt-and-pepper noise with a median blur. Measure which filter really helps. Blur an image with cv2.GaussianBlur and choose a kernel size Explain how a filter computes each new pixel from its neighbours Compare cv2.blur, cv2.GaussianBlur and cv2.medianBlur on a noisy image Remove salt-and-pepper noise with cv2.medianBlur Image smoothing Blurring (or smoothing) makes each pixel more like its neighbours. Small details and small random changes fade, while large shapes stay. Why would we want a blurrier image? Because cameras add noise : unwanted random changes in pixel values, especially in dim light. Noise confuses later steps; for example, an edge detector reports every noisy speck as an edge. A little blur before those steps removes most of it. Step 7: a Gaussian blur import cv2 img = cv2.imread("street.png") blur = cv2.GaussianBlur( img, (5, 5), 0 ) cv2.imshow("Original", img) cv2.imshow("Blurred", blur) cv2.waitKey(0) cv2.destroyAllWindows() What the arguments mean Argument Meaning --- --- img the image to blur (5, 5) the kernel size : each new pixel is computed from a 5 × 5 square of neighbours around it 0 how widely the weights spread (sigma); 0 tells OpenCV to calculate it from the kernel size The kernel width and height must be odd (3, 5, 7…), so the kernel has a centre pixel. Try (3, 3) , (5, 5) and (15, 15) : a larger kernel gives more blur . Kernel sizes (3, 3), (5, 5) and (15, 15) These are close-ups of the top-left part of the image, enlarged so you can see the difference. How a filter computes a pixel All three smoothing filters in this lecture slide a small window (the kernel) over the image. For every pixel, they look at the pixel and its neighbours, and compute one new value: Filter Code New value --- --- --- Average cv2.blur(img, (5, 5)) the plain average of the 25 neighbours Gaussian cv2.GaussianBlur(img, (5, 5), 0) a weighted average: near neighbours count more than far ones Median cv2.medianBlur(img, 5) the middle value after sorting the 25 neighbours The median is different from the other two: it doesn''t calculate a new value, it picks one of the existing ones. That matters a lot for some kinds of noise. Average or median? Try it on 9 numbers This program runs in your browser. The nine numbers are a 3 × 3 patch of a grey area (values near 13) hit by one white dot (255) and one black dot (0). import statistics patch = [12, 14, 13, 15, 255, 11, 0, 14, 13] print("average:", round(sum(patch) / len(patch), 1)) print("median:", statistics.median(patch)) Why the median wins here Sorted, the nine values are 0, 11, 12, 13, 13 , 14, 14, 15, 255. The median is the fifth one, 13 : a normal grey value. The two extreme values sit at the ends of the sorted list and are simply ignored. The average adds everything up, so the single 255 drags it to 38.6 , nearly three times too bright. An average filter doesn''t remove a white dot; it spreads it into a lighter smudge. Image noise: salt and pepper Noise = unwanted random pixels. One common kind is salt-and-pepper noise : random pixels turned pure white (salt) or pure black (pepper), for example by a faulty sensor or transmission errors. The next image has it: 4% of its pixels are salt or pepper. The noisy image This is noisy-street.png . Download it to run the next two programs. Removing salt and pepper with a median blur import cv2 import numpy as np noisy_img = cv2.imread("noisy-street.png") clean = cv2.medianBlur( noisy_img, 5 ) gray = cv2.cvtColor(noisy_img, cv2.COLOR_BGR2GRAY) print("dots before:", np.count_nonzero((gray == 0) | (gray == 255))) gray = cv2.cvtColor(clean, cv2.COLOR_BGR2GRAY) print("dots after:", np.count_nonzero((gray == 0) | (gray == 255))) cv2.imshow("Noisy Image", noisy_img) cv2.imshow("Cleaner Image", clean) cv2.waitKey(0) cv2.destroyAllWindows() Noisy and cleaner medianBlur takes a single number, the kernel size (odd, and the kernel is always square). Every one of the 9,192 dots is gone, because each dot is an extreme value in its neighbourhood. The median blur works very well with salt-and-pepper noise. The price: a 5 × 5 median also smooths away small details, such as the letters on the STOP sign. cv2.medianBlur(noisy img, 3) keeps more detail; try both. Which filter helps most? We can measure it. noisy-street.png was made from street.png , so we can rebuild the clean version and check how far each result is from it. cv2.absdiff gives the difference of every value; its average is the average error : smaller is better. import cv2 clean = cv2.resize(cv2.imread("street.png"), (640, 360), interpolation=cv2.INTER_AREA) noisy = cv2.imread("noisy-street.png") average = cv2.blur(noisy, (5, 5)) gaussian = cv2.GaussianBlur(noisy, (5, 5), 0) median = cv2.medianBlur(noisy, 5) for name, result in [("noisy", noisy), ("average", average), ("gaussian", gaussian), ("median", median)]: error = cv2.absdiff(result, clean).mean() print(name, round(error, 1)) Four results side by side Reading the results The average and Gaussian filters made the image worse than doing nothing (8.2 and 7.0 against 5.1). They blur the real details and smear every dot into a smudge instead of removing it. The median filter more than halves the error (2.8). That doesn''t make the median the best filter for everything. Real camera noise is usually many small changes on every pixel rather than a few extreme dots, and for that kind a Gaussian blur works well and is fast. Pick the filter for the noise you have: Noise Good choice --- --- salt and pepper (isolated black and white dots) cv2.medianBlur fine grain on every pixel cv2.GaussianBlur Check yourself It stops with an error: the kernel size must be odd , such as (3, 3) or (5, 5), so that the kernel has a centre pixel. Sorted: 10, 11, 12 , 13, 200, so the median is 12 . The average is 246 ÷ 5 = 49.2 , dragged up by the 200. Common mistakes - Even kernel sizes. (4, 4) or medianBlur(img, 4) stop with an error. Use odd numbers. - Too much blur. A (15, 15) kernel removes noise and the details you wanted to keep. Use the smallest kernel that works. - Using an average blur on salt and pepper. It turns dots into smudges. Use the median. - Passing a tuple to medianBlur. cv2.medianBlur(img, (5, 5)) is an error: it takes one number. Key takeaways - Blurring makes each pixel more like its neighbours and removes small noise. - cv2.GaussianBlur(img, (k, k), 0) : a larger odd k gives more blur. - Average and Gaussian filters compute a (weighted) mean; the median filter picks the middle value. - cv2.medianBlur(img, 5) removes salt-and-pepper noise almost completely.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_4fe7de1a048935ac', 'course_computer_vision', 'top_f8a91881121beec6', 'sharpening-images', 'Sharpening images with a kernel', 'Make edges and details clearer with a sharpening kernel and cv2.filter2D. Work out by hand what the kernel does to a row of pixels, then sharpen the street image.', 2, 9, 'medium', '["Explain what a kernel is and how it computes each new pixel","Sharpen an image with cv2.filter2D and a 3 × 3 kernel","Calculate the effect of the sharpening kernel on a small row of values","Explain why sharpening also makes noise stronger"]', '["Blurring and removing noise"]', 5, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_4fe7de1a048935ac';
DELETE FROM lesson_relations WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_4fe7de1a048935ac';
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_346866f4a7a3011e', 'course_computer_vision', 'les_4fe7de1a048935ac', 'explanation', 'Sharpening: the opposite of blurring', 'Blurring makes each pixel **more** like its neighbours. **Sharpening** makes each pixel **less** like its neighbours, so edges and details become clearer.

Both are done the same way: with a **kernel**, a small grid of numbers. **The kernel tells OpenCV how neighbouring pixels affect the new pixel.** This is the sharpening kernel from the lab:

| | left | centre | right |
|---|---|---|---|
| **above** | 0 | -1 | 0 |
| **middle** | -1 | **5** | -1 |
| **below** | 0 | -1 | 0 |

For every pixel, OpenCV multiplies the pixel and its neighbours by these numbers and adds the results:

**new = 5 × centre − above − below − left − right**', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e91fef8046e3f47d', 'course_computer_vision', 'les_4fe7de1a048935ac', 'code', 'Step 9: sharpen the image', '', 'import cv2
import numpy as np

img = cv2.imread("street.png")
kernel = np.array([
    [ 0, -1,  0],
    [-1,  5, -1],
    [ 0, -1,  0]
])
sharp = cv2.filter2D(
    img, -1, kernel
)
cv2.imshow("Original", img)
cv2.imshow("Sharpened", sharp)
cv2.waitKey(0)
cv2.destroyAllWindows()', 'python', 0, '', NULL, '{"notes":[{"line":2,"match":"numpy as np","text":"to build the kernel","shape":"circle","color":"sky"},{"line":6,"match":"-1","text":"each neighbour counts × -1","shape":"tri","color":"coral"},{"line":7,"match":"5","text":"the centre pixel counts × 5","shape":"square","color":"yel"},{"line":10,"match":"filter2D","text":"apply any kernel","shape":"diamond","color":"green"},{"line":11,"match":"-1","text":"same type as img","shape":"circle","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3acb96a3acee2409', 'course_computer_vision', 'les_4fe7de1a048935ac', 'diagram', 'Original and sharper', '`cv2.filter2D(img, -1, kernel)` applies any kernel you give it. The `-1` means "make the result the same type as the input", so a `uint8` image stays `uint8` and the results are kept between 0 and 255.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_4fe7de1a048935ac/cv-sharpen.png', 'Close-ups of a building''s windows and the car, before and after sharpening. In the sharpened version the window edges and the car''s outline are crisper, and the small stones on the road and the grass blades stand out more', 1044, 912, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_9a50923ee1400fa9', 'course_computer_vision', 'les_4fe7de1a048935ac', 'code', 'What the kernel does to an edge', 'A tiny image makes the calculation easy to follow: three identical rows, dark (50) on the left and bright (200) on the right.', 'import cv2
import numpy as np

row = np.array([[50, 50, 50, 50, 200, 200, 200, 200]] * 3, dtype=np.uint8)
kernel = np.array([[0, -1, 0], [-1, 5, -1], [0, -1, 0]])
sharp = cv2.filter2D(row, -1, kernel)
print(row[1])
print(sharp[1])', 'python', 0, '', '[ 50  50  50  50 200 200 200 200]
[ 50  50  50   0 255 200 200 200]
', '{"notes":[{"line":4,"match":"* 3","text":"three equal rows","shape":"circle","color":"sky"},{"line":7,"match":"row[1]","text":"the middle row","shape":"square","color":"yel"},{"line":8,"match":"sharp[1]","text":"after sharpening","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f05f232ba87eb68e', 'course_computer_vision', 'les_4fe7de1a048935ac', 'explanation', 'Following the numbers', 'Take the middle row. The rows above and below are the same, so "above" and "below" equal the centre.

| Pixel | Calculation | Result | Stored |
|---|---|---|---|
| a 50 far from the edge | 5 × 50 − 50 − 50 − 50 − 50 | 50 | 50 |
| the last 50 (right neighbour 200) | 5 × 50 − 50 − 50 − 50 − 200 | −100 | **0** |
| the first 200 (left neighbour 50) | 5 × 200 − 200 − 200 − 50 − 200 | 350 | **255** |
| a 200 far from the edge | 5 × 200 − 200 − 200 − 200 − 200 | 200 | 200 |

Two things to notice:

- In **flat areas nothing changes**, because the kernel''s numbers add up to 1 (5 − 4 = 1).
- **At the edge**, the dark side gets darker and the bright side gets brighter. That extra jump is what our eyes see as "sharper". (−100 and 350 are kept between 0 and 255.)', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0b9d0e1020141d2a', 'course_computer_vision', 'les_4fe7de1a048935ac', 'explanation', 'Sharpening makes noise stronger too', 'The kernel can''t tell a real edge from a noisy speck: both are pixels that differ from their neighbours, and both get stronger. Look at the road''s stones and the grass in the close-up: they stand out more after sharpening.

So **remove noise first, sharpen second**, and never sharpen a noisy image on its own.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3985e067e58fe66b', 'course_computer_vision', 'les_4fe7de1a048935ac', 'note', 'Check yourself', '::: check A flat grey area has every pixel equal to 90. What does the sharpening kernel turn it into?
???
**90**: 5 × 90 − 4 × 90 = 90. The kernel''s numbers add up to 1, so flat areas don''t change.
:::

::: check Why is the blur kernel in the last lesson never negative, but this one has −1s?
???
A blur takes a (weighted) **average** of the neighbours, so all its weights are positive. Sharpening **subtracts** the neighbours from the centre to make the differences bigger, so it needs negative weights.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b8ed2e96e0038be1', 'course_computer_vision', 'les_4fe7de1a048935ac', 'common_mistakes', 'Common mistakes', '- **Forgetting `import numpy as np`.** The kernel is a NumPy array; without the import, `np.array` is a `NameError`.
- **Weights that don''t add up to 1.** With a centre of 6 instead of 5, flat areas get brighter too. Check the sum.
- **Sharpening a noisy image.** The noise gets louder. Denoise first.
- **Sharpening many times.** Each pass pushes edges further towards 0 and 255; the image soon looks harsh, with bright halos.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_8daaf00ef6e74dff', 'course_computer_vision', 'les_4fe7de1a048935ac', 'key_takeaways', 'Key takeaways', '- A **kernel** says how each neighbour affects the new pixel; `cv2.filter2D(img, -1, kernel)` applies it.
- The sharpening kernel computes 5 × centre − the 4 neighbours.
- Flat areas stay the same; at edges, dark gets darker and bright gets brighter.
- Sharpening strengthens noise as well, so denoise before you sharpen.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1792022400000);
