INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'lesson', 'les_4fe7de1a048935ac', '/courses/computer-vision/lectures/sharpening-images', 'Sharpening images with a kernel', 'Make edges and details clearer with a sharpening kernel and cv2.filter2D. Work out by hand what the kernel does to a row of pixels, then sharpen the street image. Explain what a kernel is and how it computes each new pixel Sharpen an image with cv2.filter2D and a 3 × 3 kernel Calculate the effect of the sharpening kernel on a small row of values Explain why sharpening also makes noise stronger Sharpening: the opposite of blurring Blurring makes each pixel more like its neighbours. Sharpening makes each pixel less like its neighbours, so edges and details become clearer. Both are done the same way: with a kernel , a small grid of numbers. The kernel tells OpenCV how neighbouring pixels affect the new pixel. This is the sharpening kernel from the lab: left centre right --- --- --- --- above 0 -1 0 middle -1 5 -1 below 0 -1 0 For every pixel, OpenCV multiplies the pixel and its neighbours by these numbers and adds the results: new = 5 × centre − above − below − left − right Step 9: sharpen the image import cv2 import numpy as np img = cv2.imread("street.png") kernel = np.array([ [ 0, -1, 0], [-1, 5, -1], [ 0, -1, 0] ]) sharp = cv2.filter2D( img, -1, kernel ) cv2.imshow("Original", img) cv2.imshow("Sharpened", sharp) cv2.waitKey(0) cv2.destroyAllWindows() Original and sharper cv2.filter2D(img, -1, kernel) applies any kernel you give it. The -1 means "make the result the same type as the input", so a uint8 image stays uint8 and the results are kept between 0 and 255. What the kernel does to an edge A tiny image makes the calculation easy to follow: three identical rows, dark (50) on the left and bright (200) on the right. import cv2 import numpy as np row = np.array([[50, 50, 50, 50, 200, 200, 200, 200]] * 3, dtype=np.uint8) kernel = np.array([[0, -1, 0], [-1, 5, -1], [0, -1, 0]]) sharp = cv2.filter2D(row, -1, kernel) print(row[1]) print(sharp[1]) Following the numbers Take the middle row. The rows above and below are the same, so "above" and "below" equal the centre. Pixel Calculation Result Stored --- --- --- --- a 50 far from the edge 5 × 50 − 50 − 50 − 50 − 50 50 50 the last 50 (right neighbour 200) 5 × 50 − 50 − 50 − 50 − 200 −100 0 the first 200 (left neighbour 50) 5 × 200 − 200 − 200 − 50 − 200 350 255 a 200 far from the edge 5 × 200 − 200 − 200 − 200 − 200 200 200 Two things to notice: - In flat areas nothing changes , because the kernel''s numbers add up to 1 (5 − 4 = 1). - At the edge , the dark side gets darker and the bright side gets brighter. That extra jump is what our eyes see as "sharper". (−100 and 350 are kept between 0 and 255.) Sharpening makes noise stronger too The kernel can''t tell a real edge from a noisy speck: both are pixels that differ from their neighbours, and both get stronger. Look at the road''s stones and the grass in the close-up: they stand out more after sharpening. So remove noise first, sharpen second , and never sharpen a noisy image on its own. Check yourself 90 : 5 × 90 − 4 × 90 = 90. The kernel''s numbers add up to 1, so flat areas don''t change. A blur takes a (weighted) average of the neighbours, so all its weights are positive. Sharpening subtracts the neighbours from the centre to make the differences bigger, so it needs negative weights. Common mistakes - Forgetting import numpy as np . The kernel is a NumPy array; without the import, np.array is a NameError . - Weights that don''t add up to 1. With a centre of 6 instead of 5, flat areas get brighter too. Check the sum. - Sharpening a noisy image. The noise gets louder. Denoise first. - Sharpening many times. Each pass pushes edges further towards 0 and 255; the image soon looks harsh, with bright halos. Key takeaways - A kernel says how each neighbour affects the new pixel; cv2.filter2D(img, -1, kernel) applies it. - The sharpening kernel computes 5 × centre − the 4 neighbours. - Flat areas stay the same; at edges, dark gets darker and bright gets brighter. - Sharpening strengthens noise as well, so denoise before you sharpen.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_9e2de7522d4f2b45', 'course_computer_vision', 'top_ed5ce0c87ecbac13', 'histogram-equalization', 'Improving contrast automatically', 'Read an image''s histogram, see why a low-contrast image has its values bunched together, and spread them out automatically with histogram equalization.', 2, 10, 'medium', '["Explain what an image histogram shows","Recognise a low-contrast image from its histogram and its minimum and maximum values","Improve contrast automatically with cv2.equalizeHist","Say why equalization works on grayscale images and what it can''t do"]', '["Colour to grayscale","Brightness and contrast"]', 4, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_9e2de7522d4f2b45';
DELETE FROM lesson_relations WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_9e2de7522d4f2b45';
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_bad2e8dad6e5aea9', 'course_computer_vision', 'les_9e2de7522d4f2b45', 'explanation', 'What is a histogram?', 'An image''s **histogram** counts how many pixels have each value: how many are 0, how many are 1, and so on up to 255. Drawn as a bar chart, it shows at a glance how the brightness is spread:

| Histogram shape | The image looks… |
|---|---|
| bars bunched on the **left** | dark |
| bars bunched on the **right** | bright |
| bars bunched in a **narrow** band | flat, low contrast (foggy, washed out) |
| bars spread **across the whole range** | good contrast |

In the last lessons you changed contrast by hand with alpha and beta. **Histogram equalization** does it automatically: it spreads the values so they use the whole range from 0 to 255.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e488b205fe47fc12', 'course_computer_vision', 'les_9e2de7522d4f2b45', 'code', 'Step 10: histogram equalization', 'To have a low-contrast image to fix, the program first makes one: it squeezes the street''s grey values into a narrow band, like a photo taken in fog.', 'import cv2

img = cv2.imread("street.png")
gray = cv2.cvtColor(
    img,
    cv2.COLOR_BGR2GRAY
)
foggy = cv2.convertScaleAbs(gray, alpha=0.3, beta=100)
equalized = cv2.equalizeHist(foggy)
print("before:", foggy.min(), "to", foggy.max())
print("after:", equalized.min(), "to", equalized.max())
cv2.imshow("Original", foggy)
cv2.imshow("Equalized", equalized)
cv2.waitKey(0)
cv2.destroyAllWindows()', 'python', 0, '', 'before: 100 to 175
after: 0 to 255
', '{"notes":[{"line":4,"match":"cvtColor","text":"grayscale first","shape":"circle","color":"sky"},{"line":8,"match":"alpha=0.3, beta=100","text":"squeeze: a foggy copy","shape":"tri","color":"coral"},{"line":9,"match":"equalizeHist","text":"spread the values","shape":"square","color":"yel"},{"line":10,"match":"foggy.min()","text":"darkest value","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a84afd91a28a83ae', 'course_computer_vision', 'les_9e2de7522d4f2b45', 'diagram', 'Before and after, with their histograms', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_9e2de7522d4f2b45/cv-equalize.png', 'Two grayscale versions of the street scene with their histograms underneath. Before: a flat, foggy image whose histogram bars all sit between 100 and 175. After equalization: a high-contrast image with black windows, a dark, strongly textured road, light bands in the sky and white lane lines, whose histogram bars spread from 0 to 255', 1048, 608, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_4cc1b205c83276b4', 'course_computer_vision', 'les_9e2de7522d4f2b45', 'explanation', 'What changed', 'Before, every pixel was between **100 and 175**: only 76 possible greys, all of them medium, so everything looked grey and foggy. After equalization the values run from **0 to 255**: the darkest parts are black, the brightest are white, and the details in between are easier to see. Look at the grass and the road too: equalization made their texture much stronger, and the smooth sky now shows bands. It spreads whatever is there, wanted or not.

Equalization is **automatic**: you don''t choose alpha and beta. It looks at the histogram and moves crowded values apart and rare values together, so that, roughly, every brightness level is used about equally often.

**It spreads pixel intensities to improve contrast.** Low-contrast input becomes much clearer.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d55df6130eb152f1', 'course_computer_vision', 'les_9e2de7522d4f2b45', 'explanation', 'What equalization can''t do', '- **It can''t add detail.** It only moves existing values. Two pixels that had the same value still have the same value afterwards (in fact some neighbouring levels get merged).
- **It works on one channel.** `cv2.equalizeHist()` needs a grayscale (8-bit, single-channel) image. A colour image gives an error, which is why the program converts to grayscale first.
- **It can overdo it.** On an image that already has good contrast it may make noise or flat areas look harsh. Use it when the histogram is bunched.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b630e242df02bcb3', 'course_computer_vision', 'les_9e2de7522d4f2b45', 'note', 'Check yourself', '::: check A grayscale image has `img.min()` equal to 30 and `img.max()` equal to 60. Does it need more contrast?
???
**Yes.** All its values sit in a band only 31 greys wide (30 to 60), so it is very dark **and** flat. Its histogram is a narrow spike on the left; equalization would spread it over 0 to 255.
:::

::: check What happens with `cv2.equalizeHist(img)` when `img` was read in colour?
???
OpenCV stops with an error (an assertion that the input is a single-channel 8-bit image). Convert first: `gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)`.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_db7ed4e8f04803ce', 'course_computer_vision', 'les_9e2de7522d4f2b45', 'common_mistakes', 'Common mistakes', '- **Passing a colour image.** `equalizeHist` needs grayscale.
- **Expecting new detail.** Equalization spreads values; it can''t recover detail that was never captured.
- **Equalizing a noisy image.** Spreading the values also spreads the noise. Denoise first; the pipeline in the next lesson does exactly that.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_915c1c29e28db8dd', 'course_computer_vision', 'les_9e2de7522d4f2b45', 'key_takeaways', 'Key takeaways', '- A histogram counts the pixels at each brightness from 0 to 255.
- Low contrast means the histogram is bunched in a narrow band.
- `cv2.equalizeHist(gray)` spreads the values over the whole range automatically.
- It needs a grayscale image and works best on flat, foggy or dull images.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1792022400000);
DELETE FROM search_index WHERE course_id = 'course_computer_vision' AND entity_type = 'lesson' AND entity_id = 'les_9e2de7522d4f2b45';
INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'lesson', 'les_9e2de7522d4f2b45', '/courses/computer-vision/lectures/histogram-equalization', 'Improving contrast automatically', 'Read an image''s histogram, see why a low-contrast image has its values bunched together, and spread them out automatically with histogram equalization. Explain what an image histogram shows Recognise a low-contrast image from its histogram and its minimum and maximum values Improve contrast automatically with cv2.equalizeHist Say why equalization works on grayscale images and what it can''t do What is a histogram? An image''s histogram counts how many pixels have each value: how many are 0, how many are 1, and so on up to 255. Drawn as a bar chart, it shows at a glance how the brightness is spread: Histogram shape The image looks… --- --- bars bunched on the left dark bars bunched on the right bright bars bunched in a narrow band flat, low contrast (foggy, washed out) bars spread across the whole range good contrast In the last lessons you changed contrast by hand with alpha and beta. Histogram equalization does it automatically: it spreads the values so they use the whole range from 0 to 255. Step 10: histogram equalization To have a low-contrast image to fix, the program first makes one: it squeezes the street''s grey values into a narrow band, like a photo taken in fog. import cv2 img = cv2.imread("street.png") gray = cv2.cvtColor( img, cv2.COLOR_BGR2GRAY ) foggy = cv2.convertScaleAbs(gray, alpha=0.3, beta=100) equalized = cv2.equalizeHist(foggy) print("before:", foggy.min(), "to", foggy.max()) print("after:", equalized.min(), "to", equalized.max()) cv2.imshow("Original", foggy) cv2.imshow("Equalized", equalized) cv2.waitKey(0) cv2.destroyAllWindows() Before and after, with their histograms What changed Before, every pixel was between 100 and 175 : only 76 possible greys, all of them medium, so everything looked grey and foggy. After equalization the values run from 0 to 255 : the darkest parts are black, the brightest are white, and the details in between are easier to see. Look at the grass and the road too: equalization made their texture much stronger, and the smooth sky now shows bands. It spreads whatever is there, wanted or not. Equalization is automatic : you don''t choose alpha and beta. It looks at the histogram and moves crowded values apart and rare values together, so that, roughly, every brightness level is used about equally often. It spreads pixel intensities to improve contrast. Low-contrast input becomes much clearer. What equalization can''t do - It can''t add detail. It only moves existing values. Two pixels that had the same value still have the same value afterwards (in fact some neighbouring levels get merged). - It works on one channel. cv2.equalizeHist() needs a grayscale (8-bit, single-channel) image. A colour image gives an error, which is why the program converts to grayscale first. - It can overdo it. On an image that already has good contrast it may make noise or flat areas look harsh. Use it when the histogram is bunched. Check yourself Yes. All its values sit in a band only 31 greys wide (30 to 60), so it is very dark and flat. Its histogram is a narrow spike on the left; equalization would spread it over 0 to 255. OpenCV stops with an error (an assertion that the input is a single-channel 8-bit image). Convert first: gray = cv2.cvtColor(img, cv2.COLOR BGR2GRAY) . Common mistakes - Passing a colour image. equalizeHist needs grayscale. - Expecting new detail. Equalization spreads values; it can''t recover detail that was never captured. - Equalizing a noisy image. Spreading the values also spreads the noise. Denoise first; the pipeline in the next lesson does exactly that. Key takeaways - A histogram counts the pixels at each brightness from 0 to 255. - Low contrast means the histogram is bunched in a narrow band. - cv2.equalizeHist(gray) spreads the values over the whole range automatically. - It needs a grayscale image and works best on flat, foggy or dull images.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_112ebfc8b5df2c05', 'course_computer_vision', 'top_ed5ce0c87ecbac13', 'enhancement-pipeline-and-challenge', 'An enhancement pipeline and the "fix this image" challenge', 'Chain the steps of this lecture into one small enhancement pipeline, then fix a dark, flat and noisy image yourself. Ends with a summary of every OpenCV function from the lecture.', 2, 11, 'medium', '["Build a pipeline that reads, converts, resizes, denoises and enhances an image","Explain why the order of the steps matters","Diagnose an image''s problems and choose OpenCV functions to fix them","Show an original and an enhanced image side by side with np.hstack"]', '["Improving contrast automatically","Blurring and removing noise"]', 6, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_112ebfc8b5df2c05';
