INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'lesson', 'les_112ebfc8b5df2c05', '/courses/computer-vision/lectures/enhancement-pipeline-and-challenge', 'An enhancement pipeline and the "fix this image" challenge', 'Chain the steps of this lecture into one small enhancement pipeline, then fix a dark, flat and noisy image yourself. Ends with a summary of every OpenCV function from the lecture. Build a pipeline that reads, converts, resizes, denoises and enhances an image Explain why the order of the steps matters Diagnose an image''s problems and choose OpenCV functions to fix them Show an original and an enhanced image side by side with np.hstack Putting the steps together Each step of this lecture does one job. Real programs chain them into a pipeline , where the output of one step is the input of the next: Image → Grayscale → Resize → Denoise → Enhance contrast → Result This is step 2 of the computer vision pipeline from the first lecture, "image processing": preparing an image so the later steps (finding features, recognising objects) have the best possible input. A small enhancement pipeline import cv2 img = cv2.imread("street.png") gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY) resized = cv2.resize(gray, (640, 480)) blur = cv2.GaussianBlur(resized, (5, 5), 0) enhanced = cv2.equalizeHist(blur) print(img.shape, "->", enhanced.shape) cv2.imshow("Original", img) cv2.imshow("Enhanced", enhanced) cv2.waitKey(0) cv2.destroyAllWindows() Each stage of the pipeline Why this order? - Grayscale first : every later step then works on one channel instead of three, so it is faster. equalizeHist needs grayscale anyway. - Resize early : the blur and the equalization then process 307,200 pixels instead of 518,400. - Denoise before enhancing : equalization spreads values apart, and would make noise more visible if it were still there. Notice that each line uses the previous line''s variable: gray goes into resize , resized goes into GaussianBlur , and so on. A typo such as cv2.GaussianBlur(gray, …) silently skips the resize step. Lab challenge: fix this image! The image below is a poor-quality version of the street. Its problems: - low brightness : it is too dark; - low contrast : everything is a similar dull grey-green; - some noise : grain on every pixel, and black and white dots. You may use cv2.cvtColor() , cv2.resize() , cv2.convertScaleAbs() , cv2.GaussianBlur() , cv2.medianBlur() and cv2.equalizeHist() . Produce Original VS Enhanced , side by side. There is no single correct solution: experiment! The poor-quality image This is poor-street.png . Download it, and try the challenge yourself before reading on. Diagnose first Before changing anything, measure. Two quick checks help: print(img.mean()) print(img.min(), img.max()) The average is about 81, so the image is dark (the clean street averages 150). But min() and max() say 0 and 255 , which looks like full contrast. It isn''t: the salt-and-pepper dots are 0 and 255 and hide the real range. Remove the dots first, then measure again. One possible solution import cv2 import numpy as np img = cv2.imread("poor-street.png") clean = cv2.medianBlur(img, 5) print("range after median:", clean.min(), "to", clean.max()) enhanced = cv2.convertScaleAbs(clean, alpha=2.2, beta=-25) print("average before:", round(img.mean(), 1)) print("average after:", round(enhanced.mean(), 1)) both = np.hstack([img, enhanced]) cv2.imshow("Original VS Enhanced", both) cv2.waitKey(0) cv2.destroyAllWindows() Original VS Enhanced How the numbers were chosen 1. Noise first. A median blur removes the black and white dots (and smooths the grain). Now the real range shows: 22 to 132 , only 110 levels wide and all in the dark half. 2. Contrast: alpha. To spread 110 levels over most of 0 to 255, multiply by about 240 ÷ 110 ≈ 2.2 . 3. Brightness: beta. 2.2 × 22 ≈ 48, so the darkest pixels would land at 48. A beta of −25 moves them down to about 23. The brightest become 2.2 × 132 − 25 = 265, so a few of them stop at 255, which is acceptable. The average went from 80.6 to 150.4, close to the clean street''s 150. Your own solution may use different steps, for example grayscale and equalizeHist instead of alpha and beta, or a Gaussian blur after the median. Compare the results side by side and decide which looks best. What did we learn? Step Function --- --- Read an image cv2.imread() Grayscale cv2.cvtColor() Resize cv2.resize() Brightness and contrast cv2.convertScaleAbs() Denoise cv2.GaussianBlur() , cv2.medianBlur() Sharpen cv2.filter2D() Contrast enhancement cv2.equalizeHist() Next lab: feature detection and matching. We improved the image… now how can the computer find the important features inside it? Check yourself The blur works on gray , not on resized , so the resize step is skipped: enhanced comes out 960 × 540 instead of 640 × 480. No error appears; only the shape tells you. Common mistakes - Using the wrong variable. Each step must take the previous step''s result. - Enhancing before denoising. Brightening or equalizing a noisy image makes the noise stronger. - Trusting min() and max() on noisy images. A few extreme dots hide the real range; denoise, then measure. - np.hstack with different sizes or channels. Both images need the same height and the same number of channels, so don''t stack a grayscale result next to a colour original without converting it. Key takeaways - A pipeline chains steps: grayscale → resize → denoise → enhance. - Order matters: denoise before you enhance, and resize early to save work. - Diagnose an image (average, real range) before choosing a fix. - np.hstack([a, b]) shows an original and a result side by side.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_442fa32aab5eb1bb', 'course_computer_vision', 'top_fa0401151f7ab2ba', 'features-and-edges', 'Features, edges and the Canny detector', 'Find out what makes a part of an image a good feature, tell flat regions, edges and corners apart, and find edges with cv2.Canny. Then measure how the two thresholds change the result.', 3, 12, 'medium', '["Define a feature and explain why corners are easier to find again than edges","Name applications that depend on features","Detect edges with cv2.Canny on a grayscale image","Predict and measure the effect of Canny''s low and high thresholds"]', '["An enhancement pipeline and the \"fix this image\" challenge"]', 6, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_442fa32aab5eb1bb';
DELETE FROM lesson_relations WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_442fa32aab5eb1bb';
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_c6cfd52af78841ea', 'course_computer_vision', 'les_442fa32aab5eb1bb', 'explanation', 'From image enhancement to feature detection', 'Last lab ended with an improved image: read, grayscale, resize, denoise, enhance. But **how does the computer know which parts of the image are important?**

Today''s goal: find **useful visual features automatically**. This lecture has two parts. Part 1 is feature detection and matching with OpenCV. Part 2 starts the semester project, a camera-equipped vehicle.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_53dd3003329c888e', 'course_computer_vision', 'les_442fa32aab5eb1bb', 'explanation', 'What is a feature?', '**A feature is a distinctive part of an image that can be detected again**, for example in a second photo of the same place.

Imagine a small window lying on the image, and slide it a few pixels in each direction:

| Region | When the window moves… | Can you find it again? |
|---|---|---|
| **Flat region** (the sky) | nothing changes, in any direction | **hard**: it looks the same everywhere |
| **Edge** (a road line) | it changes **across** the line, not **along** it | **ambiguous**: you know the line, not where on it |
| **Corner** (a window corner) | it changes in **every** direction | **easy**: the position is unique |

**Good features are distinctive.** A detector marks the distinctive locations it finds; each one is called a **keypoint**.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_912df25f59764bd9', 'course_computer_vision', 'les_442fa32aab5eb1bb', 'diagram', 'Flat region, edge and corner', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_442fa32aab5eb1bb/cv-flat-edge-corner.png', 'Three enlarged patches cut from the street image, with every pixel visible. Flat region: plain blue sky. Edge: the white edge line of the road crossing the patch diagonally. Corner: the top-left corner of a dark window in a light building wall', 832, 356, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_23f47f2ec6bd618c', 'course_computer_vision', 'les_442fa32aab5eb1bb', 'explanation', 'Why do we need features?', 'Features are the bridge between raw pixels and understanding: **image → features → understanding**. Almost every advanced computer vision task is built on them:

| Application | What features do there |
|---|---|
| **Image matching** | decide whether two images show the same object |
| **Object recognition** | recognise an object from its typical features |
| **Tracking** | follow the same features from frame to frame |
| **Image stitching** | join photos into a panorama where their features overlap |
| **Visual SLAM** | build a map while working out where the camera is |
| **Robot navigation** | find a path using what the camera sees |
| **Autonomous vehicles** | all of the above, on a moving car: our semester project |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_c1a239ca5e8bb7ff', 'course_computer_vision', 'les_442fa32aab5eb1bb', 'explanation', 'Edges vs corners', 'An **edge** is a **strong change in image intensity**: building borders, road lines, the outline of an object.

A **corner** is where **two or more edges meet**: window corners, the corners of a road sign, building corners.

**Corners are often easier to recognise again**, for the reason in the table above: they change in every direction.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_53bc3c7186a253dc', 'course_computer_vision', 'les_442fa32aab5eb1bb', 'diagram', 'Edges and corners on the street', 'Why are there almost no corners along the long, straight road lines? Because a straight line only changes in **one** direction. Corners appear where two edges meet: the windows, the sign, the car, the snowy peaks.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_442fa32aab5eb1bb/cv-edges-vs-corners.png', 'Two versions of the street scene side by side. Left: the edges found by Canny, light blue lines on dark navy, outlining the buildings, windows, road lines, car, sign, house and tree. Right: the street with 100 red dots at the strongest corners, mostly on the window corners of two of the buildings, with some on the stop sign, the car, the tree, the snowy peaks and stones on the road, and almost none along the long straight road lines', 1236, 440, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ed4ed6e01217ca1d', 'course_computer_vision', 'les_442fa32aab5eb1bb', 'code', 'Finding edges with OpenCV', '', 'import cv2

img = cv2.imread("street.png")
gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
edges = cv2.Canny(gray, 100, 200)
cv2.imshow("Original", img)
cv2.imshow("Edges", edges)
cv2.waitKey(0)
cv2.destroyAllWindows()', 'python', 0, '', NULL, '{"notes":[{"line":4,"match":"cvtColor","text":"edges need brightness only","shape":"circle","color":"sky"},{"line":5,"match":"Canny","text":"find strong changes","shape":"square","color":"yel"},{"line":5,"match":"100, 200","text":"low and high thresholds","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_42cbc9be3014ae1c', 'course_computer_vision', 'les_442fa32aab5eb1bb', 'diagram', 'The Edges window', '**In one sentence: Canny searches for strong changes in pixel intensity.** Its result is a black image (0) with white pixels (255) on the edges.

**Project link:** lane lines, road borders and car outlines are all strong intensity changes, so they show up clearly. That is why edges are the first features our vehicle will use.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_442fa32aab5eb1bb/cv-canny.png', 'Two windows. Original shows the colour street. Edges is black with thin white lines wherever the brightness changes strongly: building outlines and windows, the road''s edge lines and centre dashes, the car, the stop sign, the house and the tree, plus scattered short marks in the grass and on the road', 1288, 425, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_355383e6364e2747', 'course_computer_vision', 'les_442fa32aab5eb1bb', 'explanation', 'The two thresholds', '`cv2.Canny(gray, low, high)` measures how strongly the brightness changes at every pixel, then uses the two numbers:

| Change at a pixel | Result |
|---|---|
| stronger than `high` | an edge, for sure |
| between `low` and `high` | an edge **only if** it connects to a sure edge |
| weaker than `low` | not an edge |

So **lower thresholds → more edges**, including weak ones such as texture. **Higher thresholds → fewer, stronger edges.** A common rule of thumb is to make `high` about **two to three times** `low`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2c5479442dd19c25', 'course_computer_vision', 'les_442fa32aab5eb1bb', 'code', 'Experiment: change the thresholds', 'Start with 100, 200, then change both numbers and run again. This program tries three pairs and measures the share of pixels that Canny marked as edges:', 'import cv2
import numpy as np

img = cv2.imread("street.png")
gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
for low, high in [(50, 100), (100, 200), (150, 250)]:
    edges = cv2.Canny(gray, low, high)
    percent = np.count_nonzero(edges) / edges.size * 100
    print(low, high, round(percent, 1), "% edges")', 'python', 0, '', '50 100 8.9 % edges
100 200 5.4 % edges
150 250 3.8 % edges
', '{"notes":[{"line":6,"match":"for low, high in","text":"three pairs to try","shape":"circle","color":"sky"},{"line":8,"match":"count_nonzero","text":"white pixels = edges","shape":"square","color":"yel"},{"line":8,"match":"edges.size","text":"all pixels","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_fb6b273aee72ae75', 'course_computer_vision', 'les_442fa32aab5eb1bb', 'diagram', 'Three pairs of thresholds', 'With **50, 100**, the grass blades and the road''s small stones fill the image with short marks. With **150, 250**, mostly the strong outlines are left. **Which values work best for your image?** Keep the edges you need and lose the noise. There is no single correct answer: the best values depend on the image and the lighting, which is why we will tune them again on live video in the project.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_442fa32aab5eb1bb/cv-canny-thresholds.png', 'Three close-ups of the bottom of the edge image: the road, the person, the car and the stop sign. 50, 100: 8.9 percent edges, with the grass and road full of short marks from the texture. 100, 200: 5.4 percent, with fewer texture marks. 150, 250: 3.8 percent, mostly clean outlines of the buildings, road lines and car', 1552, 386, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_449fa8d30844e1d7', 'course_computer_vision', 'les_442fa32aab5eb1bb', 'note', 'Check yourself', '::: check Which is easier to find again in a second photo: a point in the middle of a long straight road line, or the corner of a window? Why?
???
**The window corner.** Moving along a straight line looks the same, so the position on the line is ambiguous. A corner changes in every direction, so its position is unique.
:::

::: check You lower Canny''s thresholds from (100, 200) to (50, 100). Will the percentage of edge pixels go up or down?
???
**Up.** Weaker changes now count as edges, so more pixels are marked. On `street.png` it went from 5.4% to 8.9%.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b2b46e95589abcec', 'course_computer_vision', 'les_442fa32aab5eb1bb', 'common_mistakes', 'Common mistakes', '- **Running Canny on a colour image.** Convert to grayscale first; edges depend on brightness.
- **Expecting object outlines only.** Canny marks every strong change, including texture, shadows and noise. Blur first or raise the thresholds.
- **Changing only one threshold.** Change both together, keeping `high` about 2 to 3 times `low`. (If you swap them, OpenCV quietly uses the smaller one as `low`.)
- **Thinking an edge image is a list of lines.** It is still an image: a grid of 0s and 255s with the same size as the input.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 13, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a926ad2efccc1f3c', 'course_computer_vision', 'les_442fa32aab5eb1bb', 'key_takeaways', 'Key takeaways', '- A feature is a distinctive part of an image that can be detected again.
- Flat regions are hard to find again, edges are ambiguous, corners are easy.
- `cv2.Canny(gray, low, high)` marks strong intensity changes as white pixels.
- Lower thresholds give more edges; higher thresholds give fewer, stronger ones.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 14, 1792022400000);
