INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'lesson', 'les_442fa32aab5eb1bb', '/courses/computer-vision/lectures/features-and-edges', 'Features, edges and the Canny detector', 'Find out what makes a part of an image a good feature, tell flat regions, edges and corners apart, and find edges with cv2.Canny. Then measure how the two thresholds change the result. Define a feature and explain why corners are easier to find again than edges Name applications that depend on features Detect edges with cv2.Canny on a grayscale image Predict and measure the effect of Canny''s low and high thresholds From image enhancement to feature detection Last lab ended with an improved image: read, grayscale, resize, denoise, enhance. But how does the computer know which parts of the image are important? Today''s goal: find useful visual features automatically . This lecture has two parts. Part 1 is feature detection and matching with OpenCV. Part 2 starts the semester project, a camera-equipped vehicle. What is a feature? A feature is a distinctive part of an image that can be detected again , for example in a second photo of the same place. Imagine a small window lying on the image, and slide it a few pixels in each direction: Region When the window moves… Can you find it again? --- --- --- Flat region (the sky) nothing changes, in any direction hard : it looks the same everywhere Edge (a road line) it changes across the line, not along it ambiguous : you know the line, not where on it Corner (a window corner) it changes in every direction easy : the position is unique Good features are distinctive. A detector marks the distinctive locations it finds; each one is called a keypoint . Flat region, edge and corner Why do we need features? Features are the bridge between raw pixels and understanding: image → features → understanding . Almost every advanced computer vision task is built on them: Application What features do there --- --- Image matching decide whether two images show the same object Object recognition recognise an object from its typical features Tracking follow the same features from frame to frame Image stitching join photos into a panorama where their features overlap Visual SLAM build a map while working out where the camera is Robot navigation find a path using what the camera sees Autonomous vehicles all of the above, on a moving car: our semester project Edges vs corners An edge is a strong change in image intensity : building borders, road lines, the outline of an object. A corner is where two or more edges meet : window corners, the corners of a road sign, building corners. Corners are often easier to recognise again , for the reason in the table above: they change in every direction. Edges and corners on the street Why are there almost no corners along the long, straight road lines? Because a straight line only changes in one direction. Corners appear where two edges meet: the windows, the sign, the car, the snowy peaks. Finding edges with OpenCV import cv2 img = cv2.imread("street.png") gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY) edges = cv2.Canny(gray, 100, 200) cv2.imshow("Original", img) cv2.imshow("Edges", edges) cv2.waitKey(0) cv2.destroyAllWindows() The Edges window In one sentence: Canny searches for strong changes in pixel intensity. Its result is a black image (0) with white pixels (255) on the edges. Project link: lane lines, road borders and car outlines are all strong intensity changes, so they show up clearly. That is why edges are the first features our vehicle will use. The two thresholds cv2.Canny(gray, low, high) measures how strongly the brightness changes at every pixel, then uses the two numbers: Change at a pixel Result --- --- stronger than high an edge, for sure between low and high an edge only if it connects to a sure edge weaker than low not an edge So lower thresholds → more edges , including weak ones such as texture. Higher thresholds → fewer, stronger edges. A common rule of thumb is to make high about two to three times low . Experiment: change the thresholds Start with 100, 200, then change both numbers and run again. This program tries three pairs and measures the share of pixels that Canny marked as edges: import cv2 import numpy as np img = cv2.imread("street.png") gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY) for low, high in [(50, 100), (100, 200), (150, 250)]: edges = cv2.Canny(gray, low, high) percent = np.count_nonzero(edges) / edges.size * 100 print(low, high, round(percent, 1), "% edges") Three pairs of thresholds With 50, 100 , the grass blades and the road''s small stones fill the image with short marks. With 150, 250 , mostly the strong outlines are left. Which values work best for your image? Keep the edges you need and lose the noise. There is no single correct answer: the best values depend on the image and the lighting, which is why we will tune them again on live video in the project. Check yourself The window corner. Moving along a straight line looks the same, so the position on the line is ambiguous. A corner changes in every direction, so its position is unique. Up. Weaker changes now count as edges, so more pixels are marked. On street.png it went from 5.4% to 8.9%. Common mistakes - Running Canny on a colour image. Convert to grayscale first; edges depend on brightness. - Expecting object outlines only. Canny marks every strong change, including texture, shadows and noise. Blur first or raise the thresholds. - Changing only one threshold. Change both together, keeping high about 2 to 3 times low . (If you swap them, OpenCV quietly uses the smaller one as low .) - Thinking an edge image is a list of lines. It is still an image: a grid of 0s and 255s with the same size as the input. Key takeaways - A feature is a distinctive part of an image that can be detected again. - Flat regions are hard to find again, edges are ambiguous, corners are easy. - cv2.Canny(gray, low, high) marks strong intensity changes as white pixels. - Lower thresholds give more edges; higher thresholds give fewer, stronger ones.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_62f69d9857480dce', 'course_computer_vision', 'top_dbf66fe44460e044', 'finding-corners', 'Finding corners with Shi-Tomasi', 'Find the strongest corners in an image with cv2.goodFeaturesToTrack, understand its three parameters, and draw the corners as red dots.', 3, 13, 'medium', '["Detect corners with cv2.goodFeaturesToTrack on a grayscale image","Explain maxCorners, qualityLevel and minDistance","Convert corner positions to whole numbers and draw them with cv2.circle","Explain the shape (N, 1, 2) of the corners array"]', '["Features, edges and the Canny detector"]', 5, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
