INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_fcbf0122b45eb858', 'course_computer_vision', 'les_62f69d9857480dce', 'explanation', 'Shi-Tomasi corner detection', '`cv2.goodFeaturesToTrack()` is OpenCV''s **Shi-Tomasi corner detector**. It takes a grayscale image and returns the positions of the **strongest corners**: the places that change in every direction, which you met in the last lesson.

The name says what the corners are for: good features to **track**, that is, to find again in the next frame of a video.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_cadf74fe64d4a1f4', 'course_computer_vision', 'les_62f69d9857480dce', 'code', 'Finding corners', '', 'import cv2

img = cv2.imread("street.png")
gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
corners = cv2.goodFeaturesToTrack(
    gray,
    maxCorners=100,
    qualityLevel=0.01,
    minDistance=10
)
print(corners.shape)
print(corners[0])', 'python', 0, '', '(100, 1, 2)
[[710. 319.]]
', '{"notes":[{"line":5,"match":"goodFeaturesToTrack","text":"Shi-Tomasi corners","shape":"circle","color":"sky"},{"line":7,"match":"maxCorners=100","text":"keep at most 100","shape":"square","color":"yel"},{"line":8,"match":"qualityLevel=0.01","text":"at least 1% of the best","shape":"diamond","color":"green"},{"line":9,"match":"minDistance=10","text":"10 pixels apart","shape":"tri","color":"sky"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_4172d90cec777343', 'course_computer_vision', 'les_62f69d9857480dce', 'explanation', 'The three parameters', '| Parameter | Meaning |
|---|---|
| `maxCorners` | the **maximum** number of corners to return; it keeps the strongest |
| `qualityLevel` | the **minimum quality**, compared with the best corner in the image: 0.01 keeps corners at least 1% as strong as the best one |
| `minDistance` | the minimum **distance** in pixels between returned corners, so they don''t bunch up |

On `street.png` it returned exactly **100**, the `maxCorners` limit: the image has more corners than that. With `maxCorners=0` (no limit) it finds 1311 with the same quality and distance; with `maxCorners=20` you get only the 20 strongest.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_34cb0e6f2f7c2412', 'course_computer_vision', 'les_62f69d9857480dce', 'explanation', 'Reading the result', '`corners.shape` is `(100, 1, 2)`: **100 corners**, each stored as a tiny array holding one `[x, y]` pair. The extra `1` in the middle is just how OpenCV packs points.

`corners[0]` is `[[710. 319.]]`: the strongest corner is at **x = 710, y = 319**, in the letters of the STOP sign. The dots after the numbers mean they are **decimals** (`float32`); OpenCV can find a corner''s position more precisely than whole pixels.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_99e0844a97a0eecc', 'course_computer_vision', 'les_62f69d9857480dce', 'code', 'Drawing the corners', '', 'import cv2
import numpy as np

img = cv2.imread("street.png")
gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
corners = cv2.goodFeaturesToTrack(gray, maxCorners=100, qualityLevel=0.01, minDistance=10)

corners = np.int32(corners)
for corner in corners:
    x, y = corner.ravel()
    cv2.circle(img, (x, y), 4, (0, 0, 255), -1)
cv2.imshow("Detected Corners", img)
cv2.waitKey(0)
cv2.destroyAllWindows()', 'python', 0, '', NULL, '{"notes":[{"line":8,"match":"np.int32","text":"decimals to whole pixels","shape":"circle","color":"sky"},{"line":9,"match":"for corner in corners","text":"one corner at a time","shape":"square","color":"yel"},{"line":10,"match":"ravel","text":"[[x, y]] becomes x, y","shape":"diamond","color":"green"},{"line":11,"match":"(0, 0, 255)","text":"red in BGR","shape":"tri","color":"coral"},{"line":11,"match":"-1","text":"a filled circle","shape":"circle","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_276d4e97c8b51a4a', 'course_computer_vision', 'les_62f69d9857480dce', 'diagram', '100 corners on the street', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_62f69d9857480dce/cv-corners.png', 'The street scene with 100 small filled red dots. Most sit on the window corners of the first and third buildings; others are on the stop sign''s letters, the car, the tree, the two snowy peaks and a few stones on the road. There are none in the sky, on the house or along the straight road lines', 1018, 627, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_735dea02b90876ad', 'course_computer_vision', 'les_62f69d9857480dce', 'explanation', 'How the drawing code works', '- `np.int32(corners)` turns every position into whole pixels by dropping the decimal part (710.4 and 710.9 both become 710), because `cv2.circle` needs **integer** coordinates.
- The loop visits each corner. `corner` is `[[x, y]]`; `ravel()` flattens it, so `x, y = corner.ravel()` unpacks the two numbers.
- `cv2.circle(img, (x, y), 4, (0, 0, 255), -1)` draws on `img`: **centre** `(x, y)`, **radius** 4, **colour** `(0, 0, 255)` (red, because OpenCV uses BGR) and **thickness** `-1`, which means a filled circle.

Where are there **no** dots? In the sky, on the smooth mountain sides and along the road lines: flat regions have no corners, and long straight lines are edges, not corners. Why only two of the four buildings? Their light walls make the strongest contrast with the dark windows, and only the 100 strongest corners are kept.

**Note:** older tutorials write `np.int0(corners)`. `np.int0` was removed in NumPy 2, so it fails with an `AttributeError` there. `np.int32` works everywhere.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_347c7ac356bb126d', 'course_computer_vision', 'les_62f69d9857480dce', 'note', 'Check yourself', '::: check `goodFeaturesToTrack` returns an array with shape `(37, 1, 2)` although `maxCorners` was 100. What does that tell you?
???
The image only had **37 corners** that passed `qualityLevel` and `minDistance`, fewer than the limit. A plain image (a chessboard with few squares, a white wall) often gives fewer corners than `maxCorners`.
:::

::: check What colour is `cv2.circle(img, (x, y), 4, (255, 0, 0), -1)`?
???
**Blue.** OpenCV''s colour order is B, G, R, so `(255, 0, 0)` is full blue.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_7e2c5b91b1ff8e17', 'course_computer_vision', 'les_62f69d9857480dce', 'common_mistakes', 'Common mistakes', '- **Passing a colour image.** `goodFeaturesToTrack` needs grayscale.
- **Drawing with decimal coordinates.** `cv2.circle` needs whole numbers; convert with `np.int32` first.
- **Using `np.int0`.** It doesn''t exist in NumPy 2; use `np.int32`.
- **Drawing before detecting.** Detect on a clean image; red dots drawn first would become "corners" themselves.
- **Expecting exactly `maxCorners` corners.** It is a maximum, not a promise.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_382aced5097c8bbc', 'course_computer_vision', 'les_62f69d9857480dce', 'key_takeaways', 'Key takeaways', '- `cv2.goodFeaturesToTrack(gray, maxCorners, qualityLevel, minDistance)` returns the strongest corners.
- The result has shape `(N, 1, 2)` and holds decimal `[x, y]` positions.
- Convert with `np.int32`, unpack with `ravel()`, draw with `cv2.circle(img, (x, y), 4, (0, 0, 255), -1)`.
- Corners appear where edges meet, never in flat regions or along straight lines.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1792022400000);
