INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'lesson', 'les_62f69d9857480dce', '/courses/computer-vision/lectures/finding-corners', 'Finding corners with Shi-Tomasi', 'Find the strongest corners in an image with cv2.goodFeaturesToTrack, understand its three parameters, and draw the corners as red dots. Detect corners with cv2.goodFeaturesToTrack on a grayscale image Explain maxCorners, qualityLevel and minDistance Convert corner positions to whole numbers and draw them with cv2.circle Explain the shape (N, 1, 2) of the corners array Shi-Tomasi corner detection cv2.goodFeaturesToTrack() is OpenCV''s Shi-Tomasi corner detector . It takes a grayscale image and returns the positions of the strongest corners : the places that change in every direction, which you met in the last lesson. The name says what the corners are for: good features to track , that is, to find again in the next frame of a video. Finding corners import cv2 img = cv2.imread("street.png") gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY) corners = cv2.goodFeaturesToTrack( gray, maxCorners=100, qualityLevel=0.01, minDistance=10 ) print(corners.shape) print(corners[0]) The three parameters Parameter Meaning --- --- maxCorners the maximum number of corners to return; it keeps the strongest qualityLevel the minimum quality , compared with the best corner in the image: 0.01 keeps corners at least 1% as strong as the best one minDistance the minimum distance in pixels between returned corners, so they don''t bunch up On street.png it returned exactly 100 , the maxCorners limit: the image has more corners than that. With maxCorners=0 (no limit) it finds 1311 with the same quality and distance; with maxCorners=20 you get only the 20 strongest. Reading the result corners.shape is (100, 1, 2) : 100 corners , each stored as a tiny array holding one [x, y] pair. The extra 1 in the middle is just how OpenCV packs points. corners[0] is [[710. 319.]] : the strongest corner is at x = 710, y = 319 , in the letters of the STOP sign. The dots after the numbers mean they are decimals ( float32 ); OpenCV can find a corner''s position more precisely than whole pixels. Drawing the corners import cv2 import numpy as np img = cv2.imread("street.png") gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY) corners = cv2.goodFeaturesToTrack(gray, maxCorners=100, qualityLevel=0.01, minDistance=10) corners = np.int32(corners) for corner in corners: x, y = corner.ravel() cv2.circle(img, (x, y), 4, (0, 0, 255), -1) cv2.imshow("Detected Corners", img) cv2.waitKey(0) cv2.destroyAllWindows() 100 corners on the street How the drawing code works - np.int32(corners) turns every position into whole pixels by dropping the decimal part (710.4 and 710.9 both become 710), because cv2.circle needs integer coordinates. - The loop visits each corner. corner is [[x, y]] ; ravel() flattens it, so x, y = corner.ravel() unpacks the two numbers. - cv2.circle(img, (x, y), 4, (0, 0, 255), -1) draws on img : centre (x, y) , radius 4, colour (0, 0, 255) (red, because OpenCV uses BGR) and thickness -1 , which means a filled circle. Where are there no dots? In the sky, on the smooth mountain sides and along the road lines: flat regions have no corners, and long straight lines are edges, not corners. Why only two of the four buildings? Their light walls make the strongest contrast with the dark windows, and only the 100 strongest corners are kept. Note: older tutorials write np.int0(corners) . np.int0 was removed in NumPy 2, so it fails with an AttributeError there. np.int32 works everywhere. Check yourself The image only had 37 corners that passed qualityLevel and minDistance , fewer than the limit. A plain image (a chessboard with few squares, a white wall) often gives fewer corners than maxCorners . Blue. OpenCV''s colour order is B, G, R, so (255, 0, 0) is full blue. Common mistakes - Passing a colour image. goodFeaturesToTrack needs grayscale. - Drawing with decimal coordinates. cv2.circle needs whole numbers; convert with np.int32 first. - Using np.int0 . It doesn''t exist in NumPy 2; use np.int32 . - Drawing before detecting. Detect on a clean image; red dots drawn first would become "corners" themselves. - Expecting exactly maxCorners corners. It is a maximum, not a promise. Key takeaways - cv2.goodFeaturesToTrack(gray, maxCorners, qualityLevel, minDistance) returns the strongest corners. - The result has shape (N, 1, 2) and holds decimal [x, y] positions. - Convert with np.int32 , unpack with ravel() , draw with cv2.circle(img, (x, y), 4, (0, 0, 255), -1) . - Corners appear where edges meet, never in flat regions or along straight lines.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_302aeae469e9a462', 'course_computer_vision', 'top_dbf66fe44460e044', 'orb-keypoints-and-descriptors', 'ORB keypoints and descriptors', 'Go from corners to keypoints. Use ORB to find keypoints (where a feature is) and descriptors (what it looks like), draw them, and look inside one descriptor''s 256 bits.', 3, 14, 'medium', '["Explain the difference between a keypoint and a descriptor","Detect ORB keypoints and compute descriptors with detectAndCompute","Draw keypoints with cv2.drawKeypoints","Read a keypoint''s position, size and angle, and a descriptor''s 32 numbers"]', '["Finding corners with Shi-Tomasi"]', 5, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_302aeae469e9a462';
DELETE FROM lesson_relations WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_302aeae469e9a462';
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_368cb2551686b954', 'course_computer_vision', 'les_302aeae469e9a462', 'explanation', 'From corners to keypoints', 'A corner tells us **where** something interesting is. To find the same point in **another** image, we also need to know **what it looks like**. ORB gives us both:

**Image → feature detector → important locations: keypoints**

**ORB** (Oriented FAST and Rotated BRIEF) is a free, fast detector built into OpenCV. It can:

1. **detect** important keypoints, and
2. **describe** the appearance around each keypoint.

| | Answers | Example |
|---|---|---|
| **Keypoint** | **where** is the feature? | position (728, 325), size 31 pixels, angle 15° |
| **Descriptor** | **what** does the feature look like? | 32 numbers from 0 to 255 |

An easy way to remember it: the keypoint is the **address**, the descriptor is the **fingerprint**.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_7fd609541c633010', 'course_computer_vision', 'les_302aeae469e9a462', 'code', 'Detecting keypoints with ORB', '', 'import cv2

img = cv2.imread("street.png")
gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
orb = cv2.ORB_create()
keypoints, descriptors = orb.detectAndCompute(gray, None)
print(len(keypoints))
print(descriptors.shape)
output = cv2.drawKeypoints(img, keypoints, None)
cv2.imshow("ORB Keypoints", output)
cv2.waitKey(0)
cv2.destroyAllWindows()', 'python', 0, '', '501
(501, 32)
', '{"notes":[{"line":5,"match":"ORB_create","text":"makes the detector","shape":"circle","color":"sky"},{"line":6,"match":"detectAndCompute","text":"keypoints and descriptors","shape":"square","color":"yel"},{"line":6,"match":"None","text":"no mask: the whole image","shape":"diamond","color":"green"},{"line":9,"match":"drawKeypoints","text":"a circle on each one","shape":"circle","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b9d996f816e82536', 'course_computer_vision', 'les_302aeae469e9a462', 'diagram', 'ORB keypoints on the street', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_302aeae469e9a462/cv-orb.png', 'The street scene with about 500 small coloured circles. They cluster on the windows of the first and third buildings, the stop sign, the car and the dashed centre line, with some on the road''s stones, the house roof and the mountain tops. There are almost none in the sky, on the grass or on the plain walls', 1018, 627, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2de9a1b80c5d082d', 'course_computer_vision', 'les_302aeae469e9a462', 'explanation', 'What each function does', '| Function | What it does |
|---|---|
| `cv2.ORB_create()` | makes an ORB detector with default settings |
| `orb.detectAndCompute(gray, None)` | finds the keypoints **and** computes their descriptors; `None` means "search the whole image" (no mask) |
| `cv2.drawKeypoints(img, keypoints, None)` | draws a small circle on each keypoint, on a copy of the image |

ORB aims for **500 keypoints** by default. The exact number can come out slightly different: on `street.png` it returned **501**. Ask for more with `cv2.ORB_create(nfeatures=1000)`.

The descriptor array is `(501, 32)`: **one row per keypoint**, 32 numbers per row. Row 0 describes `keypoints[0]`, row 1 describes `keypoints[1]`, and so on.

Notice where the keypoints cluster: on the windows, the sign, the car and the lane dashes, where there is detail. Smooth areas get almost none.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_071cd764a8755034', 'course_computer_vision', 'les_302aeae469e9a462', 'code', 'Inside one keypoint and its descriptor', '', 'import cv2
import numpy as np

img = cv2.imread("street.png")
gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
orb = cv2.ORB_create()
keypoints, descriptors = orb.detectAndCompute(gray, None)
kp = keypoints[0]
print("position:", kp.pt)
print("size:", kp.size)
print("angle:", round(kp.angle))
print("descriptor:", descriptors[0][:6])
print("bits:", np.unpackbits(descriptors[0])[:16])', 'python', 0, '', 'position: (728.0, 325.0)
size: 31.0
angle: 15
descriptor: [193 185 168  63 176 141]
bits: [1 1 0 0 0 0 0 1 1 0 1 1 1 0 0 1]
', '{"notes":[{"line":8,"match":"keypoints[0]","text":"the first keypoint","shape":"circle","color":"sky"},{"line":9,"match":"kp.pt","text":"(x, y) position","shape":"square","color":"yel"},{"line":10,"match":"kp.size","text":"the area it covers","shape":"diamond","color":"green"},{"line":11,"match":"kp.angle","text":"its orientation","shape":"tri","color":"sky"},{"line":12,"match":"descriptors[0]","text":"its fingerprint","shape":"circle","color":"green"},{"line":13,"match":"unpackbits","text":"numbers as bits","shape":"square","color":"sky"}],"strips":[]}', NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_4c1951590b3e111e', 'course_computer_vision', 'les_302aeae469e9a462', 'diagram', 'One keypoint, close up', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_302aeae469e9a462/cv-keypoint.png', 'Left: a close-up of a corner of the stop sign''s white border with a circle of diameter 31 pixels centred at (728, 325) and a line from the centre showing its angle of 15 degrees. Right: a 16 by 16 grid of black and white cells, the 256 bits of its descriptor, with the first row read out as 1 1 0 0 0 0 0 1 1 0 1 1 1 0 0 1', 724, 436, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e866fd6782910b12', 'course_computer_vision', 'les_302aeae469e9a462', 'explanation', 'Reading the keypoint and the descriptor', '**The keypoint** `keypoints[0]` sits at **(728, 325)**, on a corner of the stop sign''s white border. Its **size**, 31, is the diameter of the area ORB looked at, and its **angle**, about 15°, is the direction from the centre towards the brighter side of that area. Thanks to the angle, ORB can still recognise the point when the image is rotated.

**The descriptor** is 32 numbers. ORB compares the brightness of pairs of pixels around the keypoint, always the same 256 pairs, and stores each answer ("is the first pixel darker?") as one bit, 1 or 0. 256 bits are packed into 32 numbers of 8 bits each:

- 193 in binary is **1100 0001**, the first eight bits;
- 185 in binary is **1011 1001**, the next eight.

Two keypoints that look alike have descriptors with mostly the **same bits**. That is exactly what the next lesson uses to match points between two images.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_91538371853ac34d', 'course_computer_vision', 'les_302aeae469e9a462', 'note', 'Check yourself', '::: check `descriptors.shape` is `(800, 32)`. How many keypoints were found, and how many bits describe each one?
???
**800 keypoints**, one per row. Each row has 32 numbers of 8 bits: **256 bits** per keypoint.
:::

::: check What is the difference between `kp.pt` and `descriptors[0]`?
???
`kp.pt` says **where** the feature is (its x, y position). `descriptors[0]` says **what it looks like** (its fingerprint), so it can be recognised in another image.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_355442b2b6e1d8eb', 'course_computer_vision', 'les_302aeae469e9a462', 'common_mistakes', 'Common mistakes', '- **Mixing up keypoints and descriptors.** `detectAndCompute` returns both, in that order: `keypoints, descriptors = …`.
- **Expecting exactly 500 keypoints.** 500 is ORB''s target, not an exact count.
- **Reading descriptors as brightness values.** The 32 numbers are packed bits, not pixel values; compare them bit by bit.
- **Forgetting the `None` mask argument.** `orb.detectAndCompute(gray)` is an error; pass `None` to search the whole image.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a4a85e20888bf68d', 'course_computer_vision', 'les_302aeae469e9a462', 'key_takeaways', 'Key takeaways', '- A **keypoint** says where a feature is (position, size, angle); a **descriptor** says what it looks like.
- `orb = cv2.ORB_create()` then `keypoints, descriptors = orb.detectAndCompute(gray, None)`.
- ORB''s descriptors are 32 numbers = 256 bits per keypoint; the array is `(N, 32)`.
- `cv2.drawKeypoints(img, keypoints, None)` shows where they are.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1792022400000);
