INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'lesson', 'les_302aeae469e9a462', '/courses/computer-vision/lectures/orb-keypoints-and-descriptors', 'ORB keypoints and descriptors', 'Go from corners to keypoints. Use ORB to find keypoints (where a feature is) and descriptors (what it looks like), draw them, and look inside one descriptor''s 256 bits. Explain the difference between a keypoint and a descriptor Detect ORB keypoints and compute descriptors with detectAndCompute Draw keypoints with cv2.drawKeypoints Read a keypoint''s position, size and angle, and a descriptor''s 32 numbers From corners to keypoints A corner tells us where something interesting is. To find the same point in another image, we also need to know what it looks like . ORB gives us both: Image → feature detector → important locations: keypoints ORB (Oriented FAST and Rotated BRIEF) is a free, fast detector built into OpenCV. It can: 1. detect important keypoints, and 2. describe the appearance around each keypoint. Answers Example --- --- --- Keypoint where is the feature? position (728, 325), size 31 pixels, angle 15° Descriptor what does the feature look like? 32 numbers from 0 to 255 An easy way to remember it: the keypoint is the address , the descriptor is the fingerprint . Detecting keypoints with ORB import cv2 img = cv2.imread("street.png") gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY) orb = cv2.ORB_create() keypoints, descriptors = orb.detectAndCompute(gray, None) print(len(keypoints)) print(descriptors.shape) output = cv2.drawKeypoints(img, keypoints, None) cv2.imshow("ORB Keypoints", output) cv2.waitKey(0) cv2.destroyAllWindows() ORB keypoints on the street What each function does Function What it does --- --- cv2.ORB create() makes an ORB detector with default settings orb.detectAndCompute(gray, None) finds the keypoints and computes their descriptors; None means "search the whole image" (no mask) cv2.drawKeypoints(img, keypoints, None) draws a small circle on each keypoint, on a copy of the image ORB aims for 500 keypoints by default. The exact number can come out slightly different: on street.png it returned 501 . Ask for more with cv2.ORB create(nfeatures=1000) . The descriptor array is (501, 32) : one row per keypoint , 32 numbers per row. Row 0 describes keypoints[0] , row 1 describes keypoints[1] , and so on. Notice where the keypoints cluster: on the windows, the sign, the car and the lane dashes, where there is detail. Smooth areas get almost none. Inside one keypoint and its descriptor import cv2 import numpy as np img = cv2.imread("street.png") gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY) orb = cv2.ORB_create() keypoints, descriptors = orb.detectAndCompute(gray, None) kp = keypoints[0] print("position:", kp.pt) print("size:", kp.size) print("angle:", round(kp.angle)) print("descriptor:", descriptors[0][:6]) print("bits:", np.unpackbits(descriptors[0])[:16]) One keypoint, close up Reading the keypoint and the descriptor The keypoint keypoints[0] sits at (728, 325) , on a corner of the stop sign''s white border. Its size , 31, is the diameter of the area ORB looked at, and its angle , about 15°, is the direction from the centre towards the brighter side of that area. Thanks to the angle, ORB can still recognise the point when the image is rotated. The descriptor is 32 numbers. ORB compares the brightness of pairs of pixels around the keypoint, always the same 256 pairs, and stores each answer ("is the first pixel darker?") as one bit, 1 or 0. 256 bits are packed into 32 numbers of 8 bits each: - 193 in binary is 1100 0001 , the first eight bits; - 185 in binary is 1011 1001 , the next eight. Two keypoints that look alike have descriptors with mostly the same bits . That is exactly what the next lesson uses to match points between two images. Check yourself 800 keypoints , one per row. Each row has 32 numbers of 8 bits: 256 bits per keypoint. kp.pt says where the feature is (its x, y position). descriptors[0] says what it looks like (its fingerprint), so it can be recognised in another image. Common mistakes - Mixing up keypoints and descriptors. detectAndCompute returns both, in that order: keypoints, descriptors = … . - Expecting exactly 500 keypoints. 500 is ORB''s target, not an exact count. - Reading descriptors as brightness values. The 32 numbers are packed bits, not pixel values; compare them bit by bit. - Forgetting the None mask argument. orb.detectAndCompute(gray) is an error; pass None to search the whole image. Key takeaways - A keypoint says where a feature is (position, size, angle); a descriptor says what it looks like. - orb = cv2.ORB create() then keypoints, descriptors = orb.detectAndCompute(gray, None) . - ORB''s descriptors are 32 numbers = 256 bits per keypoint; the array is (N, 32) . - cv2.drawKeypoints(img, keypoints, None) shows where they are.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_98c70721c3dc932b', 'course_computer_vision', 'top_98c70721c3dc932b', 'feature-matching', 'Matching features between two images', 'Match ORB features between two views of the same street with a brute-force matcher, keep the best matches, and measure how lighting, blur, angle, occlusion and scale make matching harder.', 3, 15, 'hard', '["Explain what feature matching is and what a wrong match is","Match ORB descriptors with cv2.BFMatcher, NORM_HAMMING and crossCheck","Sort matches by distance and draw the best ones with cv2.drawMatches","Measure how changes to the second image reduce the number of good matches"]', '["ORB keypoints and descriptors"]', 8, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_98c70721c3dc932b';
