INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b00fd0e28158218d', 'course_computer_vision', 'les_98c70721c3dc932b', 'explanation', 'What is feature matching?', 'Feature matching answers one question: **which feature in image A shows the same real-world point as a feature in image B?**

ORB finds keypoints and descriptors in **both** images. Matching compares the descriptors (the fingerprints): two keypoints whose descriptors have almost the same bits probably show the same point.

Matching can go wrong. If a keypoint on the car in image A were matched to a window in image B, that would be a **wrong match**: the two patches only look alike. That is why we keep only the **best** matches.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_88d379d8352ed562', 'course_computer_vision', 'les_98c70721c3dc932b', 'diagram', 'View A', '`view-a.png` and `view-b.png` are two views of the same street, as if the camera moved to the right and turned a little between the two photos. Download both to run the programs below.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_98c70721c3dc932b/view-a.png', 'The street seen from the first camera position: buildings on the left, the road, the car, the stop sign, and part of the house at the right edge', 720, 540, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3f1696bc4dce2ec7', 'course_computer_vision', 'les_98c70721c3dc932b', 'diagram', 'View B', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_98c70721c3dc932b/view-b.png', 'The street seen from the second camera position: shifted to the right and slightly tilted, with the whole house, the tree edge and the sun visible on the right', 720, 540, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_30565c1bfbe5e136', 'course_computer_vision', 'les_98c70721c3dc932b', 'code', 'Feature matching with ORB', '', 'import cv2

img1 = cv2.imread("view-a.png", 0)
img2 = cv2.imread("view-b.png", 0)
orb = cv2.ORB_create()
kp1, des1 = orb.detectAndCompute(img1, None)
kp2, des2 = orb.detectAndCompute(img2, None)
bf = cv2.BFMatcher(cv2.NORM_HAMMING, crossCheck=True)
matches = bf.match(des1, des2)
matches = sorted(matches, key=lambda x: x.distance)
print(len(matches), "matches")
print("best distance:", matches[0].distance)
print("30th best:", matches[29].distance)
result = cv2.drawMatches(img1, kp1, img2, kp2,
                         matches[:30], None)
cv2.imshow("Feature Matches", result)
cv2.waitKey(0)
cv2.destroyAllWindows()', 'python', 0, '', '303 matches
best distance: 1.0
30th best: 7.0
', '{"notes":[{"line":3,"match":"0)","text":"0 = load in grayscale","shape":"circle","color":"sky"},{"line":6,"match":"detectAndCompute","text":"features in both images","shape":"square","color":"yel"},{"line":8,"match":"BFMatcher","text":"compare every pair","shape":"diamond","color":"green"},{"line":8,"match":"NORM_HAMMING","text":"count differing bits","shape":"tri","color":"sky"},{"line":8,"match":"crossCheck=True","text":"both must agree","shape":"circle","color":"green"},{"line":10,"match":"sorted","text":"most similar first","shape":"square","color":"sky"},{"line":15,"match":"matches[:30]","text":"draw the best 30","shape":"diamond","color":"yel"}],"strips":[]}', NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2d435a782c0b777e', 'course_computer_vision', 'les_98c70721c3dc932b', 'diagram', 'The best 30 matches', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_98c70721c3dc932b/cv-matches.png', 'A window titled Feature Matches with view A on the left and view B on the right. Thirty coloured lines join small circles in A to circles in B: on the windows, the mountain tops, the stop sign and the car. The lines run almost horizontally, slanting slightly because the camera moved sideways and turned', 1258, 537, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_7fa1ee087177a930', 'course_computer_vision', 'les_98c70721c3dc932b', 'explanation', 'Walking through the code', '1. **Read in grayscale.** The flag `0` in `cv2.imread(…, 0)` loads each image as grayscale directly.
2. **Detect and describe.** The same ORB detector finds keypoints and descriptors in both images.
3. **Match.** `cv2.BFMatcher` is a **brute-force** matcher: it compares every descriptor in image 1 with every descriptor in image 2.
   - `cv2.NORM_HAMMING` measures the **distance** between two descriptors by counting how many of their 256 bits differ. This is the right distance for ORB''s bit descriptors. Distance 0 means identical.
   - `crossCheck=True` keeps a match only if the two features **choose each other**: A''s best match is B, **and** B''s best match is A. This removes many wrong matches.
4. **Sort and draw.** Sorting by `distance` puts the most similar pairs first; `drawMatches` draws the best 30 side by side.

Here 303 cross-checked matches were found. The best pair differs in only 1 bit out of 256, and even the 30th best differs in only 7.

**ORB** detects and describes features; **BFMatcher** compares descriptors; **drawMatches** shows the matching features.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_dbc151cde86c2fc6', 'course_computer_vision', 'les_98c70721c3dc932b', 'explanation', 'When does matching become difficult?', 'We kept image A fixed, changed image B in seven ways, and counted the **good matches**: cross-checked matches with a distance below 40 bits. In normal conditions there are **258**.

| Image B changed by… | Good matches |
|---|---|
| nothing (normal) | 258 |
| uniformly darker (half the brightness) | 252 |
| different lighting (dark on one side, bright on the other) | 91 |
| a different camera angle (stronger tilt) | 135 |
| motion blur (sideways) | 54 |
| occlusion (the left half hidden) | 106 |
| poor image quality (pixelated and noisy) | 116 |
| a large scale change (B shrunk to a quarter) | 2 |

These numbers come from our two drawn views and our OpenCV version; with other images or versions they will differ, but the pattern is typical.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3f4191d9a98ec676', 'course_computer_vision', 'les_98c70721c3dc932b', 'diagram', 'Image B, changed seven ways', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_98c70721c3dc932b/cv-match-difficulty.png', 'A grid of eight versions of view B, each labelled with its number of good matches: normal 258, darker 252, uneven lighting 91, different angle 135, motion blur 54, occlusion 106, poor quality 116 and a quarter size 2', 1556, 736, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_20c12dc8d4ffa21d', 'course_computer_vision', 'les_98c70721c3dc932b', 'explanation', 'What the experiment shows', '- **Uniform darkness barely matters** (252 of 258). ORB compares pixels **with each other**, not with fixed values, so making everything darker keeps the comparisons the same. **Uneven** lighting changes the comparisons, and hurts.
- **Motion blur and big scale changes are the worst.** Blur wipes out the fine detail the descriptors are built from; a quarter-size image has too few pixels to show the same detail. Both happen on a moving vehicle.
- **A good match is not always a correct match.** A distance below 40 means "looks alike"; it can still join two different windows.

**Lecture 2 link:** this is one reason why image enhancement and good image quality matter. Denoising, sharpening and good exposure give the matcher more to work with.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_007865d79bd53209', 'course_computer_vision', 'les_98c70721c3dc932b', 'code', 'Try it: how much does motion blur hurt?', 'This program blurs image B sideways with a filter2D kernel (an average along one row, like the camera sliding during the photo) and counts good matches with and without it. Afterwards, change the kernel to `(1, 5)` or `(1, 30)` and run again: a longer blur loses more matches.', 'import cv2
import numpy as np

img1 = cv2.imread("view-a.png", 0)
img2 = cv2.imread("view-b.png", 0)
blurred = cv2.filter2D(img2, -1, np.ones((1, 15)) / 15)

orb = cv2.ORB_create()
bf = cv2.BFMatcher(cv2.NORM_HAMMING, crossCheck=True)
kp1, des1 = orb.detectAndCompute(img1, None)

for name, img in [("normal", img2), ("motion blur", blurred)]:
    kp2, des2 = orb.detectAndCompute(img, None)
    matches = bf.match(des1, des2)
    good = [m for m in matches if m.distance < 40]
    print(name, len(good))', 'python', 0, '', 'normal 258
motion blur 54
', '{"notes":[{"line":6,"match":"np.ones((1, 15)) / 15","text":"average 15 pixels in a row","shape":"circle","color":"sky"},{"line":12,"match":"for name, img in","text":"the same test, twice","shape":"square","color":"yel"},{"line":15,"match":"m.distance < 40","text":"keep good matches only","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_57346021d28da4e5', 'course_computer_vision', 'les_98c70721c3dc932b', 'explanation', 'Mini lab task: match two images', '1. **Choose or capture two images of the same object**: a book, a keyboard, a bottle, a building, a road sign or a laptop. Move a little between the two photos. Save them as `image1.jpg` and `image2.jpg` next to your script.
2. **Detect ORB features** in each image.
3. **Match the descriptors and draw the best 30.** Reuse the matching program above: change only the file names.

**Check your result:** do the lines join the same real points? Objects with print and texture (a book cover, a labelled bottle) give many matches; plain objects (a white mug) give very few. Then try a deliberately hard pair: different lighting, a strong angle, or one photo much closer than the other. Compare the numbers with `print(len(matches))`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_df33572670bb2c50', 'course_computer_vision', 'les_98c70721c3dc932b', 'note', 'Check yourself', '::: check Two ORB descriptors differ in 3 of their 256 bits. What is their Hamming distance, and is that a good match?
???
The distance is **3**. That is very small (out of 256), so the two patches look almost identical: a good match.
:::

::: check What does `crossCheck=True` add?
???
It keeps a match only if the two features choose **each other**: the best match for A''s feature is B''s feature, and the best match for B''s feature is A''s. One-sided matches, which are often wrong, are dropped.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_cec6c925cdc3d00b', 'course_computer_vision', 'les_98c70721c3dc932b', 'common_mistakes', 'Common mistakes', '- **`NORM_L2` with ORB.** ORB descriptors are bits; use `cv2.NORM_HAMMING`.
- **Drawing all the matches.** Hundreds of lines hide everything. Sort by distance and draw the best few.
- **Assuming every match is correct.** Look at the lines: one crossing to a different object is a wrong match.
- **Images of different objects.** Matching always returns *something*; few matches with large distances mean "not the same thing".
- **No descriptors.** On a blank or very dark image `detectAndCompute` can return `None` for the descriptors, and `bf.match` then fails. Check before matching.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 13, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a859b4d4dabefccf', 'course_computer_vision', 'les_98c70721c3dc932b', 'key_takeaways', 'Key takeaways', '- Matching finds which feature in image A is the same real point as one in image B.
- `cv2.BFMatcher` with `cv2.NORM_HAMMING` and `crossCheck=True` compares ORB descriptors by counting differing bits.
- Sort matches by `distance` (smaller is better) and draw the best with `cv2.drawMatches`.
- Uneven lighting, a different angle, blur, occlusion, poor quality and scale changes all reduce good matches.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 14, 1792022400000);
