INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'lesson', 'les_98c70721c3dc932b', '/courses/computer-vision/lectures/feature-matching', 'Matching features between two images', 'Match ORB features between two views of the same street with a brute-force matcher, keep the best matches, and measure how lighting, blur, angle, occlusion and scale make matching harder. Explain what feature matching is and what a wrong match is Match ORB descriptors with cv2.BFMatcher, NORM_HAMMING and crossCheck Sort matches by distance and draw the best ones with cv2.drawMatches Measure how changes to the second image reduce the number of good matches What is feature matching? Feature matching answers one question: which feature in image A shows the same real-world point as a feature in image B? ORB finds keypoints and descriptors in both images. Matching compares the descriptors (the fingerprints): two keypoints whose descriptors have almost the same bits probably show the same point. Matching can go wrong. If a keypoint on the car in image A were matched to a window in image B, that would be a wrong match : the two patches only look alike. That is why we keep only the best matches. View A view-a.png and view-b.png are two views of the same street, as if the camera moved to the right and turned a little between the two photos. Download both to run the programs below. View B Feature matching with ORB import cv2 img1 = cv2.imread("view-a.png", 0) img2 = cv2.imread("view-b.png", 0) orb = cv2.ORB_create() kp1, des1 = orb.detectAndCompute(img1, None) kp2, des2 = orb.detectAndCompute(img2, None) bf = cv2.BFMatcher(cv2.NORM_HAMMING, crossCheck=True) matches = bf.match(des1, des2) matches = sorted(matches, key=lambda x: x.distance) print(len(matches), "matches") print("best distance:", matches[0].distance) print("30th best:", matches[29].distance) result = cv2.drawMatches(img1, kp1, img2, kp2, matches[:30], None) cv2.imshow("Feature Matches", result) cv2.waitKey(0) cv2.destroyAllWindows() The best 30 matches Walking through the code 1. Read in grayscale. The flag 0 in cv2.imread(…, 0) loads each image as grayscale directly. 2. Detect and describe. The same ORB detector finds keypoints and descriptors in both images. 3. Match. cv2.BFMatcher is a brute-force matcher: it compares every descriptor in image 1 with every descriptor in image 2. - cv2.NORM HAMMING measures the distance between two descriptors by counting how many of their 256 bits differ. This is the right distance for ORB''s bit descriptors. Distance 0 means identical. - crossCheck=True keeps a match only if the two features choose each other : A''s best match is B, and B''s best match is A. This removes many wrong matches. 4. Sort and draw. Sorting by distance puts the most similar pairs first; drawMatches draws the best 30 side by side. Here 303 cross-checked matches were found. The best pair differs in only 1 bit out of 256, and even the 30th best differs in only 7. ORB detects and describes features; BFMatcher compares descriptors; drawMatches shows the matching features. When does matching become difficult? We kept image A fixed, changed image B in seven ways, and counted the good matches : cross-checked matches with a distance below 40 bits. In normal conditions there are 258 . Image B changed by… Good matches --- --- nothing (normal) 258 uniformly darker (half the brightness) 252 different lighting (dark on one side, bright on the other) 91 a different camera angle (stronger tilt) 135 motion blur (sideways) 54 occlusion (the left half hidden) 106 poor image quality (pixelated and noisy) 116 a large scale change (B shrunk to a quarter) 2 These numbers come from our two drawn views and our OpenCV version; with other images or versions they will differ, but the pattern is typical. Image B, changed seven ways What the experiment shows - Uniform darkness barely matters (252 of 258). ORB compares pixels with each other , not with fixed values, so making everything darker keeps the comparisons the same. Uneven lighting changes the comparisons, and hurts. - Motion blur and big scale changes are the worst. Blur wipes out the fine detail the descriptors are built from; a quarter-size image has too few pixels to show the same detail. Both happen on a moving vehicle. - A good match is not always a correct match. A distance below 40 means "looks alike"; it can still join two different windows. Lecture 2 link: this is one reason why image enhancement and good image quality matter. Denoising, sharpening and good exposure give the matcher more to work with. Try it: how much does motion blur hurt? This program blurs image B sideways with a filter2D kernel (an average along one row, like the camera sliding during the photo) and counts good matches with and without it. Afterwards, change the kernel to (1, 5) or (1, 30) and run again: a longer blur loses more matches. import cv2 import numpy as np img1 = cv2.imread("view-a.png", 0) img2 = cv2.imread("view-b.png", 0) blurred = cv2.filter2D(img2, -1, np.ones((1, 15)) / 15) orb = cv2.ORB_create() bf = cv2.BFMatcher(cv2.NORM_HAMMING, crossCheck=True) kp1, des1 = orb.detectAndCompute(img1, None) for name, img in [("normal", img2), ("motion blur", blurred)]: kp2, des2 = orb.detectAndCompute(img, None) matches = bf.match(des1, des2) good = [m for m in matches if m.distance < 40] print(name, len(good)) Mini lab task: match two images 1. Choose or capture two images of the same object : a book, a keyboard, a bottle, a building, a road sign or a laptop. Move a little between the two photos. Save them as image1.jpg and image2.jpg next to your script. 2. Detect ORB features in each image. 3. Match the descriptors and draw the best 30. Reuse the matching program above: change only the file names. Check your result: do the lines join the same real points? Objects with print and texture (a book cover, a labelled bottle) give many matches; plain objects (a white mug) give very few. Then try a deliberately hard pair: different lighting, a strong angle, or one photo much closer than the other. Compare the numbers with print(len(matches)) . Check yourself The distance is 3 . That is very small (out of 256), so the two patches look almost identical: a good match. It keeps a match only if the two features choose each other : the best match for A''s feature is B''s feature, and the best match for B''s feature is A''s. One-sided matches, which are often wrong, are dropped. Common mistakes - NORM L2 with ORB. ORB descriptors are bits; use cv2.NORM HAMMING . - Drawing all the matches. Hundreds of lines hide everything. Sort by distance and draw the best few. - Assuming every match is correct. Look at the lines: one crossing to a different object is a wrong match. - Images of different objects. Matching always returns something ; few matches with large distances mean "not the same thing". - No descriptors. On a blank or very dark image detectAndCompute can return None for the descriptors, and bf.match then fails. Check before matching. Key takeaways - Matching finds which feature in image A is the same real point as one in image B. - cv2.BFMatcher with cv2.NORM HAMMING and crossCheck=True compares ORB descriptors by counting differing bits. - Sort matches by distance (smaller is better) and draw the best with cv2.drawMatches . - Uneven lighting, a different angle, blur, occlusion, poor quality and scale changes all reduce good matches.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_c2b34d76e1b701c6', 'course_computer_vision', 'top_f0b6f4af7c3d4192', 'jetson-vision-vehicle', 'The semester project: a Jetson vision vehicle', 'Meet the semester project, a vehicle that sees with a camera and thinks with an NVIDIA Jetson. Learn its SEE, UNDERSTAND, DECIDE, ACT idea, what edge AI means, the main loop that runs for every frame, and how the teams will build it.', 3, 16, 'easy', '["Describe the project''s architecture from camera to vehicle action","Explain SEE, UNDERSTAND, DECIDE and ACT with an example for each","Explain what an NVIDIA Jetson is and what edge AI means","Describe the main loop and calculate the time per frame at a given FPS"]', '["Matching features between two images"]', 6, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_c2b34d76e1b701c6';
DELETE FROM lesson_relations WHERE course_id = 'course_computer_vision' AND lesson_id = 'les_c2b34d76e1b701c6';
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_7038ed77818bf18c', 'course_computer_vision', 'les_c2b34d76e1b701c6', 'explanation', 'What if the camera is moving?', 'So far every image sat still: a file, read once. Now follow the steps:

1. a **fixed image**;
2. a **camera** that takes images;
3. a **moving camera**;
4. that camera **mounted on a vehicle**.

What changes on the vehicle? The images keep changing, there is no time to wait, and the system must understand the road, cars and people **while it moves**:

**Camera → frames → computer vision → understanding the environment**

Let''s build one.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_78a90d186a42074b', 'course_computer_vision', 'les_c2b34d76e1b701c6', 'explanation', 'The semester project', '**ECE4704 semester project: a Jetson-based intelligent vision vehicle.**

The question behind it: **how can we make a vehicle SEE and UNDERSTAND its environment?**

The project is not only about moving a car. Driving motors is the easy part. **The main goal is the vehicle''s visual intelligence**, and every lab adds a piece of it.

The whole system in one line:

**Camera → NVIDIA Jetson → computer vision → environment understanding → decision → vehicle action**

The camera captures, the Jetson runs our computer vision, the vision results become an understanding of the scene, that understanding becomes a decision, and the decision becomes an action.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b36eeb16496964f6', 'course_computer_vision', 'les_c2b34d76e1b701c6', 'explanation', 'The big idea: SEE → UNDERSTAND → DECIDE → ACT', '| Stage | What happens | Examples |
|---|---|---|
| 1. **SEE** | the camera captures the environment | camera frames |
| 2. **UNDERSTAND** | computer vision detects important information | lane, car, person, obstacle, traffic sign |
| 3. **DECIDE** | the system decides what should happen | continue, turn, slow down, stop |
| 4. **ACT** | the vehicle performs the action | motors, steering |

**Computer vision connects the camera to intelligent vehicle behaviour.** This course is mostly about stage 2, because stages 3 and 4 can only be as good as what the vision system tells them.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_59e218ae086d5bf8', 'course_computer_vision', 'les_c2b34d76e1b701c6', 'diagram', 'SEE, UNDERSTAND, DECIDE, ACT', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_c2b34d76e1b701c6/cv-see-understand-decide-act.png', 'Four boxes in a row joined by arrows. SEE: a camera frame of the street. UNDERSTAND: the same frame with the lane and the car outlined. DECIDE: the choices continue, turn, slow down and stop, with slow down highlighted. ACT: motors and steering', 1268, 306, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e8541e7bf6cde382', 'course_computer_vision', 'les_c2b34d76e1b701c6', 'explanation', 'What is NVIDIA Jetson?', '**NVIDIA Jetson** is a family of small computers designed for **computer vision**, **artificial intelligence**, **robotics** and **edge AI**. It has a graphics processor (GPU), so it runs vision and deep-learning code fast, while being small enough to sit on a robot. It runs Linux and Python with OpenCV, so the code you write on your laptop carries over.

Compare two ways to give a vehicle "brains":

| Without a computer on board | Edge AI (our project) |
|---|---|
| the vehicle''s camera sends video over a **network** to another computer | the camera''s frames are processed **on the vehicle**, by the Jetson |
| the vehicle **waits** for the answer to come back | the decision is made **on board** |
| slow, and useless if the connection drops | fast, and works without a network |

**Edge AI: AI processing happens close to where the data is generated.**', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f6deffc9de66a6ed', 'course_computer_vision', 'les_c2b34d76e1b701c6', 'explanation', 'Project hardware concept', '| Part | Kind | Job |
|---|---|---|
| **Camera** | hardware | the eyes of the vehicle |
| **NVIDIA Jetson** | hardware | the processing computer |
| **Computer vision software** | software, on the Jetson | understands what the camera sees |
| **Decision** | software, on the Jetson | chooses what should happen |
| **Motor control system** | hardware | converts the decision into movement |
| **Motors / wheels** | hardware | move the vehicle |

The exact boards and wiring may change during the semester. That doesn''t affect our code: the vision software only has to output a decision such as continue, turn, slow down or stop. Most of this course lives in the two software rows.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d558313633afe4b5', 'course_computer_vision', 'les_c2b34d76e1b701c6', 'explanation', 'What happens every second? The main loop', 'While the vehicle is operating, it repeats the same eight steps, for every frame:

1. The camera captures a frame.
2. The Jetson receives the frame.
3. The image is processed.
4. Features or objects are detected.
5. The environment is understood.
6. A decision is generated.
7. The vehicle responds.
8. Capture the next frame, and repeat.

In code, this is literally a `while True:` loop: **one pass through the loop = one frame.** Today we build steps 1 to 4, with edges as our first features.

What happens if one pass is too slow? The vehicle reacts late. That is why speed, measured in **frames per second (FPS)**, will matter.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_411cba977b962ecf', 'course_computer_vision', 'les_c2b34d76e1b701c6', 'explanation', 'Video is just many images', '**Video = frame 1 + frame 2 + frame 3 + frame 4 + …** A **frame** is one image from the video. Played quickly, a little change from frame to frame looks like motion.

**30 FPS** means about 30 frames every second: a new image about every **33 milliseconds**. Our processing has to keep up with that.

The good news: a frame is exactly the same kind of object as the images you loaded with `imread()` in lecture 2, a NumPy array of pixels. **Everything we did to `street.png` can now be applied to every frame.**', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_32e5d1b1a12697bd', 'course_computer_vision', 'les_c2b34d76e1b701c6', 'diagram', 'Four frames of a test clip', 'These are the first four frames of the test clip used to record the outputs in the next lesson: the street, shifting a few pixels each frame, like a slow camera.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_computer_vision/lessons/les_c2b34d76e1b701c6/cv-frames.png', 'Four frames of the street, side by side and numbered 1 to 4. Each one is shifted very slightly to the right compared with the one before, as if a camera were moving slowly', 1390, 270, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0a2998279af882d5', 'course_computer_vision', 'les_c2b34d76e1b701c6', 'code', 'How much time does each frame get?', 'At 30 FPS, the whole loop (capture, process, detect, decide) has about 33 ms per frame. If it takes longer, frames are processed late or skipped. This program, which runs in your browser, works out the time for three frame rates.', 'for fps in [10, 30, 60]:
    ms_per_frame = 1000 / fps
    print(fps, "FPS:", round(ms_per_frame, 1), "ms per frame")', 'python', 1, '', '10 FPS: 100.0 ms per frame
30 FPS: 33.3 ms per frame
60 FPS: 16.7 ms per frame
', '{"notes":[{"line":1,"match":"[10, 30, 60]","text":"three frame rates","shape":"circle","color":"sky"},{"line":2,"match":"1000 / fps","text":"1000 ms in a second","shape":"square","color":"yel"}],"strips":[]}', NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e18d502cec40373d', 'course_computer_vision', 'les_c2b34d76e1b701c6', 'explanation', 'We will build it step by step', '| When | Topic | What it gives the vehicle |
|---|---|---|
| Lecture 2 | image enhancement | better camera frames |
| **Lecture 3 (today)** | feature detection | the image''s structure: edges, lanes |
| Lecture 4 | object detection | cars, people and objects |
| Lecture 5 | deep-learning classification | recognising the important objects |
| Later | motion, SLAM, navigation | movement and the surroundings |
| Final | integrated vision vehicle | all capabilities working together |

**Every new lab adds one new capability to the project.**', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_1ac0a5b8e6141c03', 'course_computer_vision', 'les_c2b34d76e1b701c6', 'explanation', 'How will we divide the project?', '**Step 1, now: build the baseline together.** Every team builds the same basic vision pipeline first:

**Camera → read frames → resize → grayscale → image processing → edge detection**

That is today''s Project Part 1. Every later module (lanes, objects, decisions) uses the frames from this pipeline, so everyone must understand it, and every team has a working system before anyone specialises.

**Step 2, later: divide the modules.**

| Module | Responsible for |
|---|---|
| 1. Camera and image processing | camera connection, frame reading, resizing, image quality, noise reduction |
| 2. Lane and feature detection | edge detection, region of interest, lane detection, feature tracking |
| 3. Object detection | vehicles, people, obstacles, traffic signs |
| 4. Decision and vehicle control | use the vision results to decide: stop, turn, continue, slow down |
| 5. Integration and testing | connect the modules, test performance, debug, measure FPS, test the complete system |

**Every team should still understand the overall project pipeline**: your module only works if the others do.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_17f49db071f6eef5', 'course_computer_vision', 'les_c2b34d76e1b701c6', 'note', 'Check yourself', '::: check A team''s loop takes 50 ms per frame. How many frames per second can it handle?
???
**20 FPS**: 1000 ÷ 50 = 20. That is slower than a 30 FPS camera, so frames would arrive faster than they are processed.
:::

::: check The vehicle''s camera sees a person crossing. Which stage, SEE, UNDERSTAND, DECIDE or ACT, recognises the person, and which one stops the wheels?
???
**UNDERSTAND** recognises the person (computer vision). **DECIDE** chooses "stop", and **ACT** stops the wheels through the motor control system.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 13, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ae2a5ba2d2ad07ec', 'course_computer_vision', 'les_c2b34d76e1b701c6', 'common_mistakes', 'Common misunderstandings', '- **"The project is about driving a car."** Moving is the easy part; the course is about what the vehicle understands from its camera.
- **"Edge AI means AI at the edges of the image."** Edge AI means the processing happens on the device, close to where the data is captured.
- **"A video needs different code from an image."** A frame is an image; the same OpenCV functions work on it.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 14, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_c640841bf5568e97', 'course_computer_vision', 'les_c2b34d76e1b701c6', 'key_takeaways', 'Key takeaways', '- The project: **camera → Jetson → computer vision → understanding → decision → action**.
- **SEE → UNDERSTAND → DECIDE → ACT**; this course is mostly about UNDERSTAND.
- A Jetson is a small GPU computer for vision and AI on the vehicle itself: **edge AI**.
- The main loop handles one frame per pass; at 30 FPS each frame gets about 33 ms.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 15, 1792022400000);
DELETE FROM search_index WHERE course_id = 'course_computer_vision' AND entity_type = 'lesson' AND entity_id = 'les_c2b34d76e1b701c6';
INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'lesson', 'les_c2b34d76e1b701c6', '/courses/computer-vision/lectures/jetson-vision-vehicle', 'The semester project: a Jetson vision vehicle', 'Meet the semester project, a vehicle that sees with a camera and thinks with an NVIDIA Jetson. Learn its SEE, UNDERSTAND, DECIDE, ACT idea, what edge AI means, the main loop that runs for every frame, and how the teams will build it. Describe the project''s architecture from camera to vehicle action Explain SEE, UNDERSTAND, DECIDE and ACT with an example for each Explain what an NVIDIA Jetson is and what edge AI means Describe the main loop and calculate the time per frame at a given FPS What if the camera is moving? So far every image sat still: a file, read once. Now follow the steps: 1. a fixed image ; 2. a camera that takes images; 3. a moving camera ; 4. that camera mounted on a vehicle . What changes on the vehicle? The images keep changing, there is no time to wait, and the system must understand the road, cars and people while it moves : Camera → frames → computer vision → understanding the environment Let''s build one. The semester project ECE4704 semester project: a Jetson-based intelligent vision vehicle. The question behind it: how can we make a vehicle SEE and UNDERSTAND its environment? The project is not only about moving a car. Driving motors is the easy part. The main goal is the vehicle''s visual intelligence , and every lab adds a piece of it. The whole system in one line: Camera → NVIDIA Jetson → computer vision → environment understanding → decision → vehicle action The camera captures, the Jetson runs our computer vision, the vision results become an understanding of the scene, that understanding becomes a decision, and the decision becomes an action. The big idea: SEE → UNDERSTAND → DECIDE → ACT Stage What happens Examples --- --- --- 1. SEE the camera captures the environment camera frames 2. UNDERSTAND computer vision detects important information lane, car, person, obstacle, traffic sign 3. DECIDE the system decides what should happen continue, turn, slow down, stop 4. ACT the vehicle performs the action motors, steering Computer vision connects the camera to intelligent vehicle behaviour. This course is mostly about stage 2, because stages 3 and 4 can only be as good as what the vision system tells them. SEE, UNDERSTAND, DECIDE, ACT What is NVIDIA Jetson? NVIDIA Jetson is a family of small computers designed for computer vision , artificial intelligence , robotics and edge AI . It has a graphics processor (GPU), so it runs vision and deep-learning code fast, while being small enough to sit on a robot. It runs Linux and Python with OpenCV, so the code you write on your laptop carries over. Compare two ways to give a vehicle "brains": Without a computer on board Edge AI (our project) --- --- the vehicle''s camera sends video over a network to another computer the camera''s frames are processed on the vehicle , by the Jetson the vehicle waits for the answer to come back the decision is made on board slow, and useless if the connection drops fast, and works without a network Edge AI: AI processing happens close to where the data is generated. Project hardware concept Part Kind Job --- --- --- Camera hardware the eyes of the vehicle NVIDIA Jetson hardware the processing computer Computer vision software software, on the Jetson understands what the camera sees Decision software, on the Jetson chooses what should happen Motor control system hardware converts the decision into movement Motors / wheels hardware move the vehicle The exact boards and wiring may change during the semester. That doesn''t affect our code: the vision software only has to output a decision such as continue, turn, slow down or stop. Most of this course lives in the two software rows. What happens every second? The main loop While the vehicle is operating, it repeats the same eight steps, for every frame: 1. The camera captures a frame. 2. The Jetson receives the frame. 3. The image is processed. 4. Features or objects are detected. 5. The environment is understood. 6. A decision is generated. 7. The vehicle responds. 8. Capture the next frame, and repeat. In code, this is literally a while True: loop: one pass through the loop = one frame. Today we build steps 1 to 4, with edges as our first features. What happens if one pass is too slow? The vehicle reacts late. That is why speed, measured in frames per second (FPS) , will matter. Video is just many images Video = frame 1 + frame 2 + frame 3 + frame 4 + … A frame is one image from the video. Played quickly, a little change from frame to frame looks like motion. 30 FPS means about 30 frames every second: a new image about every 33 milliseconds . Our processing has to keep up with that. The good news: a frame is exactly the same kind of object as the images you loaded with imread() in lecture 2, a NumPy array of pixels. Everything we did to street.png can now be applied to every frame. Four frames of a test clip These are the first four frames of the test clip used to record the outputs in the next lesson: the street, shifting a few pixels each frame, like a slow camera. How much time does each frame get? At 30 FPS, the whole loop (capture, process, detect, decide) has about 33 ms per frame. If it takes longer, frames are processed late or skipped. This program, which runs in your browser, works out the time for three frame rates. for fps in [10, 30, 60]: ms_per_frame = 1000 / fps print(fps, "FPS:", round(ms_per_frame, 1), "ms per frame") We will build it step by step When Topic What it gives the vehicle --- --- --- Lecture 2 image enhancement better camera frames Lecture 3 (today) feature detection the image''s structure: edges, lanes Lecture 4 object detection cars, people and objects Lecture 5 deep-learning classification recognising the important objects Later motion, SLAM, navigation movement and the surroundings Final integrated vision vehicle all capabilities working together Every new lab adds one new capability to the project. How will we divide the project? Step 1, now: build the baseline together. Every team builds the same basic vision pipeline first: Camera → read frames → resize → grayscale → image processing → edge detection That is today''s Project Part 1. Every later module (lanes, objects, decisions) uses the frames from this pipeline, so everyone must understand it, and every team has a working system before anyone specialises. Step 2, later: divide the modules. Module Responsible for --- --- 1. Camera and image processing camera connection, frame reading, resizing, image quality, noise reduction 2. Lane and feature detection edge detection, region of interest, lane detection, feature tracking 3. Object detection vehicles, people, obstacles, traffic signs 4. Decision and vehicle control use the vision results to decide: stop, turn, continue, slow down 5. Integration and testing connect the modules, test performance, debug, measure FPS, test the complete system Every team should still understand the overall project pipeline : your module only works if the others do. Check yourself 20 FPS : 1000 ÷ 50 = 20. That is slower than a 30 FPS camera, so frames would arrive faster than they are processed. UNDERSTAND recognises the person (computer vision). DECIDE chooses "stop", and ACT stops the wheels through the motor control system. Common misunderstandings - "The project is about driving a car." Moving is the easy part; the course is about what the vehicle understands from its camera. - "Edge AI means AI at the edges of the image." Edge AI means the processing happens on the device, close to where the data is captured. - "A video needs different code from an image." A frame is an image; the same OpenCV functions work on it. Key takeaways - The project: camera → Jetson → computer vision → understanding → decision → action . - SEE → UNDERSTAND → DECIDE → ACT ; this course is mostly about UNDERSTAND. - A Jetson is a small GPU computer for vision and AI on the vehicle itself: edge AI . - The main loop handles one frame per pass; at 30 FPS each frame gets about 33 ms.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_44febf2b824a078c', 'course_computer_vision', 'top_f0b6f4af7c3d4192', 'live-camera-pipeline', 'Project part 1: a live camera pipeline', 'Build the project''s first milestone. Open a camera with cv2.VideoCapture, read frames in a loop, and resize, convert, blur and find edges in every frame, with three live windows and q to quit. Then tune the pipeline and look ahead to lane detection.', 3, 17, 'medium', '["Open a camera with cv2.VideoCapture and check it with isOpened()","Read frames in a while loop and stop when ret is False","Apply resize, grayscale, Gaussian blur and Canny to every live frame","Leave the loop with the q key and release the camera","Tune the blur kernel and Canny thresholds and explain the trade-off"]', '["The semester project: a Jetson vision vehicle","Features, edges and the Canny detector"]', 12, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
