INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_827e9b6d6383ec94', 'course_programming_applications', 'top_57b5d29d21e9f710', 'what-is-programming-and-why-python', 'What is programming, and why Python?', 'A program is a list of instructions that turns a problem into a result. See why Python is a good language to write them in, how Python runs your code line by line, and write your first program.', 1, 1, 'easy', '["Say what programming is in one sentence","Give reasons why Python is popular, and fields where it is used","Explain what the Python interpreter does with your program","Write and run a program that prints text with print()"]', '["None. This is the first lecture of the course."]', 7, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
