INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_42927fc42f4ef3e6', 'course_programming_applications', 'les_827e9b6d6383ec94', 'explanation', 'Programming is giving instructions', '**Programming** means giving a computer instructions so that it can perform a task or solve a problem. The computer follows those instructions exactly, one after another. It never guesses what you meant.

Every program follows the same path:

**Problem → Program → Computer → Result**

You start with a problem ("what is the average of these marks?"), write a program that solves it, the computer runs the program, and you get a result ("87.67").

You use programs like this every day:

- a **calculator** turns the numbers you press into an answer;
- a **temperature monitor** reads a sensor and switches a fan on when it gets too hot;
- a **website** turns a click into a new page;
- an **automated system**, such as a factory line or a traffic light, repeats its steps all day without a person.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_63600f1e9c0170cb', 'course_programming_applications', 'les_827e9b6d6383ec94', 'explanation', 'Why Python?', 'There are hundreds of programming languages. Python is one of the most popular, especially for beginners and for engineers, for six reasons:

| Advantage | What it means for you |
|---|---|
| Simple syntax | The code reads almost like English, with few symbols to remember. |
| Fewer lines of code | The same task usually needs fewer lines than in C++ or Java. |
| Easy debugging | Error messages name the line and the kind of mistake. |
| Large library ecosystem | Ready-made code exists for maths, data, images, AI, websites and much more. |
| Cross-platform | The same program runs on Windows, macOS and Linux. |
| Beginner friendly | You can write a useful program in your first hour. |

The idea behind all six: **Python lets you focus on solving the problem, not on complicated syntax.**', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2c315f37dffe31bf', 'course_programming_applications', 'les_827e9b6d6383ec94', 'example', 'One line instead of six', 'Here is the classic first program, which only prints a greeting. In C++ it takes six lines:

```cpp
#include <iostream>
using namespace std;
int main() {
    cout << "Hello, World!" << endl;
    return 0;
}
```

In Python it takes one:

```python
print("Hello, World!")
```

Both programs print the same line. Python needs no `main()`, no semicolons and no `#include`: you write the instruction itself.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_efdc41b418cdc288', 'course_programming_applications', 'les_827e9b6d6383ec94', 'explanation', 'Where is Python used?', '| Field | An example |
|---|---|
| Web development | the server side of websites and apps |
| Data analysis | reading a spreadsheet of results and finding trends |
| Artificial intelligence | programs that answer questions or recognise speech |
| Machine learning | a model that learns to predict a price from past data |
| Automation | renaming a thousand files or sending reports every morning |
| Science | simulations and calculations in physics, chemistry and biology |
| Engineering | reading sensors, controlling devices, processing signals |
| Security | scanning a network for weak passwords or open ports |

Later in this course you will use Python for graphics, and the Computer Vision course on this site uses Python to work with images.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_31f1460f0f114f5f', 'course_programming_applications', 'les_827e9b6d6383ec94', 'explanation', 'How Python runs your program', 'You write a Python program as plain text, saved in a file that ends in `.py`. A program called the **Python interpreter** then runs it:

**Python code → Python interpreter → the computer executes it → output**

The interpreter works in two steps:

1. It reads the whole file and checks the **grammar** (the syntax). A missing bracket or quote stops everything before any line runs.
2. It then **executes the program line by line**, from the top down. Each line finishes before the next one starts.

Because of step 2, a mistake in the middle of a program only shows up when Python reaches it, and the lines above it have already done their work. The example below shows exactly that.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_29a72bbcd0033177', 'course_programming_applications', 'les_827e9b6d6383ec94', 'example', 'An error stops the program at that line', 'Press **Run**. Lines 1 and 2 print, then Python reaches line 3, which uses a name it has never seen, and stops with a `NameError`. Line 4 never runs.', 'print("Line 1 runs")
print("Line 2 runs")
print(score)
print("Line 4 never runs")', 'python', 1, '', NULL, '{"notes":[{"line":3,"match":"score","text":"never created: NameError","shape":"tri","color":"coral"},{"line":4,"match":"print","text":"never reached","shape":"square","color":"sky"}],"strips":[]}', NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0ffc30c2621e9e63', 'course_programming_applications', 'les_827e9b6d6383ec94', 'code', 'Your first Python program', '`print()` displays information on the screen. Whatever you put between the brackets is shown. Text goes inside quotes.', 'print("Hello, World!")', 'python', 1, '', 'Hello, World!
', '{"notes":[{"line":1,"match":"print","text":"shows it on the screen","shape":"circle","color":"sky"},{"line":1,"match":"\"Hello, World!\"","text":"the text to display","shape":"square","color":"yel"}],"strips":[]}', NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d4645d700abf4f86', 'course_programming_applications', 'les_827e9b6d6383ec94', 'explanation', 'Reading the print line', '`print("Hello, World!")` has three parts:

- `print` is the name of a **function**: a ready-made instruction that Python already knows.
- The **brackets** `( )` hold what you give the function to work with.
- `"Hello, World!"` is a piece of **text**. The quotes tell Python where the text starts and ends. The quotes themselves are not printed.

Each `print()` starts a new line. You can also give `print()` several things separated by commas: it prints them on one line with a space between them.

Lines that start with `#` are **comments**. Python skips them. Programmers use them to explain the code to people.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_536585b1f340033c', 'course_programming_applications', 'les_827e9b6d6383ec94', 'code', 'Several lines, and a comment', '', '# My first program prints three lines
print("Hello, Python!")
print("Welcome to Programming Applications")
print("Python", "is", "fun")', 'python', 1, '', 'Hello, Python!
Welcome to Programming Applications
Python is fun
', '{"notes":[{"line":1,"match":"#","text":"a comment: Python skips it","shape":"circle","color":"green"},{"line":4,"match":",","text":"commas: a space between","shape":"square","color":"sky"}],"strips":[]}', NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ce9ffce98f647e17', 'course_programming_applications', 'les_827e9b6d6383ec94', 'note', 'Check yourself', '::: check What does this program print?
```python
print("Ready")
# print("Set")
print("Go", "!")
```
???
```output
Ready
Go !
```
The second line is a comment, so it never runs. The comma in the last line puts a space between `Go` and `!`.
:::

::: check Python finds a mistake on line 5 of a 10-line program. Which lines have already run?
???
If the mistake is a grammar mistake (a missing bracket or quote), **none**: Python checks the grammar of the whole file before running anything. Any other mistake (like using a name that doesn''t exist) is found while running, so lines 1 to 4 have already run.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d0b83e4302b9635b', 'course_programming_applications', 'les_827e9b6d6383ec94', 'common_mistakes', 'Common mistakes', '- **Forgetting the quotes.** `print(Hello)` makes Python look for something called `Hello`, and stops with `NameError`. Text always goes in quotes: `print("Hello")`.
- **Capital letters.** Python is case-sensitive: `Print("Hi")` is a `NameError`. The function is `print`, all small letters.
- **Missing a bracket.** `print("Hi"` is a grammar mistake (`SyntaxError`), so nothing in the file runs.
- **Curly quotes.** Code copied from Word or PowerPoint may use “curly” quotes, which Python doesn''t accept. Type straight quotes `"` in your editor.
- **Spaces at the start of a line.** In Python the start of a line matters. `   print("Hi")` with spaces in front, on its own, is an `IndentationError`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b37437042e38f4ac', 'course_programming_applications', 'les_827e9b6d6383ec94', 'key_takeaways', 'Key takeaways', '- Programming is giving a computer exact instructions: **problem → program → computer → result**.
- Python is popular because its code is short and readable, and it has libraries for almost everything.
- The interpreter checks the whole file''s grammar, then runs the program **line by line**, from the top.
- `print()` shows text on the screen; text goes in quotes, and commas put spaces between items.
- `#` starts a comment, which Python ignores.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1792022400000);
