INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_applications', 'lesson', 'les_827e9b6d6383ec94', '/courses/programming-applications/lectures/what-is-programming-and-why-python', 'What is programming, and why Python?', 'A program is a list of instructions that turns a problem into a result. See why Python is a good language to write them in, how Python runs your code line by line, and write your first program. Say what programming is in one sentence Give reasons why Python is popular, and fields where it is used Explain what the Python interpreter does with your program Write and run a program that prints text with print() Programming is giving instructions Programming means giving a computer instructions so that it can perform a task or solve a problem. The computer follows those instructions exactly, one after another. It never guesses what you meant. Every program follows the same path: Problem → Program → Computer → Result You start with a problem ("what is the average of these marks?"), write a program that solves it, the computer runs the program, and you get a result ("87.67"). You use programs like this every day: - a calculator turns the numbers you press into an answer; - a temperature monitor reads a sensor and switches a fan on when it gets too hot; - a website turns a click into a new page; - an automated system , such as a factory line or a traffic light, repeats its steps all day without a person. Why Python? There are hundreds of programming languages. Python is one of the most popular, especially for beginners and for engineers, for six reasons: Advantage What it means for you --- --- Simple syntax The code reads almost like English, with few symbols to remember. Fewer lines of code The same task usually needs fewer lines than in C++ or Java. Easy debugging Error messages name the line and the kind of mistake. Large library ecosystem Ready-made code exists for maths, data, images, AI, websites and much more. Cross-platform The same program runs on Windows, macOS and Linux. Beginner friendly You can write a useful program in your first hour. The idea behind all six: Python lets you focus on solving the problem, not on complicated syntax. One line instead of six Here is the classic first program, which only prints a greeting. In C++ it takes six lines: include <iostream using namespace std; int main() { cout << "Hello, World!" << endl; return 0; } In Python it takes one: print("Hello, World!") Both programs print the same line. Python needs no main() , no semicolons and no include : you write the instruction itself. Where is Python used? Field An example --- --- Web development the server side of websites and apps Data analysis reading a spreadsheet of results and finding trends Artificial intelligence programs that answer questions or recognise speech Machine learning a model that learns to predict a price from past data Automation renaming a thousand files or sending reports every morning Science simulations and calculations in physics, chemistry and biology Engineering reading sensors, controlling devices, processing signals Security scanning a network for weak passwords or open ports Later in this course you will use Python for graphics, and the Computer Vision course on this site uses Python to work with images. How Python runs your program You write a Python program as plain text, saved in a file that ends in .py . A program called the Python interpreter then runs it: Python code → Python interpreter → the computer executes it → output The interpreter works in two steps: 1. It reads the whole file and checks the grammar (the syntax). A missing bracket or quote stops everything before any line runs. 2. It then executes the program line by line , from the top down. Each line finishes before the next one starts. Because of step 2, a mistake in the middle of a program only shows up when Python reaches it, and the lines above it have already done their work. The example below shows exactly that. An error stops the program at that line Press Run . Lines 1 and 2 print, then Python reaches line 3, which uses a name it has never seen, and stops with a NameError . Line 4 never runs. print("Line 1 runs") print("Line 2 runs") print(score) print("Line 4 never runs") Your first Python program print() displays information on the screen. Whatever you put between the brackets is shown. Text goes inside quotes. print("Hello, World!") Reading the print line print("Hello, World!") has three parts: - print is the name of a function : a ready-made instruction that Python already knows. - The brackets ( ) hold what you give the function to work with. - "Hello, World!" is a piece of text . The quotes tell Python where the text starts and ends. The quotes themselves are not printed. Each print() starts a new line. You can also give print() several things separated by commas: it prints them on one line with a space between them. Lines that start with are comments . Python skips them. Programmers use them to explain the code to people. Several lines, and a comment # My first program prints three lines print("Hello, Python!") print("Welcome to Programming Applications") print("Python", "is", "fun") Check yourself print("Ready") print("Set") print("Go", "!") Ready Go ! The second line is a comment, so it never runs. The comma in the last line puts a space between Go and ! . If the mistake is a grammar mistake (a missing bracket or quote), none : Python checks the grammar of the whole file before running anything. Any other mistake (like using a name that doesn''t exist) is found while running, so lines 1 to 4 have already run. Common mistakes - Forgetting the quotes. print(Hello) makes Python look for something called Hello , and stops with NameError . Text always goes in quotes: print("Hello") . - Capital letters. Python is case-sensitive: Print("Hi") is a NameError . The function is print , all small letters. - Missing a bracket. print("Hi" is a grammar mistake ( SyntaxError ), so nothing in the file runs. - Curly quotes. Code copied from Word or PowerPoint may use “curly” quotes, which Python doesn''t accept. Type straight quotes " in your editor. - Spaces at the start of a line. In Python the start of a line matters. print("Hi") with spaces in front, on its own, is an IndentationError . Key takeaways - Programming is giving a computer exact instructions: problem → program → computer → result . - Python is popular because its code is short and readable, and it has libraries for almost everything. - The interpreter checks the whole file''s grammar, then runs the program line by line , from the top. - print() shows text on the screen; text goes in quotes, and commas put spaces between items. - starts a comment, which Python ignores.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_44e9092859c84394', 'course_programming_applications', 'top_44e9092859c84394', 'variables-and-data-types', 'Variables and data types', 'Store values in named variables, change them, and meet Python''s four basic data types, int, float, str and bool, with type() to check which one a value is.', 1, 2, 'easy', '["Create a variable with = and use its value later","Change a variable and predict its new value","Recognise int, float, str and bool values","Use type() to find a value''s data type","Choose variable names that follow Python''s rules"]', '["What is programming, and why Python?"]', 8, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_programming_applications' AND lesson_id = 'les_44e9092859c84394';
DELETE FROM lesson_relations WHERE course_id = 'course_programming_applications' AND lesson_id = 'les_44e9092859c84394';
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_cb3d12fd75cedb52', 'course_programming_applications', 'les_44e9092859c84394', 'explanation', 'A variable is a named box', 'A **variable** is a named location in the computer''s memory that stores a value. You can think of it as a box with a label on it: the label is the variable''s name, and the box holds the data.

```python
age = 20
```

This line creates a variable called `age` and stores `20` in it. From now on, whenever the program says `age`, Python uses the value inside the box: **age → 20**.

The `=` sign means **"store"**, not "is equal to". Read `age = 20` as "store 20 in age". The name always goes on the left, the value on the right.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0cc97317070b070f', 'course_programming_applications', 'les_44e9092859c84394', 'code', 'Three variables', 'Variables can hold different kinds of data: a whole number, a piece of text or a decimal number. `print()` shows the value stored in each one.', 'name = "Omar"
age = 22
temperature = 30.5

print(name)
print(age)
print(temperature)', 'python', 1, '', 'Omar
22
30.5
', '{"notes":[{"line":1,"match":"name","text":"text goes in quotes","shape":"circle","color":"sky"},{"line":2,"match":"age","text":"a whole number","shape":"square","color":"yel"},{"line":3,"match":"temperature","text":"a decimal number","shape":"diamond","color":"green"},{"line":5,"match":"name","text":"no quotes: the value","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_8a90ad9b6e3c4bb4', 'course_programming_applications', 'les_44e9092859c84394', 'explanation', 'The name, not the word', 'Notice the difference between `print(name)` and `print("name")`:

- `print(name)` has **no quotes**, so Python looks in the box called `name` and prints what it holds: `Omar`.
- `print("name")` has quotes, so it is just the word *name*, and Python prints `name`.

Quotes mean "this exact text". No quotes means "the value of this variable".', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0de33d3a1f6a17af', 'course_programming_applications', 'les_44e9092859c84394', 'code', 'Changing a variable', 'A variable can be given a new value at any time. The new value **replaces** the old one; the box only ever holds one value. A variable can even be used to work out its own new value.', 'score = 10
print(score)
score = 15
print(score)
score = score + 5
print(score)', 'python', 1, '', '10
15
20
', '{"notes":[{"line":3,"match":"score = 15","text":"the old 10 is replaced","shape":"circle","color":"coral"},{"line":5,"match":"score + 5","text":"15 + 5, stored back","shape":"square","color":"yel"}],"strips":[]}', NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_1e4c265b44251f44', 'course_programming_applications', 'les_44e9092859c84394', 'explanation', 'Reading score = score + 5', 'Python always works out the **right side first**, then stores the result in the variable on the left. So `score = score + 5` means: take the current value of `score` (15), add 5 (giving 20), and store 20 back in `score`.

In maths `score = score + 5` would be impossible. In Python it is one of the most common lines you will write.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0fed659d0bc40a96', 'course_programming_applications', 'les_44e9092859c84394', 'explanation', 'Four basic data types', 'Every value in Python has a **data type**, which says what kind of value it is and what you can do with it. These four are the ones you will use all the time:

| Type | Name in Python | What it holds | Example |
|---|---|---|---|
| Integer | `int` | whole numbers, positive or negative | `age = 20` |
| Float | `float` | numbers with a decimal point | `temperature = 30.5` |
| String | `str` | text, written in quotes | `name = "Ahmed"` |
| Boolean | `bool` | only `True` or `False` | `is_on = True` |

You don''t write the type yourself. Python decides it from the value: `20` is an `int`, `20.0` is a `float`, `"20"` is a `str`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_8275159f8fbffe38', 'course_programming_applications', 'les_44e9092859c84394', 'code', 'Asking Python for the type', 'The `type()` function tells you the data type of any value or variable.', 'student_name = "Ahmed"
student_age = 20
gpa = 3.4
is_passed = True

print(type(student_name))
print(type(student_age))
print(type(gpa))
print(type(is_passed))', 'python', 1, '', '<class ''str''>
<class ''int''>
<class ''float''>
<class ''bool''>
', '{"notes":[{"line":4,"match":"True","text":"capital T, no quotes","shape":"circle","color":"green"},{"line":6,"match":"type","text":"which data type?","shape":"square","color":"sky"}],"strips":[]}', NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0477d49000e19141', 'course_programming_applications', 'les_44e9092859c84394', 'explanation', 'Reading the answer', 'Python writes the type as `<class ''str''>`. For now, read **class** as "kind of value": `str` means String, `int` means integer, and so on. You will meet the word *class* again at the end of this course, when you learn to make your own kinds of objects.

A Boolean is written `True` or `False` with a **capital first letter** and **no quotes**. `"True"` in quotes is a String that happens to contain the word True.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_c4b04dde29fc77cc', 'course_programming_applications', 'les_44e9092859c84394', 'example', '20 and "20" are different values', 'A number in quotes is text, not a number. Python treats the two very differently: numbers are added, Strings are joined end to end.', 'print(type(20), type("20"))
print(20 + 5)
print("20" + "5")', 'python', 1, '', '<class ''int''> <class ''str''>
25
205
', '{"notes":[{"line":2,"match":"20 + 5","text":"numbers: added","shape":"circle","color":"green"},{"line":3,"match":"\"20\" + \"5\"","text":"text: joined together","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0394231ac805a481', 'course_programming_applications', 'les_44e9092859c84394', 'explanation', 'Naming rules', 'A variable name must follow these rules, or Python stops with a `SyntaxError`:

- it uses only **letters, digits and the underscore** `_` (no spaces, no `-`);
- it **doesn''t start with a digit**: `student1` is fine, `1student` is not;
- it isn''t one of Python''s own words, such as `if`, `else`, `for` or `True`.

Python is **case-sensitive**: `age`, `Age` and `AGE` are three different variables.

Good names say what the value means. Python programmers write them in small letters with underscores between the words: `student_age`, `is_passed`, `max_temperature`.

::: tip
Avoid names that Python already uses for its own functions, such as `print`, `input`, `type`, `len` or `sum`. Python lets you do it, but the original function stops working for the rest of your program.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_1e3fdf222299b858', 'course_programming_applications', 'les_44e9092859c84394', 'note', 'Check yourself', '::: check What does this program print?
```python
x = 4
y = x
x = 9
print(x, y)
```
???
```output
9 4
```
`y = x` copies the value 4 into `y` at that moment. Changing `x` later doesn''t change `y`.
:::

::: check What is the type of each value: `7`, `7.0`, `"7"`, `False`?
???
`7` is an `int`, `7.0` is a `float`, `"7"` is a `str` (it has quotes), and `False` is a `bool`.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_32f37bbc5b322f0c', 'course_programming_applications', 'les_44e9092859c84394', 'common_mistakes', 'Common mistakes', '- **Putting the value on the left.** `20 = age` is a `SyntaxError`. The variable''s name always goes on the left of `=`.
- **Using a variable before creating it.** `print(total)` before any `total = …` line stops with `NameError: name ''total'' is not defined`.
- **Mixing up the case.** `Name = "Omar"` then `print(name)` is a `NameError`: `Name` and `name` are different variables.
- **Spaces in a name.** `student age = 20` is a `SyntaxError`. Use `student_age`.
- **Writing true without a capital.** `is_on = true` makes Python look for a variable called `true`. Booleans are `True` and `False`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2b7fd6cfb4082eaf', 'course_programming_applications', 'les_44e9092859c84394', 'key_takeaways', 'Key takeaways', '- A variable is a named box that holds one value; `=` means "store the right side in the left side".
- A new value replaces the old one, and `x = x + 1` uses the old value to make the new one.
- The four basic types are `int` (whole numbers), `float` (decimals), `str` (text in quotes) and `bool` (`True` / `False`).
- `type(value)` tells you a value''s type; `20` and `"20"` are different types.
- Names use letters, digits and `_`, can''t start with a digit, and are case-sensitive.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 13, 1792022400000);
