INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_applications', 'lesson', 'les_44e9092859c84394', '/courses/programming-applications/lectures/variables-and-data-types', 'Variables and data types', 'Store values in named variables, change them, and meet Python''s four basic data types, int, float, str and bool, with type() to check which one a value is. Create a variable with = and use its value later Change a variable and predict its new value Recognise int, float, str and bool values Use type() to find a value''s data type Choose variable names that follow Python''s rules A variable is a named box A variable is a named location in the computer''s memory that stores a value. You can think of it as a box with a label on it: the label is the variable''s name, and the box holds the data. age = 20 This line creates a variable called age and stores 20 in it. From now on, whenever the program says age , Python uses the value inside the box: age → 20 . The = sign means "store" , not "is equal to". Read age = 20 as "store 20 in age". The name always goes on the left, the value on the right. Three variables Variables can hold different kinds of data: a whole number, a piece of text or a decimal number. print() shows the value stored in each one. name = "Omar" age = 22 temperature = 30.5 print(name) print(age) print(temperature) The name, not the word Notice the difference between print(name) and print("name") : - print(name) has no quotes , so Python looks in the box called name and prints what it holds: Omar . - print("name") has quotes, so it is just the word name , and Python prints name . Quotes mean "this exact text". No quotes means "the value of this variable". Changing a variable A variable can be given a new value at any time. The new value replaces the old one; the box only ever holds one value. A variable can even be used to work out its own new value. score = 10 print(score) score = 15 print(score) score = score + 5 print(score) Reading score = score + 5 Python always works out the right side first , then stores the result in the variable on the left. So score = score + 5 means: take the current value of score (15), add 5 (giving 20), and store 20 back in score . In maths score = score + 5 would be impossible. In Python it is one of the most common lines you will write. Four basic data types Every value in Python has a data type , which says what kind of value it is and what you can do with it. These four are the ones you will use all the time: Type Name in Python What it holds Example --- --- --- --- Integer int whole numbers, positive or negative age = 20 Float float numbers with a decimal point temperature = 30.5 String str text, written in quotes name = "Ahmed" Boolean bool only True or False is on = True You don''t write the type yourself. Python decides it from the value: 20 is an int , 20.0 is a float , "20" is a str . Asking Python for the type The type() function tells you the data type of any value or variable. student_name = "Ahmed" student_age = 20 gpa = 3.4 is_passed = True print(type(student_name)) print(type(student_age)) print(type(gpa)) print(type(is_passed)) Reading the answer Python writes the type as <class ''str'' . For now, read class as "kind of value": str means String, int means integer, and so on. You will meet the word class again at the end of this course, when you learn to make your own kinds of objects. A Boolean is written True or False with a capital first letter and no quotes . "True" in quotes is a String that happens to contain the word True. 20 and "20" are different values A number in quotes is text, not a number. Python treats the two very differently: numbers are added, Strings are joined end to end. print(type(20), type("20")) print(20 + 5) print("20" + "5") Naming rules A variable name must follow these rules, or Python stops with a SyntaxError : - it uses only letters, digits and the underscore (no spaces, no - ); - it doesn''t start with a digit : student1 is fine, 1student is not; - it isn''t one of Python''s own words, such as if , else , for or True . Python is case-sensitive : age , Age and AGE are three different variables. Good names say what the value means. Python programmers write them in small letters with underscores between the words: student age , is passed , max temperature . Avoid names that Python already uses for its own functions, such as print , input , type , len or sum . Python lets you do it, but the original function stops working for the rest of your program. Check yourself x = 4 y = x x = 9 print(x, y) 9 4 y = x copies the value 4 into y at that moment. Changing x later doesn''t change y . 7 is an int , 7.0 is a float , "7" is a str (it has quotes), and False is a bool . Common mistakes - Putting the value on the left. 20 = age is a SyntaxError . The variable''s name always goes on the left of = . - Using a variable before creating it. print(total) before any total = … line stops with NameError: name ''total'' is not defined . - Mixing up the case. Name = "Omar" then print(name) is a NameError : Name and name are different variables. - Spaces in a name. student age = 20 is a SyntaxError . Use student age . - Writing true without a capital. is on = true makes Python look for a variable called true . Booleans are True and False . Key takeaways - A variable is a named box that holds one value; = means "store the right side in the left side". - A new value replaces the old one, and x = x + 1 uses the old value to make the new one. - The four basic types are int (whole numbers), float (decimals), str (text in quotes) and bool ( True / False ). - type(value) tells you a value''s type; 20 and "20" are different types. - Names use letters, digits and , can''t start with a digit, and are case-sensitive.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_02f87c25ff83b0e2', 'course_programming_applications', 'top_dbb55f4ba4d26c33', 'input-processing-and-output', 'Input, processing and output', 'Every program takes input, processes it and produces output. Read what the user types with input(), turn it into a number with int() or float(), and print the result.', 1, 3, 'easy', '["Name the input, processing and output of a small program","Read text from the user with input() and a prompt","Explain why input() always gives a String","Convert typed text to a number with int() or float()","Print several values on one line with print()"]', '["Variables and data types"]', 6, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
