INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_7685490f8f3a42ad', 'course_programming_applications', 'les_02f87c25ff83b0e2', 'explanation', 'Input, processing, output', 'Almost every program has the same basic structure, in three parts:

**Input → Processing → Output**

- **Input**: the data the program receives, for example a number the user types.
- **Processing**: what the program does with it, for example multiplying it by 2.
- **Output**: the result the program shows, for example printing the answer.

Before you write a program, name these three parts. If you can say what goes in and what must come out, the processing in the middle is much easier to plan.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2163784fde9cdb46', 'course_programming_applications', 'les_02f87c25ff83b0e2', 'code', 'A complete input, processing, output program', 'The user types a number; the program doubles it and prints the result. The box under the code is what the user types. Change it and press **Run** again.', 'number = int(input("Enter a number: "))
result = number * 2
print(result)', 'python', 1, '7
', 'Enter a number: 7
14
', '{"notes":[{"line":1,"match":"input","text":"INPUT: read what is typed","shape":"circle","color":"sky"},{"line":2,"match":"number * 2","text":"PROCESSING","shape":"square","color":"yel"},{"line":3,"match":"print","text":"OUTPUT","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_8eee7fb28d50a8e2', 'course_programming_applications', 'les_02f87c25ff83b0e2', 'explanation', 'How input() works', '`input()` does three things:

1. It shows the text in its brackets, called the **prompt**, so the user knows what to type.
2. It **waits** until the user types something and presses Enter.
3. It **gives back** what was typed, which you usually store in a variable.

`print()` and `input()` are a pair: **`input()` gets information from the user, `print()` displays information to the user.**

Leave a space at the end of the prompt, as in `"Enter your name: "`, so the user''s typing doesn''t stick to the colon.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_69210c077fb6593c', 'course_programming_applications', 'les_02f87c25ff83b0e2', 'code', 'Greeting the user', '', 'name = input("Enter your name: ")
print("Hello", name)', 'python', 1, 'Omar
', 'Enter your name: Omar
Hello Omar
', '{"notes":[{"line":1,"match":"\"Enter your name: \"","text":"the prompt","shape":"circle","color":"sky"},{"line":2,"match":",","text":"comma: adds a space","shape":"square","color":"yel"}],"strips":[]}', NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d8d2fa0725dfece4', 'course_programming_applications', 'les_02f87c25ff83b0e2', 'explanation', 'input() always gives a String', 'Whatever the user types, even `20`, `input()` gives it back as **text** (a `str`). Python can''t know whether you meant a number or a word, so it keeps exactly the characters that were typed.

That matters as soon as you want to calculate. Joining two Strings with `+` puts them side by side; adding two numbers adds them. To do arithmetic with typed numbers, convert the text first:

| Function | Turns text into | Example |
|---|---|---|
| `int()` | a whole number | `int("20")` is `20` |
| `float()` | a decimal number | `float("2.5")` is `2.5` |
| `str()` | text (the other way round) | `str(20)` is `"20"` |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_9b0bafe0f43380c0', 'course_programming_applications', 'les_02f87c25ff83b0e2', 'example', 'Text that looks like a number', '`x` and `y` hold the text `"20"`. With `+`, the two Strings are joined. Converted with `int()`, they are added.', 'x = "20"
y = "20"
print(x + y)
print(int(x) + int(y))', 'python', 1, '', '2020
40
', '{"notes":[{"line":3,"match":"x + y","text":"text: joined, not added","shape":"tri","color":"coral"},{"line":4,"match":"int(x)","text":"text → number","shape":"circle","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_858f590256611da0', 'course_programming_applications', 'les_02f87c25ff83b0e2', 'code', 'Adding two numbers from the user', '`int(input(...))` reads the text and converts it in one line: Python runs the inner function first, then the outer one.', 'x = int(input("Enter first number: "))
y = int(input("Enter second number: "))

