', '{"notes":[{"line":1,"match":"int(input(","text":"read, then convert","shape":"circle","color":"sky"},{"line":4,"match":"x + y","text":"numbers now: 5 + 7","shape":"square","color":"yel"},{"line":6,"match":"\"Result =\", result","text":"text, then the value","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b9bdf1e4bbbaba7a', 'course_programming_applications', 'les_02f87c25ff83b0e2', 'code', 'Reading a name and an age', 'A name stays as text, so it needs no conversion. An age is a number, so it goes through `int()`, and then the program can calculate with it.', 'name = input("Enter your name: ")
