INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ac9094f7696a6251', 'course_programming_applications', 'les_02f87c25ff83b0e2', 'explanation', 'Decimals: float()', '`int()` only accepts whole numbers. For a value such as a temperature or a price, use `float()`:

```python
temperature = float(input("Enter the temperature: "))
```

If the user types `30.5`, `temperature` holds the number `30.5`. If they type `30`, it holds `30.0`, which is still a `float`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_35e7046bc40355af', 'course_programming_applications', 'les_02f87c25ff83b0e2', 'note', 'Check yourself', '::: check What does this program print?
```python
a = "3"
b = 3
print(a * 2, b * 2)
```
???
```output
33 6
```
`a` is the String `"3"`, and a String times 2 repeats it: `"33"`. `b` is the number 3, so `b * 2` is 6.
:::

::: check A user types `2.5` into `int(input("How many hours? "))`. What happens?
???
The program stops with `ValueError: invalid literal for int() with base 10: ''2.5''`. `int()` only accepts text that looks like a whole number. Use `float()` when the answer may have a decimal point.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_dc0d240d2b05cad4', 'course_programming_applications', 'les_02f87c25ff83b0e2', 'common_mistakes', 'Common mistakes', '- **Forgetting to convert.** `age = input("Age: ")` then `age + 1` stops with `TypeError: can only concatenate str (not "int") to str`. Wrap the input: `int(input("Age: "))`.
- **Converting a word.** If the user types `twenty`, `int()` raises a `ValueError`. Programs later in the course check the input before converting it.
- **Missing brackets.** `int(input("Age: ")` has one closing bracket too few: each `(` needs its own `)`.
- **No space in the prompt.** `input("Name:")` makes the typing look like `Name:Omar`. End the prompt with a space.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ae7620c2a7207a57', 'course_programming_applications', 'les_02f87c25ff83b0e2', 'key_takeaways', 'Key takeaways', '- Programs follow **input → processing → output**; plan those three parts before coding.
- `input("prompt ")` shows the prompt, waits for the user, and returns what was typed.
- What `input()` returns is **always a String**, even when the user types digits.
- Use `int()` for whole numbers and `float()` for decimals before doing arithmetic.
- `print(a, b)` prints several values on one line, separated by spaces.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1792022400000);
DELETE FROM search_index WHERE course_id = 'course_programming_applications' AND entity_type = 'lesson' AND entity_id = 'les_02f87c25ff83b0e2';
INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_applications', 'lesson', 'les_02f87c25ff83b0e2', '/courses/programming-applications/lectures/input-processing-and-output', 'Input, processing and output', 'Every program takes input, processes it and produces output. Read what the user types with input(), turn it into a number with int() or float(), and print the result. Name the input, processing and output of a small program Read text from the user with input() and a prompt Explain why input() always gives a String Convert typed text to a number with int() or float() Print several values on one line with print() Input, processing, output Almost every program has the same basic structure, in three parts: Input → Processing → Output - Input : the data the program receives, for example a number the user types. - Processing : what the program does with it, for example multiplying it by 2. - Output : the result the program shows, for example printing the answer. Before you write a program, name these three parts. If you can say what goes in and what must come out, the processing in the middle is much easier to plan. A complete input, processing, output program The user types a number; the program doubles it and prints the result. The box under the code is what the user types. Change it and press Run again. number = int(input("Enter a number: ")) result = number * 2 print(result) How input() works input() does three things: 1. It shows the text in its brackets, called the prompt , so the user knows what to type. 2. It waits until the user types something and presses Enter. 3. It gives back what was typed, which you usually store in a variable. print() and input() are a pair: input() gets information from the user, print() displays information to the user. Leave a space at the end of the prompt, as in "Enter your name: " , so the user''s typing doesn''t stick to the colon. Greeting the user name = input("Enter your name: ") print("Hello", name) input() always gives a String Whatever the user types, even 20 , input() gives it back as text (a str ). Python can''t know whether you meant a number or a word, so it keeps exactly the characters that were typed. That matters as soon as you want to calculate. Joining two Strings with + puts them side by side; adding two numbers adds them. To do arithmetic with typed numbers, convert the text first: Function Turns text into Example --- --- --- int() a whole number int("20") is 20 float() a decimal number float("2.5") is 2.5 str() text (the other way round) str(20) is "20" Text that looks like a number x and y hold the text "20" . With + , the two Strings are joined. Converted with int() , they are added. x = "20" y = "20" print(x + y) print(int(x) + int(y)) Adding two numbers from the user int(input(...)) reads the text and converts it in one line: Python runs the inner function first, then the outer one. x = int(input("Enter first number: ")) y = int(input("Enter second number: ")) result = x + y print("Result =", result) Reading a name and an age A name stays as text, so it needs no conversion. An age is a number, so it goes through int() , and then the program can calculate with it. name = input("Enter your name: ") age = int(input("Enter your age: ")) print("Hello", name) print("Age:", age) print("Next year you will be", age + 1) Decimals: float() int() only accepts whole numbers. For a value such as a temperature or a price, use float() : temperature = float(input("Enter the temperature: ")) If the user types 30.5 , temperature holds the number 30.5 . If they type 30 , it holds 30.0 , which is still a float . Check yourself a = "3" b = 3 print(a 2, b 2) 33 6 a is the String "3" , and a String times 2 repeats it: "33" . b is the number 3, so b 2 is 6. The program stops with ValueError: invalid literal for int() with base 10: ''2.5'' . int() only accepts text that looks like a whole number. Use float() when the answer may have a decimal point. Common mistakes - Forgetting to convert. age = input("Age: ") then age + 1 stops with TypeError: can only concatenate str (not "int") to str . Wrap the input: int(input("Age: ")) . - Converting a word. If the user types twenty , int() raises a ValueError . Programs later in the course check the input before converting it. - Missing brackets. int(input("Age: ") has one closing bracket too few: each ( needs its own ) . - No space in the prompt. input("Name:") makes the typing look like Name:Omar . End the prompt with a space. Key takeaways - Programs follow input → processing → output ; plan those three parts before coding. - input("prompt ") shows the prompt, waits for the user, and returns what was typed. - What input() returns is always a String , even when the user types digits. - Use int() for whole numbers and float() for decimals before doing arithmetic. - print(a, b) prints several values on one line, separated by spaces.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_e4a148e8ad10dfbd', 'course_programming_applications', 'top_dba1aa73426c9dc9', 'numbers-operators-and-decisions', 'Numbers, operators and a first decision', 'Calculate with Python''s arithmetic operators, including / // and %, compare values to get True or False, and let a program choose what to do with if and else.', 1, 4, 'easy', '["Use + - * / // and % and predict their results","Explain why / always gives a float","Use brackets to control the order of operations","Compare two values and get True or False","Write an if / else that chooses between two actions"]', '["Input, processing and output"]', 8, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
