INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a66978be90f7fcc5', 'course_programming_applications', 'les_e4a148e8ad10dfbd', 'explanation', 'Arithmetic operators', 'An **operator** is a symbol that does something with values. These are Python''s arithmetic operators:

| Operator | Meaning | Example | Result |
|---|---|---|---|
| `+` | addition | `10 + 5` | `15` |
| `-` | subtraction | `10 - 5` | `5` |
| `*` | multiplication | `10 * 5` | `50` |
| `/` | division | `10 / 5` | `2.0` |
| `//` | whole-number division | `17 // 5` | `3` |
| `%` | remainder (modulo) | `17 % 5` | `2` |
| `**` | power | `2 ** 3` | `8` |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_95e32fd36e9d0a5f', 'course_programming_applications', 'les_e4a148e8ad10dfbd', 'code', 'The four basic operations', '', 'num1 = 10
num2 = 5

total = num1 + num2
print("Addition =", total)
print("Subtraction =", num1 - num2)
print("Multiplication =", num1 * num2)
print("Division =", num1 / num2)', 'python', 1, '', 'Addition = 15
Subtraction = 5
Multiplication = 50
Division = 2.0
', '{"notes":[{"line":4,"match":"total","text":"store the sum first","shape":"circle","color":"sky"},{"line":6,"match":"num1 - num2","text":"or calculate inside print","shape":"square","color":"yel"},{"line":8,"match":"/","text":"always gives a float","shape":"diamond","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_fd722da1c658e78b', 'course_programming_applications', 'les_e4a148e8ad10dfbd', 'explanation', 'Why 10 / 5 is 2.0', 'The `/` operator **always gives a float**, even when the answer is a whole number. `10 / 5` is `2.0`, and `7 / 2` is `3.5`. This way you never lose a decimal part by accident.

When you want a whole-number answer, use the other two division operators:

- `//` divides and **drops the decimal part**: `17 // 5` is `3`.
- `%` gives the **remainder** that is left over: `17 % 5` is `2`, because 17 = 3 × 5 + 2.

The remainder is more useful than it looks. `n % 2` is `0` for every even number and `1` for every odd number, and `% 60` turns minutes into "minutes past the hour".', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2f01356a1dd118a7', 'course_programming_applications', 'les_e4a148e8ad10dfbd', 'code', 'Hours and minutes with // and %', '', 'minutes = 135
hours = minutes // 60
left = minutes % 60
print(minutes, "minutes is", hours, "hours and", left, "minutes")', 'python', 1, '', '135 minutes is 2 hours and 15 minutes
', '{"notes":[{"line":2,"match":"// 60","text":"whole hours: 2","shape":"circle","color":"sky"},{"line":3,"match":"% 60","text":"the rest: 15","shape":"square","color":"yel"}],"strips":[]}', NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e9c0d5fd6ade01f8', 'course_programming_applications', 'les_e4a148e8ad10dfbd', 'explanation', 'Order of operations', 'Python follows the same order as maths: `**` first, then `*`, `/`, `//` and `%`, and `+` and `-` last. Operators of the same level go from left to right. Brackets change the order, because whatever is inside them is worked out first.

| Expression | Worked out as | Result |
|---|---|---|
| `2 + 3 * 4` | `2 + 12` | `14` |
| `(2 + 3) * 4` | `5 * 4` | `20` |

When you aren''t sure, add brackets. They cost nothing and make the code easier to read.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5fdf2116e47bd1a0', 'course_programming_applications', 'les_e4a148e8ad10dfbd', 'code', 'The average of three marks', 'The brackets make Python add the three marks before dividing. `round(value, 2)` rounds a float to 2 decimal places for printing.', 'mark1 = 90
mark2 = 85
mark3 = 88

average = (mark1 + mark2 + mark3) / 3
print("Average:", average)
print("Rounded:", round(average, 2))', 'python', 1, '', 'Average: 87.66666666666667
Rounded: 87.67
', '{"notes":[{"line":5,"match":"(mark1 + mark2 + mark3)","text":"add first","shape":"circle","color":"sky"},{"line":5,"match":"/ 3","text":"then divide","shape":"square","color":"yel"},{"line":7,"match":"round","text":"2 decimal places","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_1605abab0d782fea', 'course_programming_applications', 'les_e4a148e8ad10dfbd', 'explanation', 'Comparing values', 'A **comparison operator** compares two values and gives back a Boolean: `True` or `False`.

| Operator | Means | Example | Result |
|---|---|---|---|
| `>` | greater than | `32 > 30` | `True` |
| `<` | less than | `32 < 30` | `False` |
| `>=` | greater than or equal to | `30 >= 30` | `True` |
| `<=` | less than or equal to | `29 <= 30` | `True` |
| `==` | equal to | `32 == 30` | `False` |
| `!=` | not equal to | `32 != 30` | `True` |

Equal to is **two** equals signs, `==`. A single `=` stores a value in a variable; it never compares.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_4dd15c3d47de93c3', 'course_programming_applications', 'les_e4a148e8ad10dfbd', 'code', 'Comparisons give True or False', '', 'temp = 32
print(temp > 30)
print(temp == 30)
print(temp != 30)', 'python', 1, '', 'True
False
True
', '{"notes":[{"line":2,"match":">","text":"is it bigger?","shape":"circle","color":"sky"},{"line":3,"match":"==","text":"two = signs: compare","shape":"square","color":"yel"}],"strips":[]}', NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_60ac45f82b07212a', 'course_programming_applications', 'les_e4a148e8ad10dfbd', 'explanation', 'Making a decision with if and else', 'A program often has to choose between two actions. `if` runs a block of code only when a condition is `True`; `else` runs a different block when it is `False`.

```python
if condition:
    print("this line runs when the condition is True")
else:
    print("this line runs when the condition is False")
```

Three details matter:

- a **colon** `:` ends the `if` line and the `else` line;
- the lines that belong to each branch are **indented** (pushed right, usually by 4 spaces); that indentation is how Python knows where each branch starts and ends;
- exactly one of the two branches runs, never both.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0355190e685b8d2a', 'course_programming_applications', 'les_e4a148e8ad10dfbd', 'code', 'A temperature-controlled fan', 'The program reads the temperature. If it is above 30, the fan switches on; otherwise it stays off. Run it, then change the typed temperature to `25` and run it again.', 'temp = int(input("Enter temperature: "))

if temp > 30:
    print("Fan ON")
else:
    print("Fan OFF")', 'python', 1, '35
', 'Enter temperature: 35
Fan ON
', '{"notes":[{"line":1,"match":"int(input(","text":"a number, not text","shape":"circle","color":"sky"},{"line":3,"match":"temp > 30","text":"True or False?","shape":"square","color":"yel"},{"line":3,"match":":","text":"a colon ends the line","shape":"diamond","color":"green"},{"line":4,"match":"print","text":"indented: inside if","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_65e3f6decd357113', 'course_programming_applications', 'les_e4a148e8ad10dfbd', 'note', 'Check yourself', '::: check What does this program print?
```python
a = 7
b = 2
print(a / b, a // b, a % b)
```
???
```output
3.5 3 1
```
`/` always gives a float, 3.5. `//` drops the decimal part, 3. And 7 = 3 × 2 + 1, so the remainder is 1.
:::

::: check What does this program print when the user types 30?
```python
temp = int(input("Enter temperature: "))
if temp > 30:
    print("Fan ON")
else:
    print("Fan OFF")
```
???
`Fan OFF`. 30 is not *greater* than 30, so `temp > 30` is `False` and the `else` branch runs. To switch the fan on at 30 as well, the condition would be `temp >= 30`.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_1594b37f136f7c5a', 'course_programming_applications', 'les_e4a148e8ad10dfbd', 'common_mistakes', 'Common mistakes', '- **Using = to compare.** `if temp = 30:` is a `SyntaxError`. Comparing needs `==`.
- **Forgetting the colon.** `if temp > 30` without `:` is a `SyntaxError`, and so is `else` without one.
- **Forgetting to indent.** A `print` under `if` that isn''t indented gives `IndentationError: expected an indented block`.
- **Comparing text with a number.** Without `int()`, `input()` gives a String, and `"35" > 30` stops with `TypeError: ''>'' not supported between instances of ''str'' and ''int''`.
- **Calling a variable sum.** `sum = num1 + num2` works, but it hides Python''s own `sum()` function for the rest of the program. Choose a name like `total`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_cfc868a945b3d8a5', 'course_programming_applications', 'les_e4a148e8ad10dfbd', 'key_takeaways', 'Key takeaways', '- `+ - * /` work as in maths; `/` always gives a float, `//` gives the whole part and `%` the remainder.
- Python follows the usual order of operations; brackets are worked out first.
- Comparisons (`> < >= <= == !=`) give `True` or `False`. Equal to is `==`.
- `if condition:` runs the indented block when the condition is `True`; `else:` runs when it is `False`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 13, 1792022400000);
