INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5bd9a6c7c29621a6', 'course_programming_applications', 'les_bed6deb54f895c3d', 'explanation', 'From one value to many values', 'So far every variable has held **one** value. Storing four students'' names takes four variables:

```python
student1 = "Ahmed"
student2 = "Omar"
student3 = "Sara"
student4 = "Ali"
```

Now imagine 100 students: 100 variables, and 100 `print` lines to show them all. There has to be a better way.

The better way is a **sequence**: one name that holds many values, in order. Python gives you two sequences you will use all the time, **Strings** and **Lists**. This lecture starts with Strings; Lists come two lectures later.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_eaf9c4ba52b43006', 'course_programming_applications', 'les_bed6deb54f895c3d', 'explanation', 'What is a sequence?', 'A **sequence** is an **ordered collection of elements**. "Ordered" means every element has a fixed position, and each position has a number called its **index**.

| Element | P | y | t | h | o | n |
|---|---|---|---|---|---|---|
| **Index** | 0 | 1 | 2 | 3 | 4 | 5 |

The most important rule: **Python indexing starts from 0**. The first element is at index 0, so in `"Python"` the sixth character, `n`, is at index 5.

Python''s two common sequences:

- a **String**, written in quotes, such as `"Python"`: a sequence of **characters**;
- a **List**, written in square brackets, such as `["Ahmed", "Omar", "Sara"]`: a sequence of **items**.

Both are ordered, so both use indexes starting from 0.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3663b0f760dd586a', 'course_programming_applications', 'les_bed6deb54f895c3d', 'explanation', 'A String is a sequence of characters', 'A **String** (Python''s type `str`) represents text: a name, a course title, a message. Each letter, digit, space or symbol in it is one **character**.

```python
name = "Omar"
course = "Programming Applications"
message = "Hello World"
```

You can write a String with double quotes or single quotes, as long as the opening and closing quotes match. `"Hello"` and `''Hello''` are exactly the same String.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3822550865b740c9', 'course_programming_applications', 'les_bed6deb54f895c3d', 'code', 'String indexing', 'To read one character, write the variable''s name and the index in **square brackets**. The boxes under the code show every character with its index.', 'word = "Python"
print(word[0])
print(word[2])
print(word[5])', 'python', 1, '', 'P
t
n
', '{"notes":[{"line":2,"match":"[0]","text":"first element: index 0","shape":"circle","color":"sky"},{"line":3,"match":"[2]","text":"the 3rd character","shape":"square","color":"yel"},{"line":4,"match":"[5]","text":"the last character","shape":"diamond","color":"green"}],"strips":[{"line":1,"match":"\"Python\"","kind":"chr","items":["P","y","t","h","o","n"],"negative":false,"color":"yel"}]}', NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_c29a802a18fe2a05', 'course_programming_applications', 'les_bed6deb54f895c3d', 'explanation', 'The last index is one less than the length', '`"Python"` has 6 characters, so its indexes are 0, 1, 2, 3, 4 and 5. There is **no index 6**. The last index is always the length minus one, and the `len()` function gives the length: `len(word)` is `6`, so the last character is `word[len(word) - 1]`.

::: warning Index out of range
Asking for an index that doesn''t exist stops the program. `word[6]` on a 6-character String raises `IndexError: string index out of range`.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_36ad8a2003ffaf11', 'course_programming_applications', 'les_bed6deb54f895c3d', 'code', 'Counting from the end with negative indexes', 'Python also numbers the characters from the end, using **negative indexes**: `-1` is the last character, `-2` the one before it, and so on. This is handy when you don''t know how long the text is: `word[-1]` is always the last character.', 'word = "Python"
print(word[-1])
print(word[-2])
print(word[-6])', 'python', 1, '', 'n
o
P
', '{"notes":[{"line":2,"match":"[-1]","text":"-1 is always the last","shape":"diamond","color":"coral"},{"line":4,"match":"[-6]","text":"same as word[0]","shape":"square","color":"sky"}],"strips":[{"line":1,"match":"\"Python\"","kind":"chr","items":["P","y","t","h","o","n"],"negative":true,"color":"yel"}]}', NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a081a2ad6bf7dce5', 'course_programming_applications', 'les_bed6deb54f895c3d', 'note', 'Check yourself', '::: check What does this program print?
```python
s = "Cairo"
print(s[1] + s[-1])
```
???
```output
ao
```
`s[1]` is the second character, `a`, and `s[-1]` is the last character, `o`. Using `+` on two Strings joins them.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a68357c7e2c4e6a7', 'course_programming_applications', 'les_bed6deb54f895c3d', 'explanation', 'Slicing: getting part of a String', 'Indexing gives you **one** character. **Slicing** gives you a piece of the String:

**string[start:end]**

The slice starts **at** index `start` (included) and stops **before** index `end` (not included). A handy check: `end - start` is the number of characters you get.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_60640edc62e3949e', 'course_programming_applications', 'les_bed6deb54f895c3d', 'code', 'Your first slice', '`word[0:4]` takes indexes 0, 1, 2 and 3, and stops before index 4. That is 4 − 0 = 4 characters.', 'word = "Programming"
print(word[0:4])', 'python', 1, '', 'Prog
', '{"notes":[{"line":2,"match":"0","text":"start: included","shape":"circle","color":"green"},{"line":2,"match":"4","text":"end: not included","shape":"tri","color":"coral"}],"strips":[{"line":1,"match":"\"Programming\"","kind":"chr","items":["P","r","o","g","r","a","m","m","i","n","g"],"negative":false,"color":"yel"}]}', NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_94ebe932918f45b5', 'course_programming_applications', 'les_bed6deb54f895c3d', 'code', 'More slicing examples', 'You can leave out `start` or `end`:

- `[:end]` starts **from the beginning**;
- `[start:]` runs **until the end**;
- `[:]`, with neither, copies the whole String.', 'word = "Programming"
print(word[:4])
print(word[4:])
print(word[3:8])
print(word[:])', 'python', 1, '', 'Prog
ramming
gramm
Programming
', '{"notes":[{"line":2,"match":":4","text":"from the beginning","shape":"circle","color":"sky"},{"line":3,"match":"4:","text":"until the end","shape":"square","color":"yel"},{"line":4,"match":"3:8","text":"indexes 3 to 7","shape":"diamond","color":"green"},{"line":5,"match":"[:]","text":"the whole String","shape":"tri","color":"coral"}],"strips":[{"line":1,"match":"\"Programming\"","kind":"chr","items":["P","r","o","g","r","a","m","m","i","n","g"],"negative":false,"color":"yel"}]}', NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5521d9591de2c948', 'course_programming_applications', 'les_bed6deb54f895c3d', 'example', 'A slice never goes out of range', 'Indexing past the end is an error, but slicing past the end is not: Python simply stops at the last character. A slice that starts past the end gives an empty String.', 'word = "Python"
print(word[4:10])
print(word[10:])
print(len(word[10:]))', 'python', 1, '', 'on

0
', '{"notes":[{"line":2,"match":"4:10","text":"stops at the real end","shape":"circle","color":"sky"},{"line":3,"match":"10:","text":"an empty String","shape":"square","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_1f9070059303b94a', 'course_programming_applications', 'les_bed6deb54f895c3d', 'explanation', 'A third number: the step', 'A slice can take a third number, the **step**: `string[start:end:step]`. A step of 2 takes every second character. `"Programming"[::2]` is `"Pormig"` (indexes 0, 2, 4, 6, 8 and 10). A step of -1 walks backwards, so `"Python"[::-1]` is `"nohtyP"`, the String reversed.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e2fef77e22d97f2e', 'course_programming_applications', 'les_bed6deb54f895c3d', 'note', 'Check yourself', '::: check What does `"Programming"[3:7]` give?
Count the indexes first: P is 0, r is 1, o is 2, g is 3.
???
`"gram"`. The slice starts at index 3 (`g`) and stops **before** index 7, so it takes indexes 3, 4, 5 and 6: `g`, `r`, `a`, `m`.
:::

::: check What does this program print?
```python
word = "Python"
print(word[1:3], word[-3:])
```
???
```output
yt hon
```
`word[1:3]` takes indexes 1 and 2: `yt`. `word[-3:]` starts at the third character from the end, `h`, and runs to the end: `hon`.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 13, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_1c0f2817485bc44a', 'course_programming_applications', 'les_bed6deb54f895c3d', 'common_mistakes', 'Common mistakes', '- **Starting to count at 1.** The first character is `word[0]`. `word[1]` is the second character.
- **Expecting the end index to be included.** `word[0:4]` is four characters, `Prog`, not five.
- **Using the length as an index.** `word[len(word)]` is always out of range. Use `word[-1]` or `word[len(word) - 1]`.
- **Round brackets instead of square ones.** `word(0)` makes Python try to call the String like a function: `TypeError: ''str'' object is not callable`.
- **Trying to change one character.** `word[0] = "J"` raises a `TypeError`, because Strings can''t be changed. The Strings vs Lists lecture shows what to do instead.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 14, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_7c698d68d61e9f63', 'course_programming_applications', 'les_bed6deb54f895c3d', 'key_takeaways', 'Key takeaways', '- A **sequence** is an ordered collection; every element has an index, **starting at 0**.
- A String is a sequence of characters, written in single or double quotes.
- `word[i]` reads one character; negative indexes count from the end, and `-1` is the last one.
- `word[start:end]` takes from `start` up to, but not including, `end`; either number can be left out.
- `len(word)` is the number of characters, so the last index is `len(word) - 1`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 15, 1792022400000);
