INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_947c98f6870981d7', 'course_programming_applications', 'les_0afe8b9536338d8d', 'explanation', 'Three simple tools', 'You have read parts of a String. Now you will build and change Strings with three simple tools:

| Tool | Name | What it does | Example | Result |
|---|---|---|---|---|
| `+` | concatenation | joins Strings together | `"Py" + "thon"` | `"Python"` |
| `*` | repetition | repeats a String | `"ab" * 3` | `"ababab"` |
| `len()` | length | counts the characters | `len("Python")` | `6` |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_91a488a5564418bf', 'course_programming_applications', 'les_0afe8b9536338d8d', 'code', 'Joining Strings with +', '`+` puts two Strings side by side, with nothing in between. To get a space between the first and last name, join a String that contains just a space, `" "`, in the middle.', 'first = "Omar"
last = "Ahmed"
full_name = first + " " + last
print(full_name)
print(first + last)', 'python', 1, '', 'Omar Ahmed
OmarAhmed
', '{"notes":[{"line":3,"match":"\" \"","text":"a space, joined in the middle","shape":"circle","color":"sky"},{"line":5,"match":"first + last","text":"no space added for you","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_58b7bc6e8fb8abb2', 'course_programming_applications', 'les_0afe8b9536338d8d', 'code', 'Repeating with * and counting with len()', '`*` repeats a String a whole number of times. `len()` counts every character, including spaces.', 'print("Hi" * 3)
print("-" * 20)
print(len("Python"))
print(len("Omar Ahmed"))', 'python', 1, '', 'HiHiHi
--------------------
6
10
', '{"notes":[{"line":2,"match":"\"-\" * 20","text":"a quick dividing line","shape":"circle","color":"sky"},{"line":4,"match":"\"Omar Ahmed\"","text":"the space counts: 10","shape":"square","color":"yel"}],"strips":[]}', NULL, NULL, NULL, NULL, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f5daf546d0ac7419', 'course_programming_applications', 'les_0afe8b9536338d8d', 'explanation', 'Spaces are characters too', '`len("Omar Ahmed")` is 10, not 9: the space between the two names is a character like any other. The same goes for repetition. `"Hi " * 3`, with a space inside the quotes, gives `"Hi Hi Hi "`: three copies of `Hi ` and therefore a space at the very end, which you can''t see on the screen but `len()` counts. So `len("Hi " * 3)` is 9.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_826aad5edd296d6d', 'course_programming_applications', 'les_0afe8b9536338d8d', 'explanation', 'String methods', 'A **method** is a function that belongs to a value. You call it with a **dot** after the value or variable, then the method''s name and brackets:

**name.method()**

The brackets are required, even when the method needs nothing inside them. These four methods change the letters of a String:

| Method | What it does |
|---|---|
| `upper()` | ALL CAPITAL LETTERS |
| `lower()` | all small letters |
| `capitalize()` | a capital first letter for the **whole text**, small letters after it |
| `title()` | a capital first letter for **every word** |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_504e8fa1f42da514', 'course_programming_applications', 'les_0afe8b9536338d8d', 'code', 'Four methods on one name', '', 'name = "omar ahmed"
print(name.upper())
print(name.lower())
print(name.capitalize())
print(name.title())
print(name)', 'python', 1, '', 'OMAR AHMED
omar ahmed
Omar ahmed
Omar Ahmed
omar ahmed
', '{"notes":[{"line":2,"match":".","text":"the dot calls a method","shape":"circle","color":"sky"},{"line":4,"match":"capitalize","text":"first letter of the text","shape":"square","color":"yel"},{"line":5,"match":"title","text":"first letter of each word","shape":"diamond","color":"green"},{"line":6,"match":"name","text":"still unchanged","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3019234da65f7db3', 'course_programming_applications', 'les_0afe8b9536338d8d', 'explanation', 'Methods give you a new String', 'Look at the last line of output: after four method calls, `name` still holds `"omar ahmed"`. A String method never changes the String it is called on. It **returns a new String**, which you can print or store.

To keep the result, store it in a variable, either a new one or the same one:

```python
name = "omar ahmed"
name = name.title()
print(name)
```

Now `name` holds `"Omar Ahmed"`, because the line stored the new String back in `name`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_9dde576fbb11566b', 'course_programming_applications', 'les_0afe8b9536338d8d', 'note', 'Check yourself', '::: check What does this program print?
```python
city = "cairo university"
print(city.capitalize())
print(city.title())
print(len(city))
```
???
```output
Cairo university
Cairo University
16
```
`capitalize()` only changes the very first letter of the whole text; `title()` changes the first letter of each word. `len()` counts the space too: 5 + 1 + 10 = 16.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_7e492d21ea50c6ed', 'course_programming_applications', 'les_0afe8b9536338d8d', 'explanation', 'Practice: format a name', 'Here is a small task that uses everything in this lecture. Ask the user for their first and last name, then display:

1. the full name;
2. the full name in capital letters;
3. the number of characters in the full name.

Plan it as input, processing and output: **input** the two names, **process** by joining them with a space, **output** three results using `+`, `upper()` and `len()`. Try writing it yourself in the box below before you read the solution: press **Edit**, and add your lines after the comment.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1792022400000);
