INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_22167041a1634fd5', 'course_programming_applications', 'les_0afe8b9536338d8d', 'code', 'Format a name: one possible solution', '', 'first_name = input("Enter first name: ")
