', '{"notes":[{"line":4,"match":"+ \" \" +","text":"join with a space","shape":"circle","color":"sky"},{"line":7,"match":"upper","text":"capital letters","shape":"square","color":"yel"},{"line":8,"match":"len","text":"the space counts too","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_9ffebcc15e97daaa', 'course_programming_applications', 'les_0afe8b9536338d8d', 'explanation', 'Counting only the letters', 'The answer is 10, not 9, because `len()` counts the space between the names. To count the letters only, add the lengths of the two names instead:

```python
print(len(first_name) + len(last_name))
```

For Omar Ahmed that gives 4 + 5 = 9.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_6695b8c376758a3e', 'course_programming_applications', 'les_0afe8b9536338d8d', 'common_mistakes', 'Common mistakes', '- **Forgetting the brackets.** `name.upper` without `()` doesn''t run the method. `print(name.upper)` shows something like `<built-in method upper of str object at 0x…>` instead of capital letters.
- **Expecting the variable to change.** `name.upper()` on its own line does nothing useful: the new String is made and thrown away. Write `name = name.upper()` to keep it.
- **Joining a String and a number.** `"Age: " + 20` stops with `TypeError: can only concatenate str (not "int") to str`. Convert first: `"Age: " + str(20)`.
- **Multiplying two Strings.** `"Hi" * "3"` is a `TypeError`. Repetition needs a whole number: `"Hi" * 3`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 13, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_641480c7919464df', 'course_programming_applications', 'les_0afe8b9536338d8d', 'key_takeaways', 'Key takeaways', '- `+` joins Strings, `*` repeats a String, and `len()` counts its characters, spaces included.
- A method is called with a dot and brackets: `name.upper()`.
- `upper()`, `lower()`, `capitalize()` and `title()` change the letters; `capitalize()` touches only the first letter of the text, `title()` the first letter of every word.
- String methods **return a new String**; the original is unchanged unless you store the result back.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 14, 1792022400000);
