INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_057e7cb27f9befb1', 'course_programming_applications', 'les_a6a899f0e4b6d97d', 'explanation', 'One variable, many values', 'Back to the problem from the start of the Strings lecture: one variable per student doesn''t scale. A **List** stores **multiple values inside one variable**. Instead of

```python
student1 = "Ahmed"
student2 = "Omar"
student3 = "Sara"
```

you write one variable, `students`, and put all the names inside **square brackets**, separated by commas:

```python
students = ["Ahmed", "Omar", "Sara"]
```

Each item gets an index starting from 0, just like the characters of a String. A List can hold numbers too, such as `[10, 20, 30]`, or a mix of types.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0e7e029885f7ae1d', 'course_programming_applications', 'les_a6a899f0e4b6d97d', 'code', 'Accessing List elements', 'List indexing works exactly like String indexing: square brackets and an index, positive from the start or negative from the end. `len()` works on Lists too, and counts the **items**.', 'students = ["Ahmed", "Omar", "Sara"]
print(students)
print(students[0])
print(students[2])
print(students[-1])
print(len(students))', 'python', 1, '', '[''Ahmed'', ''Omar'', ''Sara'']
Ahmed
Sara
Sara
3
', '{"notes":[{"line":3,"match":"[0]","text":"first item","shape":"circle","color":"sky"},{"line":5,"match":"[-1]","text":"last item","shape":"diamond","color":"coral"},{"line":6,"match":"len","text":"number of items","shape":"square","color":"green"}],"strips":[{"line":1,"match":"[\"Ahmed\", \"Omar\", \"Sara\"]","kind":"item","items":["Ahmed","Omar","Sara"],"negative":true,"color":"yel"}]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3cf18ebc6efb97b0', 'course_programming_applications', 'les_a6a899f0e4b6d97d', 'explanation', 'One whole item, not one character', 'There is nothing new to memorise, but notice what you get back. With a String, an index gives **one character**. With a List, it gives **one whole item**: `students[0]` is the full name `Ahmed`.

`students[2]` and `students[-1]` both give `Sara`, because Sara is the last item. And `students[3]` doesn''t exist: the last index of a 3-item List is 2.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3f82a890e38a5f7b', 'course_programming_applications', 'les_a6a899f0e4b6d97d', 'code', 'List slicing', 'Slicing follows the same rules as for Strings: the start is included, the end is not. The difference is the result. Slicing a String gives a String; slicing a List gives a **new List**, which is why the output has square brackets.', 'numbers = [10, 20, 30, 40, 50]
print(numbers[0:3])
print(numbers[2:])
print(numbers[-2:])', 'python', 1, '', '[10, 20, 30]
[30, 40, 50]
[40, 50]
', '{"notes":[{"line":2,"match":"0:3","text":"indexes 0, 1 and 2","shape":"circle","color":"sky"},{"line":3,"match":"2:","text":"index 2 to the end","shape":"square","color":"yel"},{"line":4,"match":"-2:","text":"the last two items","shape":"diamond","color":"green"}],"strips":[{"line":1,"match":"[10, 20, 30, 40, 50]","kind":"item","items":["10","20","30","40","50"],"negative":false,"color":"yel"}]}', NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_929c72a3f4530fef', 'course_programming_applications', 'les_a6a899f0e4b6d97d', 'code', 'Changing an item: Lists are mutable', 'To change one item, assign a new value to its index. The List itself changes. Because Lists can be changed, they are called **mutable** (mutable means "can be changed").', 'colors = ["Red", "Blue", "Green"]
print(colors)
colors[1] = "Black"
print(colors)', 'python', 1, '', '[''Red'', ''Blue'', ''Green'']
[''Red'', ''Black'', ''Green'']
', '{"notes":[{"line":3,"match":"colors[1] = \"Black\"","text":"replaces Blue","shape":"circle","color":"sky"}],"strips":[{"line":1,"match":"[\"Red\", \"Blue\", \"Green\"]","kind":"item","items":["Red","Blue","Green"],"negative":false,"color":"yel"}]}', NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b02fa6295be44893', 'course_programming_applications', 'les_a6a899f0e4b6d97d', 'explanation', 'Adding and removing items', 'Four methods change the length of a List. Like String methods, they are called with a dot:

| Method | What it does |
|---|---|
| `append(item)` | adds an item **to the end** |
| `insert(index, item)` | adds an item **at a position**; the items after it move one place to the right |
| `remove(value)` | removes the first item **equal to** that value, wherever it is |
| `pop()` | removes the **last** item, and gives it back |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5edf4e353b56268c', 'course_programming_applications', 'les_a6a899f0e4b6d97d', 'code', 'One List, four changes', 'Read this program as one story. The List starts with two names; each line changes it, and the `print` after it shows the result.', 'students = ["Ahmed", "Omar"]
print(students)
students.append("Ali")
print(students)
students.insert(1, "Sara")
print(students)
students.remove("Omar")
print(students)
students.pop()
print(students)', 'python', 1, '', '[''Ahmed'', ''Omar'']
[''Ahmed'', ''Omar'', ''Ali'']
[''Ahmed'', ''Sara'', ''Omar'', ''Ali'']
[''Ahmed'', ''Sara'', ''Ali'']
[''Ahmed'', ''Sara'']
', '{"notes":[{"line":3,"match":"append","text":"Ali goes to the end","shape":"circle","color":"sky"},{"line":5,"match":"insert(1,","text":"Sara goes to index 1","shape":"square","color":"yel"},{"line":7,"match":"remove","text":"deletes the value Omar","shape":"diamond","color":"coral"},{"line":9,"match":"pop","text":"deletes the last item","shape":"tri","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f01e29205284ca64', 'course_programming_applications', 'les_a6a899f0e4b6d97d', 'explanation', 'pop() gives the item back', '`pop()` does two things: it removes the last item **and returns it**. So you can keep what was removed:

```python
students = ["Ahmed", "Sara", "Ali"]
name = students.pop()
print(name)
print(students)
```

This prints `Ali`, then `[''Ahmed'', ''Sara'']`. `pop()` can also take an index: `students.pop(0)` removes and returns the **first** item.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_4d8534c48e614aa3', 'course_programming_applications', 'les_a6a899f0e4b6d97d', 'note', 'Check yourself', '::: check What does this program print?
```python
nums = [4, 8, 15]
nums.append(16)
print(nums[1] + nums[-1])
```
???
```output
24
```
After `append(16)` the List is `[4, 8, 15, 16]`. `nums[1]` is 8 and `nums[-1]` is now 16, and 8 + 16 is 24.
:::

::: check What does this program print?
```python
names = ["Ali", "Mona", "Sara"]
names.insert(0, "Omar")
names.remove("Mona")
print(names)
```
???
```output
[''Omar'', ''Ali'', ''Sara'']
```
`insert(0, "Omar")` puts Omar in front: `[''Omar'', ''Ali'', ''Mona'', ''Sara'']`. Then `remove("Mona")` deletes Mona.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d0953db32bfe7f32', 'course_programming_applications', 'les_a6a899f0e4b6d97d', 'explanation', 'Looping over a List', 'A `for` loop can visit every item of a List in order. The loop variable (here `mark`) holds one item on each round. This is the usual way to add up, count or search the items. Loops get their own lectures later; this is a first look.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1792022400000);
