INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_58afa3b1a1f14d3c', 'course_programming_applications', 'les_a6a899f0e4b6d97d', 'explanation', 'Reading the error', 'The last line of the error is the important one: `IndexError: list index out of range`. The fix is to use an index from `0` to `len(students) - 1`, or `students[-1]` for the last item.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 13, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_49dcccac0704cf90', 'course_programming_applications', 'les_a6a899f0e4b6d97d', 'common_mistakes', 'Common mistakes', '- **Starting at 1.** The first item is `students[0]`.
- **Round brackets.** `students(0)` is a `TypeError`; items are read with square brackets, `students[0]`.
- **Using `append()` to add two items at once.** `students.append("Ali", "Sara")` raises a `TypeError`. Call `append()` once per item.
- **Saving the result of `append()`.** `students = students.append("Ali")` sets `students` to `None`, because `append()` changes the List and returns nothing.
- **Removing a value that isn''t there.** `students.remove("Mona")` raises a `ValueError` if Mona is not in the List.
- **Mixing up `remove()` and `pop()`.** `remove()` takes a **value** (`remove("Omar")`); `pop()` takes an **index** or nothing.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 14, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e7c08208ddf2c071', 'course_programming_applications', 'les_a6a899f0e4b6d97d', 'key_takeaways', 'Key takeaways', '- A List stores many values in one variable: `["Ahmed", "Omar", "Sara"]`. Indexes start at 0, and `-1` is the last item.
- Indexing a List gives one whole item; slicing gives a new List.
- Lists are **mutable**: `colors[1] = "Black"` changes the List itself.
- `append()` adds to the end, `insert(i, x)` adds at index `i`, `remove(x)` deletes by value, and `pop()` removes and returns the last item.
- `for item in my_list:` visits every item, which is how you add up or search a List.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 15, 1792022400000);
