INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_6346636b5b332c27', 'course_programming_applications', 'les_546ace464d887fb1', 'explanation', 'Two sequences, side by side', 'Strings and Lists are both **sequences**, so a lot of what you learned works on both:

| | String | List |
|---|---|---|
| Written as | `"Python"` | `["Ahmed", "Omar", "Sara"]` |
| Holds | characters (text) | items (any values) |
| Indexing `[i]` | gives one character | gives one item |
| Slicing `[a:b]` | gives a new String | gives a new List |
| `len()` | counts characters | counts items |
| Can be changed? | **No** (immutable) | **Yes** (mutable) |

The last row is the key difference, and it is the subject of this lecture.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_bf70aa79d02d0ff4', 'course_programming_applications', 'les_546ace464d887fb1', 'explanation', 'Mutable and immutable', '**Mutable** means "can be changed"; **immutable** means "cannot be changed".

- A **List is mutable**. You can replace an item (`colors[1] = "Black"`), add items with `append()` and `insert()`, and remove them with `remove()` and `pop()`. The same List object changes.
- A **String is immutable**. Once a String exists, none of its characters can be replaced, added or removed. Every String method, such as `upper()`, gives you a **new** String and leaves the old one as it was.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_1d52cf0673152ba1', 'course_programming_applications', 'les_546ace464d887fb1', 'example', 'Trying to change a String', 'Run this program. Python stops at line 2 with `TypeError: ''str'' object does not support item assignment`.', 'word = "Python"
word[0] = "J"
print(word)', 'python', 1, '', NULL, '{"notes":[{"line":2,"match":"word[0] = \"J\"","text":"a String can''t change","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_6228167a20b936fe', 'course_programming_applications', 'les_546ace464d887fb1', 'code', 'Building a changed copy instead', 'To "change" a String, build a **new** one from pieces of the old one. `word[1:]` is everything except the first character, so `"J" + word[1:]` is `"Jython"`. The original `word` is still `"Python"`.', 'word = "Python"
new_word = "J" + word[1:]
print(new_word)
print(word)

colors = ["Red", "Blue", "Green"]
colors[0] = "Pink"
print(colors)', 'python', 1, '', 'Jython
Python
[''Pink'', ''Blue'', ''Green'']
', '{"notes":[{"line":2,"match":"word[1:]","text":"everything after P","shape":"circle","color":"sky"},{"line":4,"match":"word","text":"the original is unchanged","shape":"square","color":"yel"},{"line":7,"match":"colors[0] = \"Pink\"","text":"a List can change","shape":"diamond","color":"green"}],"strips":[{"line":1,"match":"\"Python\"","kind":"chr","items":["P","y","t","h","o","n"],"negative":false,"color":"yel"},{"line":6,"match":"[\"Red\", \"Blue\", \"Green\"]","kind":"item","items":["Red","Blue","Green"],"negative":false,"color":"yel"}]}', NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_620bda0c6f63dc57', 'course_programming_applications', 'les_546ace464d887fb1', 'explanation', 'Why it matters', 'The difference explains two kinds of line you will write all the time:

- With a String, you **store the result**: `name = name.upper()`. Without `name =`, the new String is lost.
- With a List, you **don''t**: `students.append("Ali")` changes `students` itself. Writing `students = students.append("Ali")` would be a mistake, because `append()` returns `None`, and `students` would become `None`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_8e5f2c7bd091c171', 'course_programming_applications', 'les_546ace464d887fb1', 'note', 'Check yourself', '::: check What does this program print?
```python
word = "cat"
word.upper()
letters = ["c", "a", "t"]
letters.append("s")
print(word, letters)
```
???
```output
cat [''c'', ''a'', ''t'', ''s'']
```
`word.upper()` makes a new String `"CAT"`, but nothing stores it, so `word` is still `"cat"`. `append()` changes the List itself, so `letters` now has 4 items.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_889f9caedf0e6b64', 'course_programming_applications', 'les_546ace464d887fb1', 'explanation', 'Final practice: six steps on one List', 'Start with this List:

```python
subjects = ["Math", "Programming", "Physics"]
```

Write the Python code for each step:

1. Display the first subject.
2. Add `"Electronics"`.
3. Replace `"Math"` with `"Calculus"`.
4. Remove `"Physics"`.
5. Display the final List.
6. Display the number of subjects.

Try it yourself first: open the solution below, press **Edit**, delete everything after the first line and write your own steps. Then compare.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
