', '{"notes":[{"line":3,"match":"[0]","text":"1. the first subject","shape":"circle","color":"sky"},{"line":4,"match":"append","text":"2. add to the end","shape":"square","color":"yel"},{"line":5,"match":"subjects[0] =","text":"3. replace Math","shape":"diamond","color":"green"},{"line":6,"match":"remove","text":"4. remove by value","shape":"tri","color":"coral"},{"line":8,"match":"len","text":"6. counts items, not letters","shape":"circle","color":"green"}],"strips":[{"line":1,"match":"[\"Math\", \"Programming\", \"Physics\"]","kind":"item","items":["Math","Programming","Physics"],"negative":false,"color":"yel"}]}', NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_334d4970b2d7fb40', 'course_programming_applications', 'les_546ace464d887fb1', 'explanation', 'Following the List step by step', '| After step | `subjects` |
|---|---|
| start | `[''Math'', ''Programming'', ''Physics'']` |
| 2. `append("Electronics")` | `[''Math'', ''Programming'', ''Physics'', ''Electronics'']` |
| 3. `subjects[0] = "Calculus"` | `[''Calculus'', ''Programming'', ''Physics'', ''Electronics'']` |
| 4. `remove("Physics")` | `[''Calculus'', ''Programming'', ''Electronics'']` |

Step 3 could also be written `subjects[subjects.index("Math")] = "Calculus"`, which finds Math wherever it is. Here Math is known to be first, so `[0]` is enough.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_11ad93e88a16d787', 'course_programming_applications', 'les_546ace464d887fb1', 'common_mistakes', 'Common mistakes', '- **Trying to change a character.** `word[0] = "J"` is a `TypeError`. Build a new String: `"J" + word[1:]`.
- **Forgetting to store a String result.** `name.title()` alone changes nothing; write `name = name.title()`.
- **Storing a List method''s result.** `subjects = subjects.append("Art")` replaces your List with `None`.
- **Doing steps in the wrong order.** In the practice, replacing `subjects[0]` *before* step 1 would print Calculus instead of Math. With a mutable List, the order of the lines decides what each line sees.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d88115061b72a0f1', 'course_programming_applications', 'les_546ace464d887fb1', 'key_takeaways', 'Key takeaways', '- Strings and Lists are both sequences: indexing, slicing and `len()` work on both.
- Lists are **mutable** (they can change); Strings are **immutable** (they can''t).
- To "change" a String, build a new one, for example `"J" + word[1:]`, and store it.
- String methods return new Strings; List methods like `append()` change the List and return `None`.
- **Store → access → modify → use**: that is what Strings and Lists let a program do with collections of data.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1792022400000);
