INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_applications', 'lesson', 'les_546ace464d887fb1', '/courses/programming-applications/lectures/strings-vs-lists-and-practice', 'Strings vs Lists, and a final practice', 'Strings and Lists are both sequences, but only Lists can be changed. See what happens when you try to change a String, how to build a changed copy instead, and finish with a step-by-step List practice. List what Strings and Lists have in common Explain the difference between mutable and immutable Build a changed copy of a String with slicing and + Solve a multi-step List task using indexes and List methods Two sequences, side by side Strings and Lists are both sequences , so a lot of what you learned works on both: String List --- --- --- Written as "Python" ["Ahmed", "Omar", "Sara"] Holds characters (text) items (any values) Indexing [i] gives one character gives one item Slicing [a:b] gives a new String gives a new List len() counts characters counts items Can be changed? No (immutable) Yes (mutable) The last row is the key difference, and it is the subject of this lecture. Mutable and immutable Mutable means "can be changed"; immutable means "cannot be changed". - A List is mutable . You can replace an item ( colors[1] = "Black" ), add items with append() and insert() , and remove them with remove() and pop() . The same List object changes. - A String is immutable . Once a String exists, none of its characters can be replaced, added or removed. Every String method, such as upper() , gives you a new String and leaves the old one as it was. Trying to change a String Run this program. Python stops at line 2 with TypeError: ''str'' object does not support item assignment . word = "Python" word[0] = "J" print(word) Building a changed copy instead To "change" a String, build a new one from pieces of the old one. word[1:] is everything except the first character, so "J" + word[1:] is "Jython" . The original word is still "Python" . word = "Python" new_word = "J" + word[1:] print(new_word) print(word) colors = ["Red", "Blue", "Green"] colors[0] = "Pink" print(colors) Why it matters The difference explains two kinds of line you will write all the time: - With a String, you store the result : name = name.upper() . Without name = , the new String is lost. - With a List, you don''t : students.append("Ali") changes students itself. Writing students = students.append("Ali") would be a mistake, because append() returns None , and students would become None . Check yourself word = "cat" word.upper() letters = ["c", "a", "t"] letters.append("s") print(word, letters) cat [''c'', ''a'', ''t'', ''s''] word.upper() makes a new String "CAT" , but nothing stores it, so word is still "cat" . append() changes the List itself, so letters now has 4 items. Final practice: six steps on one List Start with this List: subjects = ["Math", "Programming", "Physics"] Write the Python code for each step: 1. Display the first subject. 2. Add "Electronics" . 3. Replace "Math" with "Calculus" . 4. Remove "Physics" . 5. Display the final List. 6. Display the number of subjects. Try it yourself first: open the solution below, press Edit , delete everything after the first line and write your own steps. Then compare. Final practice: one possible solution subjects = ["Math", "Programming", "Physics"] print(subjects[0]) subjects.append("Electronics") subjects[0] = "Calculus" subjects.remove("Physics") print(subjects) print(len(subjects)) Following the List step by step After step subjects --- --- start [''Math'', ''Programming'', ''Physics''] 2. append("Electronics") [''Math'', ''Programming'', ''Physics'', ''Electronics''] 3. subjects[0] = "Calculus" [''Calculus'', ''Programming'', ''Physics'', ''Electronics''] 4. remove("Physics") [''Calculus'', ''Programming'', ''Electronics''] Step 3 could also be written subjects[subjects.index("Math")] = "Calculus" , which finds Math wherever it is. Here Math is known to be first, so [0] is enough. Common mistakes - Trying to change a character. word[0] = "J" is a TypeError . Build a new String: "J" + word[1:] . - Forgetting to store a String result. name.title() alone changes nothing; write name = name.title() . - Storing a List method''s result. subjects = subjects.append("Art") replaces your List with None . - Doing steps in the wrong order. In the practice, replacing subjects[0] before step 1 would print Calculus instead of Math. With a mutable List, the order of the lines decides what each line sees. Key takeaways - Strings and Lists are both sequences: indexing, slicing and len() work on both. - Lists are mutable (they can change); Strings are immutable (they can''t). - To "change" a String, build a new one, for example "J" + word[1:] , and store it. - String methods return new Strings; List methods like append() change the List and return None . - Store → access → modify → use : that is what Strings and Lists let a program do with collections of data.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_acf2557a43d5a105', 'course_programming_applications', 'top_e57cde355af1cd13', 'objects-and-methods', 'Objects and methods', 'Every value in Python is an object that holds data and can perform operations. Learn the words object, method and dot notation, using the Strings and Lists you already know, and see how new objects are created.', 3, 9, 'easy', '["Explain what an object is, with data and operations","Call a method with dot notation and name each part of the call","Tell which methods belong to Strings and which to Lists","Describe how calling a function such as Point(100, 150) creates a new object"]', '["Strings vs Lists, and a final practice"]', 8, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
