INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_04a74f77ccae4d11', 'course_programming_applications', 'les_acf2557a43d5a105', 'explanation', 'You have already used objects', 'Look at this program. Every line uses something you learned in the last lecture.

```python
name = "Omar"
grades = [90, 85, 88]
print(name)
print(grades)
name.upper()        # gives "OMAR"
grades.append(95)   # grades is now [90, 85, 88, 95]
```

What is `name`? A String. What is `grades`? A List. What can we do with them? Print them, index them, slice them, and call things like `upper()` and `append()`.

And what are `.upper()` and `.append()`? They are **methods**: actions that belong to the String and to the List. In this lecture you get the words for what you have been doing all along: **we have already been using objects and methods; we just did not call them that yet.**', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_1533a802d0dd64a7', 'course_programming_applications', 'les_acf2557a43d5a105', 'code', 'The review program, run', '', 'name = "Omar"
grades = [90, 85, 88]
