INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_applications', 'lesson', 'les_acf2557a43d5a105', '/courses/programming-applications/lectures/objects-and-methods', 'Objects and methods', 'Every value in Python is an object that holds data and can perform operations. Learn the words object, method and dot notation, using the Strings and Lists you already know, and see how new objects are created. Explain what an object is, with data and operations Call a method with dot notation and name each part of the call Tell which methods belong to Strings and which to Lists Describe how calling a function such as Point(100, 150) creates a new object You have already used objects Look at this program. Every line uses something you learned in the last lecture. name = "Omar" grades = [90, 85, 88] print(name) print(grades) name.upper() gives "OMAR" grades.append(95) grades is now [90, 85, 88, 95] What is name ? A String. What is grades ? A List. What can we do with them? Print them, index them, slice them, and call things like upper() and append() . And what are .upper() and .append() ? They are methods : actions that belong to the String and to the List. In this lecture you get the words for what you have been doing all along: we have already been using objects and methods; we just did not call them that yet. The review program, run name = "Omar" grades = [90, 85, 88] print(name.upper()) grades.append(95) print(grades) print(name) What is an object? An object is something in a program that contains information and can perform operations. Think of a car. A car has information about itself, its data : its colour, its current speed, its model. And it can do things, its actions : start, stop, move. A car A Python object --- --- --- Data (what it knows) colour, speed, model the values it holds Actions (what it can do) start, stop, move its methods A Python object is the same idea: data + operations . Try it with a phone: what data does a phone have? (A battery level, a list of contacts.) What can it do? (Call, take a photo, ring.) Objects are everywhere Every value you have used is an object. Object Data it holds Some operations it can do --- --- --- name = "Omar" (a String object) the characters O , m , a , r .upper() , .lower() , .title() students = ["Ali", "Omar"] (a List object) the items "Ali" and "Omar" .append("Sara") , .sort() , .pop() type() tells you what kind of object a value is. You saw <class ''str'' in the first lecture; now you know that a String is one kind of object, and a List is another. One List object, two methods sort() is another List method: it puts the items in order. The List object changes itself, as Lists do. students = ["Ali", "Omar"] students.append("Sara") students.sort() print(students) print(type(students)) Objects and methods A method is an operation that belongs to an object. You call it with this pattern: object.method() Follow one call from start to end. The object is the List students , holding ["Ali", "Omar"] . It receives the method call .append("Sara") . The action: the List now holds ["Ali", "Omar", "Sara"] . Each kind of object has its own methods. Strings have upper() ; Lists have append() . Calling a method that the object doesn''t have stops the program: "Omar".append("x") gives AttributeError: ''str'' object has no attribute ''append'' . Dot notation Read a method call from left to right: students . append ("Ali") --- --- --- --- the object the dot the method the argument - The dot means "use something belonging to this object." - The argument , inside the brackets, is extra information the method needs: which item to append. - Some methods need no argument, like upper() , but the brackets are still required. The same pattern appears everywhere: name.upper() students.append("Ali") circle.draw(win) The last line is a preview of the next lecture: shapes in a window are objects too, and they use the same dot. Check yourself name is the object (a String), upper is the method , and the brackets are empty because upper() needs no argument. word = "Hello" letters = list(word) letters.append("!") print(word.lower(), letters[-1], len(letters)) hello ! 6 list(word) makes a new List object holding the 5 characters. append("!") adds a sixth item. word.lower() gives a new String, "hello" . Creating objects Strings and Lists can be written directly in the code: "Omar" , [1, 2] . Many other objects are created by calling a special function whose name tells you what kind of object you get. p = Point(100, 150) Here is what happens, in three steps: 1. Call the function : Point(100, 150) . 2. A new object is made : a Point object that remembers x → 100 and y → 150 . 3. p refers to it : p is a variable, a name stuck on the new object like a label. What would Point(250, 50) create? Another, separate Point object, at x = 250 and y = 50. Point comes from the graphics library you will meet in the next lecture. You have used the same idea already: int("42") creates an int object from text, and list("Hi") creates a List object [''H'', ''i''] . Calling a type''s name creates an object number = int("42") text = str(7) letters = list("Hi") print(number + 1) print(text + "!") print(letters) Common mistakes - Leaving out the brackets. name.upper without () names the method but doesn''t call it. - Calling a method the object doesn''t have. "Omar".append("x") is an AttributeError : append belongs to Lists, not Strings. - Putting a space around the dot. students . append("Ali") happens to work, but nobody writes it that way. Write students.append("Ali") . - Forgetting that some methods change the object and some don''t. List methods like append() change the List; String methods like upper() return a new String. Key takeaways - An object holds data (what it knows) and has operations (what it can do). - Every value in Python, including Strings and Lists, is an object. - A method is an operation that belongs to an object, called with dot notation: object.method(argument) . - The dot means "use something belonging to this object"; each kind of object has its own methods. - Some objects are created by calling a function named after their kind, such as Point(100, 150) .');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_169dba8964c25c2b', 'course_programming_applications', 'top_7a6ac98b95c0c58e', 'graphics-windows-and-coordinates', 'Graphics: windows and coordinates', 'Use Zelle''s graphics library to open a window from Python, understand the window as an object with its own methods, and find any position in it with x and y coordinates.', 3, 10, 'easy', '["Explain what computer graphics are, with examples","Set up graphics.py and import it with from graphics import *","Open a window with GraphWin, keep it open with getMouse() and close it","Find a position in the window from its x and y coordinates"]', '["Objects and methods"]', 6, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
