INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e7e1d3d75d182b75', 'course_programming_applications', 'les_169dba8964c25c2b', 'explanation', 'What are computer graphics?', '**Computer graphics** means using programs to create visual elements on the screen: shapes, text, buttons, diagrams, games, simulations and user interfaces. Every app window you have ever used was drawn by a program.

Here is what happens when one of our graphics programs runs:

1. You write **code**, for example `circle.draw(win)`.
2. A **graphics library** does the hard work of talking to the screen.
3. A **window** opens.
4. **Shapes** appear in it.

The key idea for this course: **every shape you draw is an object**, just like a String or a List. It has data (its position, its size, its colour) and methods (draw it, move it, colour it).', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b519e71614e4b259', 'course_programming_applications', 'les_169dba8964c25c2b', 'explanation', 'Our graphics library: graphics.py', 'We use **graphics.py**, a small library written by John Zelle for teaching programming. It is a single Python file. It is not built into Python, so it has to be set up once:

- **Keep `graphics.py` in the same folder as your program.** Your teacher gives you the file, or you can download it from its author''s website.
- It draws with **Tkinter**, which comes with the standard Python installer on Windows and macOS. On some Linux systems Tkinter is a separate package (for example `python3-tk`).

The first line of every graphics program loads the library:

```python
from graphics import *
```

`graphics` is the name of the file (without `.py`), and `import *` brings in **everything** it provides:

| Name | Creates |
|---|---|
| `GraphWin` | windows |
| `Point` | positions |
| `Line`, `Circle`, `Rectangle`, `Oval`, `Polygon` | shapes |
| `Text` | words in the window |

All of these are **classes** that someone else wrote. Today we only **use** them to make objects; building our own classes comes later in the course.

::: warning These programs run on your computer, not in the browser
The Run button on this site runs Python in your browser, which has no windows to open. So the graphics programs in these lectures have no Run button: copy them into a file next to `graphics.py` and run them with Python on your computer. The pictures show what the window looks like.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_974045a0381f3a5c', 'course_programming_applications', 'les_169dba8964c25c2b', 'code', 'Our first graphics window', '', 'from graphics import *

win = GraphWin("My First Window", 500, 400)
win.getMouse()
win.close()', 'python', 0, '', NULL, '{"notes":[{"line":1,"match":"import *","text":"1. load the library","shape":"circle","color":"sky"},{"line":3,"match":"GraphWin","text":"2. title, width, height","shape":"square","color":"yel"},{"line":4,"match":"getMouse","text":"3. wait for a click","shape":"diamond","color":"green"},{"line":5,"match":"close","text":"4. close the window","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_88cf31afac94019c', 'course_programming_applications', 'les_169dba8964c25c2b', 'diagram', 'The window it opens', 'The program opens an empty window titled **My First Window**, 500 pixels wide and 400 pixels tall, and waits. When you click anywhere inside it, the program closes it. The title bar looks different on Windows, macOS and Linux; the drawing area is the same.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_applications/lessons/les_169dba8964c25c2b/py-first-window.png', 'An empty window titled My First Window, 500 pixels wide and 400 pixels tall, with a plain light grey drawing area', 1004, 868, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_269c2d670505b674', 'course_programming_applications', 'les_169dba8964c25c2b', 'explanation', 'Line by line', '1. `from graphics import *` loads the library.
2. `GraphWin("My First Window", 500, 400)` creates a window: its **title**, its **width** (500 pixels) and its **height** (400 pixels).
3. `win.getMouse()` pauses the program until the user clicks inside the window. Without it, the program would reach the last line straight away, and the window would open and close before you could see it.
4. `win.close()` closes the window.

Change the title and the two numbers, run it again, and watch the window change.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f4258e26500160ca', 'course_programming_applications', 'les_169dba8964c25c2b', 'explanation', 'The window is an object', '```python
win = GraphWin("My Window", 500, 400)
```

`GraphWin(...)` **creates the window object**. `win` is only a **variable**: a name that refers to that object, exactly like `p` referred to a Point object in the last lecture.

Because `win` refers to a window object, you can ask it to do things with dot notation:

| Method | What it does |
|---|---|
| `win.getMouse()` | waits for a click inside the window |
| `win.close()` | closes the window |

If you wrote `w2 = GraphWin("Second", 300, 300)` as well, you would have **two separate window objects**, each with its own name, size and shapes.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_4eabfb4f5b55f868', 'course_programming_applications', 'les_169dba8964c25c2b', 'explanation', 'The coordinate system', 'Every position in the window is a pair of numbers, **(x, y)**:

- **(0, 0) is the top-left corner** of the window.
- **x grows to the right**: it says how far from the left edge.
- **y grows downward**: it says how far from the top edge. This is the opposite of a maths graph, where y grows upward, so it surprises almost everyone at first.

For a 500 × 400 window, the four corners are (0, 0), (500, 0), (0, 400) and (500, 400).', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2204d722a26cfa04', 'course_programming_applications', 'les_169dba8964c25c2b', 'diagram', 'Coordinates in a 500 × 400 window', 'Each grid square is 50 × 50 pixels. The dot in the middle is **Point(250, 200)**: half of 500 across and half of 400 down, the exact centre of the window.

Strictly, the pixels are numbered 0 to 499 across and 0 to 399 down, so (500, 400) is the outer edge of the window rather than a pixel inside it.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_applications/lessons/les_169dba8964c25c2b/py-coordinates.png', 'A 500 by 400 window with a grid every 50 pixels. The corners are labelled (0, 0) at the top left, (500, 0) at the top right, (0, 400) at the bottom left and (500, 400) at the bottom right. An arrow along the top shows x growing to the right and an arrow down the left side shows y growing downward. A dot marks the centre at (250, 200)', 1004, 868, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_09a24b19ed851db3', 'course_programming_applications', 'les_169dba8964c25c2b', 'note', 'Check yourself', '::: check Where is Point(250, 200) in a 500 × 400 window?
???
In the exact **centre**: 250 is half of the width and 200 is half of the height.
:::

::: check In a 500 × 400 window, which point is nearer the bottom: (100, 350) or (400, 50)?
???
**(100, 350)**. y grows downward, so the larger y, 350, is nearer the bottom. (400, 50) is near the top-right corner.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_be0ecf0d8ee9e7b6', 'course_programming_applications', 'les_169dba8964c25c2b', 'common_mistakes', 'Common mistakes', '- **graphics.py in the wrong folder.** If Python can''t find the file, the first line stops with `ModuleNotFoundError: No module named ''graphics''`. Put `graphics.py` next to your program.
- **Naming your own file graphics.py.** Then `from graphics import *` imports *your* file instead of the library. Call your program something else, such as `my_window.py`.
- **No getMouse() before close().** The window flashes open and shut. Wait for a click before closing.
- **Thinking y grows upward.** In the window, a larger y is **lower** on the screen.
- **Swapping width and height.** `GraphWin("Tall", 300, 500)` is 300 wide and 500 tall: width comes first.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_24a6a1725886eb1f', 'course_programming_applications', 'les_169dba8964c25c2b', 'key_takeaways', 'Key takeaways', '- Graphics programs draw visual elements; with graphics.py, every window and shape is an object.
- Keep `graphics.py` next to your program and start with `from graphics import *`.
- `GraphWin(title, width, height)` creates a window object; `win.getMouse()` waits for a click and `win.close()` closes it.
- (0, 0) is the top-left corner; x grows to the right and **y grows downward**.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1792022400000);
