INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_applications', 'lesson', 'les_169dba8964c25c2b', '/courses/programming-applications/lectures/graphics-windows-and-coordinates', 'Graphics: windows and coordinates', 'Use Zelle''s graphics library to open a window from Python, understand the window as an object with its own methods, and find any position in it with x and y coordinates. Explain what computer graphics are, with examples Set up graphics.py and import it with from graphics import * Open a window with GraphWin, keep it open with getMouse() and close it Find a position in the window from its x and y coordinates What are computer graphics? Computer graphics means using programs to create visual elements on the screen: shapes, text, buttons, diagrams, games, simulations and user interfaces. Every app window you have ever used was drawn by a program. Here is what happens when one of our graphics programs runs: 1. You write code , for example circle.draw(win) . 2. A graphics library does the hard work of talking to the screen. 3. A window opens. 4. Shapes appear in it. The key idea for this course: every shape you draw is an object , just like a String or a List. It has data (its position, its size, its colour) and methods (draw it, move it, colour it). Our graphics library: graphics.py We use graphics.py , a small library written by John Zelle for teaching programming. It is a single Python file. It is not built into Python, so it has to be set up once: - Keep graphics.py in the same folder as your program. Your teacher gives you the file, or you can download it from its author''s website. - It draws with Tkinter , which comes with the standard Python installer on Windows and macOS. On some Linux systems Tkinter is a separate package (for example python3-tk ). The first line of every graphics program loads the library: from graphics import graphics is the name of the file (without .py ), and import brings in everything it provides: Name Creates --- --- GraphWin windows Point positions Line , Circle , Rectangle , Oval , Polygon shapes Text words in the window All of these are classes that someone else wrote. Today we only use them to make objects; building our own classes comes later in the course. The Run button on this site runs Python in your browser, which has no windows to open. So the graphics programs in these lectures have no Run button: copy them into a file next to graphics.py and run them with Python on your computer. The pictures show what the window looks like. Our first graphics window from graphics import * win = GraphWin("My First Window", 500, 400) win.getMouse() win.close() The window it opens The program opens an empty window titled My First Window , 500 pixels wide and 400 pixels tall, and waits. When you click anywhere inside it, the program closes it. The title bar looks different on Windows, macOS and Linux; the drawing area is the same. Line by line 1. from graphics import loads the library. 2. GraphWin("My First Window", 500, 400) creates a window: its title , its width (500 pixels) and its height (400 pixels). 3. win.getMouse() pauses the program until the user clicks inside the window. Without it, the program would reach the last line straight away, and the window would open and close before you could see it. 4. win.close() closes the window. Change the title and the two numbers, run it again, and watch the window change. The window is an object win = GraphWin("My Window", 500, 400) GraphWin(...) creates the window object . win is only a variable : a name that refers to that object, exactly like p referred to a Point object in the last lecture. Because win refers to a window object, you can ask it to do things with dot notation: Method What it does --- --- win.getMouse() waits for a click inside the window win.close() closes the window If you wrote w2 = GraphWin("Second", 300, 300) as well, you would have two separate window objects , each with its own name, size and shapes. The coordinate system Every position in the window is a pair of numbers, (x, y) : - (0, 0) is the top-left corner of the window. - x grows to the right : it says how far from the left edge. - y grows downward : it says how far from the top edge. This is the opposite of a maths graph, where y grows upward, so it surprises almost everyone at first. For a 500 × 400 window, the four corners are (0, 0), (500, 0), (0, 400) and (500, 400). Coordinates in a 500 × 400 window Each grid square is 50 × 50 pixels. The dot in the middle is Point(250, 200) : half of 500 across and half of 400 down, the exact centre of the window. Strictly, the pixels are numbered 0 to 499 across and 0 to 399 down, so (500, 400) is the outer edge of the window rather than a pixel inside it. Check yourself In the exact centre : 250 is half of the width and 200 is half of the height. (100, 350) . y grows downward, so the larger y, 350, is nearer the bottom. (400, 50) is near the top-right corner. Common mistakes - graphics.py in the wrong folder. If Python can''t find the file, the first line stops with ModuleNotFoundError: No module named ''graphics'' . Put graphics.py next to your program. - Naming your own file graphics.py. Then from graphics import imports your file instead of the library. Call your program something else, such as my window.py . - No getMouse() before close(). The window flashes open and shut. Wait for a click before closing. - Thinking y grows upward. In the window, a larger y is lower on the screen. - Swapping width and height. GraphWin("Tall", 300, 500) is 300 wide and 500 tall: width comes first. Key takeaways - Graphics programs draw visual elements; with graphics.py, every window and shape is an object. - Keep graphics.py next to your program and start with from graphics import . - GraphWin(title, width, height) creates a window object; win.getMouse() waits for a click and win.close() closes it. - (0, 0) is the top-left corner; x grows to the right and y grows downward .');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_00f7eb556125a847', 'course_programming_applications', 'top_7a6ac98b95c0c58e', 'drawing-shapes', 'Drawing shapes', 'Draw points, lines, circles, rectangles, ovals, polygons and text in a graphics.py window, and see how bigger shapes are built from Point objects.', 3, 11, 'easy', '["Create a Point and draw it in a window","Build a Line, a Circle and a Rectangle from Point objects","Work out a rectangle''s width and height from its corners","Use Oval, Polygon and Text"]', '["Graphics: windows and coordinates"]', 10, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_programming_applications' AND lesson_id = 'les_00f7eb556125a847';
DELETE FROM lesson_relations WHERE course_id = 'course_programming_applications' AND lesson_id = 'les_00f7eb556125a847';
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_605648547913b6a8', 'course_programming_applications', 'les_00f7eb556125a847', 'explanation', 'Every shape follows the same pattern', 'Drawing anything with graphics.py takes two steps:

1. **Create** the shape object, giving it the positions and sizes it needs.
2. **Draw** it in a window with its `draw()` method: `shape.draw(win)`.

A shape you create but never draw stays invisible. All the programs in this lecture are complete: copy one into a file next to `graphics.py`, run it, and click the window to close it.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_6bd2cd9ef5a39fbc', 'course_programming_applications', 'les_00f7eb556125a847', 'code', 'The Point object', '`Point(x, y)` creates a Point object. The first number is **x**, how far to the right of the left edge; the second is **y**, how far down from the top. `p.draw(win)` displays it in the window `win`.', 'from graphics import *

win = GraphWin("Point", 500, 400)
p = Point(100, 150)
p.draw(win)
win.getMouse()
win.close()', 'python', 0, '', NULL, '{"notes":[{"line":4,"match":"100","text":"x: how far right","shape":"circle","color":"sky"},{"line":4,"match":"150","text":"y: how far down","shape":"square","color":"yel"},{"line":5,"match":"draw(win)","text":"show it in win","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_50127e65231ac6e8', 'course_programming_applications', 'les_00f7eb556125a847', 'diagram', 'One point at (100, 150)', 'On a real screen a Point is a **single pixel**, very hard to see. It is drawn bigger here, and the dashed lines and label were added to the picture to show where it is. That is why Points are mostly used to describe **positions** for other shapes, as in the rest of this lecture.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_applications/lessons/les_00f7eb556125a847/py-point.png', 'A 500 by 400 window titled Point. A small black dot sits 100 pixels from the left and 150 pixels from the top, labelled (100, 150), with dashed guide lines to the top and left edges', 1004, 868, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_73a570696ab2da2a', 'course_programming_applications', 'les_00f7eb556125a847', 'code', 'Drawing several points', 'Each Point is a separate object with its own name and its own coordinates, and each one needs its own `draw` call.', 'from graphics import *

win = GraphWin("Three Points", 500, 400)
p1 = Point(100, 100)
p2 = Point(200, 150)
p3 = Point(300, 250)
p1.draw(win)
p2.draw(win)
p3.draw(win)
win.getMouse()
win.close()', 'python', 0, '', NULL, '{"notes":[{"line":4,"match":"p1","text":"its own object","shape":"circle","color":"sky"},{"line":7,"match":"p1.draw(win)","text":"one draw per Point","shape":"square","color":"yel"}],"strips":[]}', NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5a73c986164fcc2b', 'course_programming_applications', 'les_00f7eb556125a847', 'diagram', 'The three points', 'Which point is closest to the top-left corner, (0, 0)? **p1**, because both of its numbers are the smallest. Change `p3` to `Point(450, 350)` and it moves near the bottom-right corner; `p1` and `p2` stay where they are, because each object is independent.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_applications/lessons/les_00f7eb556125a847/py-points.png', 'A 500 by 400 window with three dots labelled p1 (100, 100), p2 (200, 150) and p3 (300, 250), going down and to the right from the top-left area', 1004, 868, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_28269236675aba35', 'course_programming_applications', 'les_00f7eb556125a847', 'code', 'Drawing a line', '`Line(point1, point2)` builds one object from two others: a Line needs two Point objects, **where it starts** and **where it ends**.', 'from graphics import *

win = GraphWin("Line", 500, 400)
p1 = Point(100, 100)
p2 = Point(300, 200)
line = Line(p1, p2)
line.draw(win)
win.getMouse()
win.close()', 'python', 0, '', NULL, '{"notes":[{"line":6,"match":"Line(p1, p2)","text":"Point + Point = Line","shape":"circle","color":"sky"},{"line":7,"match":"line.draw","text":"only the line is drawn","shape":"square","color":"yel"}],"strips":[]}', NULL, NULL, NULL, NULL, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3d77018f61bfb112', 'course_programming_applications', 'les_00f7eb556125a847', 'diagram', 'A line from (100, 100) to (300, 200)', 'The two Points only give the line its position. They are not drawn themselves; the labels at the ends were added to the picture. To draw a horizontal line across the whole window, you would write `Line(Point(0, 200), Point(500, 200))`.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_applications/lessons/les_00f7eb556125a847/py-line.png', 'A 500 by 400 window with a thin black line going down and to the right, from (100, 100) to (300, 200); both ends are labelled', 1004, 868, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_21390e6bbb2afafb', 'course_programming_applications', 'les_00f7eb556125a847', 'code', 'Drawing a circle', '`Circle(center, radius)` needs a **center**, which is a Point object, and a **radius**, a number of pixels from the center to the edge.', 'from graphics import *

win = GraphWin("Circle", 500, 400)
center = Point(250, 200)
circle = Circle(center, 80)
circle.draw(win)
win.getMouse()
win.close()', 'python', 0, '', NULL, '{"notes":[{"line":4,"match":"Point(250, 200)","text":"the middle","shape":"circle","color":"sky"},{"line":5,"match":"80","text":"radius in pixels","shape":"square","color":"yel"}],"strips":[]}', NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_78c81ae5dcc40e51', 'course_programming_applications', 'les_00f7eb556125a847', 'diagram', 'A circle with radius 80', 'The circle is **160 pixels wide**, because its width is two radii. To make it bigger, change the **radius**; to move it, change the **center** Point.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_applications/lessons/les_00f7eb556125a847/py-circle.png', 'A 500 by 400 window with a black circle outline in the centre. A dashed line from the centre point (250, 200) to the right edge of the circle is labelled radius = 80', 1004, 868, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b7073d0767d0c909', 'course_programming_applications', 'les_00f7eb556125a847', 'code', 'Drawing a rectangle', '`Rectangle(point1, point2)` is defined by **two opposite corners**, both Point objects. Here Point 1 is the top-left corner and Point 2 is the bottom-right corner. The Points are created right inside the `Rectangle(...)` call, which is the same as creating them in variables first.', 'from graphics import *

win = GraphWin("Rectangle", 500, 400)
rect = Rectangle(
    Point(100, 100),
    Point(300, 250)
)
rect.draw(win)
win.getMouse()
win.close()', 'python', 0, '', NULL, '{"notes":[{"line":5,"match":"Point(100, 100)","text":"Point 1: top-left","shape":"circle","color":"sky"},{"line":6,"match":"Point(300, 250)","text":"Point 2: bottom-right","shape":"square","color":"yel"}],"strips":[]}', NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_234a90d527bd6c64', 'course_programming_applications', 'les_00f7eb556125a847', 'diagram', 'A 200 × 150 rectangle', 'The size comes from subtraction: **width = 300 − 100 = 200** and **height = 250 − 100 = 150**. What would `Rectangle(Point(0, 0), Point(500, 400))` draw? A rectangle covering the whole window.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_applications/lessons/les_00f7eb556125a847/py-rectangle.png', 'A 500 by 400 window with a black rectangle outline. Its top-left corner is labelled (100, 100) and its bottom-right corner (300, 250); its size is marked as 200 wide by 150 tall', 1004, 868, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e2ba56d3388fd4ef', 'course_programming_applications', 'les_00f7eb556125a847', 'explanation', 'More graphical objects', 'Four more shapes complete the set. Each one is drawn the same way, with `name.draw(win)`:

| Object | How it is defined | Example |
|---|---|---|
| `Oval` | fits inside an invisible box set by **2 opposite corners** | `Oval(Point(100, 100), Point(300, 200))` |
| `Polygon` | joins **3 or more points** in order, and closes the shape | `Polygon(Point(250, 50), Point(150, 250), Point(350, 250))` |
| `Line` | joins **exactly 2 points** | `Line(Point(50, 50), Point(250, 150))` |
| `Text` | words **centered on a point** | `Text(Point(250, 50), "Hi!")` |

Three Points in a Polygon make a triangle; four can make any four-sided shape.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ba5ecb838b349558', 'course_programming_applications', 'les_00f7eb556125a847', 'code', 'Four shapes in one window', 'The program draws all four in one window, with positions chosen so they don''t overlap.', 'from graphics import *

win = GraphWin("More Shapes", 500, 400)

oval = Oval(Point(40, 60), Point(240, 160))
oval.draw(win)

triangle = Polygon(Point(380, 40), Point(290, 180), Point(470, 180))
triangle.draw(win)

line = Line(Point(40, 250), Point(240, 350))
line.draw(win)

label = Text(Point(380, 300), "Hi!")
label.draw(win)

win.getMouse()
win.close()', 'python', 0, '', NULL, '{"notes":[{"line":5,"match":"Oval","text":"2 corners of a box","shape":"circle","color":"sky"},{"line":8,"match":"Polygon","text":"3 points: a triangle","shape":"square","color":"yel"},{"line":11,"match":"Line","text":"exactly 2 points","shape":"diamond","color":"green"},{"line":14,"match":"Text","text":"centered on the Point","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 13, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_6a71342087b3f069', 'course_programming_applications', 'les_00f7eb556125a847', 'diagram', 'Oval, polygon, line and text', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_applications/lessons/les_00f7eb556125a847/py-more-shapes.png', 'A 500 by 400 window with four shapes: a black oval outline at the top left, a triangle outline at the top right, a diagonal line at the bottom left and the word Hi! at the bottom right', 1004, 868, 14, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e80ebcfdad7eb817', 'course_programming_applications', 'les_00f7eb556125a847', 'note', 'Check yourself', '::: check Which number would you change to make a circle bigger? And which object would you change to move it?
???
Change the **radius** to make it bigger, and the **center Point** to move it.
:::

::: check How wide and how tall is `Rectangle(Point(50, 80), Point(250, 130))`?
???
**200 wide** (250 − 50) and **50 tall** (130 − 80).
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 15, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_56fee2992f745059', 'course_programming_applications', 'les_00f7eb556125a847', 'common_mistakes', 'Common mistakes', '- **Creating a shape but not drawing it.** Nothing appears until you call `shape.draw(win)`.
- **Giving numbers where Points are needed.** `Line(100, 100, 300, 200)` is an error: a Line takes **two Point objects**, `Line(Point(100, 100), Point(300, 200))`.
- **Using a diameter as the radius.** `Circle(center, 160)` is 320 pixels wide. The radius is half the width.
- **Drawing the same object twice.** Calling `rect.draw(win)` a second time stops with `GraphicsError: Object currently drawn`. Each object is drawn once; create another object for a second copy.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 16, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b9cabf0c0aab8376', 'course_programming_applications', 'les_00f7eb556125a847', 'key_takeaways', 'Key takeaways', '- Create a shape object, then show it with `shape.draw(win)`.
- `Point(x, y)` is a position; Points are used to build the other shapes.
- `Line` takes 2 Points, `Circle` a center Point and a radius, and `Rectangle` and `Oval` 2 opposite corners.
- `Polygon` joins 3 or more Points; `Text` shows a String centered on a Point.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 17, 1792022400000);
DELETE FROM search_index WHERE course_id = 'course_programming_applications' AND entity_type = 'lesson' AND entity_id = 'les_00f7eb556125a847';
INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_applications', 'lesson', 'les_00f7eb556125a847', '/courses/programming-applications/lectures/drawing-shapes', 'Drawing shapes', 'Draw points, lines, circles, rectangles, ovals, polygons and text in a graphics.py window, and see how bigger shapes are built from Point objects. Create a Point and draw it in a window Build a Line, a Circle and a Rectangle from Point objects Work out a rectangle''s width and height from its corners Use Oval, Polygon and Text Every shape follows the same pattern Drawing anything with graphics.py takes two steps: 1. Create the shape object, giving it the positions and sizes it needs. 2. Draw it in a window with its draw() method: shape.draw(win) . A shape you create but never draw stays invisible. All the programs in this lecture are complete: copy one into a file next to graphics.py , run it, and click the window to close it. The Point object Point(x, y) creates a Point object. The first number is x , how far to the right of the left edge; the second is y , how far down from the top. p.draw(win) displays it in the window win . from graphics import * win = GraphWin("Point", 500, 400) p = Point(100, 150) p.draw(win) win.getMouse() win.close() One point at (100, 150) On a real screen a Point is a single pixel , very hard to see. It is drawn bigger here, and the dashed lines and label were added to the picture to show where it is. That is why Points are mostly used to describe positions for other shapes, as in the rest of this lecture. Drawing several points Each Point is a separate object with its own name and its own coordinates, and each one needs its own draw call. from graphics import * win = GraphWin("Three Points", 500, 400) p1 = Point(100, 100) p2 = Point(200, 150) p3 = Point(300, 250) p1.draw(win) p2.draw(win) p3.draw(win) win.getMouse() win.close() The three points Which point is closest to the top-left corner, (0, 0)? p1 , because both of its numbers are the smallest. Change p3 to Point(450, 350) and it moves near the bottom-right corner; p1 and p2 stay where they are, because each object is independent. Drawing a line Line(point1, point2) builds one object from two others: a Line needs two Point objects, where it starts and where it ends . from graphics import * win = GraphWin("Line", 500, 400) p1 = Point(100, 100) p2 = Point(300, 200) line = Line(p1, p2) line.draw(win) win.getMouse() win.close() A line from (100, 100) to (300, 200) The two Points only give the line its position. They are not drawn themselves; the labels at the ends were added to the picture. To draw a horizontal line across the whole window, you would write Line(Point(0, 200), Point(500, 200)) . Drawing a circle Circle(center, radius) needs a center , which is a Point object, and a radius , a number of pixels from the center to the edge. from graphics import * win = GraphWin("Circle", 500, 400) center = Point(250, 200) circle = Circle(center, 80) circle.draw(win) win.getMouse() win.close() A circle with radius 80 The circle is 160 pixels wide , because its width is two radii. To make it bigger, change the radius ; to move it, change the center Point. Drawing a rectangle Rectangle(point1, point2) is defined by two opposite corners , both Point objects. Here Point 1 is the top-left corner and Point 2 is the bottom-right corner. The Points are created right inside the Rectangle(...) call, which is the same as creating them in variables first. from graphics import * win = GraphWin("Rectangle", 500, 400) rect = Rectangle( Point(100, 100), Point(300, 250) ) rect.draw(win) win.getMouse() win.close() A 200 × 150 rectangle The size comes from subtraction: width = 300 − 100 = 200 and height = 250 − 100 = 150 . What would Rectangle(Point(0, 0), Point(500, 400)) draw? A rectangle covering the whole window. More graphical objects Four more shapes complete the set. Each one is drawn the same way, with name.draw(win) : Object How it is defined Example --- --- --- Oval fits inside an invisible box set by 2 opposite corners Oval(Point(100, 100), Point(300, 200)) Polygon joins 3 or more points in order, and closes the shape Polygon(Point(250, 50), Point(150, 250), Point(350, 250)) Line joins exactly 2 points Line(Point(50, 50), Point(250, 150)) Text words centered on a point Text(Point(250, 50), "Hi!") Three Points in a Polygon make a triangle; four can make any four-sided shape. Four shapes in one window The program draws all four in one window, with positions chosen so they don''t overlap. from graphics import * win = GraphWin("More Shapes", 500, 400) oval = Oval(Point(40, 60), Point(240, 160)) oval.draw(win) triangle = Polygon(Point(380, 40), Point(290, 180), Point(470, 180)) triangle.draw(win) line = Line(Point(40, 250), Point(240, 350)) line.draw(win) label = Text(Point(380, 300), "Hi!") label.draw(win) win.getMouse() win.close() Oval, polygon, line and text Check yourself Change the radius to make it bigger, and the center Point to move it. 200 wide (250 − 50) and 50 tall (130 − 80). Common mistakes - Creating a shape but not drawing it. Nothing appears until you call shape.draw(win) . - Giving numbers where Points are needed. Line(100, 100, 300, 200) is an error: a Line takes two Point objects , Line(Point(100, 100), Point(300, 200)) . - Using a diameter as the radius. Circle(center, 160) is 320 pixels wide. The radius is half the width. - Drawing the same object twice. Calling rect.draw(win) a second time stops with GraphicsError: Object currently drawn . Each object is drawn once; create another object for a second copy. Key takeaways - Create a shape object, then show it with shape.draw(win) . - Point(x, y) is a position; Points are used to build the other shapes. - Line takes 2 Points, Circle a center Point and a radius, and Rectangle and Oval 2 opposite corners. - Polygon joins 3 or more Points; Text shows a String centered on a Point.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_0c2476c4f9984e9a', 'course_programming_applications', 'top_7a6ac98b95c0c58e', 'colors-moving-and-text', 'Colours, moving and text', 'Change graphical objects with their methods. Colour the inside and the edge of a shape, move it with move(dx, dy), and change the size and colour of text.', 3, 12, 'easy', '["Use draw(), setFill(), setOutline() and move() on a shape","Write colours as Strings, or mix your own with color_rgb()","Predict where a shape ends up after move(dx, dy)","Change a Text object''s size and colour"]', '["Drawing shapes"]', 8, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_programming_applications' AND lesson_id = 'les_0c2476c4f9984e9a';
