INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_fe42ad90aaf72518', 'course_programming_applications', 'les_0c2476c4f9984e9a', 'explanation', 'Object methods in graphics', 'Shapes are objects, so they have methods, called with the same dot notation as `name.upper()`:

```python
circle.draw(win)
circle.setFill("blue")
circle.setOutline("black")
circle.move(20, 0)
```

`circle` is the **object**; `draw`, `setFill`, `setOutline` and `move` are its **methods**. Each method does one job:

| Method | What it does |
|---|---|
| `draw(win)` | shows the shape in the window `win` |
| `setFill(color)` | colours the **inside** of the shape |
| `setOutline(color)` | colours the **edge** of the shape |
| `move(dx, dy)` | shifts the shape''s position |

Which method would you use to make a shape''s edge red? `setOutline("red")`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_c14f59e0be1dcce3', 'course_programming_applications', 'les_0c2476c4f9984e9a', 'code', 'Colouring a circle', '', 'from graphics import *

win = GraphWin("Colors", 500, 400)
circle = Circle(Point(250, 200), 80)
circle.setFill("blue")
circle.setOutline("black")
circle.draw(win)
win.getMouse()
win.close()', 'python', 0, '', NULL, '{"notes":[{"line":5,"match":"setFill","text":"the inside","shape":"circle","color":"sky"},{"line":6,"match":"setOutline","text":"the edge","shape":"square","color":"yel"},{"line":5,"match":"\"blue\"","text":"colours are Strings","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_30d49f0b575c15f6', 'course_programming_applications', 'les_0c2476c4f9984e9a', 'diagram', 'A filled circle', 'A new shape starts **empty** (no fill) with a **black outline**, like the circles in the last lecture. After `setFill("blue")` it is filled. You can set colours before or after `draw()`: the window updates either way.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_applications/lessons/les_0c2476c4f9984e9a/py-colors.png', 'A 500 by 400 window with a circle in the centre, filled solid blue with a black edge', 1004, 868, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_47ff33c19b085146', 'course_programming_applications', 'les_0c2476c4f9984e9a', 'explanation', 'Writing colours', 'Colour names are **Strings**, so they need quotes. Common ones are `"red"`, `"blue"`, `"green"`, `"yellow"`, `"black"` and `"white"`; the library understands many more, such as `"orange"`, `"purple"`, `"pink"` and `"gray"`.

For any other colour, mix it yourself with `color_rgb(red, green, blue)`. Each amount is from 0 to 255: `color_rgb(255, 120, 0)` is orange, and `color_rgb(0, 0, 0)` is black.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_90d14d846e694d30', 'course_programming_applications', 'les_0c2476c4f9984e9a', 'code', 'A row of colours', '', 'from graphics import *

win = GraphWin("Colour Row", 500, 160)
colors = ["red", "green", "blue", "yellow", "black", color_rgb(255, 120, 0)]
x = 50
for color in colors:
    dot = Circle(Point(x, 80), 30)
    dot.setFill(color)
    dot.draw(win)
    x = x + 80
win.getMouse()
win.close()', 'python', 0, '', NULL, '{"notes":[{"line":4,"match":"color_rgb(255, 120, 0)","text":"mix your own: orange","shape":"circle","color":"sky"},{"line":6,"match":"for color in colors","text":"one circle per colour","shape":"square","color":"yel"},{"line":10,"match":"x + 80","text":"the next one, 80 to the right","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3ba25780bd1846f2', 'course_programming_applications', 'les_0c2476c4f9984e9a', 'diagram', 'Six filled circles', 'The `for` loop from the Lists lecture creates one Circle object per colour, each 80 pixels to the right of the last.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_applications/lessons/les_0c2476c4f9984e9a/py-color-row.png', 'A wide window with six circles in a row, filled red, green, blue, yellow, black and orange', 1004, 388, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a01a98c1381a06b9', 'course_programming_applications', 'les_0c2476c4f9984e9a', 'explanation', 'Moving objects', '`move(dx, dy)` shifts an object by **dx** pixels sideways and **dy** pixels up or down:

| Call | Moves the shape |
|---|---|
| `move(50, 0)` | 50 pixels **right** (positive dx) |
| `move(-50, 0)` | 50 pixels **left** (negative dx) |
| `move(0, 50)` | 50 pixels **down** (positive dy) |
| `move(0, -50)` | 50 pixels **up** (negative dy) |

Because y grows downward, a **positive dy moves down**. That is the most common surprise.

`move()` shifts the **same object**. It doesn''t draw a copy: the shape disappears from its old place and appears in the new one.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_52ad5ebf73f22f1a', 'course_programming_applications', 'les_0c2476c4f9984e9a', 'code', 'Moving a circle three times', 'The first `getMouse()` lets you see the circle where it starts. After your click, it moves 50 pixels right three times, and the second `getMouse()` keeps the window open so you can see where it ended up.', 'from graphics import *

win = GraphWin("Moving", 500, 400)
circle = Circle(Point(250, 200), 50)
circle.setFill("yellow")
circle.draw(win)
win.getMouse()
circle.move(50, 0)
circle.move(50, 0)
circle.move(50, 0)
win.getMouse()
win.close()', 'python', 0, '', NULL, '{"notes":[{"line":7,"match":"getMouse","text":"wait: see the start","shape":"circle","color":"sky"},{"line":8,"match":"move(50, 0)","text":"50 right, each time","shape":"square","color":"yel"},{"line":11,"match":"getMouse","text":"wait: see the end","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0539301a9076d4ee', 'course_programming_applications', 'les_0c2476c4f9984e9a', 'diagram', '150 pixels to the right', 'Three calls of `move(50, 0)` move the circle **150 pixels** to the right in total, so its center goes from (250, 200) to **(400, 200)**. The dashed outline was added to the picture to show where it started; the real window only shows the circle in its new place.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_applications/lessons/les_0c2476c4f9984e9a/py-move.png', 'A 500 by 400 window. A dashed outline shows where the circle started, centred at (250, 200). A yellow circle is drawn 150 pixels to the right, centred at (400, 200)', 1004, 868, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f95fc58ee3497b3b', 'course_programming_applications', 'les_0c2476c4f9984e9a', 'explanation', 'Adding text', '`Text(point, string)` is another graphical object: a Point for its position, and the String to show. The text is **centered on the Point**, not started from it.

| Method | What it does |
|---|---|
| `setSize(size)` | the font size; graphics.py accepts sizes from 5 to 36 |
| `setTextColor(color)` | the colour of the letters |
| `setText(string)` | changes the words |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f4221efdc61fd08c', 'course_programming_applications', 'les_0c2476c4f9984e9a', 'code', 'A blue title', '', 'from graphics import *

win = GraphWin("Text", 500, 400)
message = Text(
    Point(250, 50),
    "Hello Python"
)
message.draw(win)
message.setSize(20)
message.setTextColor("blue")
win.getMouse()
win.close()', 'python', 0, '', NULL, '{"notes":[{"line":5,"match":"Point(250, 50)","text":"the centre of the text","shape":"circle","color":"sky"},{"line":9,"match":"setSize(20)","text":"bigger letters","shape":"square","color":"yel"},{"line":10,"match":"setTextColor","text":"blue letters","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b86a3ba881f6dd0d', 'course_programming_applications', 'les_0c2476c4f9984e9a', 'diagram', 'Text centered on (250, 50)', 'Same pattern as before: create the object, call its methods, draw it. To put a caption near the bottom of the window, you would use a Text at about `Point(250, 370)`.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_applications/lessons/les_0c2476c4f9984e9a/py-text.png', 'A 500 by 400 window with the words Hello Python in blue near the top, centred on the point (250, 50), which is marked', 1004, 868, 12, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f17f34fdb1ac0c7b', 'course_programming_applications', 'les_0c2476c4f9984e9a', 'note', 'Check yourself', '::: check A circle is centered at (100, 100). Where is its center after `move(30, -20)` and then `move(0, 50)`?
???
**(130, 130)**. x: 100 + 30 + 0 = 130. y: 100 − 20 + 50 = 130. The first move goes right and **up** (negative dy), the second goes **down**.
:::

::: check What does `message.setSize(40)` do?
???
It stops the program with `GraphicsError: Illegal option value`, because graphics.py only accepts text sizes from 5 to 36.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 13, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_659f07e26f055479', 'course_programming_applications', 'les_0c2476c4f9984e9a', 'common_mistakes', 'Common mistakes', '- **Colours without quotes.** `setFill(blue)` makes Python look for a variable called `blue`: `NameError`. Write `setFill("blue")`.
- **A misspelt colour.** `setFill("bleu")` stops with an error from Tkinter (`unknown color name "bleu"`).
- **Moving up with a positive dy.** `move(0, 50)` moves **down**. Up is `move(0, -50)`.
- **Expecting move() to leave a copy.** It moves the same object; to have two shapes, create two objects.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 14, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_47a995fb65f469d3', 'course_programming_applications', 'les_0c2476c4f9984e9a', 'key_takeaways', 'Key takeaways', '- Shapes are objects with methods: `draw()`, `setFill()`, `setOutline()` and `move()`.
- Colours are Strings like `"blue"`, or `color_rgb(r, g, b)` with amounts from 0 to 255.
- `move(dx, dy)` shifts the same object: positive dx is right, **positive dy is down**.
- `Text(point, string)` is centered on its Point; `setSize()` (5 to 36) and `setTextColor()` change its look.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 15, 1792022400000);
