INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_applications', 'lesson', 'les_0c2476c4f9984e9a', '/courses/programming-applications/lectures/colors-moving-and-text', 'Colours, moving and text', 'Change graphical objects with their methods. Colour the inside and the edge of a shape, move it with move(dx, dy), and change the size and colour of text. Use draw(), setFill(), setOutline() and move() on a shape Write colours as Strings, or mix your own with color_rgb() Predict where a shape ends up after move(dx, dy) Change a Text object''s size and colour Object methods in graphics Shapes are objects, so they have methods, called with the same dot notation as name.upper() : circle.draw(win) circle.setFill("blue") circle.setOutline("black") circle.move(20, 0) circle is the object ; draw , setFill , setOutline and move are its methods . Each method does one job: Method What it does --- --- draw(win) shows the shape in the window win setFill(color) colours the inside of the shape setOutline(color) colours the edge of the shape move(dx, dy) shifts the shape''s position Which method would you use to make a shape''s edge red? setOutline("red") . Colouring a circle from graphics import * win = GraphWin("Colors", 500, 400) circle = Circle(Point(250, 200), 80) circle.setFill("blue") circle.setOutline("black") circle.draw(win) win.getMouse() win.close() A filled circle A new shape starts empty (no fill) with a black outline , like the circles in the last lecture. After setFill("blue") it is filled. You can set colours before or after draw() : the window updates either way. Writing colours Colour names are Strings , so they need quotes. Common ones are "red" , "blue" , "green" , "yellow" , "black" and "white" ; the library understands many more, such as "orange" , "purple" , "pink" and "gray" . For any other colour, mix it yourself with color rgb(red, green, blue) . Each amount is from 0 to 255: color rgb(255, 120, 0) is orange, and color rgb(0, 0, 0) is black. A row of colours from graphics import * win = GraphWin("Colour Row", 500, 160) colors = ["red", "green", "blue", "yellow", "black", color_rgb(255, 120, 0)] x = 50 for color in colors: dot = Circle(Point(x, 80), 30) dot.setFill(color) dot.draw(win) x = x + 80 win.getMouse() win.close() Six filled circles The for loop from the Lists lecture creates one Circle object per colour, each 80 pixels to the right of the last. Moving objects move(dx, dy) shifts an object by dx pixels sideways and dy pixels up or down: Call Moves the shape --- --- move(50, 0) 50 pixels right (positive dx) move(-50, 0) 50 pixels left (negative dx) move(0, 50) 50 pixels down (positive dy) move(0, -50) 50 pixels up (negative dy) Because y grows downward, a positive dy moves down . That is the most common surprise. move() shifts the same object . It doesn''t draw a copy: the shape disappears from its old place and appears in the new one. Moving a circle three times The first getMouse() lets you see the circle where it starts. After your click, it moves 50 pixels right three times, and the second getMouse() keeps the window open so you can see where it ended up. from graphics import * win = GraphWin("Moving", 500, 400) circle = Circle(Point(250, 200), 50) circle.setFill("yellow") circle.draw(win) win.getMouse() circle.move(50, 0) circle.move(50, 0) circle.move(50, 0) win.getMouse() win.close() 150 pixels to the right Three calls of move(50, 0) move the circle 150 pixels to the right in total, so its center goes from (250, 200) to (400, 200) . The dashed outline was added to the picture to show where it started; the real window only shows the circle in its new place. Adding text Text(point, string) is another graphical object: a Point for its position, and the String to show. The text is centered on the Point , not started from it. Method What it does --- --- setSize(size) the font size; graphics.py accepts sizes from 5 to 36 setTextColor(color) the colour of the letters setText(string) changes the words A blue title from graphics import * win = GraphWin("Text", 500, 400) message = Text( Point(250, 50), "Hello Python" ) message.draw(win) message.setSize(20) message.setTextColor("blue") win.getMouse() win.close() Text centered on (250, 50) Same pattern as before: create the object, call its methods, draw it. To put a caption near the bottom of the window, you would use a Text at about Point(250, 370) . Check yourself (130, 130) . x: 100 + 30 + 0 = 130. y: 100 − 20 + 50 = 130. The first move goes right and up (negative dy), the second goes down . It stops the program with GraphicsError: Illegal option value , because graphics.py only accepts text sizes from 5 to 36. Common mistakes - Colours without quotes. setFill(blue) makes Python look for a variable called blue : NameError . Write setFill("blue") . - A misspelt colour. setFill("bleu") stops with an error from Tkinter ( unknown color name "bleu" ). - Moving up with a positive dy. move(0, 50) moves down . Up is move(0, -50) . - Expecting move() to leave a copy. It moves the same object; to have two shapes, create two objects. Key takeaways - Shapes are objects with methods: draw() , setFill() , setOutline() and move() . - Colours are Strings like "blue" , or color rgb(r, g, b) with amounts from 0 to 255. - move(dx, dy) shifts the same object: positive dx is right, positive dy is down . - Text(point, string) is centered on its Point; setSize() (5 to 36) and setTextColor() change its look.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_bddd50d355ecf96e', 'course_programming_applications', 'top_7a6ac98b95c0c58e', 'mouse-clicks', 'Mouse clicks and an interactive target', 'getMouse() does more than pause a program. It returns the click as a Point object, so a program can draw where the user clicks. Finish with an interactive target that reports where it was hit.', 3, 13, 'medium', '["Explain what getMouse() returns","Read a click''s coordinates with getX() and getY()","Use a click Point as the center of a new shape","Build a complete interactive program from windows, shapes, text and clicks"]', '["Colours, moving and text"]', 8, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
