INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_applications', 'lesson', 'les_bddd50d355ecf96e', '/courses/programming-applications/lectures/mouse-clicks', 'Mouse clicks and an interactive target', 'getMouse() does more than pause a program. It returns the click as a Point object, so a program can draw where the user clicks. Finish with an interactive target that reports where it was hit. Explain what getMouse() returns Read a click''s coordinates with getX() and getY() Use a click Point as the center of a new shape Build a complete interactive program from windows, shapes, text and clicks getMouse() gives you a Point Until now, win.getMouse() only paused the program until a click. It actually gives something back : a Point object describing where the user clicked. click = win.getMouse() Three things happen on this line: 1. getMouse() waits until the user clicks inside the window. 2. It returns a Point object at the click position. 3. click refers to that Point, so you can call its methods: click.getX() and click.getY() read its coordinates. Where did you click? from graphics import * win = GraphWin("Where did you click?", 500, 400) click = win.getMouse() print(click.getX()) print(click.getY()) win.close() A click at (320, 180) For a click at (320, 180), the program prints the two coordinates, 320 and 180, in the terminal, not in the window. Current versions of graphics.py store coordinates as decimals, so they appear as 320.0 and 180.0 . You will see different numbers, because you will click somewhere else. Try clicking near each corner: the numbers should match the coordinate system from the windows lecture. Click to create a circle This is our first interactive program. The click Point is used directly as the center of a new Circle. from graphics import * win = GraphWin("Click Example", 500, 400) click = win.getMouse() circle = Circle(click, 30) circle.setFill("blue") circle.draw(win) win.getMouse() win.close() A blue circle where the user clicked Follow the chain: user click → win.getMouse() → a Point, click → Circle(click, 30) → circle.draw(win) . The second getMouse() keeps the window open until another click, then close() ends the program. What type of object is click ? A Point . What changes if you replace 30 with 60? The circle becomes twice as wide; its center is still wherever the user clicked. Check yourself A circle centered at (120, 340) with radius 20: from x = 100 to 140 and from y = 320 to 360. Mini project: an interactive target Build it in seven steps, using only what you have learned: 1. Open a graphics window. 2. Draw three circles with different sizes. 3. Give them different colours. 4. Add a title with a Text object. 5. Wait for a mouse click. 6. Draw a small circle where the user clicked. 7. Display the click coordinates as text. Steps 1 to 4 build the picture; steps 5 to 7 make it interactive. Two hints: - Draw the biggest circle first , so the smaller ones appear on top of it. - For step 7, build the message with + and str() , which turns a number into text. Try it before you read the complete program below. Interactive target: the complete program from graphics import * win = GraphWin("Interactive Target", 500, 500) title = Text(Point(250, 40), "Click the Target!") title.setSize(24) title.draw(win) outer = Circle(Point(250, 270), 150) outer.setFill("red") outer.draw(win) middle = Circle(Point(250, 270), 100) middle.setFill("white") middle.draw(win) inner = Circle(Point(250, 270), 50) inner.setFill("blue") inner.draw(win) click = win.getMouse() dot = Circle(click, 8) dot.setFill("yellow") dot.draw(win) x = int(click.getX()) y = int(click.getY()) msg = "Clicked at " + str(x) + ", " + str(y) info = Text(Point(250, 470), msg) info.draw(win) win.getMouse() win.close() The target after a click at (310, 230) How the program works - Steps 1 to 4: a 500 × 500 window, a title Text with size 24, then three Circles that share one center, (250, 270), biggest first, each with its own colour. - Step 5: win.getMouse() returns the click as a Point. - Step 6: a small yellow Circle is drawn with the click Point as its center. - Step 7: getX() and getY() read the coordinates. int() turns them into whole numbers, because graphics.py stores them as decimals and str(310.0) would show 310.0 . str() turns each number into text so + can join everything into one message, and a Text object shows it near the bottom. - The last getMouse() keeps the window open until one more click. Every line uses only objects and methods from this lecture and the ones before it. Common mistakes - Ignoring what getMouse() returns. win.getMouse() on its own waits for a click but throws the Point away. Store it: click = win.getMouse() . - Joining numbers to text without str(). "Clicked at " + x is a TypeError . Write "Clicked at " + str(x) . - Drawing the small circles first. The big red circle, drawn last, would cover them. Shapes drawn later appear on top. - Looking for print() output in the window. print() writes in the terminal (the Python shell). To show text in the window, use a Text object. Key takeaways - win.getMouse() waits for a click and returns a Point at the click position. - click.getX() and click.getY() read the click''s coordinates. - The click Point can be used directly as a shape''s position, as in Circle(click, 30) . - Interactive programs follow the same pattern: draw, wait for a click, react, and keep the window open until the user is done.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_b638a80716b65acd', 'course_programming_applications', 'top_7a6ac98b95c0c58e', 'graphics-practice-and-debugging', 'Graphics practice: traffic light, house and bug hunt', 'Plan and draw a traffic light, design your own house picture, and learn the five most common graphics mistakes by finding four bugs in a short program. Ends with a summary of objects and methods.', 3, 14, 'medium', '["Plan a picture''s coordinates before writing code","Draw a complete picture from rectangles, circles, polygons, lines and text","Find and fix the five most common graphics.py mistakes","Name each graphics object and the methods it can perform"]', '["Mouse clicks and an interactive target"]', 8, 'published', 1792022400000, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
