INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_40d15d15dcf974e2', 'course_programming_applications', 'les_b638a80716b65acd', 'explanation', 'Mini practice: a traffic light', 'Your turn: draw a simple traffic light with

- **1 Rectangle** for the black body, and
- **3 Circles** for the red, yellow and green lights.

You decide every number yourself: the window size, the rectangle''s two corners, the three circle centers, the radius and the colours. **Sketch it on squared paper first**, with each square 50 × 50 pixels. Check that every object is drawn and that the circles fit inside the rectangle. Then compare with the solution below; a picture with different numbers is just as right if it works.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2a8ac4544dcdf323', 'course_programming_applications', 'les_b638a80716b65acd', 'code', 'Traffic light: one possible solution', '', 'from graphics import *

win = GraphWin("Traffic Light", 300, 500)

body = Rectangle(Point(75, 50), Point(225, 450))
body.setFill("black")
body.draw(win)

red = Circle(Point(150, 140), 50)
red.setFill("red")
red.draw(win)

yellow = Circle(Point(150, 250), 50)
yellow.setFill("yellow")
yellow.draw(win)

green = Circle(Point(150, 360), 50)
green.setFill("green")
green.draw(win)

win.getMouse()
win.close()', 'python', 0, '', NULL, '{"notes":[{"line":3,"match":"300, 500","text":"a tall window","shape":"circle","color":"sky"},{"line":5,"match":"Rectangle","text":"the body, drawn first","shape":"square","color":"yel"},{"line":9,"match":"150","text":"x = 150 for every light","shape":"diamond","color":"green"},{"line":9,"match":"50)","text":"the same radius, 50","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ce1855e8eb17b3ec', 'course_programming_applications', 'les_b638a80716b65acd', 'diagram', 'The traffic light', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_applications/lessons/les_b638a80716b65acd/py-traffic-light.png', 'A tall window, 300 by 500, titled Traffic Light. A black rectangle runs from (75, 50) to (225, 450). Inside it are three circles of radius 50, one above the other: red at (150, 140), yellow at (150, 250) and green at (150, 360)', 604, 1068, 3, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_afd36df53b665bb8', 'course_programming_applications', 'les_b638a80716b65acd', 'explanation', 'Reading the solution', 'The program is one pattern repeated four times: **create the object, set its colour, draw it**.

| Object | Kind | Position |
|---|---|---|
| body | Rectangle | from (75, 50) to (225, 450) |
| red | Circle | center (150, 140), radius 50 |
| yellow | Circle | center (150, 250), radius 50 |
| green | Circle | center (150, 360), radius 50 |

Why do all three circles use **x = 150**? Because 150 is halfway between 75 and 225, the left and right sides of the body, so every light sits in the middle of it.

**Order matters:** the body is drawn first. If it were drawn last, the black rectangle would cover the lights.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_9ebf6624c9720104', 'course_programming_applications', 'les_b638a80716b65acd', 'explanation', 'Mini project: draw a house', 'This time there is no solution code, on purpose: design it yourself. Draw a house in a 500 × 400 window titled **My House**, using:

| Object | Draws the… |
|---|---|
| Rectangle | house body |
| Polygon | roof |
| Rectangle | door |
| Rectangles | windows |
| Circle | sun |
| Text | title |
| Line | ground |

Use Points for every position, and colours for everything. Plan the coordinates on paper first, and draw **back to front**: the body and roof before the door and windows, so they appear on top.

**Bonus:** move the sun across the sky with `sun.move(-50, 0)`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e51162226b4b06a1', 'course_programming_applications', 'les_b638a80716b65acd', 'diagram', 'One possible house', 'This is one possible answer. Yours can look completely different: other colours, a bigger house, two suns. What matters is that every part of the picture is an object you created and drew.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_applications/lessons/les_b638a80716b65acd/py-house.png', 'A 500 by 400 window titled My House: a light-blue sky, green grass under a dark ground line, a brown house body with a red triangular roof, a dark brown door and two white windows, a yellow sun at the top right and the bold title My House at the top left', 1004, 868, 6, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f50c6c137ebc3e67', 'course_programming_applications', 'les_b638a80716b65acd', 'explanation', 'Debugging graphics programs', 'Five mistakes cause most broken graphics programs. When something goes wrong, check them in order:

| Common mistake | What to check |
|---|---|
| 1. An object is created but not drawn | every shape calls `.draw(win)` |
| 2. Coordinates outside the window | x between 0 and the width, y between 0 and the height |
| 3. `close()` called too early | `win.close()` is the last line |
| 4. Wrong Point coordinates | x comes first; y grows downward |
| 5. The import is missing | line 1 is `from graphics import *` |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_107583c6dc30b950', 'course_programming_applications', 'les_b638a80716b65acd', 'explanation', 'Bug hunt', 'This program should show a yellow sun. It has **four bugs**. Use the checklist above to find them before you open the answer.

```python
win = GraphWin("Bug Hunt", 400, 300)
sun = Circle(Point(600, 100), 40)
sun.setFill("yellow")
win.close()
sun.draw(win)
```

::: check Which four bugs did you find?
???
1. **The import is missing.** Without `from graphics import *` on line 1, the program stops at once with `NameError: name ''GraphWin'' is not defined`.
2. **The sun is outside the window.** Its center x is 600, but the window is only 400 wide.
3. **`close()` comes before `draw()`.** Drawing on a closed window raises `GraphicsError: Can''t draw to closed window`.
4. **There is no `win.getMouse()` before `close()`.** Even with the other bugs fixed, the window would vanish instantly.

The fixed order is: import, create the window, create and colour the sun, draw it, wait for a click, close.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_974f199469db067f', 'course_programming_applications', 'les_b638a80716b65acd', 'code', 'The fixed program', '', 'from graphics import *

win = GraphWin("Bug Hunt", 400, 300)
sun = Circle(Point(200, 100), 40)
sun.setFill("yellow")
sun.draw(win)
win.getMouse()
win.close()', 'python', 0, '', NULL, '{"notes":[{"line":1,"match":"from graphics import *","text":"bug 1: the import","shape":"circle","color":"sky"},{"line":4,"match":"200","text":"bug 2: inside the window","shape":"square","color":"yel"},{"line":6,"match":"draw","text":"bug 3: draw before close","shape":"diamond","color":"green"},{"line":7,"match":"getMouse","text":"bug 4: wait for a click","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 9, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_beec7d40807882b3', 'course_programming_applications', 'les_b638a80716b65acd', 'diagram', 'The yellow sun', '', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_applications/lessons/les_b638a80716b65acd/py-sun.png', 'A 400 by 300 window titled Bug Hunt with a yellow circle of radius 40 centred at (200, 100)', 804, 668, 10, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_54117e835c1e8f32', 'course_programming_applications', 'les_b638a80716b65acd', 'explanation', 'Objects and their methods', 'Here is everything from this lecture in one table. **Objects** are the things; **methods** are the actions those things can perform, always written after a dot.

| Object | Its methods |
|---|---|
| `win` (a GraphWin) | `.getMouse()`, `.close()` |
| `circle` | `.draw()`, `.move()`, `.setFill()`, `.setOutline()` |
| `rectangle` | `.draw()`, `.move()`, `.setFill()`, `.setOutline()` |
| `text` | `.draw()`, `.move()`, `.setSize()`, `.setTextColor()` |
| `click` (a Point) | `.getX()`, `.getY()` |

Read `circle.move(50, 0)` aloud: the **thing** is `circle`, the **action** is `move`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_1c735bcf780f460c', 'course_programming_applications', 'les_b638a80716b65acd', 'explanation', 'Coming next: classes', 'In these lectures you **used** objects that someone else designed: `GraphWin`, `Point`, `Circle`, `Text`. Next, you will learn **classes**, which let you design **your own** kinds of objects, with their own data and their own methods.

A question to think about until then: what if you wanted a `TrafficLight` object, with a method called `change()` that switches the light from red to green?', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e2965bb03d0e19a3', 'course_programming_applications', 'les_b638a80716b65acd', 'common_mistakes', 'Common mistakes', '- **Drawing back to front the wrong way round.** Shapes drawn later cover earlier ones. Draw large background shapes first.
- **Guessing coordinates.** Sketch the picture on squared paper first; guessing numbers and re-running wastes time.
- **Copying the same object.** To draw three lights, create three Circle objects; one object can only be drawn once.
- **Fixing one bug and stopping.** A program can have several bugs, as the bug hunt shows. Run the checklist to the end.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 13, 1792022400000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_1738c53e437eacc4', 'course_programming_applications', 'les_b638a80716b65acd', 'key_takeaways', 'Key takeaways', '- Plan coordinates before coding, and draw back to front.
- A picture is many objects, each following the same pattern: create, colour, draw.
- When a graphics program fails, check: drawn? inside the window? `close()` last? x before y? import present?
- Objects are the things (windows, shapes, text, points); methods are the actions they perform.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 14, 1792022400000);
