INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_de9e9c05688ce607', 'course_programming_fundamentals', 'top_3087c084dc60a631', 'what-is-programming', 'What is programming?', 'A program is a list of exact steps a computer follows to turn input into output. See how a C++ program runs, and why good programmers think first and code second.', 1, 1, 'easy', '["Say what a program is in one sentence","Name the input, the processing and the output of a small program","Describe how C++ source code becomes something the CPU can run","List the four stages of programming, from understanding to testing"]', '["None. This is the first lecture."]', 5, 'published', 1791504000000, 1791504000000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_programming_fundamentals' AND lesson_id = 'les_de9e9c05688ce607';
DELETE FROM lesson_relations WHERE course_id = 'course_programming_fundamentals' AND lesson_id = 'les_de9e9c05688ce607';
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a05df0d768abc2f6', 'course_programming_fundamentals', 'les_de9e9c05688ce607', 'explanation', 'A program is a set of instructions', 'A **program** is a set of step-by-step instructions that a computer follows. The computer does exactly what the steps say, in the order they are written. It never guesses what you meant.

Three ideas sit behind every program:

- A program is a list of **precise steps**.
- A program turns **input** into meaningful **output**.
- Programmers write those steps in a **programming language**, such as C++, so that both people and the computer can read them.

A recipe is a good everyday picture. The ingredients are the input, the cooking steps are the processing, and the finished meal is the output. A recipe that says "add some salt" is fine for a person. A computer needs "add 5 grams of salt".', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e0a67e8a98b81688', 'course_programming_fundamentals', 'les_de9e9c05688ce607', 'explanation', 'Programming is not just coding', 'Typing code is only one part of programming. The work goes through four stages:

1. **Understand** the problem: what goes in, what must come out, and what the rules are.
2. **Design** the solution: plan the steps, for example with a flowchart or pseudocode.
3. **Write** the code in a programming language.
4. **Test and improve**: run it with real values, find mistakes and fix them.

::: tip
Good programmers think first, then code. Most beginner bugs are mistakes in the plan, not typing mistakes.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 2, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ed6a8b951c8f0a4a', 'course_programming_fundamentals', 'les_de9e9c05688ce607', 'explanation', 'How a program runs', 'You write a C++ program as plain text. This text is called the **source code**. The computer''s processor (the **CPU**) can''t read C++ directly. It only understands **machine code**: very simple instructions stored as numbers.

So there is a translation step:

| Step | What happens |
|---|---|
| 1. Write | You type the source code, for example in a file called `main.cpp`. |
| 2. Compile | A program called a **compiler** checks your code and translates it into machine code. If something is wrong, it stops and shows an error. |
| 3. Run | The CPU carries out the machine instructions one after another, very fast. |

On this site, the C++ outputs you see were made exactly this way: we compiled each program and ran it, and the OUTPUT box shows what it printed.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_7521da6aec91a0f1', 'course_programming_fundamentals', 'les_de9e9c05688ce607', 'code', 'Your first C++ program', 'This program has no input. It prints two lines, in order, and stops.', '#include <iostream>
using namespace std;

int main()
{
    cout << "Hello! I am a program." << endl;
    cout << "I follow my steps in order." << endl;
    return 0;
}', 'cpp', 1, '', 'Hello! I am a program.
I follow my steps in order.
', '{"notes":[{"line":1,"match":"iostream","text":"lets us print with cout","shape":"circle","color":"sky"},{"line":4,"match":"int main()","text":"the program starts here","shape":"square","color":"yel"},{"line":6,"match":"cout","text":"prints to the screen","shape":"diamond","color":"green"},{"line":6,"match":"endl","text":"moves to a new line","shape":"tri","color":"sky"},{"line":8,"match":"return 0;","text":"finished with no problems","shape":"circle","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 4, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_66d837aa6b037a6e', 'course_programming_fundamentals', 'les_de9e9c05688ce607', 'code', 'Input, processing and output', 'Here is a program with all three parts. It **reads** two numbers (input), **adds** them (processing) and **prints** the sum (output). The user typed `4 7` and pressed Enter.', '#include <iostream>
using namespace std;

int main()
{
    int a, b;
    cout << "Enter two numbers: ";
    cin >> a >> b;
    int sum = a + b;
    cout << "Sum = " << sum << endl;
    return 0;
}', 'cpp', 1, '4 7
', 'Enter two numbers: 4 7
Sum = 11
', '{"notes":[{"line":8,"match":"cin >> a >> b;","text":"INPUT: read two numbers","shape":"circle","color":"sky"},{"line":9,"match":"a + b","text":"PROCESSING: add them","shape":"square","color":"yel"},{"line":10,"match":"cout","text":"OUTPUT: show the result","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 5, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0707e0641ae8b701', 'course_programming_fundamentals', 'les_de9e9c05688ce607', 'explanation', 'Reading the OUTPUT box', 'The OUTPUT box shows the screen as the user saw it. The green text, `4 7`, is what the **user typed**. Everything else was **printed by the program**. You will learn `cin` and `cout` properly in a later lecture; for now, notice the three parts and the order they run in.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a8e901ddbde7cbe8', 'course_programming_fundamentals', 'les_de9e9c05688ce607', 'note', 'Check yourself', '::: check A calculator app adds a 14% tax to a price. What is the input, the processing and the output?
???
**Input:** the price. **Processing:** multiply the price by 0.14 and add the result to the price. **Output:** the final price, shown on the screen.
:::

::: check Which stage comes first: writing the code, or understanding the problem?
???
Understanding the problem. If you don''t know what goes in and what must come out, you can''t plan the steps, and code written without a plan usually has to be rewritten.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_271fe9da9eceb8bc', 'course_programming_fundamentals', 'les_de9e9c05688ce607', 'key_takeaways', 'Key takeaways', '- A program is a set of precise, step-by-step instructions that a computer follows exactly.
- Every program turns **input** into **output** through **processing**.
- C++ source code is translated by a **compiler** into machine code, which the CPU runs.
- Programming is understand → design → write → test and improve. Think first, then code.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1791504000000);
DELETE FROM search_index WHERE course_id = 'course_programming_fundamentals' AND entity_type = 'lesson' AND entity_id = 'les_de9e9c05688ce607';
INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'lesson', 'les_de9e9c05688ce607', '/courses/programming-fundamentals/lectures/what-is-programming', 'What is programming?', 'A program is a list of exact steps a computer follows to turn input into output. See how a C++ program runs, and why good programmers think first and code second. Say what a program is in one sentence Name the input, the processing and the output of a small program Describe how C++ source code becomes something the CPU can run List the four stages of programming, from understanding to testing A program is a set of instructions A program is a set of step-by-step instructions that a computer follows. The computer does exactly what the steps say, in the order they are written. It never guesses what you meant. Three ideas sit behind every program: - A program is a list of precise steps . - A program turns input into meaningful output . - Programmers write those steps in a programming language , such as C++, so that both people and the computer can read them. A recipe is a good everyday picture. The ingredients are the input, the cooking steps are the processing, and the finished meal is the output. A recipe that says "add some salt" is fine for a person. A computer needs "add 5 grams of salt". Programming is not just coding Typing code is only one part of programming. The work goes through four stages: 1. Understand the problem: what goes in, what must come out, and what the rules are. 2. Design the solution: plan the steps, for example with a flowchart or pseudocode. 3. Write the code in a programming language. 4. Test and improve : run it with real values, find mistakes and fix them. Good programmers think first, then code. Most beginner bugs are mistakes in the plan, not typing mistakes. How a program runs You write a C++ program as plain text. This text is called the source code . The computer''s processor (the CPU ) can''t read C++ directly. It only understands machine code : very simple instructions stored as numbers. So there is a translation step: Step What happens --- --- 1. Write You type the source code, for example in a file called main.cpp . 2. Compile A program called a compiler checks your code and translates it into machine code. If something is wrong, it stops and shows an error. 3. Run The CPU carries out the machine instructions one after another, very fast. On this site, the C++ outputs you see were made exactly this way: we compiled each program and ran it, and the OUTPUT box shows what it printed. Your first C++ program This program has no input. It prints two lines, in order, and stops. #include <iostream> using namespace std; int main() { cout << "Hello! I am a program." << endl; cout << "I follow my steps in order." << endl; return 0; } Input, processing and output Here is a program with all three parts. It reads two numbers (input), adds them (processing) and prints the sum (output). The user typed 4 7 and pressed Enter. #include <iostream> using namespace std; int main() { int a, b; cout << "Enter two numbers: "; cin >> a >> b; int sum = a + b; cout << "Sum = " << sum << endl; return 0; } Reading the OUTPUT box The OUTPUT box shows the screen as the user saw it. The green text, 4 7 , is what the user typed . Everything else was printed by the program . You will learn cin and cout properly in a later lecture; for now, notice the three parts and the order they run in. Check yourself Input: the price. Processing: multiply the price by 0.14 and add the result to the price. Output: the final price, shown on the screen. Understanding the problem. If you don''t know what goes in and what must come out, you can''t plan the steps, and code written without a plan usually has to be rewritten. Key takeaways - A program is a set of precise, step-by-step instructions that a computer follows exactly. - Every program turns input into output through processing . - C++ source code is translated by a compiler into machine code, which the CPU runs. - Programming is understand → design → write → test and improve. Think first, then code.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_6063a88c5a315cf3', 'course_programming_fundamentals', 'top_5d3151db5feee6a4', 'from-problem-to-program', 'From problem to program: a method that works', 'Solve programming problems in a fixed order. Understand the problem, find its input, processing and output, plan the steps, then write, test and refine the code.', 1, 2, 'easy', '["Follow the three-step process from problem to program","Break a problem into input, processing and output","Write an everyday task as ordered steps","Use test cases to find a mistake and fix it"]', '["What is programming?"]', 5, 'published', 1791504000000, 1791504000000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
