INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_95cef97ebb8f2ecd', 'course_programming_fundamentals', 'les_ae371952c0c968ae', 'explanation', 'What is an algorithm?', 'An **algorithm** is an exact, ordered list of steps that solves a problem. You design the algorithm **before** you write any code. Then the code is just a translation of it.

There are three common ways to write an algorithm down:

| Way | What it looks like | Good for |
|---|---|---|
| **Plain-language steps** | numbered sentences: "1. Start. 2. Read the mark…" | Easy for anyone to understand, but not exact enough to code from directly. |
| **Flowchart** | shapes joined by arrows | Seeing the logic as a picture, especially decisions and repetition. |
| **Pseudocode** | structured English with keywords such as `INPUT`, `IF`, `WHILE` | A bridge between human logic and real code. Each line maps to a line of code. |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_278b132cc39e92c7', 'course_programming_fundamentals', 'les_ae371952c0c968ae', 'diagram', 'The flowchart symbols', 'Each shape in a flowchart has one meaning. Ovals start and end the chart, parallelograms read or print values, rectangles do calculations, and diamonds ask a question with two exits.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_fundamentals/lessons/les_ae371952c0c968ae/flowchart-symbols.png', 'A legend of flowchart symbols on a navy background: a green oval labelled Start for start and end, a blue parallelogram labelled Input T for input or output, a white rectangle labelled area ← l * w for a process, a yellow diamond labelled T > 30? for a decision with YES and NO exits, and an arrow for the order of the steps', 1520, 1080, 2, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e047819e59afa702', 'course_programming_fundamentals', 'les_ae371952c0c968ae', 'example', 'Worked example 1: the average of three numbers', '**Problem:** calculate the average of three numbers.

- **Input:** `N1`, `N2`, `N3`
- **Processing:** `SUM = N1 + N2 + N3`, then `AVERAGE = SUM / 3`
- **Output:** `AVERAGE`

**As plain-language steps:**

1. Start.
2. Read the three numbers N1, N2 and N3.
3. Add them and store the result in SUM.
4. Divide SUM by 3 and store the result in AVERAGE.
5. Print AVERAGE.
6. End.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d6c002664da472b1', 'course_programming_fundamentals', 'les_ae371952c0c968ae', 'diagram', 'Average of three numbers as a flowchart', 'Read it from top to bottom. Each step above became one shape.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_fundamentals/lessons/les_ae371952c0c968ae/average-of-three.png', 'A flowchart: Start, then the parallelogram Input N1, N2, N3, then the rectangles SUM ← N1 + N2 + N3 and AVERAGE ← SUM / 3, then the parallelogram Print AVERAGE, then End', 1040, 1280, 4, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_c15cd3e953656260', 'course_programming_fundamentals', 'les_ae371952c0c968ae', 'code', 'Average of three numbers as pseudocode', 'The same steps in pseudocode. The arrow `←` means "store the value on the right in the name on the left". The user typed `10 20 30`.', 'BEGIN
    INPUT N1, N2, N3
    SUM ← N1 + N2 + N3
    AVERAGE ← SUM / 3
    PRINT AVERAGE
END', 'pseudocode', 0, '10 20 30
', '10 20 30
20
', '{"notes":[{"line":2,"match":"INPUT","text":"read the three numbers","shape":"circle","color":"sky"},{"line":3,"match":"SUM ← N1 + N2 + N3","text":"processing","shape":"square","color":"yel"},{"line":4,"match":"AVERAGE ← SUM / 3","text":"processing","shape":"square","color":"yel"},{"line":5,"match":"PRINT","text":"output","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 5, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_7a23fb1739ab624c', 'course_programming_fundamentals', 'les_ae371952c0c968ae', 'example', 'Worked example 2: temperature monitoring', '**Problem:** a temperature sensor reads the room temperature. If the temperature is greater than 30 °C, turn the fan ON. Otherwise, turn the fan OFF.

- **Input:** the temperature `T`
- **Processing:** compare `T` with 30
- **Output:** `Fan ON` or `Fan OFF`

**As plain-language steps:**

1. Start.
2. Read the temperature T.
3. Check if T > 30.
4. If true, turn the fan ON.
5. Otherwise, turn the fan OFF.
6. End.

Steps 3 to 5 are a **decision**. Only one of step 4 or step 5 happens each time, never both.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_acf82a082edafc28', 'course_programming_fundamentals', 'les_ae371952c0c968ae', 'diagram', 'Temperature monitoring as a flowchart', 'The diamond asks the question. The YES path and the NO path meet again before End.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_fundamentals/lessons/les_ae371952c0c968ae/temperature-fan.png', 'A flowchart: Start, Input T, then a yellow diamond T > 30?. The YES exit on the left leads to Print "Fan ON", the NO exit on the right leads to Print "Fan OFF", and both paths join and lead to End', 1400, 1200, 7, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_8c80eaa4067bfe6b', 'course_programming_fundamentals', 'les_ae371952c0c968ae', 'code', 'Temperature monitoring as pseudocode', '`IF … THEN … ELSE … END IF` is the decision. The sensor read `32`.', 'BEGIN
    INPUT T
    IF T > 30 THEN
        PRINT "Fan ON"
    ELSE
        PRINT "Fan OFF"
    END IF
END', 'pseudocode', 0, '32
', '32
Fan ON
', '{"notes":[{"line":3,"match":"T > 30","text":"the question: TRUE or FALSE","shape":"square","color":"yel"},{"line":4,"match":"PRINT \"Fan ON\"","text":"when it is TRUE","shape":"circle","color":"green"},{"line":6,"match":"PRINT \"Fan OFF\"","text":"when it is FALSE","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 8, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5e14f662617d4122', 'course_programming_fundamentals', 'les_ae371952c0c968ae', 'code', 'A peek ahead: the same plan in C++', 'You will learn every part of this later in the course. For now, compare it with the pseudocode above: the logic is the same, only the way it is written changes.', '#include <iostream>
using namespace std;

