INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f14bc78466bc84b5', 'course_programming_fundamentals', 'les_ae371952c0c968ae', 'common_mistakes', 'Maths symbols are not C++ symbols', 'When you write a condition, use the symbols C++ understands. Your keyboard has no `≥` key, and in C++ a single `=` means "store", not "is equal to".

| Meaning | In maths | In C++ (and in our pseudocode) |
|---|---|---|
| is equal to | `=` | `==` |
| is greater than or equal to | `≥` | `>=` |
| is less than or equal to | `≤` | `<=` |
| is not equal to | `≠` | `!=` |
| is greater than / less than | `>` / `<` | `>` / `<` |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3c59ab49288a1780', 'course_programming_fundamentals', 'les_ae371952c0c968ae', 'note', 'Check yourself', '::: check Which flowchart shape do you use for "Read the mark"? And for "Is the mark at least 50?"
???
"Read the mark" is input, so it goes in a **parallelogram**. "Is the mark at least 50?" is a question with a yes/no answer, so it goes in a **diamond**.
:::

::: check Write the condition "age is at least 18" the way C++ needs it.
???
`age >= 18`. "At least" includes 18 itself, so it is `>=`, not `>`.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f8d2b51c5c45b4e8', 'course_programming_fundamentals', 'les_ae371952c0c968ae', 'key_takeaways', 'Key takeaways', '- An algorithm is an exact, ordered list of steps, designed before any code.
- The same algorithm can be written as plain steps, a flowchart or pseudocode. Same logic, different representation.
- Flowchart shapes: oval = start/end, parallelogram = input/output, rectangle = process, diamond = decision, arrow = order.
- A decision creates two possible paths, and only one of them runs.
- In conditions, write `==`, `>=`, `<=` and `!=`, not the maths symbols.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1791504000000);
DELETE FROM search_index WHERE course_id = 'course_programming_fundamentals' AND entity_type = 'lesson' AND entity_id = 'les_ae371952c0c968ae';
INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'lesson', 'les_ae371952c0c968ae', '/courses/programming-fundamentals/lectures/algorithms-steps-flowcharts-pseudocode', 'Algorithms: steps, flowcharts and pseudocode', 'Describe one algorithm in three ways, as plain steps, as a flowchart and as pseudocode, with two worked examples, the average of three numbers and a temperature-controlled fan. Say what an algorithm is Describe the same algorithm as plain steps, a flowchart and pseudocode Recognise the five flowchart symbols Write comparison symbols the way C++ needs them What is an algorithm? An algorithm is an exact, ordered list of steps that solves a problem. You design the algorithm before you write any code. Then the code is just a translation of it. There are three common ways to write an algorithm down: Way What it looks like Good for --- --- --- Plain-language steps numbered sentences: "1. Start. 2. Read the mark…" Easy for anyone to understand, but not exact enough to code from directly. Flowchart shapes joined by arrows Seeing the logic as a picture, especially decisions and repetition. Pseudocode structured English with keywords such as INPUT , IF , WHILE A bridge between human logic and real code. Each line maps to a line of code. The flowchart symbols Each shape in a flowchart has one meaning. Ovals start and end the chart, parallelograms read or print values, rectangles do calculations, and diamonds ask a question with two exits. Worked example 1: the average of three numbers Problem: calculate the average of three numbers. - Input: N1 , N2 , N3 - Processing: SUM = N1 + N2 + N3 , then AVERAGE = SUM / 3 - Output: AVERAGE As plain-language steps: 1. Start. 2. Read the three numbers N1, N2 and N3. 3. Add them and store the result in SUM. 4. Divide SUM by 3 and store the result in AVERAGE. 5. Print AVERAGE. 6. End. Average of three numbers as a flowchart Read it from top to bottom. Each step above became one shape. Average of three numbers as pseudocode The same steps in pseudocode. The arrow ← means "store the value on the right in the name on the left". The user typed 10 20 30 . BEGIN INPUT N1, N2, N3 SUM ← N1 + N2 + N3 AVERAGE ← SUM / 3 PRINT AVERAGE END Worked example 2: temperature monitoring Problem: a temperature sensor reads the room temperature. If the temperature is greater than 30 °C, turn the fan ON. Otherwise, turn the fan OFF. - Input: the temperature T - Processing: compare T with 30 - Output: Fan ON or Fan OFF As plain-language steps: 1. Start. 2. Read the temperature T. 3. Check if T 30. 4. If true, turn the fan ON. 5. Otherwise, turn the fan OFF. 6. End. Steps 3 to 5 are a decision . Only one of step 4 or step 5 happens each time, never both. Temperature monitoring as a flowchart The diamond asks the question. The YES path and the NO path meet again before End. Temperature monitoring as pseudocode IF … THEN … ELSE … END IF is the decision. The sensor read 32 . BEGIN INPUT T IF T > 30 THEN PRINT "Fan ON" ELSE PRINT "Fan OFF" END IF END A peek ahead: the same plan in C++ You will learn every part of this later in the course. For now, compare it with the pseudocode above: the logic is the same, only the way it is written changes. #include <iostream> using namespace std; int main() { float T; cin >> T; if (T > 30) { cout << "Fan ON" << endl; } else { cout << "Fan OFF" << endl; } return 0; } Maths symbols are not C++ symbols When you write a condition, use the symbols C++ understands. Your keyboard has no ≥ key, and in C++ a single = means "store", not "is equal to". Meaning In maths In C++ (and in our pseudocode) --- --- --- is equal to = == is greater than or equal to ≥ = is less than or equal to ≤ <= is not equal to ≠ != is greater than / less than / < / < Check yourself "Read the mark" is input, so it goes in a parallelogram . "Is the mark at least 50?" is a question with a yes/no answer, so it goes in a diamond . age = 18 . "At least" includes 18 itself, so it is = , not . Key takeaways - An algorithm is an exact, ordered list of steps, designed before any code. - The same algorithm can be written as plain steps, a flowchart or pseudocode. Same logic, different representation. - Flowchart shapes: oval = start/end, parallelogram = input/output, rectangle = process, diamond = decision, arrow = order. - A decision creates two possible paths, and only one of them runs. - In conditions, write == , = , <= and != , not the maths symbols.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_b1f22f1b15df7fbf', 'course_programming_fundamentals', 'top_90210695d2bff4ab', 'pseudocode-planning-before-code', 'Pseudocode: planning before code', 'Write an algorithm in structured English with BEGIN, INPUT, PRINT, ← and IF … THEN … ELSE … END IF, then see how each line turns into C++.', 2, 4, 'easy', '["Explain what pseudocode is and why we use it","Use the BEGIN, INPUT, PROCESS, OUTPUT, END template","Use the keywords INPUT, PRINT, SET / ←, IF, THEN, ELSE and END IF","Go from a problem to pseudocode in three steps"]', '["Algorithms: steps, flowcharts and pseudocode"]', 6, 'published', 1791504000000, 1791504000000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
