INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2357fe78a91f90cc', 'course_programming_fundamentals', 'les_b1f22f1b15df7fbf', 'explanation', 'What is pseudocode?', '**Pseudocode** is an informal way of describing an algorithm with simple, structured, English-like statements.

- It is **not** a real programming language, so no computer runs it.
- It has **no strict syntax rules**. It is written for people.
- It focuses on the **logic**, not on the details of a language.
- It helps you **plan** a program before you write it.

Pseudocode sits between how we think and how a computer is programmed:

**human thinking** (ideas and logic) → **pseudocode** (structured English) → **programming code** (C++, Python, Java…)', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e383f49a99aab279', 'course_programming_fundamentals', 'les_b1f22f1b15df7fbf', 'explanation', 'Why do we use pseudocode?', '- **Easy to read:** plain, structured English that anyone can follow.
- **Helps plan logic:** you think about the steps before worrying about semicolons and brackets.
- **Language independent:** the same pseudocode works for C++, Python, Java or any other language.
- **Easy to convert into code:** each line maps naturally to a line of code.

::: tip
Think first. Code later. Most beginner errors are logic errors, not typing errors, and pseudocode is where you catch them.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 2, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f0f5112d64b8e899', 'course_programming_fundamentals', 'les_b1f22f1b15df7fbf', 'code', 'The basic structure', 'Almost every simple algorithm follows the same template: **input → process → output**, between `BEGIN` and `END`.', 'BEGIN
    INPUT data
    PROCESS data
    OUTPUT result
END', 'pseudocode', 0, '', NULL, '{"notes":[{"line":1,"match":"BEGIN","text":"start of the algorithm","shape":"circle","color":"green"},{"line":2,"match":"INPUT","text":"read data","shape":"square","color":"sky"},{"line":3,"match":"PROCESS","text":"do the calculations","shape":"diamond","color":"yel"},{"line":4,"match":"OUTPUT","text":"show the result","shape":"tri","color":"green"},{"line":5,"match":"END","text":"end of the algorithm","shape":"circle","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 3, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_65056bfe97bde6b8', 'course_programming_fundamentals', 'les_b1f22f1b15df7fbf', 'explanation', 'Pseudocode keywords', 'These are the words we use in this course. Write them in **CAPITALS** so every step stands out.

| Keyword | Meaning |
|---|---|
| `BEGIN` | start of the algorithm |
| `END` | end of the algorithm |
| `INPUT` | read a value (from the user or a sensor) |
| `PRINT` | display a value |
| `SET` / `←` | store a value: `SET x ← 5` and `x ← 5` mean the same thing |
| `IF` | start a decision and check a condition |
| `THEN` | what to do when the condition is TRUE |
| `ELSE` | what to do when the condition is FALSE |
| `END IF` | end of the decision |

The decision keywords always come as a group: `IF … THEN … ELSE … END IF`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_afe7069e07ac6a4e', 'course_programming_fundamentals', 'les_b1f22f1b15df7fbf', 'code', 'Example: calculate the average', '**Problem:** calculate the average of three numbers. The user typed `12 15 18`.', 'BEGIN
    INPUT N1, N2, N3
    SUM ← N1 + N2 + N3
    AVERAGE ← SUM / 3
    PRINT AVERAGE
END', 'pseudocode', 0, '12 15 18
', '12 15 18
15
', '{"notes":[{"line":2,"match":"INPUT N1, N2, N3","text":"INPUT: read by the user","shape":"circle","color":"sky"},{"line":3,"match":"SUM ← N1 + N2 + N3","text":"PROCESSING","shape":"square","color":"yel"},{"line":4,"match":"AVERAGE ← SUM / 3","text":"PROCESSING","shape":"square","color":"yel"},{"line":5,"match":"PRINT AVERAGE","text":"OUTPUT: the result","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 5, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f4cf96c00b79b623', 'course_programming_fundamentals', 'les_b1f22f1b15df7fbf', 'code', 'Example: a decision', 'The temperature problem from Lecture 1, with the decision keywords. This time the sensor read `25`.', 'BEGIN
