INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f4d55b5a556b2149', 'course_programming_fundamentals', 'les_b1f22f1b15df7fbf', 'example', 'From problem to pseudocode in three steps', '**Problem:** read the length and width of a rectangle and calculate its area.

**Step 1: identify the variables.** We need `length`, `width` and `area`.

**Step 2: choose the data types.** Lengths can have decimals (2.5 m), so `float` is the safe choice for all three.

| Variable | Data type |
|---|---|
| `length` | `float` |
| `width` | `float` |
| `area` | `float` |

**Step 3: write the pseudocode.** You''ll find it in the next section.

- **Input:** `length`, `width`
- **Processing:** `area ← length * width`
- **Output:** `area`', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ca8bcc348eb7c9ee', 'course_programming_fundamentals', 'les_b1f22f1b15df7fbf', 'code', 'Rectangle area in pseudocode', 'Two `INPUT` lines, one calculation, one `PRINT`. The user typed `8`, then `5`.', 'BEGIN
    INPUT length
    INPUT width
    area ← length * width
    PRINT area
END', 'pseudocode', 0, '8
5
', '8
5
40
', '{"notes":[{"line":2,"match":"INPUT length","text":"first input","shape":"circle","color":"sky"},{"line":3,"match":"INPUT width","text":"second input","shape":"circle","color":"sky"},{"line":4,"match":"length * width","text":"* means multiply","shape":"square","color":"yel"},{"line":5,"match":"PRINT area","text":"output","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 8, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_91ca81ab742060a9', 'course_programming_fundamentals', 'les_b1f22f1b15df7fbf', 'explanation', 'Each line becomes a line of C++', 'When the plan is right, turning it into C++ is mostly a matter of swapping words for symbols:

| Pseudocode | C++ |
|---|---|
| `INPUT length` | `cin >> length;` |
| `area ← length * width` | `area = length * width;` |
| `PRINT area` | `cout << area;` |
| `IF T > 30 THEN … ELSE … END IF` | `if (T > 30) { … } else { … }` |
| `BEGIN … END` | `int main() { … }` |

In C++ every statement ends with a semicolon `;`. You''ll write the full rectangle program in C++ in the flowcharts lecture.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2b60fd1086aefd67', 'course_programming_fundamentals', 'les_b1f22f1b15df7fbf', 'note', 'Check yourself', '::: check Write pseudocode that reads a rectangle''s length and width and prints its perimeter.
???
```pseudocode
BEGIN
    INPUT length
    INPUT width
    perimeter ← 2 * (length + width)
    PRINT perimeter
END
```
:::

::: check Is there one "correct" way to write pseudocode?
???
No. Pseudocode has no strict syntax, because it is for people. What matters is that the steps are clear, in the right order, and easy to turn into code. Using the same keywords as your class makes it easier for others to read.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5a91dd52575a55f8', 'course_programming_fundamentals', 'les_b1f22f1b15df7fbf', 'key_takeaways', 'Key takeaways', '- Pseudocode is structured English for planning an algorithm. No computer runs it.
- The basic template is `BEGIN`, input, process, output, `END`.
- `←` (or `SET`) stores a value; `INPUT` reads one; `PRINT` shows one.
- Decisions are written `IF … THEN … ELSE … END IF`.
- To solve a problem: identify the variables, choose their data types, then write the pseudocode.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1791504000000);
