INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'lesson', 'les_b1f22f1b15df7fbf', '/courses/programming-fundamentals/lectures/pseudocode-planning-before-code', 'Pseudocode: planning before code', 'Write an algorithm in structured English with BEGIN, INPUT, PRINT, ← and IF … THEN … ELSE … END IF, then see how each line turns into C++. Explain what pseudocode is and why we use it Use the BEGIN, INPUT, PROCESS, OUTPUT, END template Use the keywords INPUT, PRINT, SET / ←, IF, THEN, ELSE and END IF Go from a problem to pseudocode in three steps What is pseudocode? Pseudocode is an informal way of describing an algorithm with simple, structured, English-like statements. - It is not a real programming language, so no computer runs it. - It has no strict syntax rules . It is written for people. - It focuses on the logic , not on the details of a language. - It helps you plan a program before you write it. Pseudocode sits between how we think and how a computer is programmed: human thinking (ideas and logic) → pseudocode (structured English) → programming code (C++, Python, Java…) Why do we use pseudocode? - Easy to read: plain, structured English that anyone can follow. - Helps plan logic: you think about the steps before worrying about semicolons and brackets. - Language independent: the same pseudocode works for C++, Python, Java or any other language. - Easy to convert into code: each line maps naturally to a line of code. Think first. Code later. Most beginner errors are logic errors, not typing errors, and pseudocode is where you catch them. The basic structure Almost every simple algorithm follows the same template: input → process → output , between BEGIN and END . BEGIN INPUT data PROCESS data OUTPUT result END Pseudocode keywords These are the words we use in this course. Write them in CAPITALS so every step stands out. Keyword Meaning --- --- BEGIN start of the algorithm END end of the algorithm INPUT read a value (from the user or a sensor) PRINT display a value SET / ← store a value: SET x ← 5 and x ← 5 mean the same thing IF start a decision and check a condition THEN what to do when the condition is TRUE ELSE what to do when the condition is FALSE END IF end of the decision The decision keywords always come as a group: IF … THEN … ELSE … END IF . Example: calculate the average Problem: calculate the average of three numbers. The user typed 12 15 18 . BEGIN INPUT N1, N2, N3 SUM ← N1 + N2 + N3 AVERAGE ← SUM / 3 PRINT AVERAGE END Example: a decision The temperature problem from Lecture 1, with the decision keywords. This time the sensor read 25 . BEGIN INPUT T IF T > 30 THEN PRINT "Fan ON" ELSE PRINT "Fan OFF" END IF END From problem to pseudocode in three steps Problem: read the length and width of a rectangle and calculate its area. Step 1: identify the variables. We need length , width and area . Step 2: choose the data types. Lengths can have decimals (2.5 m), so float is the safe choice for all three. Variable Data type --- --- length float width float area float Step 3: write the pseudocode. You''ll find it in the next section. - Input: length , width - Processing: area ← length width - Output: area Rectangle area in pseudocode Two INPUT lines, one calculation, one PRINT . The user typed 8 , then 5 . BEGIN INPUT length INPUT width area ← length * width PRINT area END Each line becomes a line of C++ When the plan is right, turning it into C++ is mostly a matter of swapping words for symbols: Pseudocode C++ --- --- INPUT length cin length; area ← length width area = length width; PRINT area cout << area; IF T 30 THEN … ELSE … END IF if (T 30) { … } else { … } BEGIN … END int main() { … } In C++ every statement ends with a semicolon ; . You''ll write the full rectangle program in C++ in the flowcharts lecture. Check yourself BEGIN INPUT length INPUT width perimeter ← 2 (length + width) PRINT perimeter END No. Pseudocode has no strict syntax, because it is for people. What matters is that the steps are clear, in the right order, and easy to turn into code. Using the same keywords as your class makes it easier for others to read. Key takeaways - Pseudocode is structured English for planning an algorithm. No computer runs it. - The basic template is BEGIN , input, process, output, END . - ← (or SET ) stores a value; INPUT reads one; PRINT shows one. - Decisions are written IF … THEN … ELSE … END IF . - To solve a problem: identify the variables, choose their data types, then write the pseudocode.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_f7b18d0e5ec4fdbd', 'course_programming_fundamentals', 'top_bf35d27534681d59', 'variables-named-boxes-in-memory', 'Variables: named boxes in memory', 'A variable is a named place in memory that holds a value. Create variables in C++, change their values, and choose names the compiler accepts and people understand.', 2, 5, 'easy', '["Explain what a variable is, using the labelled-box picture","Create a variable in C++ and give it a value","Change a variable''s value while the program runs","Apply the naming rules and spot invalid names"]', '["Pseudocode: planning before code"]', 6, 'published', 1791504000000, 1791504000000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
