INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'lesson', 'les_f7b18d0e5ec4fdbd', '/courses/programming-fundamentals/lectures/variables-named-boxes-in-memory', 'Variables: named boxes in memory', 'A variable is a named place in memory that holds a value. Create variables in C++, change their values, and choose names the compiler accepts and people understand. Explain what a variable is, using the labelled-box picture Create a variable in C++ and give it a value Change a variable''s value while the program runs Apply the naming rules and spot invalid names Where do we store data? To solve problems, a program needs places to keep information: the mark a student typed, the latest sensor reading, a running total. A variable is a named memory location used to store a value. Picture the computer''s memory (RAM) as a shelf of boxes. Each box has a label (the variable''s name) and holds one value : Name (label on the box) Value (inside the box) In C++ --- --- --- age 18 age = 18; temperature 32.5 temperature = 32.5; grade ''A'' grade = ''A''; Creating variables in C++ In C++ you must say what type of value a box holds before you use it. This is called declaring the variable. Here we declare three variables, give each a value, and print them. #include <iostream> using namespace std; int main() { int age = 18; float temperature = 32.5; char grade = ''A''; cout << "age = " << age << endl; cout << "temperature = " << temperature << endl; cout << "grade = " << grade << endl; return 0; } Name and value Every variable has three things: - a name , such as temperature , which stays the same; - a value , such as 32.5 , which is what''s stored in the box; - a type , such as float , which says what kind of value fits in the box. Look at line 9 again: "age = " is in double quotes, so it is printed exactly as written. age without quotes means "the value inside the box called age", so 18 is printed. The value can change The name stays the same, but the value can change while the program runs. A new sensor reading replaces the old value in the same box. The old value is gone. #include <iostream> using namespace std; int main() { float temperature = 32.5; cout << "first reading: " << temperature << endl; temperature = 35.7; cout << "new reading: " << temperature << endl; return 0; } In pseudocode, the arrow does the same job In pseudocode we write temperature ← 35.7 . In C++ we write temperature = 35.7; . Both mean: store 35.7 in the box called temperature . Read it from right to left: the value on the right goes into the variable on the left. Naming rules Good names make programs easy to read. C++ also has rules that every name must follow: 1. Start with a letter or an underscore . 2. Use only letters, digits and . 3. No spaces. 4. Do not start with a number. 5. Use meaningful names: total marks tells the reader far more than t or x2 . Valid Invalid Why it is invalid --- --- --- age 2marks starts with a number studentGrade student grade contains a space total marks total-price the hyphen - is not allowed (C++ reads it as minus) temperature1 Two more C++ facts: names are case-sensitive , so age , Age and AGE are three different variables; and you can''t use C++''s own words, such as int or while , as names. A name that starts with a number The compiler refuses this program. It never runs, so there is no output. #include <iostream> using namespace std; int main() { int 2marks = 90; cout << 2marks << endl; return 0; } What the compiler said When we compiled that program with g++, the first error was: error: expected unqualified-id before numeric constant That is compiler language for "I expected a name here, but found a number". Other compilers word it differently. The fix is a valid name, for example marks2 or second marks . Check yourself Valid: count and finalMark . Invalid: 3d (starts with a digit), final mark (a space) and price$ ( $ is not a letter, digit or underscore; some compilers accept it, but the rules above don''t allow it, so don''t use it). 9 . The second assignment replaced the 4. A variable holds one value at a time. Key takeaways - A variable is a named memory location that stores a value. - Every variable has a name, a value and a type. The name stays; the value can change. - = in C++ and ← in pseudocode both mean "store the value on the right in the variable on the left". - Names start with a letter or , use only letters, digits and , have no spaces, and should be meaningful.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_a369e9ead4fd7321', 'course_programming_fundamentals', 'top_a369e9ead4fd7321', 'data-types', 'Data types: int, float, char, string and bool', 'A data type tells the computer what kind of value a variable stores. Meet the five types you will use most, and learn to choose the right one for each value.', 2, 6, 'easy', '["Explain what a data type is and why it matters","Use int, float or double, char, string and bool in C++","Choose the right data type for a value by asking five questions","Avoid losing the decimal part by storing it in an int"]', '["Variables: named boxes in memory"]', 6, 'published', 1791504000000, 1791504000000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
