INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_6f39d53a808afe57', 'course_programming_fundamentals', 'les_a369e9ead4fd7321', 'explanation', 'What is a data type?', 'A **data type** tells the computer what **kind** of data a variable stores.

Why does it matter? Different kinds of values need different amounts of memory and allow different operations. A whole number and a decimal number are stored differently, and you can multiply two numbers but not two names. The data type tells the computer which rules apply.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f7839b4b817a0df7', 'course_programming_fundamentals', 'les_a369e9ead4fd7321', 'explanation', 'The five types you will use most', '| Data type | Used for | Example |
|---|---|---|
| `int` | whole numbers | `20` |
| `float` / `double` | decimal numbers | `25.75` |
| `char` | a single character | `''A''` |
| `string` | text | `"Omar"` |
| `bool` | true or false | `true` |

A few details:

- `float` and `double` both store decimals. `double` is more precise, because it uses more memory.
- A `char` value goes in **single** quotes: `''A''`. A `string` value goes in **double** quotes: `"Omar"`.
- To use `string` in C++, add `#include <string>` at the top of the program.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 2, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_1e31a8854cc7a599', 'course_programming_fundamentals', 'les_a369e9ead4fd7321', 'code', 'All five types in one program', '', '#include <iostream>
#include <string>
using namespace std;

int main()
{
    int age = 19;
    float temperature = 32.5;
    double price = 25.75;
    char grade = ''A'';
    string name = "Omar";
    bool fanOn = true;
    cout << age << endl;
    cout << temperature << endl;
    cout << price << endl;
    cout << grade << endl;
    cout << name << endl;
    cout << fanOn << endl;
    return 0;
}', 'cpp', 1, '', '19
32.5
25.75
A
Omar
1
', '{"notes":[{"line":2,"match":"string","text":"needed for string","shape":"circle","color":"sky"},{"line":7,"match":"int","text":"whole number","shape":"square","color":"yel"},{"line":8,"match":"float","text":"decimal number","shape":"square","color":"yel"},{"line":10,"match":"''A''","text":"char: single quotes","shape":"tri","color":"green"},{"line":11,"match":"\"Omar\"","text":"string: double quotes","shape":"tri","color":"green"},{"line":18,"match":"fanOn","text":"true prints as 1","shape":"diamond","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 3, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_378064abd2078b3d', 'course_programming_fundamentals', 'les_a369e9ead4fd7321', 'explanation', 'Why did true print as 1?', 'Inside the computer, `true` is stored as `1` and `false` as `0`. By default, `cout` prints a `bool` as that number. The value is still `true`; only the way it is printed is different.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_fea00baa8e302c5b', 'course_programming_fundamentals', 'les_a369e9ead4fd7321', 'example', 'Choosing the correct data type', 'Ask yourself these questions about the value, in this order:

1. Is it a **whole number**? → `int`
2. Does it have a **decimal point**? → `float` (or `double`)
3. Is it a **single character**? → `char`
4. Is it **text**, such as a word or a name? → `string`
5. Is it only **true or false**? → `bool`

| Value | Example | Type |
|---|---|---|
| Student age | `19` | `int` |
| Temperature | `32.5` | `float` |
| Student name | `"Omar"` | `string` |
| Exam grade letter | `''A''` | `char` |
| Fan ON/OFF state | `true` / `false` | `bool` |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a4feed876283ca29', 'course_programming_fundamentals', 'les_a369e9ead4fd7321', 'common_mistakes', 'A decimal stored in an int', 'An `int` box can only hold whole numbers. If you store 32.5 in it, C++ drops the `.5` without asking. Our compiler didn''t even warn about it, even with warnings turned on.', '#include <iostream>
using namespace std;

int main()
{
    int temperature = 32.5;
    cout << temperature << endl;
    return 0;
}', 'cpp', 1, '', '32
', '{"notes":[{"line":6,"match":"int","text":"wrong type for 32.5","shape":"tri","color":"coral"},{"line":6,"match":"32.5","text":"the .5 is lost","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 6, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_814f28b3666c6f2c', 'course_programming_fundamentals', 'les_a369e9ead4fd7321', 'common_mistakes', 'Dividing two ints', 'When **both** numbers in a division are `int`, C++ does whole-number division and cuts off the decimal part. The total 24 divided by 5 gives 4, not 4.8. With a `float`, the decimal part stays.', '#include <iostream>
using namespace std;

int main()
{
    int total = 24;
    cout << total / 5 << endl;
    float sum = 24;
    cout << sum / 5 << endl;
    return 0;
}', 'cpp', 1, '', '4
4.8
', '{"notes":[{"line":7,"match":"total / 5","text":"int / int: 4","shape":"tri","color":"coral"},{"line":9,"match":"sum / 5","text":"float / int: 4.8","shape":"circle","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 7, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b05a3574595e995b', 'course_programming_fundamentals', 'les_a369e9ead4fd7321', 'note', 'Check yourself', '::: check What data type would you use for a temperature, an age and a student''s name?
???
Temperature: `float` (it can have a decimal part, such as 32.5). Age: `int` (a whole number). Student''s name: `string` (text).
:::

::: check Which type fits "has the student paid the fees?"
???
`bool`. The answer is only ever yes or no, which is `true` or `false`.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ed70dea12442dc85', 'course_programming_fundamentals', 'les_a369e9ead4fd7321', 'key_takeaways', 'Key takeaways', '- A data type tells the computer what kind of value a variable stores.
- `int` for whole numbers, `float`/`double` for decimals, `char` for one character, `string` for text, `bool` for true/false.
- `char` uses single quotes `''A''`; `string` uses double quotes `"Omar"` and needs `#include <string>`.
- Storing a decimal in an `int`, or dividing two `int`s, loses the decimal part.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1791504000000);
