INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'lesson', 'les_a369e9ead4fd7321', '/courses/programming-fundamentals/lectures/data-types', 'Data types: int, float, char, string and bool', 'A data type tells the computer what kind of value a variable stores. Meet the five types you will use most, and learn to choose the right one for each value. Explain what a data type is and why it matters Use int, float or double, char, string and bool in C++ Choose the right data type for a value by asking five questions Avoid losing the decimal part by storing it in an int What is a data type? A data type tells the computer what kind of data a variable stores. Why does it matter? Different kinds of values need different amounts of memory and allow different operations. A whole number and a decimal number are stored differently, and you can multiply two numbers but not two names. The data type tells the computer which rules apply. The five types you will use most Data type Used for Example --- --- --- int whole numbers 20 float / double decimal numbers 25.75 char a single character ''A'' string text "Omar" bool true or false true A few details: - float and double both store decimals. double is more precise, because it uses more memory. - A char value goes in single quotes: ''A'' . A string value goes in double quotes: "Omar" . - To use string in C++, add include <string at the top of the program. All five types in one program #include <iostream> #include <string> using namespace std; int main() { int age = 19; float temperature = 32.5; double price = 25.75; char grade = ''A''; string name = "Omar"; bool fanOn = true; cout << age << endl; cout << temperature << endl; cout << price << endl; cout << grade << endl; cout << name << endl; cout << fanOn << endl; return 0; } Why did true print as 1? Inside the computer, true is stored as 1 and false as 0 . By default, cout prints a bool as that number. The value is still true ; only the way it is printed is different. Choosing the correct data type Ask yourself these questions about the value, in this order: 1. Is it a whole number ? → int 2. Does it have a decimal point ? → float (or double ) 3. Is it a single character ? → char 4. Is it text , such as a word or a name? → string 5. Is it only true or false ? → bool Value Example Type --- --- --- Student age 19 int Temperature 32.5 float Student name "Omar" string Exam grade letter ''A'' char Fan ON/OFF state true / false bool A decimal stored in an int An int box can only hold whole numbers. If you store 32.5 in it, C++ drops the .5 without asking. Our compiler didn''t even warn about it, even with warnings turned on. #include <iostream> using namespace std; int main() { int temperature = 32.5; cout << temperature << endl; return 0; } Dividing two ints When both numbers in a division are int , C++ does whole-number division and cuts off the decimal part. The total 24 divided by 5 gives 4, not 4.8. With a float , the decimal part stays. #include <iostream> using namespace std; int main() { int total = 24; cout << total / 5 << endl; float sum = 24; cout << sum / 5 << endl; return 0; } Check yourself Temperature: float (it can have a decimal part, such as 32.5). Age: int (a whole number). Student''s name: string (text). bool . The answer is only ever yes or no, which is true or false . Key takeaways - A data type tells the computer what kind of value a variable stores. - int for whole numbers, float / double for decimals, char for one character, string for text, bool for true/false. - char uses single quotes ''A'' ; string uses double quotes "Omar" and needs include <string . - Storing a decimal in an int , or dividing two int s, loses the decimal part.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_5e676150e110b6d3', 'course_programming_fundamentals', 'top_5e676150e110b6d3', 'operators', 'Operators: calculate, store and compare', 'Use arithmetic operators to calculate, = to store a value, and relational operators to compare values and get TRUE or FALSE, plus the % trick for even and odd numbers.', 2, 7, 'easy', '["Use the arithmetic operators + - * / and %","Use % to tell even numbers from odd ones","Read an assignment from right to left","Compare values with > < == != >= <= and explain the TRUE/FALSE result"]', '["Data types: int, float, char, string and bool"]', 8, 'published', 1791504000000, 1791504000000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
