INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_7040d71065200c04', 'course_programming_fundamentals', 'les_5e676150e110b6d3', 'explanation', 'Three families of operators', '**Operators** are symbols that perform operations on values and variables. This lecture covers three families:

| Family | Job | Symbols |
|---|---|---|
| **Arithmetic** | calculate values | `+` `-` `*` `/` `%` |
| **Relational** | compare values | `>` `<` `==` `!=` `>=` `<=` |
| **Assignment** | store values | `=` in code, `←` in pseudocode |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_30c9e2a163c6c802', 'course_programming_fundamentals', 'les_5e676150e110b6d3', 'code', 'Arithmetic operators', '| Operator | Meaning |
|---|---|
| `+` | addition |
| `-` | subtraction |
| `*` | multiplication |
| `/` | division |
| `%` | modulus: the **remainder** after division |', '#include <iostream>
using namespace std;

int main()
{
    int A = 17;
    int B = 5;
    cout << "A + B = " << A + B << endl;
    cout << "A - B = " << A - B << endl;
    cout << "A * B = " << A * B << endl;
    cout << "A / B = " << A / B << endl;
    cout << "A % B = " << A % B << endl;
    return 0;
}', 'cpp', 1, '', 'A + B = 22
A - B = 12
A * B = 85
A / B = 3
A % B = 2
', '{"notes":[{"line":11,"match":"A / B","text":"int / int: whole part only","shape":"square","color":"yel"},{"line":12,"match":"A % B","text":"the remainder","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3a4afe22c9479b66', 'course_programming_fundamentals', 'les_5e676150e110b6d3', 'explanation', 'Division and remainder go together', '17 divided by 5 is 3, with 2 left over (5 × 3 = 15, and 17 − 15 = 2).

- `17 / 5` gives the **3**. Because both numbers are `int`, the decimal part is cut off.
- `17 % 5` gives the **2**, the remainder.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5400c129cdc41069', 'course_programming_fundamentals', 'les_5e676150e110b6d3', 'code', '% for even and odd', 'A number is **even** when dividing it by 2 leaves nothing over, and **odd** when 1 is left over. So `number % 2` tells you which it is: `0` means even, `1` means odd.', '#include <iostream>
using namespace std;

int main()
{
    cout << "8 % 2 = " << 8 % 2 << endl;
    cout << "7 % 2 = " << 7 % 2 << endl;
    return 0;
}', 'cpp', 1, '', '8 % 2 = 0
7 % 2 = 1
', '{"notes":[{"line":6,"match":"8 % 2","text":"0 left over: even","shape":"circle","color":"green"},{"line":7,"match":"7 % 2","text":"1 left over: odd","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 4, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_4d33973d62dfff1f', 'course_programming_fundamentals', 'les_5e676150e110b6d3', 'code', 'The assignment operator', '`=` means **assign**: store a value. Read it from **right to left**: work out the right side first, then store the result in the variable on the left. `x = 5` means "store the value 5 inside x". It is not the maths "equals".', '#include <iostream>
using namespace std;

int main()
{
    int A = 4, B = 6;
    int x = 5;
    int sum = A + B;
    x = x + 1;
    cout << "sum = " << sum << endl;
    cout << "x = " << x << endl;
    return 0;
}', 'cpp', 1, '', 'sum = 10
x = 6
', '{"notes":[{"line":7,"match":"x = 5;","text":"store 5 in x","shape":"circle","color":"sky"},{"line":8,"match":"A + B","text":"worked out first","shape":"square","color":"yel"},{"line":9,"match":"x = x + 1;","text":"old x + 1, stored back","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 5, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0607e697c2211292', 'course_programming_fundamentals', 'les_5e676150e110b6d3', 'explanation', 'Careful: =, == and ←', '| Symbol | Where | Meaning |
|---|---|---|
| `=` | C++ | **store** a value: `x = 5` |
| `==` | C++ and pseudocode | **compare** two values: `x == 5` asks "is x equal to 5?" |
| `←` | pseudocode | the same as `=` in C++: `x ← 5` |

`x = x + 1` looks impossible in maths, but in code it is normal: take the old value of `x`, add 1, and store the result back in `x`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_176c938813ee90c5', 'course_programming_fundamentals', 'les_5e676150e110b6d3', 'code', 'Relational operators give TRUE or FALSE', 'A comparison is a question, and its answer is always **TRUE** or **FALSE**. That is exactly what an `IF` needs.

| Operator | Meaning | Example |
|---|---|---|
| `>` | greater than | `7 > 3` |
| `<` | less than | `2 < 9` |
| `==` | equal to | `x == 5` |
| `>=` | greater than or equal to | `age >= 18` |
| `<=` | less than or equal to | `T <= 30` |
| `!=` | not equal to | `n != 0` |

Here `cout` prints the answer of `temperature > 30`. Remember that `cout` shows TRUE as `1` and FALSE as `0`. The brackets are needed around a comparison inside `cout`.', '#include <iostream>
using namespace std;

int main()
{
    int temperature = 32;
    cout << (temperature > 30) << endl;
    temperature = 25;
    cout << (temperature > 30) << endl;
    return 0;
}', 'cpp', 1, '', '1
0
', '{"notes":[{"line":7,"match":"(temperature > 30)","text":"32 > 30 is TRUE","shape":"circle","color":"green"},{"line":9,"match":"(temperature > 30)","text":"25 > 30 is FALSE","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 7, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_815c00bc3b06bf86', 'course_programming_fundamentals', 'les_5e676150e110b6d3', 'example', 'The same comparison in pseudocode', '```pseudocode
IF temperature > 30 THEN
    PRINT "Fan ON"
END IF
```

When `temperature` is 32, `32 > 30` is TRUE and "Fan ON" is printed. When it is 25, `25 > 30` is FALSE and nothing is printed.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_69375529b09aab1f', 'course_programming_fundamentals', 'les_5e676150e110b6d3', 'common_mistakes', 'Common operator mistakes', '- **Writing `=` when you mean `==`.** `x = 5` stores 5; `x == 5` compares. In a condition you almost always want `==`.
- **Maths symbols.** C++ has no `≥`, `≤` or `≠`. Write `>=`, `<=` and `!=`, with no space between the two characters.
- **Expecting decimals from `int / int`.** `7 / 2` is `3`. If you need `3.5`, at least one of the values must be a `float` or `double`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_007589d3ef4a49da', 'course_programming_fundamentals', 'les_5e676150e110b6d3', 'note', 'Check yourself', '::: check What does this print?
```cpp
cout << 23 / 5 << " " << 23 % 5 << endl;
```
???
```output
4 3
```
23 divided by 5 is 4 (5 × 4 = 20), with 3 left over.
:::

::: check Is 15 even or odd? Use %.
???
Odd: `15 % 2` is `1`.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e8ffaa4e7291d08c', 'course_programming_fundamentals', 'les_5e676150e110b6d3', 'key_takeaways', 'Key takeaways', '- Arithmetic: `+ - * /` and `%`, the remainder. `int / int` keeps only the whole part.
- `number % 2 == 0` means even; `1` means odd.
- `=` stores a value (read right to left); `==` compares; `←` is pseudocode''s `=`.
- Relational operators answer TRUE or FALSE, which is what decisions need.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1791504000000);
