INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_83dc8d608ad359a2', 'course_programming_fundamentals', 'les_e07719c8d778f2a7', 'explanation', 'From problem to solution', 'Every problem in this course goes through the same path. First we **analyze** it, then we **represent** the solution:

1. **Analyze:** understand the problem, then identify its **input**, **processing** and **output**.
2. **Represent:** write the **steps**, draw the **flowchart**, write the **pseudocode**.

This lecture practises both stages on bigger problems.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3e32409bd1c5c41f', 'course_programming_fundamentals', 'les_e07719c8d778f2a7', 'diagram', 'The flowchart symbols', 'Keep this legend in mind while you read the charts in this lecture.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_fundamentals/lessons/les_e07719c8d778f2a7/flowchart-symbols.png', 'A legend of flowchart symbols on a navy background: a green oval labelled Start for start and end, a blue parallelogram labelled Input T for input or output, a white rectangle labelled area ← l * w for a process, a yellow diamond labelled T > 30? for a decision with YES and NO exits, and an arrow for the order of the steps', 1520, 1080, 2, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5872333576ee979d', 'course_programming_fundamentals', 'les_e07719c8d778f2a7', 'example', 'Worked example: the area of a rectangle', '**Problem:** calculate the area of a rectangle, given its length and width.

| Question | Answer |
|---|---|
| What are the inputs? | Length, Width |
| What is the processing? | Area = Length × Width |
| What is the output? | Area |

**Example:** Length = 8 and Width = 5, so Area = 8 × 5 = 40.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_65b97a537a460730', 'course_programming_fundamentals', 'les_e07719c8d778f2a7', 'diagram', 'Rectangle area as a flowchart', 'Input and output use the **parallelogram**; the calculation uses the **rectangle**.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_fundamentals/lessons/les_e07719c8d778f2a7/rectangle-area.png', 'A flowchart: Start, the parallelogram Input Length, Width, the rectangle Area = Length × Width, the parallelogram Print Area, then End', 1080, 1120, 4, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e75743d0a45f7a48', 'course_programming_fundamentals', 'les_e07719c8d778f2a7', 'explanation', 'Three representations, matched line by line', 'Each numbered step is one flowchart shape and one pseudocode line. Same algorithm, different representations.

| Step | Flowchart shape | Pseudocode |
|---|---|---|
| 1. Start | oval: Start | `BEGIN` |
| 2. Read Length | parallelogram: Input Length, Width | `INPUT length` |
| 3. Read Width | (same parallelogram) | `INPUT width` |
| 4. Calculate Area = Length × Width | rectangle | `area ← length * width` |
| 5. Print Area | parallelogram | `PRINT area` |
| 6. End | oval: End | `END` |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_9457b35655c1f74b', 'course_programming_fundamentals', 'les_e07719c8d778f2a7', 'code', 'From the flowchart to C++', 'Now the same plan as a complete C++ program. Lengths can have decimals, so all three variables are `float`. The user typed `2.5` and `4`.', '#include <iostream>
using namespace std;

int main()
{
    float length, width, area;
    cout << "Enter length: ";
    cin >> length;
    cout << "Enter width: ";
    cin >> width;
    area = length * width;
    cout << "Area = " << area << endl;
    return 0;
}', 'cpp', 1, '2.5
4
', 'Enter length: 2.5
Enter width: 4
Area = 10
', '{"notes":[{"line":6,"match":"float","text":"decimals allowed","shape":"circle","color":"sky"},{"line":8,"match":"cin >> length;","text":"Input Length","shape":"square","color":"sky"},{"line":11,"match":"area = length * width;","text":"the rectangle shape","shape":"diamond","color":"yel"},{"line":12,"match":"cout","text":"Print Area","shape":"tri","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 6, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ead22c59aa20228f', 'course_programming_fundamentals', 'les_e07719c8d778f2a7', 'explanation', 'From simple to more complex', 'So far every algorithm ran in **one straight path**: input, calculation, output. Every step ran once, top to bottom.

Real problems often need a **decision**: the algorithm checks a condition and chooses one of **two possible paths**.

| So far: simple | Now: more complex |
|---|---|
| Input → Calculation → Output | Input → Calculation → **Decision** → Output A **or** Output B |
| one straight path | two possible paths |

In a flowchart the decision is the **diamond**. It always has exactly two exits, YES and NO. The next lecture is all about decisions.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d32b0eb25ad57209', 'course_programming_fundamentals', 'les_e07719c8d778f2a7', 'common_mistakes', 'Flowchart mistakes to avoid', '- **The wrong shape.** Reading or printing a value goes in a parallelogram, not a rectangle. Rectangles are for calculations.
- **A decision with one exit.** Every diamond has exactly two exits, labelled YES and NO (or TRUE and FALSE).
- **Paths that never meet again.** After a decision, the two paths should join before End, so the chart has one End.
- **Missing arrows.** Without arrows the reader can''t tell the order of the steps.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_efe5a328b49c3d8b', 'course_programming_fundamentals', 'les_e07719c8d778f2a7', 'note', 'Check yourself', '::: check Draw (on paper) the flowchart for: read a price and a quantity, and print the total cost.
???
Start → parallelogram `Input price, quantity` → rectangle `total ← price * quantity` → parallelogram `Print total` → End. One straight path, no decision.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 9, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_00c85fc7d4c5652e', 'course_programming_fundamentals', 'les_e07719c8d778f2a7', 'key_takeaways', 'Key takeaways', '- Analyze first (input, processing, output), then represent: steps, flowchart, pseudocode.
- Each step is one flowchart shape and one pseudocode line.
- Input and output: parallelogram. Calculation: rectangle. Decision: diamond with two exits.
- A decision turns one straight path into two possible paths.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1791504000000);
DELETE FROM search_index WHERE course_id = 'course_programming_fundamentals' AND entity_type = 'lesson' AND entity_id = 'les_e07719c8d778f2a7';
INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'lesson', 'les_e07719c8d778f2a7', '/courses/programming-fundamentals/lectures/flowcharts', 'Flowcharts: one problem, three representations', 'Draw an algorithm as a flowchart, match every shape to a plain step and a pseudocode line, and write the rectangle-area program in C++ from the plan. Use the right flowchart symbol for each kind of step Match plain steps, flowchart shapes and pseudocode lines one to one Tell a straight-line algorithm from one with a decision Turn a flowchart into a C++ program From problem to solution Every problem in this course goes through the same path. First we analyze it, then we represent the solution: 1. Analyze: understand the problem, then identify its input , processing and output . 2. Represent: write the steps , draw the flowchart , write the pseudocode . This lecture practises both stages on bigger problems. The flowchart symbols Keep this legend in mind while you read the charts in this lecture. Worked example: the area of a rectangle Problem: calculate the area of a rectangle, given its length and width. Question Answer --- --- What are the inputs? Length, Width What is the processing? Area = Length × Width What is the output? Area Example: Length = 8 and Width = 5, so Area = 8 × 5 = 40. Rectangle area as a flowchart Input and output use the parallelogram ; the calculation uses the rectangle . Three representations, matched line by line Each numbered step is one flowchart shape and one pseudocode line. Same algorithm, different representations. Step Flowchart shape Pseudocode --- --- --- 1. Start oval: Start BEGIN 2. Read Length parallelogram: Input Length, Width INPUT length 3. Read Width (same parallelogram) INPUT width 4. Calculate Area = Length × Width rectangle area ← length width 5. Print Area parallelogram PRINT area 6. End oval: End END From the flowchart to C++ Now the same plan as a complete C++ program. Lengths can have decimals, so all three variables are float . The user typed 2.5 and 4 . #include <iostream> using namespace std; int main() { float length, width, area; cout << "Enter length: "; cin >> length; cout << "Enter width: "; cin >> width; area = length * width; cout << "Area = " << area << endl; return 0; } From simple to more complex So far every algorithm ran in one straight path : input, calculation, output. Every step ran once, top to bottom. Real problems often need a decision : the algorithm checks a condition and chooses one of two possible paths . So far: simple Now: more complex --- --- Input → Calculation → Output Input → Calculation → Decision → Output A or Output B one straight path two possible paths In a flowchart the decision is the diamond . It always has exactly two exits, YES and NO. The next lecture is all about decisions. Flowchart mistakes to avoid - The wrong shape. Reading or printing a value goes in a parallelogram, not a rectangle. Rectangles are for calculations. - A decision with one exit. Every diamond has exactly two exits, labelled YES and NO (or TRUE and FALSE). - Paths that never meet again. After a decision, the two paths should join before End, so the chart has one End. - Missing arrows. Without arrows the reader can''t tell the order of the steps. Check yourself Start → parallelogram Input price, quantity → rectangle total ← price quantity → parallelogram Print total → End. One straight path, no decision. Key takeaways - Analyze first (input, processing, output), then represent: steps, flowchart, pseudocode. - Each step is one flowchart shape and one pseudocode line. - Input and output: parallelogram. Calculation: rectangle. Decision: diamond with two exits. - A decision turns one straight path into two possible paths.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_810ecce8c9e38678', 'course_programming_fundamentals', 'top_d06bd9ff15d1e6cd', 'decisions-if-then-else', 'Decisions: IF … THEN … ELSE', 'Let an algorithm choose between two paths. Three worked examples, pass or fail, the larger of two numbers, and even or odd, each as steps, a flowchart, pseudocode and C++.', 3, 9, 'easy', '["Write a decision as steps, a flowchart and IF … THEN … ELSE … END IF","Test a decision with boundary cases such as a mark of exactly 50","Use % to decide whether a number is even or odd","Translate IF … THEN … ELSE into C++ if and else"]', '["Flowcharts: one problem, three representations","Operators: calculate, store and compare"]', 11, 'published', 1791504000000, 1791504000000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
