INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5d11268682efe652', 'course_programming_fundamentals', 'les_810ecce8c9e38678', 'example', 'Worked example: pass or fail', '**Problem:** read a student''s mark. If the mark is greater than or equal to 50, display PASS. Otherwise, display FAIL.

| Question | Answer |
|---|---|
| What is the input? | Mark |
| What is processed? | compare the mark with 50 |
| What is the decision? | Mark >= 50 ? |
| What is the output? | PASS or FAIL |

**Test cases:** mark = 72 gives PASS, mark = 50 gives PASS, mark = 41 gives FAIL.

Is 50 a pass? **Yes:** `50 >= 50` is TRUE. The `=` in `>=` includes the boundary. Always test the boundary value; it is where most decision bugs hide.

**As plain steps:**

1. Start.
2. Read Mark.
3. Check if Mark >= 50.
4. If true, display PASS.
5. Otherwise, display FAIL.
6. End.

Only **one** of step 4 or step 5 runs each time, never both.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_92593662796cffdb', 'course_programming_fundamentals', 'les_810ecce8c9e38678', 'diagram', 'Pass or fail as a flowchart', 'Trace both paths with your finger: mark = 72 goes left (YES), mark = 41 goes right (NO). Both paths meet again before End.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_fundamentals/lessons/les_810ecce8c9e38678/pass-or-fail.png', 'A flowchart: Start, Input Mark, then the diamond Mark >= 50?. YES on the left leads to Print "PASS", NO on the right leads to Print "FAIL", and both paths join before End', 1400, 1200, 2, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_70d0368619668cd3', 'course_programming_fundamentals', 'les_810ecce8c9e38678', 'code', 'Pass or fail in pseudocode', '`IF` starts the decision and checks the condition, `THEN` is the path when it is TRUE, `ELSE` is the path when it is FALSE, and `END IF` closes it. Indent the lines inside each path so the two paths are easy to see. The mark typed was `50`, the boundary.', 'BEGIN
    INPUT mark
    IF mark >= 50 THEN
        PRINT "PASS"
    ELSE
        PRINT "FAIL"
    END IF
END', 'pseudocode', 0, '50
', '50
PASS
', '{"notes":[{"line":3,"match":"IF","text":"starts the decision","shape":"circle","color":"yel"},{"line":3,"match":"mark >= 50","text":"50 >= 50 is TRUE","shape":"square","color":"green"},{"line":5,"match":"ELSE","text":"the FALSE path","shape":"tri","color":"coral"},{"line":7,"match":"END IF","text":"closes the decision","shape":"diamond","color":"sky"}],"strips":[]}', NULL, NULL, NULL, NULL, 3, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_6be7402665248a50', 'course_programming_fundamentals', 'les_810ecce8c9e38678', 'code', 'Pass or fail in C++', 'The C++ version has the same shape. `IF … THEN` becomes `if ( )` with the condition in brackets, each path goes inside curly braces `{ }`, and `ELSE` becomes `else`. This time the mark typed was `41`.', '#include <iostream>
using namespace std;

int main()
{
    int mark;
    cout << "Enter mark: ";
    cin >> mark;
    if (mark >= 50)
    {
        cout << "PASS" << endl;
    }
    else
    {
        cout << "FAIL" << endl;
    }
    return 0;
}', 'cpp', 1, '41
', 'Enter mark: 41
FAIL
', '{"notes":[{"line":9,"match":"if (mark >= 50)","text":"IF mark >= 50 THEN","shape":"circle","color":"yel"},{"line":10,"match":"{","text":"the TRUE path starts","shape":"square","color":"green"},{"line":13,"match":"else","text":"ELSE","shape":"tri","color":"coral"},{"line":16,"match":"}","text":"END IF","shape":"diamond","color":"sky"}],"strips":[]}', NULL, NULL, NULL, NULL, 4, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_754cfef660a1497b', 'course_programming_fundamentals', 'les_810ecce8c9e38678', 'example', 'Worked example: find the larger number', '**Problem:** read two numbers A and B. Display the larger number.

- **Input:** A, B
- **Decision:** A > B ?
- **Output:** the larger number

**Example run:** A = 17, B = 42. `17 > 42` is FALSE, so B is printed: `42`.

**Think deeper:** what if A = B? Then `A > B` is FALSE, so B is printed. That is still correct, because both values are equal.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e79508d469eed59e', 'course_programming_fundamentals', 'les_810ecce8c9e38678', 'diagram', 'Larger number as a flowchart', 'Every decision has exactly two exits: YES and NO.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_fundamentals/lessons/les_810ecce8c9e38678/larger-number.png', 'A flowchart: Start, Input A, B, then the diamond A > B?. YES leads to Print A, NO leads to Print B, and both paths join before End', 1400, 1200, 6, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2472baeeea22fe6a', 'course_programming_fundamentals', 'les_810ecce8c9e38678', 'code', 'Larger number in C++', 'The user typed `17 42` on one line.', '#include <iostream>
