INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_879da7a27a236c65', 'course_programming_fundamentals', 'les_810ecce8c9e38678', 'example', 'Worked example: even or odd', '**Problem:** read an integer N. Decide whether it is even or odd.

- **Input:** N
- **Processing:** N % 2
- **Output:** EVEN or ODD

**Key idea:** `%` gives the remainder after dividing by 2. Group the items in pairs: if every item has a partner, the remainder is 0 and the number is even. If one item is left over, the remainder is 1 and the number is odd.

- N = 8: `8 % 2 = 0`, so EVEN.
- N = 7: `7 % 2 = 1`, so ODD.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0eeae0419f5758ca', 'course_programming_fundamentals', 'les_810ecce8c9e38678', 'diagram', 'Even or odd as a flowchart', 'The only new idea is the condition `N % 2 == 0`. Note the `==`: it compares, while `←` stores.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_fundamentals/lessons/les_810ecce8c9e38678/even-or-odd.png', 'A flowchart: Start, Input N, then the diamond N % 2 == 0?. YES leads to Print "EVEN", NO leads to Print "ODD", and both paths join before End', 1400, 1200, 9, 1791504000000);
