INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a912941e5b73d6a2', 'course_programming_fundamentals', 'les_810ecce8c9e38678', 'common_mistakes', '= instead of == in a condition', 'This program should print FAIL, because the mark is 30. But the condition says `mark = 50`, with **one** `=`. That **stores** 50 in `mark` instead of comparing, and a value that isn''t 0 counts as TRUE. So it prints PASS, and `mark` is now 50.

With warnings turned on, g++ notices and suggests brackets, which is its way of asking "did you mean `==`?".', '#include <iostream>
using namespace std;

int main()
{
    int mark = 30;
    if (mark = 50)
    {
        cout << "PASS" << endl;
    }
    else
    {
        cout << "FAIL" << endl;
    }
    cout << "mark is now " << mark << endl;
    return 0;
}', 'cpp', 1, '', 'PASS
mark is now 50
', '{"notes":[{"line":7,"match":"mark = 50","text":"stores 50! use ==","shape":"tri","color":"coral"},{"line":15,"match":"mark","text":"changed to 50","shape":"circle","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 11, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_9e19f1710f69323e', 'course_programming_fundamentals', 'les_810ecce8c9e38678', 'note', 'Check yourself', '::: check What does this print when N is 0?
```cpp
int N = 0;
if (N % 2 == 0)
{
    cout << "EVEN" << endl;
}
else
{
    cout << "ODD" << endl;
}
```
???
```output
EVEN
```
`0 % 2` is 0 (nothing is left over), so 0 is even.
:::

::: check With the condition `mark > 50` instead of `mark >= 50`, which test case gives the wrong answer: 72, 50 or 41?
???
50. With `>`, `50 > 50` is FALSE, so a mark of exactly 50 would FAIL. That is why the boundary is always one of your test cases.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_8ac69917fa279612', 'course_programming_fundamentals', 'les_810ecce8c9e38678', 'key_takeaways', 'Key takeaways', '- A decision makes two possible paths. Only one of them runs each time.
- In a flowchart, a decision is a diamond with exactly two exits, and the paths join again before End.
- Pseudocode: `IF condition THEN … ELSE … END IF`. C++: `if (condition) { … } else { … }`.
- Test the boundary: with `>=`, the boundary value is included.
- `N % 2 == 0` means N is even. Use `==` to compare; `=` stores.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 13, 1791504000000);
