INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_9738c71f8a8a4328', 'course_programming_fundamentals', 'les_0a16fb429d30296a', 'explanation', 'The question', '**Exam results processor.** A teacher enters the marks of 5 students. For each student, read the mark and print PASS if the mark is 50 or more, otherwise print FAIL. Count how many students passed and print that number at the end.

**Test data** for your trace: `72`, `45`, `50`, `38`, `90`.

**A. Design the solution**

1. Identify the input, processing and output.
2. Choose the variables and their data types.
3. Write the plain-language steps.
4. Draw the complete flowchart.

**B. Pseudocode and trace**

5. Write the pseudocode using WHILE and IF … ELSE.
6. Label the initialization, condition and update.
7. Trace the test data: how many students passed?
8. What happens if the update line is missing?

**Bonus:** also print EVEN or ODD for each mark, using the `%` operator.

::: tip
Try it on paper before you read the answers below. Answers 1 to 8 follow in order.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_4a08f342c33d8da3', 'course_programming_fundamentals', 'les_0a16fb429d30296a', 'explanation', 'Answers 1 and 2: input, processing, output and variables', '| Part | Answer |
|---|---|
| Input | `mark`, read 5 times |
| Processing | check `mark >= 50` and count the passes |
| Output | PASS or FAIL for each student, then the number of students who passed |

| Variable | Data type | Job |
|---|---|---|
| `counter` | `int` | counts the students, 1 to 5 |
| `mark` | `int` | the mark just entered (use `float` if marks can have decimals) |
| `passCount` | `int` | how many students passed so far |', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 2, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_c0d3ca6c746f9eeb', 'course_programming_fundamentals', 'les_0a16fb429d30296a', 'explanation', 'Answer 3: the plain-language steps', '1. Start.
2. Set counter ← 1 and passCount ← 0.
3. If counter <= 5 is FALSE, go to step 9.
4. Read mark.
5. If mark >= 50, print PASS and add 1 to passCount.
6. Otherwise, print FAIL.
7. Increase counter by 1.
8. Go back to step 3.
9. Print passCount, then End.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f3f546281ead110b', 'course_programming_fundamentals', 'les_0a16fb429d30296a', 'diagram', 'Answer 4: the flowchart', 'The decision `mark >= 50?` sits **inside** the loop. The yellow backward arrow returns to `counter <= 5?`; when that check is NO, passCount is printed and the algorithm ends.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_fundamentals/lessons/les_0a16fb429d30296a/exam-results.png', 'A flowchart: Start, then counter ← 1 and passCount ← 0, then the diamond counter <= 5?. YES leads to Input mark and the diamond mark >= 50?. Its YES path prints "PASS" and sets passCount ← passCount + 1; its NO path prints "FAIL". The paths join at counter ← counter + 1, and a yellow repeat arrow goes back to counter <= 5?. The NO exit of counter <= 5? leads to Print passCount and End', 1800, 2330, 4, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0fb9a177e73b1ae2', 'course_programming_fundamentals', 'les_0a16fb429d30296a', 'code', 'Answers 5 and 6: the pseudocode, with the loop parts', '`passCount ← 0` is also set before the loop, because it is a running count. The marks typed are the test data.', 'BEGIN
