INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3abc21e34dcdd915', 'course_programming_fundamentals', 'les_0a16fb429d30296a', 'common_mistakes', 'Answer 8: the missing update', 'Without `counter ← counter + 1`, `counter` stays 1, so `counter <= 5` is always TRUE. The program keeps asking for marks **forever**: an infinite loop.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_22cfc2ba7ee8c2be', 'course_programming_fundamentals', 'les_0a16fb429d30296a', 'code', 'The same algorithm in C++', 'Next lecture you''ll write loops in C++. Here is a preview of this exact algorithm, with a prompt before each mark. Compare it line by line with the pseudocode.', '#include <iostream>
using namespace std;

int main()
{
    int counter = 1;
    int passCount = 0;
    int mark;
    while (counter <= 5)
    {
        cout << "Enter mark: ";
        cin >> mark;
        if (mark >= 50)
        {
            cout << "PASS" << endl;
            passCount = passCount + 1;
        }
        else
        {
            cout << "FAIL" << endl;
        }
        counter = counter + 1;
    }
    cout << "Students passed: " << passCount << endl;
    return 0;
}', 'cpp', 1, '72
