INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_fb05318cf9d4df88', 'course_programming_fundamentals', 'les_0a16fb429d30296a', 'key_takeaways', 'Key takeaways', '- Big problems are solved with the same method: input/processing/output, variables, steps, flowchart, pseudocode.
- A decision can sit inside a loop; it is then made again for every value.
- A second counter (`passCount`) can count how often something happens. It starts at 0, before the loop.
- Print totals **after** the loop, once all the values are in.
- Tracing with test data shows the output before you ever run the program.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1791504000000);
