INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'lesson', 'les_0a16fb429d30296a', '/courses/programming-fundamentals/lectures/exam-results-processor', 'Final challenge: the exam results processor', 'One long problem that uses everything from Lecture 3, with a loop, a decision inside it and a counter. Design it, write the pseudocode, trace it with real marks, then see it in C++. Design a solution from input, processing and output to a flowchart Write a WHILE loop with an IF … ELSE inside it Use a second counter to count the passes Trace an algorithm with test data and predict its output The question Exam results processor. A teacher enters the marks of 5 students. For each student, read the mark and print PASS if the mark is 50 or more, otherwise print FAIL. Count how many students passed and print that number at the end. Test data for your trace: 72 , 45 , 50 , 38 , 90 . A. Design the solution 1. Identify the input, processing and output. 2. Choose the variables and their data types. 3. Write the plain-language steps. 4. Draw the complete flowchart. B. Pseudocode and trace 5. Write the pseudocode using WHILE and IF … ELSE. 6. Label the initialization, condition and update. 7. Trace the test data: how many students passed? 8. What happens if the update line is missing? Bonus: also print EVEN or ODD for each mark, using the % operator. Try it on paper before you read the answers below. Answers 1 to 8 follow in order. Answers 1 and 2: input, processing, output and variables Part Answer --- --- Input mark , read 5 times Processing check mark = 50 and count the passes Output PASS or FAIL for each student, then the number of students who passed Variable Data type Job --- --- --- counter int counts the students, 1 to 5 mark int the mark just entered (use float if marks can have decimals) passCount int how many students passed so far Answer 3: the plain-language steps 1. Start. 2. Set counter ← 1 and passCount ← 0. 3. If counter <= 5 is FALSE, go to step 9. 4. Read mark. 5. If mark = 50, print PASS and add 1 to passCount. 6. Otherwise, print FAIL. 7. Increase counter by 1. 8. Go back to step 3. 9. Print passCount, then End. Answer 4: the flowchart The decision mark = 50? sits inside the loop. The yellow backward arrow returns to counter <= 5? ; when that check is NO, passCount is printed and the algorithm ends. Answers 5 and 6: the pseudocode, with the loop parts passCount ← 0 is also set before the loop, because it is a running count. The marks typed are the test data. BEGIN counter ← 1 passCount ← 0 WHILE counter <= 5 DO INPUT mark IF mark >= 50 THEN PRINT "PASS" passCount ← passCount + 1 ELSE PRINT "FAIL" END IF counter ← counter + 1 END WHILE PRINT passCount END Answer 7: the trace Iteration mark Output passCount --- --- --- --- 1 72 PASS 1 2 45 FAIL 1 3 50 PASS 2 4 38 FAIL 2 5 90 PASS 3 Result: passCount = 3. The body runs 5 times, and the condition is checked 6 times: the sixth check, 6 <= 5 , is FALSE. Answer 8: the missing update Without counter ← counter + 1 , counter stays 1, so counter <= 5 is always TRUE. The program keeps asking for marks forever : an infinite loop. The same algorithm in C++ Next lecture you''ll write loops in C++. Here is a preview of this exact algorithm, with a prompt before each mark. Compare it line by line with the pseudocode. #include <iostream> using namespace std; int main() { int counter = 1; int passCount = 0; int mark; while (counter <= 5) { cout << "Enter mark: "; cin >> mark; if (mark >= 50) { cout << "PASS" << endl; passCount = passCount + 1; } else { cout << "FAIL" << endl; } counter = counter + 1; } cout << "Students passed: " << passCount << endl; return 0; } Bonus: EVEN or ODD for each mark Add a second decision inside the loop, right after INPUT mark . Only 45 is odd. BEGIN counter ← 1 passCount ← 0 WHILE counter <= 5 DO INPUT mark IF mark % 2 == 0 THEN PRINT "EVEN" ELSE PRINT "ODD" END IF IF mark >= 50 THEN PRINT "PASS" passCount ← passCount + 1 ELSE PRINT "FAIL" END IF counter ← counter + 1 END WHILE PRINT passCount END Key takeaways - Big problems are solved with the same method: input/processing/output, variables, steps, flowchart, pseudocode. - A decision can sit inside a loop; it is then made again for every value. - A second counter ( passCount ) can count how often something happens. It starts at 0, before the loop. - Print totals after the loop, once all the values are in. - Tracing with test data shows the output before you ever run the program.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_1946d5476bda30c9', 'course_programming_fundamentals', 'top_e519989412df8f8b', 'while-loops-in-cpp', 'While loops in C++: from pseudocode to real code', 'Turn last lecture''s WHILE pseudocode into a complete C++ program, read it line by line, trace it, and use ++, -- and += to count up, count down and count in steps.', 4, 12, 'easy', '["Translate a WHILE loop from pseudocode into C++","Explain every line of a complete C++ program","Write the while syntax correctly, with no semicolon after while ( )","Use counter++, counter-- and counter += 2 as updates"]', '["Repetition: the WHILE loop in pseudocode"]', 13, 'published', 1791504000000, 1791504000000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
