INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_4f0625a3e98fdd7e', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'explanation', 'Where did we stop?', 'Every loop runs the same cycle: **initialization** once, then **condition**, **body**, **update**, and back to the condition.

Last lecture we wrote this pseudocode:

```pseudocode
counter ← 1
WHILE counter <= 5 DO
    PRINT counter
    counter ← counter + 1
END WHILE
```

What are the three essential parts? **Initialization** (`counter ← 1`), **condition** (`counter <= 5`) and **update** (`counter ← counter + 1`). Miss any one of them and the loop breaks. Today we write it in real C++.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_bf82bb50fdd63c16', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'diagram', 'The same example as a flowchart', 'After the update, the flow jumps back to the **condition**, not to Start. Only the NO exit reaches End.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_fundamentals/lessons/les_1946d5476bda30c9/count-1-to-5.png', 'A flowchart: Start, counter ← 1, then the diamond counter <= 5?. YES leads down to Print counter and counter ← counter + 1, and a yellow repeat arrow goes back up to the diamond. NO leads right to End', 1560, 1244, 2, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ec9573b8ac17d86a', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'explanation', 'Same logic, different syntax', 'Put the pseudocode and the C++ side by side and go row by row. The three parts stay in the same places; only the way they are written changes.

| Pseudocode | C++ |
|---|---|
| `counter ← 1` | `int counter = 1;` |
| `WHILE counter <= 5 DO` | `while (counter <= 5)` |
| indentation | `{ … }` |
| `PRINT counter` | `cout << counter << endl;` |
| `counter ← counter + 1` | `counter = counter + 1;` |
| `END WHILE` | `}` |

And in C++ every statement ends with a semicolon `;`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b92577b9e23e08fd', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'code', 'The first complete C++ program', 'This is a complete program you can compile and run. It prints 1 to 5, each on its own line.', '#include <iostream>
using namespace std;
int main()
{
    int counter = 1;

    while (counter <= 5)
    {
        cout << counter << endl;
        counter = counter + 1;
    }
    return 0;
}', 'cpp', 1, '', '1
2
3
4
5
', '{"notes":[{"line":1,"match":"#include <iostream>","text":"gives us cin and cout","shape":"circle","color":"sky"},{"line":3,"match":"int main()","text":"the program starts here","shape":"square","color":"sky"},{"line":5,"match":"int counter = 1;","text":"initialization","shape":"circle","color":"sky"},{"line":7,"match":"counter <= 5","text":"condition","shape":"square","color":"yel"},{"line":9,"match":"cout << counter << endl;","text":"print, then a new line","shape":"tri","color":"green"},{"line":10,"match":"counter = counter + 1;","text":"update","shape":"diamond","color":"green"},{"line":12,"match":"return 0;","text":"program finished OK","shape":"circle","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 4, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_7b994616a6b54b85', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'explanation', 'Line by line', '| Line | Meaning |
|---|---|
| `#include <iostream>` | Allows input and output: lets us use `cin` and `cout`. |
| `using namespace std;` | Lets us write `cout` and `cin` directly, without `std::`. |
| `int main()` | The program starts running here. Its body is between `{` and `}`. |
| `int counter = 1;` | Creates an `int` variable and initializes it to 1. |
| `while (counter <= 5)` | The loop condition: repeat while it is TRUE. |
| `cout << counter << endl;` | Prints the current value; `endl` moves to a new line. |
| `counter = counter + 1;` | Updates the counter: takes its value and adds 1. The right side is worked out first with the old value, then stored back. |
| `return 0;` | Tells the operating system the program finished normally. |

The symbols beginners mix up:

- `;` ends a statement.
- `( )` hold the condition.
- `{ }` group the loop body.
- `<<` sends a value to `cout`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_205cd85f1fc996ad', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'explanation', 'while syntax', '```cpp
while (condition)
{
    statements;
}
```

- `while` is a keyword, always **lowercase**. C++ is case-sensitive, so `While` or `WHILE` won''t compile.
- `( condition )` is a test: TRUE or FALSE.
- `{ }` hold the body: what repeats.

How it runs:

1. The condition is checked **first**.
2. If TRUE, the loop body executes.
3. If FALSE, the loop stops, and the program continues after the `}`.
4. After the body, the condition is checked again.

::: warning No ; after while ( )
`while (counter <= 5);` ends the loop right there: the semicolon becomes an empty body, so the real body never repeats. One of the most common beginner bugs.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_99747aa9622af8b3', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'diagram', 'Flow of execution', 'The condition is checked before every repetition, and one last time when it becomes FALSE. The update happens inside the repetition, every time, right after the body.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_fundamentals/lessons/les_1946d5476bda30c9/loop-three-parts.png', 'A loop flowchart: the rectangle 1 Initialize (runs once), then the diamond 2 Condition? (checked before every pass). TRUE leads down to Execute the body, then 3 Update (after the body, every time), and a yellow repeat arrow goes back up to the condition. FALSE leads right to the oval Exit loop', 1560, 1072, 7, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b623d20e1469bbf0', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'explanation', 'Trace the loop', 'Each row is one pass. Tracing tables like this are the best way to predict output and find bugs before running the code.

| Iteration | counter before | Condition | Output | counter after |
|---|---|---|---|---|
| 1 | 1 | `1 <= 5` TRUE | 1 | 2 |
| 2 | 2 | `2 <= 5` TRUE | 2 | 3 |
| 3 | 3 | `3 <= 5` TRUE | 3 | 4 |
| 4 | 4 | `4 <= 5` TRUE | 4 | 5 |
| 5 | 5 | `5 <= 5` TRUE | 5 | 6 |
| 6 | 6 | `6 <= 5` FALSE | (none) | (none) |

Row 6 is only a check: the condition is FALSE, so the body doesn''t run and the loop ends. The body executes **5** times; the condition is checked **6** times. After the loop, `counter` is 6.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_83fa70c40fe180d6', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'code', 'Initialization, condition, update', 'Every counting loop has these three parts. In a `while` loop, the initialization comes **before** the loop, the condition sits **inside the ( )**, and the update goes at the **end of the body**. This version uses `counter++`, a short way to write `counter = counter + 1`. Without `endl`, the numbers print side by side.', '#include <iostream>
using namespace std;
int main()
{
    int counter = 1;

    while (counter <= 5)
    {
        cout << counter;
        counter++;
    }
    cout << endl;
    return 0;
}', 'cpp', 1, '', '12345
', '{"notes":[{"line":5,"match":"int counter = 1;","text":"before the loop: runs once","shape":"circle","color":"sky"},{"line":7,"match":"counter <= 5","text":"inside ( ): repeat or stop","shape":"square","color":"yel"},{"line":10,"match":"counter++;","text":"in the body: every time","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 9, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_9804406a93b88331', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'explanation', 'Increment and decrement operators', 'Three ways to add 1. All three increase `counter` by 1: if `counter` is 3, it becomes 4.

| Code | Meaning |
|---|---|
| `counter = counter + 1;` | long form: take counter, add 1, store it back |
| `counter += 1;` | shorthand: "add 1 to counter" |
| `counter++;` | increment operator: the shortest way |

And the other direction and bigger steps:

| Code | Meaning |
|---|---|
| `counter--;` | `counter = counter - 1`: if counter is 3, it becomes 2 |
| `counter += 2;` | adds 2 each time (we use it for even numbers) |

The long form is never wrong; use whichever you find clearest. For now, write `++` and `--` as statements on their own line.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ec5afcca3f0e1f3c', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'code', 'Example: count down 5, 4, 3, 2, 1', 'Logic first: start at 5, keep going while counter is at least 1, subtract 1 each time.', '#include <iostream>
using namespace std;
int main()
{
    int counter = 5;

    while (counter >= 1)
    {
        cout << counter << endl;
        counter--;
    }
    return 0;
}', 'cpp', 1, '', '5
4
3
2
1
', '{"notes":[{"line":5,"match":"5","text":"start: 1 → 5","shape":"circle","color":"sky"},{"line":7,"match":">= 1","text":"condition: <= 5 → >= 1","shape":"square","color":"yel"},{"line":10,"match":"counter--;","text":"update: ++ → --","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 11, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_128abb501d0716c3', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'explanation', 'What changed from 1 to 5?', 'Compared with the count-up program, **three** things changed together:

- the starting value: 1 → 5;
- the condition: `<= 5` → `>= 1`;
- the update direction: `++` → `--`.

Quick trace: 5, 4, 3, 2, 1 are printed; then `counter` becomes 0, `0 >= 1` is FALSE, and the loop stops.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_bfdc042182cec89b', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'code', 'Example: even numbers from 2 to 10', 'Start at 2, add 2 each time, stop after 10. The logic in pseudocode is `number ← 2`, `WHILE number <= 10 DO`, `PRINT number`, `number ← number + 2`, `END WHILE`. The only new idea in C++ is the update `number += 2`, which jumps by 2.', '#include <iostream>
using namespace std;
int main()
{
    int number = 2;

    while (number <= 10)
    {
        cout << number << endl;
        number += 2;
    }
    return 0;
}', 'cpp', 1, '', '2
4
6
