', '{"notes":[{"line":5,"match":"number = 2","text":"start at 2","shape":"circle","color":"sky"},{"line":7,"match":"number <= 10","text":"stop after 10","shape":"square","color":"yel"},{"line":10,"match":"number += 2;","text":"jump by 2","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 13, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d72ed6d166b275c4', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'explanation', 'Trace the even numbers', '`number` takes the values 2 → 4 → 6 → 8 → 10 → 12. Then `12 <= 10` is FALSE, so the loop stops. The value 12 is never printed; it only makes the condition false.

What if we started at 1? We would print the **odd** numbers 1, 3, 5, 7, 9.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 14, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_9eff711e2fedfa13', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'note', 'Check yourself', '::: check What does this print?
```cpp
int counter = 10;
while (counter >= 4)
{
    cout << counter << " ";
    counter -= 3;
}
cout << endl;
```
???
```output
10 7 4 
```
`counter` goes 10, 7, 4, then 1. `1 >= 4` is FALSE, so 1 is never printed.
