INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e068fb0595008db7', 'course_programming_fundamentals', 'les_1946d5476bda30c9', 'key_takeaways', 'Key takeaways', '- Pseudocode turns into C++ line by line: `←` becomes `=`, `WHILE … DO` becomes `while ( )`, indentation becomes `{ }`, `PRINT` becomes `cout <<`, `END WHILE` becomes `}`.
- A `while` loop checks its condition **before** every pass; no `;` after `while ( )`.
- Initialization before the loop, condition in the `( )`, update at the end of the body.
- `counter++` adds 1, `counter--` subtracts 1, `counter += 2` adds 2.
- To count down, change all three together: start high, use `>=`, and decrement.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 16, 1791504000000);
