INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'lesson', 'les_1946d5476bda30c9', '/courses/programming-fundamentals/lectures/while-loops-in-cpp', 'While loops in C++: from pseudocode to real code', 'Turn last lecture''s WHILE pseudocode into a complete C++ program, read it line by line, trace it, and use ++, -- and += to count up, count down and count in steps. Translate a WHILE loop from pseudocode into C++ Explain every line of a complete C++ program Write the while syntax correctly, with no semicolon after while ( ) Use counter++, counter-- and counter += 2 as updates Where did we stop? Every loop runs the same cycle: initialization once, then condition , body , update , and back to the condition. Last lecture we wrote this pseudocode: counter ← 1 WHILE counter <= 5 DO PRINT counter counter ← counter + 1 END WHILE What are the three essential parts? Initialization ( counter ← 1 ), condition ( counter <= 5 ) and update ( counter ← counter + 1 ). Miss any one of them and the loop breaks. Today we write it in real C++. The same example as a flowchart After the update, the flow jumps back to the condition , not to Start. Only the NO exit reaches End. Same logic, different syntax Put the pseudocode and the C++ side by side and go row by row. The three parts stay in the same places; only the way they are written changes. Pseudocode C++ --- --- counter ← 1 int counter = 1; WHILE counter <= 5 DO while (counter <= 5) indentation { … } PRINT counter cout << counter << endl; counter ← counter + 1 counter = counter + 1; END WHILE } And in C++ every statement ends with a semicolon ; . The first complete C++ program This is a complete program you can compile and run. It prints 1 to 5, each on its own line. #include <iostream> using namespace std; int main() { int counter = 1; while (counter <= 5) { cout << counter << endl; counter = counter + 1; } return 0; } Line by line Line Meaning --- --- include <iostream Allows input and output: lets us use cin and cout . using namespace std; Lets us write cout and cin directly, without std:: . int main() The program starts running here. Its body is between { and } . int counter = 1; Creates an int variable and initializes it to 1. while (counter <= 5) The loop condition: repeat while it is TRUE. cout << counter << endl; Prints the current value; endl moves to a new line. counter = counter + 1; Updates the counter: takes its value and adds 1. The right side is worked out first with the old value, then stored back. return 0; Tells the operating system the program finished normally. The symbols beginners mix up: - ; ends a statement. - ( ) hold the condition. - { } group the loop body. - << sends a value to cout . while syntax while (condition) { statements; } - while is a keyword, always lowercase . C++ is case-sensitive, so While or WHILE won''t compile. - ( condition ) is a test: TRUE or FALSE. - { } hold the body: what repeats. How it runs: 1. The condition is checked first . 2. If TRUE, the loop body executes. 3. If FALSE, the loop stops, and the program continues after the } . 4. After the body, the condition is checked again. while (counter <= 5); ends the loop right there: the semicolon becomes an empty body, so the real body never repeats. One of the most common beginner bugs. Flow of execution The condition is checked before every repetition, and one last time when it becomes FALSE. The update happens inside the repetition, every time, right after the body. Trace the loop Each row is one pass. Tracing tables like this are the best way to predict output and find bugs before running the code. Iteration counter before Condition Output counter after --- --- --- --- --- 1 1 1 <= 5 TRUE 1 2 2 2 2 <= 5 TRUE 2 3 3 3 3 <= 5 TRUE 3 4 4 4 4 <= 5 TRUE 4 5 5 5 5 <= 5 TRUE 5 6 6 6 6 <= 5 FALSE (none) (none) Row 6 is only a check: the condition is FALSE, so the body doesn''t run and the loop ends. The body executes 5 times; the condition is checked 6 times. After the loop, counter is 6. Initialization, condition, update Every counting loop has these three parts. In a while loop, the initialization comes before the loop, the condition sits inside the ( ) , and the update goes at the end of the body . This version uses counter++ , a short way to write counter = counter + 1 . Without endl , the numbers print side by side. #include <iostream> using namespace std; int main() { int counter = 1; while (counter <= 5) { cout << counter; counter++; } cout << endl; return 0; } Increment and decrement operators Three ways to add 1. All three increase counter by 1: if counter is 3, it becomes 4. Code Meaning --- --- counter = counter + 1; long form: take counter, add 1, store it back counter += 1; shorthand: "add 1 to counter" counter++; increment operator: the shortest way And the other direction and bigger steps: Code Meaning --- --- counter--; counter = counter - 1 : if counter is 3, it becomes 2 counter += 2; adds 2 each time (we use it for even numbers) The long form is never wrong; use whichever you find clearest. For now, write ++ and -- as statements on their own line. Example: count down 5, 4, 3, 2, 1 Logic first: start at 5, keep going while counter is at least 1, subtract 1 each time. #include <iostream> using namespace std; int main() { int counter = 5; while (counter >= 1) { cout << counter << endl; counter--; } return 0; } What changed from 1 to 5? Compared with the count-up program, three things changed together: - the starting value: 1 → 5; - the condition: <= 5 → = 1 ; - the update direction: ++ → -- . Quick trace: 5, 4, 3, 2, 1 are printed; then counter becomes 0, 0 = 1 is FALSE, and the loop stops. Example: even numbers from 2 to 10 Start at 2, add 2 each time, stop after 10. The logic in pseudocode is number ← 2 , WHILE number <= 10 DO , PRINT number , number ← number + 2 , END WHILE . The only new idea in C++ is the update number += 2 , which jumps by 2. #include <iostream> using namespace std; int main() { int number = 2; while (number <= 10) { cout << number << endl; number += 2; } return 0; } Trace the even numbers number takes the values 2 → 4 → 6 → 8 → 10 → 12. Then 12 <= 10 is FALSE, so the loop stops. The value 12 is never printed; it only makes the condition false. What if we started at 1? We would print the odd numbers 1, 3, 5, 7, 9. Check yourself int counter = 10; while (counter = 4) { cout << counter << " "; counter -= 3; } cout << endl; 10 7 4 counter goes 10, 7, 4, then 1. 1 = 4 is FALSE, so 1 is never printed. Key takeaways - Pseudocode turns into C++ line by line: ← becomes = , WHILE … DO becomes while ( ) , indentation becomes { } , PRINT becomes cout << , END WHILE becomes } . - A while loop checks its condition before every pass; no ; after while ( ) . - Initialization before the loop, condition in the ( ) , update at the end of the body. - counter++ adds 1, counter-- subtracts 1, counter += 2 adds 2. - To count down, change all three together: start high, use = , and decrement.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_e81daa799465081b', 'course_programming_fundamentals', 'top_e519989412df8f8b', 'counters-accumulators-and-input-loops', 'Accumulators, input loops and infinite loops', 'Keep a running total with an accumulator, read many values with one cin inside a loop, compute a sum and an average, and debug two loops that never stop.', 4, 13, 'medium', '["Use an accumulator that starts at 0 to build a total","Read several values with one cin inside a loop","Divide once, after the loop, to get an average","Find and fix a missing update and an update that goes the wrong way"]', '["While loops in C++: from pseudocode to real code"]', 14, 'published', 1791504000000, 1791504000000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
