INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_72db4113ba3c88e7', 'course_programming_fundamentals', 'les_e81daa799465081b', 'code', 'Example: the sum from 1 to 5', '**Problem:** calculate 1 + 2 + 3 + 4 + 5.

**New idea, the accumulator:** a variable that collects a **running total**. It starts at 0, because adding 0 changes nothing. Now there are two variables with two jobs: `counter` controls the repetition, and `sum` stores the accumulated total.', '#include <iostream>
using namespace std;
int main()
{
    int counter = 1;
    int sum = 0;

    while (counter <= 5)
    {
        sum = sum + counter;  // add to the total
        counter++;
    }
    cout << sum << endl;
    return 0;
}', 'cpp', 1, '', '15
', '{"notes":[{"line":5,"match":"counter = 1","text":"controls the repetition","shape":"circle","color":"sky"},{"line":6,"match":"sum = 0","text":"the accumulator starts at 0","shape":"square","color":"yel"},{"line":10,"match":"sum = sum + counter;","text":"add to the total","shape":"diamond","color":"green"},{"line":10,"match":"// add to the total","text":"a comment: ignored","shape":"tri","color":"sky"},{"line":13,"match":"cout << sum","text":"after the loop: once","shape":"circle","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 1, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_175196bdbe98323e', 'course_programming_fundamentals', 'les_e81daa799465081b', 'explanation', 'Trace the sum', 'Each pass takes the **old** total and adds the current counter.

| Iteration | counter | sum before | sum = sum + counter | sum after |
|---|---|---|---|---|
| 1 | 1 | 0 | 0 + 1 | 1 |
| 2 | 2 | 1 | 1 + 2 | 3 |
| 3 | 3 | 3 | 3 + 3 | 6 |
| 4 | 4 | 6 | 6 + 4 | 10 |
| 5 | 5 | 10 | 10 + 5 | 15 |

`counter` controls the repetition, 1 to 5; at 6 the condition is FALSE. `sum` stores the accumulated result: 0 → 1 → 3 → 6 → 10 → 15. Check: 1 + 2 + 3 + 4 + 5 really is 15.

Two details in the code:

- `//` starts a **comment**: a note for humans that the compiler ignores.
- The `cout` is **after** the loop, so only the final total is printed.

::: warning Always initialize an accumulator
If you forget `sum = 0`, the starting value of `sum` in C++ is unpredictable, so the total is garbage. Always set accumulators to 0 before the loop.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 2, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_2f57407fadea6ba0', 'course_programming_fundamentals', 'les_e81daa799465081b', 'code', 'Example: ask the user for 5 numbers', 'Without a loop we would need five `cout` lines and five `cin` lines. With a loop we write them once, and the same input instruction repeats automatically 5 times.

`cin >> number;` waits for the user to type a value and press Enter, then stores it in `number`. The arrows `>>` point **into** the variable: the value flows into it. (The arrows of `cout` point toward the screen.)', '#include <iostream>
using namespace std;
int main()
{
    int count = 1;
    int number;

    while (count <= 5)
    {
        cout << "Enter number: ";
        cin >> number;
        count++;
    }
    return 0;
}', 'cpp', 1, '4
7
