', 'Enter number: 4
Enter number: 7
Enter number: 1
Enter number: 9
Enter number: 3
', '{"notes":[{"line":10,"match":"\"Enter number: \"","text":"printed exactly as written","shape":"circle","color":"sky"},{"line":11,"match":"cin >> number;","text":"the value flows into number","shape":"square","color":"yel"},{"line":12,"match":"count++;","text":"the update","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 3, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_1fed36dd9c436cf9', 'course_programming_fundamentals', 'les_e81daa799465081b', 'explanation', 'Only the last value survives', 'Each new value **replaces** the old one in `number`. After the loop, `number` only holds 3, the last value typed. To keep the total, we add an accumulator.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_95472b829de23861', 'course_programming_fundamentals', 'les_e81daa799465081b', 'code', 'Example: read 5 numbers and add them', 'This combines the last two ideas: input in a loop plus an accumulator. The pattern is **read, process, repeat**, and it shows up everywhere: reading sensor values, grades, prices. This version has no prompt, so the user just types the numbers.', '#include <iostream>
using namespace std;
int main()
{
    int count = 1;
    int number;
    int sum = 0;
    while (count <= 5)
    {
        cin >> number;        // read
        sum = sum + number;   // process
        count++;              // repeat
    }
    cout << "Sum = " << sum << endl;
    return 0;
}', 'cpp', 1, '4
