', '{"notes":[{"line":10,"match":"cin >> number;","text":"read","shape":"circle","color":"sky"},{"line":11,"match":"sum = sum + number;","text":"process","shape":"square","color":"yel"},{"line":12,"match":"count++;","text":"repeat","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 5, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b0aab9b7f3348b97', 'course_programming_fundamentals', 'les_e81daa799465081b', 'explanation', 'Trace the sum of inputs', 'The user types 4, 7, 1, 9, 3:

| count | number | sum after |
|---|---|---|
| 1 | 4 | 0 + 4 = 4 |
| 2 | 7 | 4 + 7 = 11 |
| 3 | 1 | 11 + 1 = 12 |
| 4 | 9 | 12 + 9 = 21 |
| 5 | 3 | 21 + 3 = 24 |

Output: `Sum = 24`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ff35f7651963ee10', 'course_programming_fundamentals', 'les_e81daa799465081b', 'code', 'Example: the average of 5 numbers', 'Same read-process-repeat pattern, plus one division at the end.

1. **Sum first**, inside the loop (line 11).
2. **Divide once**, after the loop (line 14), because only then is the full total known.

`sum += number` means `sum = sum + number`.', '#include <iostream>
using namespace std;
int main()
{
    int count = 1;
    float number;
    float sum = 0;
    while (count <= 5)
    {
        cin >> number;
        sum += number;  // inside loop
        count++;
    }
    float average = sum / 5;  // after loop
    cout << average << endl;
    return 0;
}', 'cpp', 1, '4
7
1
9
3
', '4
7
1
9
3
4.8
', '{"notes":[{"line":7,"match":"float sum = 0;","text":"float keeps the decimals","shape":"circle","color":"sky"},{"line":11,"match":"sum += number;","text":"sum inside the loop","shape":"square","color":"yel"},{"line":14,"match":"sum / 5","text":"divide once, after","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 7, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_c22c3e5145080fcf', 'course_programming_fundamentals', 'les_e81daa799465081b', 'explanation', 'Why float?', 'With the input 4, 7, 1, 9, 3, `sum` is 24 and the average is 24 / 5 = **4.8**. We use `float` so the average can have a decimal part. If `sum` were an `int`, `24 / 5` would give **4**: the decimal part is cut off.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_c15aef1fe427b835', 'course_programming_fundamentals', 'les_e81daa799465081b', 'common_mistakes', 'Infinite loop: the update is missing', 'What is wrong with this loop? (It has no OUTPUT box on purpose: it never finishes.)', '#include <iostream>
using namespace std;
int main()
{
    int counter = 1;

    while (counter <= 5)
    {
        cout << counter;
        // ???
    }
    return 0;
}', 'cpp', 1, '', NULL, '{"notes":[{"line":7,"match":"counter <= 5","text":"always TRUE","shape":"tri","color":"coral"},{"line":10,"match":"// ???","text":"the update is missing","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 9, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_96d5567df22f1ab6', 'course_programming_fundamentals', 'les_e81daa799465081b', 'explanation', 'Why it never stops, and the fix', '`counter` never changes. It stays 1, so `counter <= 5` is always TRUE and the loop runs forever, printing `1111111111111111…`. In a terminal, press **Ctrl + C** to stop a program like this.

**Fix:** add `counter++;` inside the body.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5e9c1b0371bbec0f', 'course_programming_fundamentals', 'les_e81daa799465081b', 'common_mistakes', 'Another infinite loop: the update goes the wrong way', 'Will this loop stop?', '#include <iostream>
using namespace std;
int main()
{
    int x = 10;

    while (x > 0)
    {
        cout << x;
        x++;
    }
    return 0;
}', 'cpp', 1, '', NULL, '{"notes":[{"line":7,"match":"x > 0","text":"stays TRUE","shape":"tri","color":"coral"},{"line":10,"match":"x++;","text":"moves away from 0","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 11, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_fbeb8070a81f7b7a', 'course_programming_fundamentals', 'les_e81daa799465081b', 'explanation', 'No, it never stops', 'This loop has an update, but it goes the wrong way. `x` starts at 10 and `x++` makes it bigger: 11, 12, 13 … `x` moves **away** from the stopping condition, so `x > 0` stays TRUE. (Strictly speaking an `int` can''t grow forever, but what happens then is undefined in C++, so treat it as a loop that never stops.)

**Rule:** the update must move the variable **toward** the stopping condition.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_966898712eed773e', 'course_programming_fundamentals', 'les_e81daa799465081b', 'code', 'The fix: x--', 'With `x--`, `x` goes 10, 9, … 1, 0. At 0, `x > 0` is FALSE and the loop stops. There is no `endl` or space between the numbers, so they print side by side.', '#include <iostream>
using namespace std;
int main()
{
    int x = 10;

    while (x > 0)
    {
        cout << x;
        x--;
    }
    cout << endl;
    return 0;
}', 'cpp', 1, '', '10987654321
', '{"notes":[{"line":10,"match":"x--;","text":"moves toward 0","shape":"circle","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 13, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0d25697990f0f14d', 'course_programming_fundamentals', 'les_e81daa799465081b', 'key_takeaways', 'Key takeaways', '- An accumulator collects a running total. Start it at 0 **before** the loop.
- One `cin` inside a loop reads many values; each new value replaces the old one.
- Read, process, repeat: read a value, add it to the total, update the counter.
- Divide for an average **once, after** the loop, and use `float` to keep the decimals.
- A loop with no update, or an update that moves the wrong way, never stops.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 14, 1791504000000);
