INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'lesson', 'les_e81daa799465081b', '/courses/programming-fundamentals/lectures/counters-accumulators-and-input-loops', 'Accumulators, input loops and infinite loops', 'Keep a running total with an accumulator, read many values with one cin inside a loop, compute a sum and an average, and debug two loops that never stop. Use an accumulator that starts at 0 to build a total Read several values with one cin inside a loop Divide once, after the loop, to get an average Find and fix a missing update and an update that goes the wrong way Example: the sum from 1 to 5 Problem: calculate 1 + 2 + 3 + 4 + 5. New idea, the accumulator: a variable that collects a running total . It starts at 0, because adding 0 changes nothing. Now there are two variables with two jobs: counter controls the repetition, and sum stores the accumulated total. #include <iostream> using namespace std; int main() { int counter = 1; int sum = 0; while (counter <= 5) { sum = sum + counter; // add to the total counter++; } cout << sum << endl; return 0; } Trace the sum Each pass takes the old total and adds the current counter. Iteration counter sum before sum = sum + counter sum after --- --- --- --- --- 1 1 0 0 + 1 1 2 2 1 1 + 2 3 3 3 3 3 + 3 6 4 4 6 6 + 4 10 5 5 10 10 + 5 15 counter controls the repetition, 1 to 5; at 6 the condition is FALSE. sum stores the accumulated result: 0 → 1 → 3 → 6 → 10 → 15. Check: 1 + 2 + 3 + 4 + 5 really is 15. Two details in the code: - // starts a comment : a note for humans that the compiler ignores. - The cout is after the loop, so only the final total is printed. If you forget sum = 0 , the starting value of sum in C++ is unpredictable, so the total is garbage. Always set accumulators to 0 before the loop. Example: ask the user for 5 numbers Without a loop we would need five cout lines and five cin lines. With a loop we write them once, and the same input instruction repeats automatically 5 times. cin number; waits for the user to type a value and press Enter, then stores it in number . The arrows point into the variable: the value flows into it. (The arrows of cout point toward the screen.) #include <iostream> using namespace std; int main() { int count = 1; int number; while (count <= 5) { cout << "Enter number: "; cin >> number; count++; } return 0; } Only the last value survives Each new value replaces the old one in number . After the loop, number only holds 3, the last value typed. To keep the total, we add an accumulator. Example: read 5 numbers and add them This combines the last two ideas: input in a loop plus an accumulator. The pattern is read, process, repeat , and it shows up everywhere: reading sensor values, grades, prices. This version has no prompt, so the user just types the numbers. #include <iostream> using namespace std; int main() { int count = 1; int number; int sum = 0; while (count <= 5) { cin >> number; // read sum = sum + number; // process count++; // repeat } cout << "Sum = " << sum << endl; return 0; } Trace the sum of inputs The user types 4, 7, 1, 9, 3: count number sum after --- --- --- 1 4 0 + 4 = 4 2 7 4 + 7 = 11 3 1 11 + 1 = 12 4 9 12 + 9 = 21 5 3 21 + 3 = 24 Output: Sum = 24 . Example: the average of 5 numbers Same read-process-repeat pattern, plus one division at the end. 1. Sum first , inside the loop (line 11). 2. Divide once , after the loop (line 14), because only then is the full total known. sum += number means sum = sum + number . #include <iostream> using namespace std; int main() { int count = 1; float number; float sum = 0; while (count <= 5) { cin >> number; sum += number; // inside loop count++; } float average = sum / 5; // after loop cout << average << endl; return 0; } Why float? With the input 4, 7, 1, 9, 3, sum is 24 and the average is 24 / 5 = 4.8 . We use float so the average can have a decimal part. If sum were an int , 24 / 5 would give 4 : the decimal part is cut off. Infinite loop: the update is missing What is wrong with this loop? (It has no OUTPUT box on purpose: it never finishes.) #include <iostream> using namespace std; int main() { int counter = 1; while (counter <= 5) { cout << counter; // ??? } return 0; } Why it never stops, and the fix counter never changes. It stays 1, so counter <= 5 is always TRUE and the loop runs forever, printing 1111111111111111… . In a terminal, press Ctrl + C to stop a program like this. Fix: add counter++; inside the body. Another infinite loop: the update goes the wrong way Will this loop stop? #include <iostream> using namespace std; int main() { int x = 10; while (x > 0) { cout << x; x++; } return 0; } No, it never stops This loop has an update, but it goes the wrong way. x starts at 10 and x++ makes it bigger: 11, 12, 13 … x moves away from the stopping condition, so x 0 stays TRUE. (Strictly speaking an int can''t grow forever, but what happens then is undefined in C++, so treat it as a loop that never stops.) Rule: the update must move the variable toward the stopping condition. The fix: x-- With x-- , x goes 10, 9, … 1, 0. At 0, x 0 is FALSE and the loop stops. There is no endl or space between the numbers, so they print side by side. #include <iostream> using namespace std; int main() { int x = 10; while (x > 0) { cout << x; x--; } cout << endl; return 0; } Key takeaways - An accumulator collects a running total. Start it at 0 before the loop. - One cin inside a loop reads many values; each new value replaces the old one. - Read, process, repeat: read a value, add it to the total, update the counter. - Divide for an average once, after the loop, and use float to keep the decimals. - A loop with no update, or an update that moves the wrong way, never stops.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_4b0a034921210e04', 'course_programming_fundamentals', 'top_7bc76727bcec74a6', 'input-and-output-with-cout-and-cin', 'Input and output with cout and cin', 'Print text and numbers with cout, read the user''s values with cin, and avoid the classic mistakes with integer division and names that contain spaces.', 4, 14, 'easy', '["Print text, numbers and calculations with cout and <<","Control new lines with endl","Read one or more values from the keyboard with cin and >>","Read a whole line, spaces included, with getline"]', '["Data types: int, float, char, string and bool"]', 9, 'published', 1791417600000, 1791417600000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
