INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_28dda899399c8a64', 'course_programming_fundamentals', 'les_4b0a034921210e04', 'explanation', 'Programs talk through input and output', 'Almost every program does three things: it **reads** some values (input), **works** on them, and **shows** a result (output). In C++ the keyboard and the screen are reached through two objects from the `<iostream>` library:

- `cout` (console output) sends values **to the screen**, using the `<<` operator.
- `cin` (console input) reads values **from the keyboard**, using the `>>` operator.

A memory trick: the arrows point the way the data flows. `cout << "Hi"` pushes `"Hi"` out to the screen; `cin >> age` pulls a value in from the keyboard and puts it into `age`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1791417600000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_21d01f22fd90c6d8', 'course_programming_fundamentals', 'les_4b0a034921210e04', 'code', 'Your first output', '', '#include <iostream>
using namespace std;

int main() {
    cout << "Hello, Code_Expert!" << endl;
    cout << "C++ is fun";
    cout << " and fast" << endl;
    return 0;
}', 'cpp', 1, '', 'Hello, Code_Expert!
C++ is fun and fast
', '{"notes":[{"line":1,"match":"iostream","text":"gives you cout and cin","shape":"circle","color":"sky"},{"line":5,"match":"<<","text":"sends text to cout","shape":"square","color":"yel"},{"line":5,"match":"endl","text":"ends the line","shape":"diamond","color":"green"},{"line":6,"match":"\"C++ is fun\"","text":"no endl: line continues","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1791417600000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_3bbcc06deee69447', 'course_programming_fundamentals', 'les_4b0a034921210e04', 'explanation', 'Why the second and third lines joined', '`cout` doesn''t start a new line on its own. Only `endl` (or the character `\n` inside a string) moves to the next line. Line 6 printed `C++ is fun` with no `endl`, so line 7 carried on right after it.

::: tip What about std::?
`cout`, `cin` and `endl` really belong to a namespace called `std`. The line `using namespace std;` lets you write `cout` instead of `std::cout`. Both are correct C++; your course may use either.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1791417600000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_548e3cd480240689', 'course_programming_fundamentals', 'les_4b0a034921210e04', 'code', 'Printing numbers and calculations', '`cout` prints numbers and the results of calculations, and you can chain several values with `<<`.', '#include <iostream>
using namespace std;

int main() {
    int apples = 7;
    cout << "Apples: " << apples << endl;
    cout << "Double: " << apples * 2 << endl;
    cout << 7 / 2 << " and " << 7.0 / 2 << endl;
    return 0;
}', 'cpp', 1, '', 'Apples: 7
Double: 14
3 and 3.5
', '{"notes":[{"line":6,"match":"apples","text":"prints the value, 7","shape":"circle","color":"sky"},{"line":7,"match":"apples * 2","text":"calculated first","shape":"square","color":"yel"},{"line":8,"match":"7 / 2","text":"int / int drops .5","shape":"tri","color":"coral"},{"line":8,"match":"7.0 / 2","text":"a double keeps .5","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 4, 1791417600000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_00a3d81f959a0cfa', 'course_programming_fundamentals', 'les_4b0a034921210e04', 'note', 'Check yourself', '::: check What does this line print?
```cpp
cout << 10 / 4 << " " << 10 % 4 << endl;
```
???
```output
2 2
```
`10 / 4` divides two `int` values, so the result is the whole part, `2`. `10 % 4` is the **remainder** of that division, which is also `2`.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 5, 1791417600000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_30875ae93e691be5', 'course_programming_fundamentals', 'les_4b0a034921210e04', 'code', 'Reading a value with cin', '`cin >> age;` waits for the user to type a value and press Enter, then stores it in `age`. Print a short message first (a **prompt**) so the user knows what to type.', '#include <iostream>
using namespace std;

int main() {
    int age;
    cout << "Enter your age: ";
    cin >> age;
    cout << "Next year you will be " << age + 1 << endl;
    return 0;
}', 'cpp', 1, '19
', 'Enter your age: 19
Next year you will be 20
', '{"notes":[{"line":5,"match":"int age;","text":"a box for the answer","shape":"circle","color":"sky"},{"line":6,"match":"\"Enter your age: \"","text":"the prompt","shape":"square","color":"yel"},{"line":7,"match":">>","text":"stores what was typed","shape":"diamond","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 6, 1791417600000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_81705599f3894eef', 'course_programming_fundamentals', 'les_4b0a034921210e04', 'explanation', 'Who wrote what?', 'The OUTPUT box shows the terminal exactly as you would see it. The `19` (in green, underlined) is what the **user typed**; the terminal shows your typing as you type it. Everything else was **printed by the program**. `cin` itself prints nothing: it only reads.

The prompt ends with a space and no `endl`, so the typing appears on the same line as the question.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 7, 1791417600000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_d004359993c21be9', 'course_programming_fundamentals', 'les_4b0a034921210e04', 'code', 'Reading several values at once', 'One `cin` can read several values. They can be typed on one line separated by spaces, or on separate lines.', '#include <iostream>
#include <string>
using namespace std;

int main() {
    string name;
    double mark1, mark2;
    cin >> name >> mark1 >> mark2;
    cout << name << "''s average is " << (mark1 + mark2) / 2 << endl;
