}', 'cpp', 1, 'Omar 17.5 19
', 'Omar 17.5 19
Omar''s average is 18.25
', '{"notes":[{"line":8,"match":"cin >> name >> mark1 >> mark2","text":"reads 3 values in order","shape":"circle","color":"sky"},{"line":9,"match":"(mark1 + mark2) / 2","text":"brackets: add first","shape":"square","color":"yel"}],"strips":[]}', NULL, NULL, NULL, NULL, 8, 1791417600000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a4f707c6d4dfd696', 'course_programming_fundamentals', 'les_4b0a034921210e04', 'common_mistakes', 'Names with spaces: cin stops at a space', '`cin >>` reads **one word**: it stops at the first space. Typing a full name loses everything after the first word.', '#include <iostream>
#include <string>
using namespace std;

int main() {
    string name;
    cin >> name;
    cout << "Hello, " << name << endl;
    return 0;
}', 'cpp', 1, 'Omar Ahmed
', 'Omar Ahmed
Hello, Omar
', '{"notes":[{"line":7,"match":"cin >> name","text":"stops at the space","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 9, 1791417600000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b210ac61156c1d5c', 'course_programming_fundamentals', 'les_4b0a034921210e04', 'example', 'The fix: getline reads the whole line', '`getline(cin, name)` reads everything the user typed up to Enter, spaces included.', '#include <iostream>
#include <string>
using namespace std;

int main() {
    string name;
    getline(cin, name);
    cout << "Hello, " << name << endl;
    return 0;
}', 'cpp', 1, 'Omar Ahmed
', 'Omar Ahmed
Hello, Omar Ahmed
', '{"notes":[{"line":7,"match":"getline","text":"reads the whole line","shape":"circle","color":"green"}],"strips":[]}', NULL, NULL, NULL, NULL, 10, 1791417600000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_205431eb606d35a7', 'course_programming_fundamentals', 'les_4b0a034921210e04', 'common_mistakes', 'Other common mistakes', '- **Arrows the wrong way.** It''s `cout << x` and `cin >> x`. `cin << x` does not compile.
- **Forgetting the semicolon** at the end of a `cout` or `cin` statement.
- **Integer division by surprise.** `7 / 2` is `3`. Write `7.0 / 2`, or store the values in `double` variables, when you need the decimal part.
- **No prompt.** Without a `cout` before `cin`, the program waits silently and the user doesn''t know what to type.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1791417600000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_a0b124a23d8e4479', 'course_programming_fundamentals', 'les_4b0a034921210e04', 'key_takeaways', 'Key takeaways', '- `cout << value` prints; chain several values with more `<<`.
- Only `endl` or `\n` start a new line.
- `cin >> variable` reads one value and stops at a space; chain `>>` to read several.
- Use `getline(cin, text)` to read a whole line, including spaces.
- `int / int` gives a whole number; use a `double` to keep the decimal part.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1791417600000);
