INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'lesson', 'les_4b0a034921210e04', '/courses/programming-fundamentals/lectures/input-and-output-with-cout-and-cin', 'Input and output with cout and cin', 'Print text and numbers with cout, read the user''s values with cin, and avoid the classic mistakes with integer division and names that contain spaces. Print text, numbers and calculations with cout and << Control new lines with endl Read one or more values from the keyboard with cin and >> Read a whole line, spaces included, with getline Programs talk through input and output Almost every program does three things: it reads some values (input), works on them, and shows a result (output). In C++ the keyboard and the screen are reached through two objects from the <iostream library: - cout (console output) sends values to the screen , using the << operator. - cin (console input) reads values from the keyboard , using the operator. A memory trick: the arrows point the way the data flows. cout << "Hi" pushes "Hi" out to the screen; cin age pulls a value in from the keyboard and puts it into age . Your first output #include <iostream> using namespace std; int main() { cout << "Hello, Code_Expert!" << endl; cout << "C++ is fun"; cout << " and fast" << endl; return 0; } Why the second and third lines joined cout doesn''t start a new line on its own. Only endl (or the character \n inside a string) moves to the next line. Line 6 printed C++ is fun with no endl , so line 7 carried on right after it. cout , cin and endl really belong to a namespace called std . The line using namespace std; lets you write cout instead of std::cout . Both are correct C++; your course may use either. Printing numbers and calculations cout prints numbers and the results of calculations, and you can chain several values with << . #include <iostream> using namespace std; int main() { int apples = 7; cout << "Apples: " << apples << endl; cout << "Double: " << apples * 2 << endl; cout << 7 / 2 << " and " << 7.0 / 2 << endl; return 0; } Check yourself cout << 10 / 4 << " " << 10 % 4 << endl; 2 2 10 / 4 divides two int values, so the result is the whole part, 2 . 10 % 4 is the remainder of that division, which is also 2 . Reading a value with cin cin age; waits for the user to type a value and press Enter, then stores it in age . Print a short message first (a prompt ) so the user knows what to type. #include <iostream> using namespace std; int main() { int age; cout << "Enter your age: "; cin >> age; cout << "Next year you will be " << age + 1 << endl; return 0; } Who wrote what? The OUTPUT box shows the terminal exactly as you would see it. The 19 (in green, underlined) is what the user typed ; the terminal shows your typing as you type it. Everything else was printed by the program . cin itself prints nothing: it only reads. The prompt ends with a space and no endl , so the typing appears on the same line as the question. Reading several values at once One cin can read several values. They can be typed on one line separated by spaces, or on separate lines. #include <iostream> #include <string> using namespace std; int main() { string name; double mark1, mark2; cin >> name >> mark1 >> mark2; cout << name << "''s average is " << (mark1 + mark2) / 2 << endl; return 0; } Names with spaces: cin stops at a space cin reads one word : it stops at the first space. Typing a full name loses everything after the first word. #include <iostream> #include <string> using namespace std; int main() { string name; cin >> name; cout << "Hello, " << name << endl; return 0; } The fix: getline reads the whole line getline(cin, name) reads everything the user typed up to Enter, spaces included. #include <iostream> #include <string> using namespace std; int main() { string name; getline(cin, name); cout << "Hello, " << name << endl; return 0; } Other common mistakes - Arrows the wrong way. It''s cout << x and cin x . cin << x does not compile. - Forgetting the semicolon at the end of a cout or cin statement. - Integer division by surprise. 7 / 2 is 3 . Write 7.0 / 2 , or store the values in double variables, when you need the decimal part. - No prompt. Without a cout before cin , the program waits silently and the user doesn''t know what to type. Key takeaways - cout << value prints; chain several values with more << . - Only endl or \n start a new line. - cin variable reads one value and stops at a space; chain to read several. - Use getline(cin, text) to read a whole line, including spaces. - int / int gives a whole number; use a double to keep the decimal part.');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_a4b48227d1aff1d2', 'course_programming_fundamentals', 'top_a4b48227d1aff1d2', 'for-loops', 'For loops: the three parts in one line', 'A for loop puts initialization, condition and update in one header. Compare it with while, follow the order its parts run in, count up, count in steps, count down, and solve the practice problems.', 4, 15, 'easy', '["Write the for loop header with its three parts and two semicolons","Explain the order the parts run in","Count up, count in steps and count down with for","Rewrite a while loop as a for loop and back"]', '["While loops in C++: from pseudocode to real code","Accumulators, input loops and infinite loops"]', 15, 'published', 1791504000000, 1791504000000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
DELETE FROM lesson_sections WHERE course_id = 'course_programming_fundamentals' AND lesson_id = 'les_a4b48227d1aff1d2';
DELETE FROM lesson_relations WHERE course_id = 'course_programming_fundamentals' AND lesson_id = 'les_a4b48227d1aff1d2';
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e760a3bcddec4049', 'course_programming_fundamentals', 'les_a4b48227d1aff1d2', 'explanation', 'The for loop', 'A `for` loop is useful when we **know how many times** we want to repeat something. It packs the same three parts we have been using into one line:

```cpp
for (initialization; condition; update)
{
    statements;
}
```

| Part | When it runs |
|---|---|
| **Initialization** | once, at the start |
| **Condition** | checked before each repetition |
| **Update** | after each repetition |

The symbols: the `( )` hold all three parts, **two** semicolons `;` separate them, and there is **no** `;` after the update or after the closing `)`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_0f4b4b4c2012cf04', 'course_programming_fundamentals', 'les_a4b48227d1aff1d2', 'code', 'while vs for', 'Here is the loop that prints 1 to 5, written as a `while` loop:

```cpp
int i = 1;
while (i <= 5)
{
    cout << i;
    i++;
}
```

And here is the same loop as a `for` loop. The initialization, condition and update move into one line. Same result, different structure: you can see the whole plan of the loop at a glance.', '#include <iostream>
using namespace std;
int main()
{
    for (int i = 1; i <= 5; i++)
    {
        cout << i;
    }
