}', 'cpp', 1, '', '12345
', '{"notes":[{"line":5,"match":"int i = 1","text":"initialization","shape":"circle","color":"sky"},{"line":5,"match":"i <= 5","text":"condition","shape":"square","color":"yel"},{"line":5,"match":"i++","text":"update","shape":"diamond","color":"green"},{"line":7,"match":"cout << i;","text":"the body","shape":"tri","color":"sky"}],"strips":[]}', NULL, NULL, NULL, NULL, 2, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_962591b0932232dc', 'course_programming_fundamentals', 'les_a4b48227d1aff1d2', 'diagram', 'The order of execution', 'The first part runs once. Then the loop goes: check the condition, run the body, run the update, and back to the condition.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_fundamentals/lessons/les_a4b48227d1aff1d2/for-loop-order.png', 'A loop flowchart: the rectangle int i = 1 (runs once), then the diamond i <= 5 ? (checked before every pass). TRUE leads down to cout << i; then i++ (after the body, every time), and a yellow repeat arrow goes back up to the condition. FALSE leads right to the oval Exit loop', 1560, 1072, 3, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_f8de3ecb5a1b760f', 'course_programming_fundamentals', 'les_a4b48227d1aff1d2', 'explanation', 'Understanding the for header', 'For `for (int i = 1; i <= 5; i++)`:

1. **Initialization** `int i = 1`: creates `i` and sets it to 1. Runs once.
2. **Condition** `i <= 5`: checked before each pass. FALSE ends the loop.
3. **Update** `i++`: runs after each pass of the body.

The order is: `int i = 1` → `i <= 5 ?` → body → `i++` → back to the condition, until it is FALSE.

::: warning The update is written first but runs last
In the header, `i++` is written **before** the body, but it runs **after** the body. This is the most common confusion with for loops.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1791504000000);
