INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_87812eafe30fe76d', 'course_programming_fundamentals', 'les_a4b48227d1aff1d2', 'explanation', 'Trace and a question', '**Trace:** `i` is 2 → 4 → 6 → 8 → 10 → 12. `12 <= 10` is FALSE, so the loop stops.

