INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_cecc0dd111672a65', 'course_programming_fundamentals', 'les_a4b48227d1aff1d2', 'code', 'Example: count down 5, 4, 3, 2, 1', 'The same countdown as the while version, now as a for loop. When counting down, all three parts change together: **start high** (`int i = 5`), **stop after 1** (`i >= 1`), **go down by 1** (`i--`).', '#include <iostream>
