INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_cedd6d1407e9d6f5', 'course_programming_fundamentals', 'les_a4b48227d1aff1d2', 'explanation', 'Trace the countdown', '`i` = 5, 4, 3, 2, 1 are printed. Then `i` becomes 0, and `0 >= 1` is FALSE, so the loop stops.

If you mix the parts, for example `i--` with `i <= 5`, you get an infinite loop: `i` goes down forever and is always at most 5. You''ll debug exactly that in the debugging lecture.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_59e90fcbb6c1f6e8', 'course_programming_fundamentals', 'les_a4b48227d1aff1d2', 'note', 'Practice challenge: your turn', 'Write C++ code using loops to:

1. print the numbers 1 to 20;
2. print the even numbers from 2 to 20;
3. calculate the sum from 1 to 10.

Hint: start with a `for` loop. Then try rewriting one answer with `while`. Write the three parts first: where do I start, when do I stop, how do I move? For the sum, remember the accumulator that starts at 0.

::: check Answer 1: print the numbers 1 to 20
???
The only change from the 1-to-10 example is the number in the condition.
```cpp
for (int i = 1; i <= 20; i++)
{
    cout << i << endl;
}
```
The same result with `while`:
```cpp
int i = 1;
while (i <= 20)
{
    cout << i << endl;
    i++;
}
```
With `endl`, the output is 20 lines: 1 to 20.
:::', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1791504000000);
