INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_01b2dd8597139bdb', 'course_programming_fundamentals', 'les_a4b48227d1aff1d2', 'common_mistakes', 'The stray semicolon', 'A semicolon right after the `for (...)` header ends the loop there. The loop then repeats **nothing**, and the block below runs **once**, after the loop has finished. With warnings turned on (`g++ -Wall`), the compiler warns: *this ''for'' clause does not guard…*. That''s a good reason to always compile with warnings on.', '#include <iostream>
using namespace std;
int main()
{
    int i;
    for (i = 1; i <= 5; i++);
    {
        cout << i << endl;
    }
    return 0;
}', 'cpp', 1, '', '6
', '{"notes":[{"line":6,"match":";","text":"this ends the loop","shape":"tri","color":"coral"},{"line":8,"match":"cout << i","text":"runs once, i is 6","shape":"circle","color":"sky"}],"strips":[]}', NULL, NULL, NULL, NULL, 15, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_6fa0d610cfd20e2a', 'course_programming_fundamentals', 'les_a4b48227d1aff1d2', 'common_mistakes', 'Off-by-one errors', 'The most common loop bug is running one time too many or one too few:

- `for (int i = 1; i < 5; i++)` runs **4** times (1, 2, 3, 4). Use `<=` to include 5.
- `for (int i = 0; i <= 5; i++)` runs **6** times (0 to 5).

When unsure, write a quick trace for the first pass and the last one.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 16, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_de3145af4a36fe3d', 'course_programming_fundamentals', 'les_a4b48227d1aff1d2', 'key_takeaways', 'Key takeaways', '- `for (initialization; condition; update)`: two semicolons inside, none after the `)`.
- Initialization runs once; the condition is checked before each pass; the update runs after each pass.
- `for` is the clearest choice when you know how many times to repeat.
- To count down, change all three parts: start high, use `>=`, use `i--`.
- Any for loop can be written as a while loop, and the other way round.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 17, 1791504000000);
