INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_49ac0bd438aea4eb', 'course_programming_fundamentals', 'les_9962b1823b489bb3', 'explanation', 'The do-while loop', 'The third loop. A `do-while` loop executes the **body first**, then checks the condition.

```cpp
do
{
    statements;
}
while (condition);
```

Two syntax points:

- The keyword `do` opens the loop.
- The line `while (condition);` **ends with a semicolon**. A normal `while` loop has none there.

Because the check is at the end, the body **always executes at least once**.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e120a59ca474b0f2', 'course_programming_fundamentals', 'les_9962b1823b489bb3', 'diagram', 'How do-while runs', 'It starts with the body: there is no check first. TRUE goes back up to run the body again; FALSE leaves the loop.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_fundamentals/lessons/les_9962b1823b489bb3/do-while-flow.png', 'A flowchart: the oval Loop starts (no check first), then the rectangle Run the body (the body always runs at least once), then the diamond Condition?. TRUE leads back up to Run the body along a yellow repeat arrow; FALSE leads down to the oval Exit loop', 1440, 940, 2, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_8b5003b5fe83c0a7', 'course_programming_fundamentals', 'les_9962b1823b489bb3', 'code', 'A classic use: checking input', 'Keep asking until the user types a positive number. The question has to be asked at least once, which is exactly what `do-while` guarantees. The user typed `-3`, then `0`, then `7`.', '#include <iostream>
using namespace std;
int main()
{
    int number;
    do
    {
        cout << "Enter a positive number: ";
        cin >> number;
    }
    while (number <= 0);
    cout << "Thank you: " << number << endl;
    return 0;
}', 'cpp', 1, '-3
0
7
', 'Enter a positive number: -3
