INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'lesson', 'les_9962b1823b489bb3', '/courses/programming-fundamentals/lectures/do-while-and-choosing-a-loop', 'Do-while, and choosing the right loop', 'The do-while loop runs its body first and checks the condition after, so it always runs at least once. Compare it with while, use it to check input, and learn when to pick while, for or do-while. Write a do-while loop, with the semicolon after while (condition) Explain why a do-while body always runs at least once Predict the different output of while and do-while with the same condition Choose between while, for and do-while for a problem The do-while loop The third loop. A do-while loop executes the body first , then checks the condition. do { statements; } while (condition); Two syntax points: - The keyword do opens the loop. - The line while (condition); ends with a semicolon . A normal while loop has none there. Because the check is at the end, the body always executes at least once . How do-while runs It starts with the body: there is no check first. TRUE goes back up to run the body again; FALSE leaves the loop. A classic use: checking input Keep asking until the user types a positive number. The question has to be asked at least once, which is exactly what do-while guarantees. The user typed -3 , then 0 , then 7 . #include <iostream> using namespace std; int main() { int number; do { cout << "Enter a positive number: "; cin >> number; } while (number <= 0); cout << "Thank you: " << number << endl; return 0; } while vs do-while Same variable, same condition, different result. Predict both outputs before you look. - The while loop checks 10 < 5 first . It is FALSE, so the body is skipped completely and nothing is printed. - The do-while loop prints 10 first , then checks 10 < 5 . It is FALSE, so it stops after one pass. (Neither loop has an update. That is only safe here because the condition is FALSE from the start.) #include <iostream> using namespace std; int main() { int x = 10; cout << "while prints: ["; while (x < 5) { cout << x; } cout << "]" << endl; cout << "do-while prints: ["; do { cout << x; } while (x < 5); cout << "]" << endl; return 0; } Choosing the right loop Any loop can be rewritten as any other, so the question is which one is clearest for the problem. while for do-while --- --- --- --- Use when the number of repetitions is not clearly known the number of repetitions is known the body must run at least once Condition checked before the body before the body after the body Body runs at least 0 times 0 times 1 time Example read numbers until the user types 0 print 1 to 10, read 5 sensor values ask for input, then check it is valid The rule of thumb: - Count known → for - Count unknown (repeat until something happens) → while - Must run once (show a menu, ask for input) → do-while Check yourself (a) for : the count, 12, is known. (b) while : we don''t know how many prices will come before the 0. (c) do-while : the menu must be shown at least once before we can check the choice. int n = 0; do { cout << "Hi" << endl; n++; } while (n 5); Hi Once. The body runs first and prints Hi , then n is 1 and 1 5 is FALSE, so the loop stops. Semicolons in the wrong place The two while lines look alike but need opposite rules: - In a do-while , the semicolon after while (condition) is required . Without it, g++ stops with error: expected '';'' before … . - In a normal while , a semicolon after while (condition) is a bug : it becomes an empty body, and the real body never repeats. do { … } while (x < 5); // correct: do-while ends with ; while (x < 5) { … } // correct: no ; after while ( ) while (x < 5); { … } // bug: the ; is the whole loop Key takeaways - do-while runs the body first and checks the condition after it. - Its body always runs at least once; while and for bodies can run zero times. - while (condition); ends a do-while with a semicolon; a normal while has none. - Count known → for . Count unknown → while . Must run once → do-while .');
INSERT INTO lessons (id, course_id, topic_id, slug, title, description, lecture_number, sort_order, difficulty, objectives, prerequisites, reading_minutes, status, published_at, updated_at) VALUES ('les_b34272f68889dda4', 'course_programming_fundamentals', 'top_7715d7f27a99aecb', 'loops-with-decisions-and-debugging', 'Loops with decisions, and debugging loops', 'Put an if/else inside a for loop to control a fan from five temperature readings, then learn the six loop mistakes to check first and fix a loop that counts the wrong way.', 4, 17, 'medium', '["Combine a for loop with an if/else decision","Explain why the decision is made again on every repetition","Recognise six common loop mistakes and what each one causes","Trace a broken loop to find its bug"]', '["Do-while, and choosing the right loop","Decisions: IF … THEN … ELSE"]', 9, 'published', 1791504000000, 1791504000000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, slug = excluded.slug, title = excluded.title, description = excluded.description, lecture_number = excluded.lecture_number, sort_order = excluded.sort_order, difficulty = excluded.difficulty, objectives = excluded.objectives, prerequisites = excluded.prerequisites, reading_minutes = excluded.reading_minutes, status = excluded.status, published_at = coalesce(lessons.published_at, excluded.published_at), updated_at = excluded.updated_at;
