INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_e0db6fcacb569b85', 'course_programming_fundamentals', 'les_b34272f68889dda4', 'code', 'Computer engineering example: a temperature sensor loop', 'Read the temperature 5 times. Above 30 → Fan ON. Otherwise → Fan OFF.

- The `for` loop repeats exactly 5 times.
- The `if / else` decision from Lecture 3, now in C++ syntax, decides every time.

In a real device the reading would come from a sensor instead of `cin`. Here the user typed 28, 31.5, 30, 35 and 22.', '#include <iostream>
using namespace std;
int main()
{
    float temperature;
    for (int i = 1; i <= 5; i++)
    {
        cout << "Enter temperature: ";
        cin >> temperature;
        if (temperature > 30)
        {
            cout << "Fan ON" << endl;
        }
        else
        {
            cout << "Fan OFF" << endl;
        }
    }
    return 0;
}', 'cpp', 1, '28
31.5
30
35
22
', 'Enter temperature: 28
Fan OFF
Enter temperature: 31.5
Fan ON
Enter temperature: 30
Fan OFF
Enter temperature: 35
Fan ON
Enter temperature: 22
Fan OFF
', '{"notes":[{"line":5,"match":"float","text":"31.5 needs decimals","shape":"circle","color":"sky"},{"line":6,"match":"for (int i = 1; i <= 5; i++)","text":"repeats 5 times","shape":"square","color":"yel"},{"line":10,"match":"temperature > 30","text":"decides every time","shape":"diamond","color":"yel"},{"line":12,"match":"\"Fan ON\"","text":"TRUE path","shape":"circle","color":"green"},{"line":16,"match":"\"Fan OFF\"","text":"FALSE path","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 1, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_ea7e11f8fa540341', 'course_programming_fundamentals', 'les_b34272f68889dda4', 'explanation', 'Walk through the readings', '| Reading | `temperature > 30`? | Output |
|---|---|---|
| 28 | FALSE | Fan OFF |
| 31.5 | TRUE | Fan ON |
| 30 | FALSE | Fan OFF |
| 35 | TRUE | Fan ON |
| 22 | FALSE | Fan OFF |

30 gives Fan OFF, because `30 > 30` is FALSE. If the fan should also turn on at exactly 30, the condition must be `temperature >= 30`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 2, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_6608c10949772d95', 'course_programming_fundamentals', 'les_b34272f68889dda4', 'diagram', 'How the logic connects', 'Input, then the decision: TRUE goes to Fan ON, FALSE goes to Fan OFF. Both paths meet again at the update, and the yellow arrow repeats everything for i = 1 to 5. The decision is **inside** the loop, so it is made fresh for every reading.', NULL, NULL, 0, '', NULL, NULL, 'courses/course_programming_fundamentals/lessons/les_b34272f68889dda4/fan-control-loop.png', 'A flowchart: Start, int i = 1, then the diamond i <= 5?. YES leads to Input temperature and the diamond temperature > 30?, whose YES path prints "Fan ON" and NO path prints "Fan OFF". The paths join at i++, and a yellow repeat arrow goes back to i <= 5?. The NO exit of i <= 5? leads to End', 1800, 1920, 3, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_aa481d35fcefb9a1', 'course_programming_fundamentals', 'les_b34272f68889dda4', 'common_mistakes', 'Six common loop mistakes', 'When a loop misbehaves, check these first.

| Mistake | Code | What happens |
|---|---|---|
| **Missing update** | `while (i <= 5) { cout << i; }` | Infinite loop: `i` never changes. |
| **Wrong condition** | `for (int i = 1; i < 5; i++)` | Too few (or too many) iterations: this prints 1 to 4 only. |
| **`=` instead of `==`** | `while (x = 5)` | Stores 5 in `x` instead of comparing. `while (x == 5)` compares. |
| **Wrong starting value** | `int i = 0; while (i <= 5) …` | Off-by-one: 0 to 5 is six numbers, not five. |
| **Missing braces** | `while (i <= 5)` then `cout << i;` then `i++;` | Only the first statement after `while` is in the loop, so `i++` never runs: infinite loop. |
| **Extra semicolon** | `while (i <= 5); { cout << i; i++; }` | The `;` is the whole loop body, so the real body never repeats; the loop never ends. |

Off-by-one errors come from the start value or from `<` versus `<=`.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_b1e3b2bbbf17f362', 'course_programming_fundamentals', 'les_b34272f68889dda4', 'code', 'Wrong condition: one too few', 'The goal was 1 to 5, but `<` stops before 5.', '#include <iostream>
using namespace std;
int main()
{
    for (int i = 1; i < 5; i++)
    {
        cout << i;
