}', 'cpp', 1, '', '1234
', '{"notes":[{"line":5,"match":"i < 5","text":"5 < 5 is FALSE: 5 is missed","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 5, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_734d4e208c1cb860', 'course_programming_fundamentals', 'les_b34272f68889dda4', 'code', 'Wrong starting value: one too many', 'The goal was five numbers, but starting at 0 gives six.', '#include <iostream>
