INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_bb9bc391c64afe69', 'course_programming_fundamentals', 'les_b34272f68889dda4', 'common_mistakes', 'Find the bug', 'The goal is to print `12345`. What is wrong? Trace it on paper first. (No OUTPUT box: this loop never finishes.)', '#include <iostream>
using namespace std;
int main()
{
    for (int i = 1; i <= 5; i--)
    {
        cout << i;
    }
    return 0;
}', 'cpp', 1, '', NULL, '{"notes":[{"line":5,"match":"i--","text":"makes i smaller","shape":"tri","color":"coral"},{"line":5,"match":"i <= 5","text":"stays TRUE forever","shape":"tri","color":"coral"}],"strips":[]}', NULL, NULL, NULL, NULL, 7, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_98142c0953e851aa', 'course_programming_fundamentals', 'les_b34272f68889dda4', 'explanation', 'The answer', '`i--` makes `i` smaller: 1 → 0 → -1 → -2 → … `i` is always less than or equal to 5, so the condition `i <= 5` stays TRUE and the loop never ends. The update moves **away** from the stopping condition, just like the `x++` example in the while lecture.

**Fix:** `i++`. Then the loop prints `12345` and stops when `i` becomes 6.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 8, 1791504000000);
