INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_5ab3b049329f67be', 'course_programming_fundamentals', 'les_b34272f68889dda4', 'explanation', 'The habit to build', 'This is the process to follow for every problem:

**Problem** → **Pseudocode** → **C++ code** → **Test** → **Debug**

Understand the problem, plan it in pseudocode, write the C++, test it with real values, and debug with a trace table when the output is wrong.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1791504000000);
INSERT INTO lesson_sections (id, course_id, lesson_id, kind, title, body_md, code, code_language, runnable, sample_input, expected_output, annotations, image_key, image_alt, image_width, image_height, sort_order, updated_at) VALUES ('sec_82ab1cffd5b2f0fa', 'course_programming_fundamentals', 'les_b34272f68889dda4', 'key_takeaways', 'Key takeaways (Lecture 4)', '1. Pseudocode logic can be translated directly into C++.
2. `while` checks the condition before each repetition.
3. `for` combines initialization, condition and update.
4. `do-while` always executes at least once.
5. Counters control repetition.
6. Accumulators store running totals.
7. Always make sure the loop can stop.', NULL, NULL, 0, '', NULL, NULL, NULL, NULL, NULL, NULL, 11, 1791504000000);
